struct Params {
  threshold: f32, // @default 1.2  Linear radiance where bloom starts.
  knee: f32, // @default 0.8  Softness of the threshold.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let color = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb;
  let brightness = max(color.r, max(color.g, color.b));
  let soft = clamp(brightness - params.threshold + params.knee, 0.0, 2.0 * params.knee);
  let weight = max(soft * soft / (4.0 * params.knee + 1e-4), brightness - params.threshold) / max(brightness, 1e-4);
  return vec4f(color * weight, 1.0);
}

// MUSIC HUD (Silk Medusa): a debug overlay over the finished picture, in two bottom-corner panels.
// HEARD (left), what the music source gives: five voice meters, bass to melody (the bar is the voice's
// envelope as the scene eases it, the note name sits under it, a mark over it flashes at each strike and
// fades in about half a second, brighter for a harder strike); the twelve pitch classes on a ring in
// circle-of-fifths order (C at the top, clockwise: the bell's order) lit as the bell lights them, a tick
// outside at the root as the bell eases toward it, the chord named in the middle with its quality, the
// ring flashing at a chord strike; tempo; kick, snare and hat pulses (the DRUMS caption brightens
// when an audio source detects drums); sustain pedal; overall level (with a gate dot for an audio
// source); confidence of a guessed pitch reading. A reading the source does not have shows --.
// DRIVING (right), what the scene does with it: section (calm, medium, peak) and the energy, light and
// density levels; tension; the colour mood on the palette walk (the needle is mood, the ring on the strip
// the journey); the swim phase and the bell's stroke; melody force (right of centre rising, left falling);
// reaction strength (centre tick = as built); the chord accent into light; MUSIC or MANUAL (slider_auto)
// at the top, and a hand-trimmed level's name in the manual colour.
// OFF is the Layer's own switch (layer_hud on the Panel): bypassed, this pass is pruned and costs nothing.
// Layout is in 1080p design pixels scaled to the output; text is a 5x7 pixel font at a whole-pixel size.
struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
struct Params {
 e0: f32, // @default 0 Voice 0 (bass) envelope as the scene eases it (lag_env env0).
 e1: f32, // @default 0 Voice 1 envelope (lag_env env1).
 e2: f32, // @default 0 Voice 2 envelope (lag_env env2).
 e3: f32, // @default 0 Voice 3 envelope (lag_env env3).
 e4: f32, // @default 0 Voice 4 (melody) envelope (lag_env env4).
 p0: f32, // @default 0 Voice 0 pitch class 0..11 (music source).
 p1: f32, // @default 0 Voice 1 pitch class.
 p2: f32, // @default 0 Voice 2 pitch class.
 p3: f32, // @default 0 Voice 3 pitch class.
 p4: f32, // @default 0 Voice 4 pitch class.
 a0: f32, // @default 100 Seconds since voice 0 last struck (music source start time).
 a1: f32, // @default 100 Seconds since voice 1 last struck.
 a2: f32, // @default 100 Seconds since voice 2 last struck.
 a3: f32, // @default 100 Seconds since voice 3 last struck.
 a4: f32, // @default 100 Seconds since voice 4 last struck.
 v0: f32, // @default 0.7 Voice 0 strike velocity 0..1.
 v1: f32, // @default 0.7 Voice 1 strike velocity.
 v2: f32, // @default 0.7 Voice 2 strike velocity.
 v3: f32, // @default 0.7 Voice 3 strike velocity.
 v4: f32, // @default 0.7 Voice 4 strike velocity.
 rC: f32, // @default 1 Chord root on the circle of fifths, cosine (expression_herochord rC).
 rS: f32, // @default 0 Chord root on the circle of fifths, sine (expression_herochord rS).
 n0: f32, // @default 0 Note place 0 in circle-of-fifths order, as the bell lights it (lag_heronote2 s0).
 n1: f32, // @default 0 Note place 1 in circle-of-fifths order, as the bell lights it (lag_heronote2 s1).
 n2: f32, // @default 0 Note place 2 in circle-of-fifths order, as the bell lights it (lag_heronote2 s2).
 n3: f32, // @default 0 Note place 3 in circle-of-fifths order, as the bell lights it (lag_heronote2 s3).
 n4: f32, // @default 0 Note place 4 in circle-of-fifths order, as the bell lights it (lag_heronote2 s4).
 n5: f32, // @default 0 Note place 5 in circle-of-fifths order, as the bell lights it (lag_heronote2 s5).
 n6: f32, // @default 0 Note place 6 in circle-of-fifths order, as the bell lights it (lag_heronote2 s6).
 n7: f32, // @default 0 Note place 7 in circle-of-fifths order, as the bell lights it (lag_heronote2 s7).
 n8: f32, // @default 0 Note place 8 in circle-of-fifths order, as the bell lights it (lag_heronote2 s8).
 n9: f32, // @default 0 Note place 9 in circle-of-fifths order, as the bell lights it (lag_heronote2 s9).
 n10: f32, // @default 0 Note place 10 in circle-of-fifths order, as the bell lights it (lag_heronote2 s10).
 n11: f32, // @default 0 Note place 11 in circle-of-fifths order, as the bell lights it (lag_heronote2 s11).
 rC2: f32, // @default 1 Chord root angle as the bell eases it, cosine (lag_herochord2 rC).
 rS2: f32, // @default 0 Chord root angle as the bell eases it, sine (lag_herochord2 rS).
 qMaj: f32, // @default 0 The chord is major (expression_herochord qMaj).
 qMin: f32, // @default 0 The chord is minor (expression_herochord qMin).
 chordAge: f32, // @default 100 Seconds since the last chord strike (rig age).
 bpm: f32, // @default 68 Tempo the swim follows, in beats per minute (rig swimBpm * 2).
 kick: f32, // @default 0 Kick pulse (rig bioKick over reactGain).
 snare: f32, // @default 0 Snare pulse (rig bioSnare over reactGain).
 hat: f32, // @default 0 Hat pulse (rig bioHat over reactGain).
 pedal: f32, // @default -1 Sustain pedal 0..1; below 0: the source has no pedal (shown as --).
 input: f32, // @default -1 Analyser input level 0..1; below 0: not an audio source (level from the voices).
 gate: f32, // @default -1 1 while the audio rig hears music; below 0: not an audio source.
 drums: f32, // @default -1 Drums detected 0..1 (audio rig); below 0: the source does not detect drums.
 conf: f32, // @default -1 Confidence of the pitch reading 0..1 (audio chroma); below 0: the source does not guess pitch.
 energy: f32, // @default 0.5 Rig energy 0..1 (section level, motion).
 lum: f32, // @default 0.6 Rig lum 0.2..1.04 (light).
 density: f32, // @default 0.5 Rig density 0..1.
 tension: f32, // @default 0.3 Rig tension 0..1.
 mood: f32, // @default 0 Rig mood, palette position (wraps at 4).
 journey: f32, // @default 0 Rig journey, the slow colour walk (wraps at 4).
 pulsePhase: f32, // @default 0 Rig pulsePhase 0..1, the swim cycle.
 pulse: f32, // @default 0 Rig pulse 0..1, the bell's stroke.
 hit: f32, // @default 0 Rig hit 0..1, the chord-strike accent into light and waves.
 melody: f32, // @default 0 Melody force: (lag_heromel2 - lag_heromel3) / 4, up positive.
 react: f32, // @default 1 Rig reactGain (music reaction strength 0..2).
 autoOn: f32, // @default 1 slider_auto: 1 the music drives the state, 0 manual.
 lumTrim: f32, // @default 0 slider_lum trim.
 densityTrim: f32, // @default 0 slider_density trim.
 energyTrim: f32, // @default 0 slider_energy trim.
 palette: f32, // @default 0 slider_palette mood offset.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}

const FONT = array<vec2u, 43>(
 vec2u(0u, 0u),
 vec2u(476789u, 26158u),
 vec2u(143492u, 4238u),
 vec2u(476194u, 4383u),
 vec2u(1017986u, 1582u),
 vec2u(72018u, 31810u),
 vec2u(1033153u, 1582u),
 vec2u(205342u, 17966u),
 vec2u(1016900u, 8456u),
 vec2u(476718u, 17966u),
 vec2u(476719u, 1100u),
 vec2u(476735u, 17969u),
 vec2u(1001022u, 17982u),
 vec2u(476688u, 16942u),
 vec2u(1001009u, 17982u),
 vec2u(1032734u, 16927u),
 vec2u(1032734u, 16912u),
 vec2u(476695u, 17967u),
 vec2u(575039u, 17969u),
 vec2u(462980u, 4238u),
 vec2u(231490u, 2636u),
 vec2u(576152u, 21073u),
 vec2u(541200u, 16927u),
 vec2u(585397u, 17969u),
 vec2u(575285u, 20017u),
 vec2u(476721u, 17966u),
 vec2u(1001022u, 16912u),
 vec2u(476721u, 22093u),
 vec2u(1001022u, 21073u),
 vec2u(508430u, 1086u),
 vec2u(1020036u, 4228u),
 vec2u(575025u, 17966u),
 vec2u(575025u, 17732u),
 vec2u(575029u, 22186u),
 vec2u(574788u, 10801u),
 vec2u(574788u, 4228u),
 vec2u(1016900u, 8735u),
 vec2u(338922u, 32074u),
 vec2u(14u, 0u),
 vec2u(4255u, 4224u),
 vec2u(0u, 396u),
 vec2u(34884u, 8464u),
 vec2u(853u, 22065u));
// glyph of each note name's letter (C C# D D# E F F# G G# A A# B), and whether a sharp follows it
const NOTE = array<u32, 12>(13u, 13u, 14u, 14u, 15u, 16u, 16u, 17u, 17u, 11u, 11u, 12u);
const SHARP = array<u32, 12>(0u, 1u, 0u, 1u, 0u, 0u, 1u, 0u, 1u, 0u, 1u, 0u);
const SPACE = 0u;
const HASH = 37u;
const DASH = 38u;

// panel size and margins, design pixels (1080p)
const PW = 464.0;
const PH = 160.0;
const MX = 30.0;
const MY = 28.0;

fn lin(c: vec3f) -> vec3f { return pow(c, vec3f(2.2)); }

fn glyphBit(g: u32, c: vec2i) -> f32 {
 let e = FONT[g];
 let w = select(e.y >> u32((6 - c.y) * 5), e.x >> u32((3 - c.y) * 5), c.y < 4);
 return f32((w >> u32(4 - c.x)) & 1u);
}
// coverage of string s (n glyphs) with its top-left at o, screen pixels; fp = screen pixels per font cell
fn txt(p: vec2f, o: vec2f, s: vec4u, n: u32, fp: f32) -> f32 {
 let q = floor((p - o) / fp);
 if (q.x < 0.0 || q.y < 0.0 || q.y > 6.0) { return 0.0; }
 let ci = u32(q.x) / 6u;
 if (ci >= n) { return 0.0; }
 let cx = i32(q.x) - i32(ci) * 6;
 if (cx > 4) { return 0.0; }
 let code = (s[ci / 4u] >> ((ci % 4u) * 8u)) & 0xffu;
 return glyphBit(code, vec2i(cx, i32(q.y)));
}
// text placed in panel design coordinates: at = top edge, x of the left (align 0), centre (1) or right (2)
fn tAt(p: vec2f, org: vec2f, u: f32, fp: f32, at: vec2f, s: vec4u, n: u32, align: f32) -> f32 {
 let w = (f32(n) * 6.0 - 1.0) * fp;
 return txt(p, org + floor(at * u - vec2f(w * align * 0.5, 0.0)), s, n, fp);
}
fn pack4(a: u32, b: u32, c: u32, d: u32) -> u32 { return a | (b << 8u) | (c << 16u) | (d << 24u); }
fn digit(d: f32) -> u32 { return 1u + u32(clamp(d, 0.0, 9.0)); }

fn cov(d: f32) -> f32 { return clamp(0.5 - d, 0.0, 1.0); }
fn sdBox(l: vec2f, a: vec2f, b: vec2f, r: f32) -> f32 {
 let q = abs(l - 0.5 * (a + b)) - (0.5 * (b - a) - r);
 return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0) - r;
}
fn box(l: vec2f, a: vec2f, b: vec2f, r: f32, u: f32) -> f32 { return cov(sdBox(l, a, b, r) * u); }
fn disc(l: vec2f, c: vec2f, r: f32, u: f32) -> f32 { return cov((length(l - c) - r) * u); }
fn hoop(l: vec2f, c: vec2f, r: f32, w: f32, u: f32) -> f32 { return cov((abs(length(l - c) - r) - 0.5 * w) * u); }
fn put(col: ptr<function, vec3f>, c: vec3f, a: f32) { *col = mix(*col, c, clamp(a, 0.0, 1.0)); }

// a strike or event mark: rises over 0.07 s, then fades out by about 0.57 s
fn mark(age: f32) -> f32 {
 let up = clamp(age / 0.07, 0.0, 1.0);
 let d = 1.0 - clamp((age - 0.07) / 0.5, 0.0, 1.0);
 return select(up * d * d, 0.0, age < 0.0);
}

fn back(l: vec2f, u: f32, col: ptr<function, vec3f>) {
 let d = sdBox(l, vec2f(0.0), vec2f(PW, PH), 9.0);
 *col = *col * (1.0 - 0.16 * smoothstep(12.0, 0.0, d)) * (1.0 - 0.42 * cov(d * u));
 put(col, vec3f(1.0), 0.07 * cov((abs(d + 0.5) - 0.5) * u));
}

const INKC = vec3f(0.88, 0.89, 0.92);
const HEARC = vec3f(0.60, 0.86, 0.92);
const DRIVEC = vec3f(0.98, 0.82, 0.62);
const MANC = vec3f(1.00, 0.60, 0.40);
const FLASHC = vec3f(1.00, 0.97, 0.90);

// a horizontal level bar from x0 to x1, centred on y, with a dim track
fn hbar(l: vec2f, u: f32, x0: f32, x1: f32, y: f32, v: f32, c: vec3f, col: ptr<function, vec3f>) {
 put(col, lin(INKC), 0.16 * box(l, vec2f(x0, y - 2.5), vec2f(x1, y + 2.5), 2.5, u));
 let x = x0 + (x1 - x0) * clamp(v, 0.0, 1.0);
 put(col, c, 0.9 * box(l, vec2f(x0, y - 2.5), vec2f(max(x, x0 + 0.01), y + 2.5), 2.5, u) * step(0.002, v));
}

fn heard(p: vec2f, org: vec2f, u: f32, fp: f32, col: ptr<function, vec3f>) {
 let l = (p - org) / u;
 back(l, u, col);
 let ink = lin(INKC); let acc = lin(HEARC); let fl = lin(FLASHC);
 put(col, acc, 0.95 * tAt(p, org, u, fp, vec2f(14.0, 12.0), vec4u(470486802u, 14u, 0u, 0u), 5u, 0.0));
 // tempo, right of the title row
 let b = clamp(round(params.bpm), 0.0, 999.0);
 let h = floor(b / 100.0); let t = floor(b / 10.0) % 10.0; let o = b % 10.0;
 var ts = vec4u(0u);
 var tn = 6u;
 if (h > 0.0) { ts.x = pack4(digit(h), digit(t), digit(o), SPACE); ts.y = pack4(12u, 26u, 23u, 0u); tn = 7u; }
 else { ts.x = pack4(digit(t), digit(o), SPACE, 12u); ts.y = pack4(26u, 23u, 0u, 0u); }
 put(col, ink, 0.75 * tAt(p, org, u, fp, vec2f(PW - 14.0, 12.0), ts, tn, 2.0));

 // ---- voices
 var E = array<f32, 5>(params.e0, params.e1, params.e2, params.e3, params.e4);
 var P = array<f32, 5>(params.p0, params.p1, params.p2, params.p3, params.p4);
 var A = array<f32, 5>(params.a0, params.a1, params.a2, params.a3, params.a4);
 var V = array<f32, 5>(params.v0, params.v1, params.v2, params.v3, params.v4);
 put(col, ink, 0.45 * tAt(p, org, u, fp, vec2f(14.0, 38.0), vec4u(219355424u, 7439u, 0u, 0u), 6u, 0.0));
 if (l.x < 196.0) {
  let i = clamp(i32(floor((l.x - 13.0) / 34.0)), 0, 4);
  let cx = 30.0 + 34.0 * f32(i);
  let e = clamp(E[i], 0.0, 1.0);
  let m = mark(A[i]) * (0.45 + 0.55 * clamp(V[i], 0.0, 1.0));
  put(col, ink, 0.14 * box(l, vec2f(cx - 5.0, 64.0), vec2f(cx + 5.0, 120.0), 2.0, u));
  let top = 120.0 - 56.0 * e;
  put(col, mix(acc, fl, 0.6 * m), (0.55 + 0.4 * e) * box(l, vec2f(cx - 5.0, top), vec2f(cx + 5.0, 120.0), 2.0, u) * step(0.004, e));
  put(col, acc, 0.35 * m * smoothstep(9.0, 0.0, sdBox(l, vec2f(cx - 7.0, 53.0), vec2f(cx + 7.0, 58.0), 2.5)));
  put(col, fl, m * box(l, vec2f(cx - 7.0, 53.0), vec2f(cx + 7.0, 58.0), 2.5, u));
  let pc = u32((i32(round(P[i])) % 12 + 12) % 12);
  let s = vec4u(pack4(NOTE[pc], select(0u, HASH, SHARP[pc] == 1u), 0u, 0u), 0u, 0u, 0u);
  put(col, ink, select(mix(0.35, 1.0, smoothstep(0.0, 0.25, A[i])), 0.35, A[i] < 0.0) * (0.3 + 0.65 * smoothstep(0.02, 0.3, e)) * tAt(p, org, u, fp, vec2f(cx, 128.0), s, 1u + SHARP[pc], 1.0));
 }

 // ---- pitch-class ring, circle-of-fifths order, C at the top, clockwise: the bell's note places
 let rc = vec2f(250.0, 100.0);
 let R = 36.0;
 put(col, ink, 0.45 * tAt(p, org, u, fp, vec2f(rc.x, 38.0), vec4u(471405069u, 14u, 0u, 0u), 5u, 1.0));
 let kr = (i32(round(atan2(params.rS, params.rC) / 0.5235988)) % 12 + 12) % 12;
 let rootPc = u32((kr * 7) % 12);
 let sounding = smoothstep(0.03, 0.25, max(max(max(E[0], E[1]), max(E[2], E[3])), E[4]));
 let cm = mark(params.chordAge);
 let dl = l - rc;
 if (length(dl) < R + 16.0) {
  var NP = array<f32, 12>(params.n0, params.n1, params.n2, params.n3, params.n4, params.n5, params.n6, params.n7, params.n8, params.n9, params.n10, params.n11);
  let ang = atan2(dl.x, -dl.y);
  let k = (i32(round(ang / 0.5235988)) % 12 + 12) % 12;
  let a = f32(k) * 0.5235988;
  let dc = rc + R * vec2f(sin(a), -cos(a));
  let s = clamp(NP[k], 0.0, 1.0);
  put(col, ink, 0.18 * disc(l, dc, 3.6, u));
  put(col, acc, smoothstep(0.0, 0.5, s) * disc(l, dc, 3.0 + 2.0 * s, u));
  // the root: a short radial tick outside the ring, at the angle the bell eases toward it
  let ra = atan2(params.rS2, params.rC2);
  let rd = vec2f(sin(ra), -cos(ra));
  let rq = dl - rd * clamp(dot(dl, rd), R + 6.0, R + 11.0);
  put(col, mix(ink, fl, 0.5 + 0.5 * cm), 0.95 * cov((length(rq) - 1.3) * u));
  put(col, fl, 0.4 * cm * hoop(l, rc, R + 13.0, 1.2, u));
 }
 // the chord in the middle: root name, quality under it, fading in after each chord strike
 let rs = vec4u(pack4(NOTE[rootPc], select(0u, HASH, SHARP[rootPc] == 1u), 0u, 0u), 0u, 0u, 0u);
 let fade = smoothstep(0.0, 0.2, params.chordAge);
 put(col, ink, fade * (0.35 + 0.6 * sounding) * tAt(p, org, u, fp, vec2f(rc.x, 84.0), rs, 1u + SHARP[rootPc], 1.0));
 if (params.qMin > 0.5) { put(col, ink, fade * (0.25 + 0.4 * sounding) * tAt(p, org, u, fp, vec2f(rc.x, 102.0), vec4u(1577751u, 0u, 0u, 0u), 3u, 1.0)); }
 else if (params.qMaj > 0.5) { put(col, ink, fade * (0.25 + 0.4 * sounding) * tAt(p, org, u, fp, vec2f(rc.x, 102.0), vec4u(1313559u, 0u, 0u, 0u), 3u, 1.0)); }

 // ---- drums, pedal, level, confidence (a source that has no such reading shows --)
 let x0 = 316.0;
 let bx = 384.0; let bx1 = PW - 14.0;
 let drumsKnown = params.drums >= 0.0;
 put(col, ink, select(0.45, 0.3 + 0.5 * clamp(params.drums, 0.0, 1.0), drumsKnown) * tAt(p, org, u, fp, vec2f(x0, 38.0), vec4u(387914766u, 29u, 0u, 0u), 5u, 0.0));
 var D = array<f32, 3>(params.kick, params.snare, params.hat);
 var DL = array<u32, 3>(21u, 29u, 18u);
 for (var j = 0; j < 3; j++) {
  // the letter, then its pulse as a filled dot (a ring after a letter read as the letter O)
  let c = vec2f(x0 + 20.0 + 42.0 * f32(j), 63.0);
  let v = clamp(D[j], 0.0, 1.0);
  put(col, ink, (0.45 + 0.45 * v) * tAt(p, org, u, fp, vec2f(x0 + 42.0 * f32(j), 56.0), vec4u(DL[j], 0u, 0u, 0u), 1u, 0.0));
  put(col, ink, 0.16 * disc(l, c, 5.5, u));
  put(col, acc, v * disc(l, c, 5.5, u));
 }
 let dash = vec4u(pack4(DASH, DASH, 0u, 0u), 0u, 0u, 0u);
 let hasPedal = params.pedal >= 0.0;
 put(col, ink, select(0.25, 0.6, hasPedal) * tAt(p, org, u, fp, vec2f(x0, 82.0), vec4u(185470746u, 22u, 0u, 0u), 5u, 0.0));
 if (hasPedal) { hbar(l, u, bx, bx1, 89.0, params.pedal, acc, col); }
 else { put(col, ink, 0.25 * tAt(p, org, u, fp, vec2f(bx, 82.0), dash, 2u, 0.0)); }
 // level: the analyser's input where the source is audio, else the five voices together
 let voices = clamp((0.8 * E[0] + 0.55 * (E[1] + E[2] + E[3]) + 1.2 * E[4]) / 2.2, 0.0, 1.0);
 let lv = select(voices, params.input, params.input >= 0.0);
 put(col, ink, 0.6 * tAt(p, org, u, fp, vec2f(x0, 102.0), vec4u(253759254u, 22u, 0u, 0u), 5u, 0.0));
 hbar(l, u, bx, bx1, 109.0, lv, acc, col);
 if (params.gate >= 0.0) {
  put(col, ink, 0.25 * hoop(l, vec2f(x0 - 8.0, 109.0), 2.8, 1.0, u));
  put(col, acc, clamp(params.gate, 0.0, 1.0) * disc(l, vec2f(x0 - 8.0, 109.0), 2.8, u));
 }
 // confidence of the pitch reading, where the source has to guess it
 let hasConf = params.conf >= 0.0;
 put(col, ink, select(0.25, 0.6, hasConf) * tAt(p, org, u, fp, vec2f(x0, 122.0), vec4u(270014733u, 0u, 0u, 0u), 4u, 0.0));
 if (hasConf) { hbar(l, u, bx, bx1, 129.0, params.conf, acc, col); }
 else { put(col, ink, 0.25 * tAt(p, org, u, fp, vec2f(bx, 122.0), dash, 2u, 0.0)); }
}

fn driving(p: vec2f, org: vec2f, u: f32, fp: f32, col: ptr<function, vec3f>) {
 let l = (p - org) / u;
 back(l, u, col);
 let ink = lin(INKC); let acc = lin(DRIVEC); let man = lin(MANC); let fl = lin(FLASHC);
 put(col, acc, 0.95 * tAt(p, org, u, fp, vec2f(14.0, 12.0), vec4u(538123278u, 1120275u, 0u, 0u), 7u, 0.0));
 let manual = params.autoOn < 0.5;
 if (manual) { put(col, man, 0.95 * tAt(p, org, u, fp, vec2f(PW - 14.0, 12.0), vec4u(521669399u, 5643u, 0u, 0u), 6u, 2.0)); }
 else { put(col, ink, 0.75 * tAt(p, org, u, fp, vec2f(PW - 14.0, 12.0), vec4u(320675607u, 13u, 0u, 0u), 5u, 2.0)); }

 // ---- section: calm | medium | peak, the needle at energy
 let sx0 = 14.0; let sx1 = 236.0; let sw = (sx1 - sx0) / 3.0;
 let ev = clamp(params.energy, 0.0, 1.0);
 var SL = array<vec4u, 3>(vec4u(387320589u, 0u, 0u, 0u), vec4u(921367u, 0u, 0u, 0u), vec4u(353046298u, 0u, 0u, 0u));
 var SN = array<u32, 3>(4u, 3u, 4u);
 for (var j = 0; j < 3; j++) {
  let on = smoothstep(-0.03, 0.03, ev - f32(j) / 3.0) * (1.0 - smoothstep(-0.03, 0.03, ev - f32(j + 1) / 3.0));
  let a = sx0 + sw * f32(j) + 2.0; let b2 = sx0 + sw * f32(j + 1) - 2.0;
  put(col, mix(ink, acc, on), (0.16 + 0.5 * on) * box(l, vec2f(a, 58.0), vec2f(b2, 62.0), 2.0, u));
  put(col, mix(ink, acc, on), (0.4 + 0.5 * on) * tAt(p, org, u, fp, vec2f(0.5 * (a + b2), 38.0), SL[j], SN[j], 1.0));
 }
 let nx = sx0 + (sx1 - sx0) * ev;
 put(col, select(fl, man, manual), 0.95 * box(l, vec2f(nx - 1.2, 52.0), vec2f(nx + 1.2, 68.0), 1.0, u));
 // ---- levels
 let bx0 = 106.0;
 put(col, select(ink, man, abs(params.energyTrim) > 0.005), 0.6 * tAt(p, org, u, fp, vec2f(sx0, 76.0), vec4u(470751247u, 8977u, 0u, 0u), 6u, 0.0));
 hbar(l, u, bx0, sx1, 83.0, ev, acc, col);
 put(col, select(ink, man, abs(params.lumTrim) > 0.005), 0.6 * tAt(p, org, u, fp, vec2f(sx0, 96.0), vec4u(303108886u, 30u, 0u, 0u), 5u, 0.0));
 hbar(l, u, bx0, sx1, 103.0, (params.lum - 0.2) / 0.8, acc, col);
 put(col, select(ink, man, abs(params.densityTrim) > 0.005), 0.6 * tAt(p, org, u, fp, vec2f(sx0, 116.0), vec4u(488115982u, 2301459u, 0u, 0u), 7u, 0.0));
 hbar(l, u, bx0, sx1, 123.0, params.density, acc, col);
 put(col, ink, 0.6 * tAt(p, org, u, fp, vec2f(sx0, 136.0), vec4u(488115998u, 1579283u, 0u, 0u), 7u, 0.0));
 hbar(l, u, bx0, sx1, 143.0, params.tension, acc, col);

 // ---- mood on the palette walk
 let mx0 = 258.0; let mx1 = PW - 14.0;
 put(col, select(ink, man, abs(params.palette) > 0.005), 0.45 * tAt(p, org, u, fp, vec2f(mx0, 38.0), vec4u(236525847u, 0u, 0u, 0u), 4u, 0.0));
 if (l.y > 50.0 && l.y < 72.0 && l.x > mx0 - 6.0 && l.x < mx1 + 6.0) {
  let t = clamp((l.x - mx0) / (mx1 - mx0), 0.0, 1.0);
  let mc = moodColor(4.0 * t, 0.55);
  let g = dot(mc, vec3f(0.3, 0.5, 0.2));
  put(col, lin(mix(vec3f(g), mc, 0.55) * 0.85), 0.8 * box(l, vec2f(mx0, 58.0), vec2f(mx1, 64.0), 2.0, u));
  let m = params.mood - 4.0 * floor(params.mood / 4.0);
  let jx = mx0 + (mx1 - mx0) * (params.journey - 4.0 * floor(params.journey / 4.0)) / 4.0;
  let mxp = mx0 + (mx1 - mx0) * m / 4.0;
  put(col, ink, 0.85 * hoop(l, vec2f(jx, 61.0), 3.6, 1.3, u));
  put(col, fl, 0.95 * box(l, vec2f(mxp - 1.2, 53.0), vec2f(mxp + 1.2, 69.0), 1.0, u));
 }
 // ---- swim, melody, react, accent: rows beside energy .. tension
 let rx0 = 258.0; let rb0 = 338.0; let rb1 = PW - 14.0;
 put(col, ink, 0.6 * tAt(p, org, u, fp, vec2f(rx0, 76.0), vec4u(387129629u, 0u, 0u, 0u), 4u, 0.0));
 // the swim cycle: the dot runs the track once per cycle, the track fills with the bell's stroke
 hbar(l, u, rb0, rb1, 83.0, params.pulse, acc, col);
 // (it fades out at the right end and back in at the left, so the wrap to a new cycle is not a jump)
 let ph = fract(params.pulsePhase);
 put(col, fl, 0.95 * smoothstep(0.0, 0.08, ph) * (1.0 - smoothstep(0.92, 1.0, ph)) * disc(l, vec2f(rb0 + (rb1 - rb0) * ph, 83.0), 3.4, u));
 // melody force: right of the centre tick is a rising line, left a falling one
 put(col, ink, 0.6 * tAt(p, org, u, fp, vec2f(rx0, 96.0), vec4u(420876055u, 8974u, 0u, 0u), 6u, 0.0));
 let mc = 0.5 * (rb0 + rb1);
 let mv = clamp(params.melody, -1.0, 1.0);
 put(col, ink, 0.16 * box(l, vec2f(rb0, 100.5), vec2f(rb1, 105.5), 2.5, u));
 put(col, acc, 0.9 * box(l, vec2f(min(mc, mc + (rb1 - mc) * mv), 100.5), vec2f(max(mc, mc + (rb1 - mc) * mv), 105.5), 2.0, u) * step(0.01, abs(mv)));
 put(col, ink, 0.55 * box(l, vec2f(mc - 0.7, 97.0), vec2f(mc + 0.7, 109.0), 0.5, u));
 // reaction strength 0..2, the tick at 1 (as built)
 put(col, ink, 0.6 * tAt(p, org, u, fp, vec2f(rx0, 116.0), vec4u(218828572u, 30u, 0u, 0u), 5u, 0.0));
 hbar(l, u, rb0, rb1, 123.0, params.react / 2.0, acc, col);
 put(col, ink, 0.55 * box(l, vec2f(mc - 0.7, 117.0), vec2f(mc + 0.7, 129.0), 0.5, u));
 // the chord-strike accent the rig sends into light and waves (rig hit)
 put(col, ink, 0.6 * tAt(p, org, u, fp, vec2f(rx0, 136.0), vec4u(252513547u, 7704u, 0u, 0u), 6u, 0.0));
 hbar(l, u, rb0, rb1, 143.0, params.hit, mix(acc, fl, 0.5 * clamp(params.hit, 0.0, 1.0)), col);
}

@fragment fn fs(@builtin(position) pos: vec4f, @location(0) uv: vec2f) -> @location(0) vec4f {
 // this pass's own pixels (the shared frame's resolution need not be this target's size)
 let res = floor(pos.xy / uv + 0.5);
 let p = pos.xy;
 let ins = vec2f(textureDimensions(inputTexture));
 var base: vec4f;
 if (all(ins == res)) { base = textureLoad(inputTexture, vec2i(p), 0); }
 else { base = textureSampleLevel(inputTexture, inputSampler, uv, 0.0); }
 let u = res.y / 1080.0;
 let fp = max(1.0, round(2.0 * u));
 let size = vec2f(PW, PH) * u;
 let oL = vec2f(round(MX * u), round(res.y - (MY + PH) * u));
 let oR = vec2f(round(res.x - (MX + PW) * u), oL.y);
 let pad = 14.0 * u;
 let inL = all(p > oL - pad) && all(p < oL + size + pad);
 let inR = all(p > oR - pad) && all(p < oR + size + pad);
 if (!inL && !inR) { return base; }
 var col = base.rgb;
 if (inL) { heard(p, oL, u, fp, &col); }
 if (inR) { driving(p, oR, u, fp, &col); }
 return vec4f(col, base.a);
}

