parameters.source:
// @use hash
struct Params {
 lum: f32, // @default 0.5 Illumination (rig lum): calm keeps rim, faint sheen and a small core.
 mood: f32, // @default 0 Palette position (rig mood).
 tension: f32, // @default 0.3 Thin-film phase shift and canal heat (rig tension).
 pulse: f32, // @default 0 Kept for the merge; unused since pass 6 (its peak has a curvature break, the light kinked there).
 pulsePhase: f32, // @default 0 Swim phase (rig pulsePhase): the canals and core flare with the same C2 stroke the geometry makes.
 hitAge: f32, // @default 9 Kept for the merge; unused since pass 4 (it resets at each strike).
 kick0: f32, // @default 0 Strike force at the bell (lag_herokick2.imp): the core blooms, light leaves along the canals.
 kick1: f32, // @default 0 The same later (lag_herokick4.imp): the light half way out.
 kick2: f32, // @default 0 Later still (lag_herokick5.imp): the light at the margin.
 kickS: f32, // @default 0 Slow mean of the strikes (lag_herokick7.imp): only what is new makes light travel.
 env4: f32, // @default 0 Melody envelope (lag_env.env4): the inner light swells with the top line.
 nt0: f32, // @default 0 Note place 0 (pitch class 0, fifths order) (lag_heronote2.s0): lights its canals, margin and lappets.
 nt1: f32, // @default 0 Note place 1 (pitch class 7, fifths order) (lag_heronote2.s1): lights its canals, margin and lappets.
 nt2: f32, // @default 0 Note place 2 (pitch class 2, fifths order) (lag_heronote2.s2): lights its canals, margin and lappets.
 nt3: f32, // @default 0 Note place 3 (pitch class 9, fifths order) (lag_heronote2.s3): lights its canals, margin and lappets.
 nt4: f32, // @default 0 Note place 4 (pitch class 4, fifths order) (lag_heronote2.s4): lights its canals, margin and lappets.
 nt5: f32, // @default 0 Note place 5 (pitch class 11, fifths order) (lag_heronote2.s5): lights its canals, margin and lappets.
 nt6: f32, // @default 0 Note place 6 (pitch class 6, fifths order) (lag_heronote2.s6): lights its canals, margin and lappets.
 nt7: f32, // @default 0 Note place 7 (pitch class 1, fifths order) (lag_heronote2.s7): lights its canals, margin and lappets.
 nt8: f32, // @default 0 Note place 8 (pitch class 8, fifths order) (lag_heronote2.s8): lights its canals, margin and lappets.
 nt9: f32, // @default 0 Note place 9 (pitch class 3, fifths order) (lag_heronote2.s9): lights its canals, margin and lappets.
 nt10: f32, // @default 0 Note place 10 (pitch class 10, fifths order) (lag_heronote2.s10): lights its canals, margin and lappets.
 nt11: f32, // @default 0 Note place 11 (pitch class 5, fifths order) (lag_heronote2.s11): lights its canals, margin and lappets.
 nh0: f32, // @default 0 Its consonant share (lag_heronote2.h0): root, fifth and thirds glow warm and climb, the rest glint cool at the margin.
 nh1: f32, // @default 0 Its consonant share (lag_heronote2.h1): root, fifth and thirds glow warm and climb, the rest glint cool at the margin.
 nh2: f32, // @default 0 Its consonant share (lag_heronote2.h2): root, fifth and thirds glow warm and climb, the rest glint cool at the margin.
