const TAU = 6.2831853;
const VM = 0.9;    // exumbrella lappet roots (ring canal)
const VS = 0.74;   // subumbrella margin

fn vnoise(p: vec2f, px: i32, seed: u32) -> f32 {
 let i = floor(p);
 let f = p - i;
 let w = f * f * (3.0 - 2.0 * f);
 let ix = i32(i.x);
 let iy = i32(i.y);
 let x0 = ((ix % px) + px) % px;
 let x1 = (((ix + 1) % px) + px) % px;
 let a = unitFloat(hash2i(vec2i(x0, iy), seed));
 let b = unitFloat(hash2i(vec2i(x1, iy), seed));
 let c = unitFloat(hash2i(vec2i(x0, iy + 1), seed));
 let d = unitFloat(hash2i(vec2i(x1, iy + 1), seed));
 return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}
fn gauss(x: f32) -> f32 { return exp(-x * x); }
// strike ripple (as in the hero kernels' common.wgsl): what is new in the strikes, core to margin
fn smoother(a: f32, b: f32, x: f32) -> f32 { let t = clamp((x - a) / (b - a), 0.0, 1.0); return t * t * t * (t * (t * 6.0 - 15.0) + 10.0); }
fn kickRipple(k: vec3f, kS: f32) -> vec3f { let x = (k - vec3f(kS)) * vec3f(2.0, 4.0, 5.5); return x / sqrt(vec3f(1.0) + x * x); }
fn rippleAt(r: vec3f, s: f32) -> f32 { return mix(mix(r.x, r.y, smoother(0.0, 0.5, s)), r.z, smoother(0.5, 1.0, s)); }
fn softPos(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.0004)); }
// full-strength hue of a colour (its brightest channel at 1)
fn satn(c: vec3f) -> vec3f { return c / max(max(c.r, c.g), max(c.b, 0.05)); }
// push colour away from grey: additive layers of different hues otherwise sum toward lavender-white
fn vivid(c: vec3f, k: f32) -> vec3f { let y = dot(c, vec3f(0.2126, 0.7152, 0.0722)); return max(mix(vec3f(y), c, k), vec3f(0.0)); }
// Thin film tied to the palette: the angle sweeps the mood's own shadow > body > highlight hues, with
// a quarter of the next mood for accents (deep blue > amethyst > peach with aqua and gold glints).
fn filmPal(m: f32, ph: f32) -> vec3f {
 let c = cos(TAU * ph);
 return satn(mix(moodColor(m, 0.5 + 0.5 * c), moodColor(m + 1.0, 0.6 + 0.4 * cos(TAU * ph + 2.1)), 0.28));
}
// 1 on a line of half-width w (in the units of d), antialiased over aa.
fn aaLine(d: f32, w: f32, aa: f32) -> f32 { return 1.0 - smoothstep(w, w + aa, d); }
// distance to the nearest of n radial lines at coordinate x = u * n, in cells
fn radial(x: f32) -> f32 { return abs(fract(x + 0.5) - 0.5); }

// the four hues weighted by the root direction; while a far root change passes the lagged direction
// through the centre (weights small) the colour eases to their mean instead of flipping (pass 7)
fn chordHueM(w: vec4f, a: vec3f, b: vec3f, c: vec3f, d: vec3f) -> vec3f {
 let sw = w.x + w.y + w.z + w.w;
 return (w.x * a + w.y * b + w.z * c + w.w * d + max(0.6 - sw, 0.0) * 0.25 * (a + b + c + d)) / max(sw, 0.6);
}
fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
 var o = surfaceDefaults(s);
 o.albedo = vec4f(0.0, 0.0, 0.0, 1.0);
 let uv = s.uv;
 let du = max(fwidth(uv.x), 1e-5);
 let dv = max(fwidth(uv.y), 1e-5);
 let sheet = i32(round(s.tint.x));
 // grid normals point OUT of the bell; Nf faces the viewer on either wall
 let N = normalize(s.normal);
 let V = normalize(s.eye - s.world);
 let ndv = dot(N, V);
 let front = ndv > 0.0;            // the outside of a wall is turned to us
 let Nf = select(-N, N, front);
 let nv = abs(ndv);
 let fres = 1.0 - nv;
 let L = p.lum;
 // the stroke as the bell kernel makes it (common.wgsl pulseEnv, C2 at both ends and at the peak): the
 // rig's pulse has a curvature break at its peak (phase 0.28), which showed as the light steps at Clair
 // 70.6 s and 88.1 s (both at phase 0.28)
 let px = fract(p.pulsePhase);
 let pz = smoother(0.0, 0.3, px) * (1.0 - smoother(0.3, 0.7, px));
 // ---- pass 6: the music as characters ----
 // radial place on the body: 0 the heart, 1 the margin
 let rv = select(select(select(0.0, 0.35, sheet == 2), min(uv.y / VS, 1.0), sheet == 1), min(uv.y / VM, 1.0), sheet == 0);
 // a chord change is a colour wave: the root on the circle of fifths leans the palette, reaching the
 // heart first and the margin a second or so later; its quality sets the tone (major lighter, minor deeper)
 let rl = mix(vec2f(p.rC2, p.rS2), vec2f(p.rC3, p.rS3), smoothstep(0.15, 1.0, rv));
 let md = p.mood + chordLean(rl, (p.chordGain * p.react));
 let tq = (p.chordGain * p.react) * (0.05 * p.qMaj - 0.05 * p.qMin);
 // a note's place round the bell (fifths order) and how consonant it is with the root
 let phiB = uv.x * TAU;
 let nRaw = secSum(vec4f(p.nt0, p.nt1, p.nt2, p.nt3), vec4f(p.nt4, p.nt5, p.nt6, p.nt7), vec4f(p.nt8, p.nt9, p.nt10, p.nt11), phiB);
 let hRaw = secSum(vec4f(p.nh0, p.nh1, p.nh2, p.nh3), vec4f(p.nh4, p.nh5, p.nh6, p.nh7), vec4f(p.nh8, p.nh9, p.nh10, p.nh11), phiB);
 let uRaw = secSum(vec4f(p.nu0, p.nu1, p.nu2, p.nu3), vec4f(p.nu4, p.nu5, p.nu6, p.nu7), vec4f(p.nu8, p.nu9, p.nu10, p.nu11), phiB);
 let nS = (p.noteGain * p.react) * noteSoft(nRaw);
 // what is new: a fresh note flares over its held level (now above a little later)
 let nOn = (p.noteGain * p.react) * noteSoft(2.0 * softPos(nRaw - uRaw));
 let nP = 0.6 * nS + nOn;
 let cons = clamp(hRaw / max(nRaw, 1e-3), 0.0, 1.0);
 let nCons = nP * cons;
 let nDis = nP * (1.0 - cons);
 let ud = melodyUD(p.melF, p.melS, (p.melodyGain * p.react));
 let rr = tensionRR(p.teF, p.teS, (p.tensionGain * p.react));
 // the warm accent is the same peach-gold in every mood (core, canals, glints); the body takes the mood.
 // Rising tension cools it a little, a release lets it settle warm.
 let ACC = vec3f(1.0, 0.66, 0.36);
 let warm = mix(ACC, moodColor(md, 0.92), clamp(0.2 + 0.2 * rr.x - 0.15 * rr.y, 0.0, 1.0));
 // a dissonant note's glint: the highlight of the palette two moods away (cool against the accent)
 let cool = satn(moodColor(md + 2.0, 0.9));
 // the chord change's own colour: a hue a mood and a half away, set by the new root, carried by the
 // strike ripple from the heart out to the margin (and down the appendages)
 // the chord's own colour: the root's place on the circle of fifths picks among four hues of the next two
 // palettes, all cool against the warm body and lines (for the deep-blue mood: aqua, cyan, teal, blue), so
 // neighbouring chords differ and the same root always returns in the same colour
 let cw4 = max(vec4f(rl.x, rl.y, -rl.x, -rl.y), vec4f(0.0));
 let waveCol = chordHueM(cw4, satn(moodColor(md + 1.0, 0.5)), satn(moodColor(md + 2.0, 0.95)), satn(moodColor(md + 1.0, 0.25)), satn(moodColor(md + 2.0, 0.6)));
 let cwv = chordWave(p.kick0, p.kick1, p.kick2, p.kickS, (p.chordGain * p.react));
 let wv = rippleAt(cwv, rv);
 let gold = mix(ACC, ACC * ACC, 0.5);    // saturated incandescence that survives the tone map
 let ember = gold * gold;                // deeper still: the glow of the core inside the shell
 let body = moodColor(md, 0.32 + tq);
 let lilac = moodColor(md, 0.5 + tq);
 let deep = moodColor(md, 0.1 + 0.5 * tq);
 let jewel = satn(mix(body, lilac, 0.25));  // the glass colour itself, full strength
 let t = s.absTime;
 // chord strike: light leaves the core and runs out along the canals to the margin (the force ripple)
 let rip = kickRipple(vec3f(p.kick0, p.kick1, p.kick2), p.kickS);
 let strike = softPos(rip.x);
 let melody = p.env4;
 // Contrast rule (the boards): body panels barely brighten with the music (peak at most about 1.3x
 // calm); the LINES (canals, ring canal, lappet edges, gonads) carry the growth (about 2.5x).
 var e = vec3f(0.0);

 if (sheet == 0) {
  // ---- exumbrella: a filled glassy dome ----
  let vd = min(uv.y / VM, 1.0);
  let mott = vnoise(vec2f(uv.x * 40.0, uv.y * 12.0), 40, 3u) * 0.6 + vnoise(vec2f(uv.x * 120.0, uv.y * 36.0), 120, 5u) * 0.4;
  let rimThin = pow(fres, 6.0);
  let rimSoft = pow(fres, 2.6);
  // thin film: optical path from a soft thickness map and the refracted angle; tension shifts it
  let thick = 0.5 + 0.3 * vnoise(vec2f(uv.x * 8.0, uv.y * 4.0 + t * 0.02), 8, 11u) + 0.4 * p.tension + 0.25 * uv.y;
  let cosT = sqrt(max(1.0 - (1.0 - nv * nv) / 1.77, 0.0));
  let fc = mix(filmPal(md, thick * 2.0 * cosT + 0.12 * rl.y), vec3f(1.0), 0.12);
  // a soft environment for the sheen: sky above, a bright horizon band, a window up-left
  let Rf = reflect(-V, Nf);
  let band = gauss((Rf.y - 0.25) / 0.22);
  // the window glint is a sharp lobe (power 30): on the small curling lappets it popped on and off as they
  // turned edge-on at the stroke's peak (the light break at Clair 80.2 s, 4.7x the median, bell alone), so
  // it stays on the dome and fades out across the ring canal; the soft horizon band still runs over them
  let win = pow(max(dot(Rf, normalize(vec3f(-0.55, 0.8, -0.1))), 0.0), 30.0) * (1.0 - smoothstep(0.86, 0.93, uv.y));
  let env = 0.06 + 0.3 * smoothstep(-0.2, 1.0, Rf.y) + 0.5 * band + 2.2 * win;
  // canals: 16 smooth meridians from the crown; toward peak they branch in the outer third (two
  // generations, gently curved, not zig-zag), plus the ring canal at the rim
  let mean = 0.03 * sin(uv.y * 9.0 + floor(uv.x * 16.0) * 1.7);
  let c1 = aaLine(radial(uv.x * 16.0 + mean), 0.007 + 0.007 * L, du * 16.0) * smoothstep(0.05, 0.22, vd);
  let grow = smoothstep(0.35, 0.9, L);
  let b1w = 0.22 * (vnoise(vec2f(uv.x * 32.0, vd * 3.0), 32, 41u) - 0.5);
  let br1 = aaLine(radial(uv.x * 32.0 + 0.5 + b1w), 0.012, du * 32.0) * smoothstep(0.66, 0.8, vd);
  let b2w = 0.3 * (vnoise(vec2f(uv.x * 64.0, vd * 5.0), 64, 43u) - 0.5);
  let br2 = aaLine(radial(uv.x * 64.0 + 0.5 + b2w), 0.02, du * 64.0) * smoothstep(0.82, 0.93, vd) * step(0.3, vnoise(vec2f(uv.x * 64.0, 2.0), 64, 47u));
  let ring = aaLine(abs(uv.y - VM), 0.004, dv);
  let canal = max(max(c1, ring), max(br1, br2 * 0.8) * grow);
  let heat = 0.2 + 0.6 * L + 0.9 * L * L;
  let hitBand = softPos(rippleAt(rip, vd));
  // lappets: 16 rounded lobes hanging from the ring canal (a rhopalium in every second notch)
  let lx = fract(uv.x * 16.0) * 2.0 - 1.0;
  let lobeH = (1.0 - VM) * 0.88 * (0.9 + 0.2 * vnoise(vec2f(uv.x * 16.0, 0.5), 16, 29u));
  let edgeV = VM + lobeH * pow(max(1.0 - lx * lx, 0.0), 0.45);
  let inLap = 1.0 - smoothstep(edgeV - dv * 0.7, edgeV + dv * 0.7, uv.y);
  let lapEdge = gauss((uv.y - edgeV) / (0.007 + 1.2 * dv)) * smoothstep(VM - 0.005, VM + 0.01, uv.y);
  // warm core light scattering through the crown
  let scatter = gauss(vd / 0.3) * (0.4 + 0.6 * nv);
  let wall = select(0.45, 1.0, front);
  // the filled body: a saturated glass volume, brightest at the shoulders, darker toward the rim
  let shoulder = smoothstep(0.08, 0.5, vd) * (1.0 - 0.7 * smoothstep(0.75, 1.0, vd));

  var d = vec3f(0.0);
  d += mix(deep, jewel, 0.75) * (0.02 + 0.55 * rimSoft) * (0.6 + 0.8 * mott) * (1.0 + 0.25 * L);
  d += jewel * shoulder * 0.085 * (0.55 + 0.45 * nv) * (0.7 + 0.6 * mott) * (1.0 + 0.2 * L);
  // a bright thin rim in the glass colour, film-tinted
  d += mix(jewel, fc, 0.25) * rimThin * (1.6 + 0.4 * L) * wall;
  // gloss: a window up-left and a horizon band, film-tinted; front walls only
  let streak = 0.15 + 0.85 * smoothstep(0.25, 0.85, vnoise(vec2f(uv.x * 96.0, uv.y * 2.0), 96, 31u));
  let gloss = (5.0 * win + 0.4 * band) * streak;
  d += mix(fc, vec3f(0.75, 0.88, 1.0), 0.4) * gloss * (0.3 + 0.1 * L) * select(0.0, 1.0, front);
  // light from above: the crown of the dome carries more of everything
  d *= (0.6 + 0.6 * smoothstep(-0.3, 0.9, Nf.y)) * (0.6 + 0.6 * smoothstep(-0.5, 0.9, dot(Nf, normalize(vec3f(-0.5, 0.8, 0.3)))));
  // iridescent membrane: film colour where the wall turns away, a little everywhere (no milky lift)
  d += (mix(jewel, fc, 0.45) * 0.05 * (0.5 + 0.5 * env) + fc * 0.35 * rimSoft) * (0.7 + 0.6 * mott) * select(0.3, 1.0, front);
  // the lines carry the music
  // the chord change: its colour runs out along the canals and through the glass with the wave
  d += mix(mix(warm * 0.9, gold, L), waveCol, min(0.9 * wv, 0.8)) * canal * (heat + 2.4 * hitBand + 0.6 * wv) * (0.85 + 0.35 * pz) * (0.7 + 0.6 * mott) * select(0.35, 1.0, front);
  d += warm * hitBand * 0.1 * (1.0 - smoothstep(0.85, 1.0, vd));
  d += waveCol * wv * 0.25 * (0.55 + 0.45 * nv) * (0.7 + 0.6 * mott) * (1.0 - smoothstep(0.9, 1.0, vd)) * select(0.6, 1.0, front);
  // a note's place: a consonant tone lights its canals from the margin up toward the crown (the
  // higher the melody climbs, the further), warm; a dissonant one glints cool at the margin only;
  // the glass of the place glows faintly with it
  let reach = 0.45 - 0.25 * ud.x + 0.2 * ud.y;
  let profC = smoothstep(reach, 1.0, vd + 0.1);
  let profD = smoothstep(0.72, 1.0, vd);
  let nWall = select(0.85, 1.0, front);
  d += (mix(gold, vec3f(1.0), 0.25) * 2.0 * nCons * profC + cool * 1.6 * nDis * profD) * canal * (0.5 + 0.7 * L) * (0.7 + 0.6 * mott) * nWall;
  d += (mix(jewel, warm, 0.6) * nCons * profC + mix(jewel, cool, 0.6) * nDis * profD) * 0.5 * (0.55 + 0.45 * nv) * (0.7 + 0.6 * mott) * nWall;
  d += mix(warm, ember, L) * scatter * (0.03 + 0.1 * L) * (1.0 + 0.4 * pz * (1.0 + p.bass) + 0.4 * melody + 0.4 * ud.x + 0.5 * rr.y);
  // the margin band glows a little; a falling line pools light there
  d += mix(jewel, warm, 0.35) * smoothstep(0.72, 1.0, vd) * (0.05 + 0.03 * L + 0.08 * ud.y);
  e = d * select(1.0, inLap, uv.y > VM);
  e += mix(mix(warm, gold, 0.3 + 0.6 * L), waveCol, min(0.9 * cwv.z, 0.8)) * lapEdge * (0.25 + 0.5 * L + 0.6 * L * L + 0.8 * softPos(rip.z) + 0.35 * cwv.z) * (0.8 + 0.4 * mott) * select(0.5, 1.0, front);
  // the lappets of a sounding place: their edges carry the note's colour
  e += (warm * nCons + cool * nDis) * lapEdge * 1.6 * (0.8 + 0.4 * mott) * select(0.6, 1.0, front);
 } else if (sheet == 1) {
  // ---- subumbrella: the darker inner dome, pleated, arches at the margin; frill skirt below ----
  let rimSoft = pow(fres, 2.5);
  if (uv.y <= VS) {
   let w = uv.y / VS;
   let rib = aaLine(radial(uv.x * 16.0), 0.014, du * 16.0) * smoothstep(0.2, 0.45, w);
   let ax = fract(uv.x * 16.0) * 2.0 - 1.0;
   let archV = 1.0 - 0.18 * (1.0 - ax * ax);
   let arch = aaLine(abs(w - archV), 0.006, dv / VS * 1.2) * smoothstep(0.6, 0.85, w) * 0.5;
   let mott = vnoise(vec2f(uv.x * 64.0, uv.y * 24.0), 64, 13u);
   let scatter = gauss(w / 0.34) * (0.3 + 0.7 * nv * nv);
   e += mix(deep, jewel, 0.3) * (0.006 + 0.07 * rimSoft) * (0.6 + 0.8 * mott);
   e += mix(mix(mix(lilac, warm, 0.6), gold, L), waveCol, min(0.6 * rippleAt(cwv, w), 0.75)) * (rib * 0.5 + arch * 0.6) * (0.03 + 0.12 * L + 0.2 * pow(L, 2.0) + 1.0 * softPos(rippleAt(rip, w)) + 0.4 * rippleAt(cwv, w) + 0.4 * nP * smoothstep(0.4, 1.0, w));
   e += mix(warm, ember, L) * scatter * (0.04 + 0.12 * L) * (1.0 + 0.4 * pz * (1.0 + p.bass) + 0.8 * strike + 0.5 * melody + 0.5 * rr.y);
  } else {
   let sk = (uv.y - VS) / (1.0 - VS);
   let cut = 1.0 - 0.35 * vnoise(vec2f(uv.x * 96.0, 0.5), 96, 17u) - 0.15 * vnoise(vec2f(uv.x * 300.0, 0.5), 300, 19u);
   let ds = dv / (1.0 - VS);
   let inside = 1.0 - smoothstep(cut - ds, cut + ds, sk);
   let edge = gauss((sk - cut) / (0.04 + 1.5 * ds));
   let folds = 0.55 + 0.45 * sin(uv.x * TAU * 30.0 + 2.0 * sin(uv.x * TAU * 5.0));
   e += mix(deep, jewel, 0.5) * (0.03 + 0.12 * rimSoft) * folds * inside;
   e += mix(jewel, warm, 0.5) * edge * inside * (0.12 + 0.25 * L);
  }
 } else if (sheet == 2) {
  // ---- gonads: four frilled lace loops, lit through their thickness (no outline) ----
  let gran = vnoise(vec2f(uv.x * 400.0, uv.y * 10.0), 400, 23u);
  let fil = aaLine(radial(uv.x * 200.0 + 1.5 * sin(uv.y * TAU)), 0.12, du * 200.0);
  let thickness = pow(nv, 2.0);
  // a major chord brightens the lace threads, a minor one the grain
  let qa = (p.chordGain * p.react) * p.qMaj;
  let qi = (p.chordGain * p.react) * p.qMin;
  e += mix(warm, gold, L) * thickness * (0.04 + 0.12 * L + 0.3 * pow(L, 2.0)) * (0.2 + 0.4 * gran * (1.0 + 0.6 * qi) + 1.3 * fil * (1.0 + 0.4 * qa)) * (1.0 + 0.5 * pz + 1.0 * strike);
 } else {
  // ---- core glow: a soft warm volume at the manubrium, brightest where the eye looks through it ----
  let thickness = pow(nv, 3.0);
  e += mix(warm, gold, 0.3 + 0.7 * L) * thickness * (0.05 + 0.1 * L + 0.12 * pow(L, 2.0)) * (1.0 + 0.6 * pz * (1.0 + p.bass) + 1.2 * strike + 0.6 * melody + 0.5 * rr.y);
  // a small hot heart: the star seen through the bell even when calm
  e += mix(gold, vec3f(1.0), 0.12) * pow(nv, 22.0) * (0.5 + 0.3 * L) * (1.0 + 0.5 * pz + 0.8 * strike + 0.5 * melody);
 }
 o.emissive = vivid(e, 1.35);
 return o;
}
// ---- hero only: the music as characters (pass 6). Not part of the shared family. ----
// Twelve places round the bell, one per pitch class in circle-of-fifths order: sector k holds pitch class
// 7k mod 12, so a fifth is a neighbour and a triad is always the same small shape (root, its neighbour,
// and the third four places round). A note lights and moves its own place; a chord shows as the set of
// places its tones hold. The values per sector come from expression_herochord through lags (two 0.3 s
// stages with a four times slower release: S-shaped onset, seconds of decay; one more 0.8 s stage for
// the tips), so nothing here can step.
fn noteSecW(x: f32, k: f32) -> f32 {
 let d = abs(fract((x - k) / 12.0 + 0.5) - 0.5) * 12.0;   // distance in sectors, wrapped
 return 1.0 - smoother(0.3, 0.7, d);                       // a plateau per sector, soft 0.4-sector seams
}
fn secW4(x: f32, k0: f32) -> vec4f {
 return vec4f(noteSecW(x, k0), noteSecW(x, k0 + 1.0), noteSecW(x, k0 + 2.0), noteSecW(x, k0 + 3.0));
}
// the twelve sector values (a = sectors 0..3, b = 4..7, c = 8..11) as felt at bell azimuth phi
fn secSum(a: vec4f, b: vec4f, c: vec4f, phi: f32) -> f32 {
 let x = fract(phi / TAU) * 12.0;
 return dot(a, secW4(x, 0.0)) + dot(b, secW4(x, 4.0)) + dot(c, secW4(x, 8.0));
}
// where in its sector an azimuth lies, -0.5 .. 0.5 (a sector's filaments fan apart from its centre)
fn secOffset(phi: f32) -> f32 { return fract(fract(phi / TAU) * 12.0 + 0.5) - 0.5; }
// soft limit: many notes on one place never add up to more than about one
fn noteSoft(x: f32) -> f32 { return x / sqrt(1.0 + x * x); }
// melodic motion: the top voice's pitch through a quick and a slow lag; their difference (semitones)
// is a damped force, up > 0. Returns (rising, falling), each 0..1, softly limited.
fn melodyUD(melF: f32, melS: f32, g: f32) -> vec2f {
 let m = g * (melF - melS) / 4.0;
 return vec2f(noteSoft(softPos(m)), noteSoft(softPos(-m)));
}
// tension against its own slow mean: (rising, releasing), each 0..1. A release is the exhale.
fn tensionRR(teF: f32, teS: f32, g: f32) -> vec2f {
 let d = g * 5.0 * (teF - teS);
 return vec2f(noteSoft(softPos(d)), noteSoft(softPos(-d)));
}
// the chord root on the circle of fifths leans the palette (a hue change of the whole animal); the lean
// reaches the heart first and the margin, then the tips, later (lag_herochord2, 3, 4)
fn chordLean(r: vec2f, g: f32) -> f32 { return g * (0.25 * r.x + 0.15 * r.y); }
// A chord change as a wave with duration: differences of successive stages of the strike response
// (lag_herokick2 - 4, 4 - 5, 5 - 7; every stage is at least second order, so every difference starts
// with zero slope), normalised so one strike peaks near 1 at the heart (about 0.6 s after it), half way
// out (1.3 s) and at the margin and down the appendages (2.4 s). A train of strikes overlaps into a
// gentle shimmer, never a sum. (A first-order stage here, lag_herokick6, dropped the margin's light the
// instant a strike began and then stopped dead at zero: a light step 0.1 s after every strike.)
fn softKnee(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.01)); }
fn chordWave(k0: f32, k1: f32, k2: f32, kS: f32, g: f32) -> vec3f {
 let w = vec3f(3.0 * (k0 - k1), 10.0 * (k1 - k2), 15.0 * (k2 - kS));
 return g * vec3f(noteSoft(softKnee(w.x)), noteSoft(softKnee(w.y)), noteSoft(softKnee(w.z)));
}
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}

parameters.kernel:
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
