 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}
// ---- hero common (kernels): frame, pulse envelope, bell profile, trail ----
const TAU = 6.2831853;
// The bell in its own frame: rim radius 1, up +y, rim (margin) plane at BELL_Y0, apex BELL_H above it.
// World = hero position + rotZ(tiltZ) * rotX(tiltX) * (local * heroScale).
// A flattened dome (the boards: height/width about 0.38 for the dome, 0.45 with the lappets): the profile
// stops at 79 degrees, so the shoulders slope into the rim and never stand as a vertical wall; 16
// rounded lappets hang LAP_LEN below the rim.
const BELL_H = 0.64;
const BELL_Y0 = -0.35;
const BELL_THMAX = 1.38;
const BELL_VM = 0.9;       // exumbrella: v of the rim (ring canal); the lappets hang over VM..1
const LAP_LEN = 0.14;

struct HF { o: vec3f, ca: f32, sa: f32, cb: f32, sb: f32, k: f32, };
fn hfMake(x: f32, y: f32, z: f32, tx: f32, tz: f32, k: f32) -> HF {
 return HF(vec3f(x, y, z), cos(tx), sin(tx), cos(tz), sin(tz), k);
}
fn hfDir(f: HF, d: vec3f) -> vec3f {
 let y1 = d.y * f.ca - d.z * f.sa;
 let z1 = d.y * f.sa + d.z * f.ca;
 return vec3f(d.x * f.cb - y1 * f.sb, d.x * f.sb + y1 * f.cb, z1);
}
fn hfPos(f: HF, p: vec3f) -> vec3f { return f.o + hfDir(f, p * f.k); }

// The stroke, as a periodic function of the swim phase (the cycle is about 3.5 s): a slow full
// contraction over 30 % of it, a release over 40 %, then a 30 % glide at rest. Every geometric use of
// the swim reads this (the bell body too), so the bell and everything lagging it agree.
// the warm accent: one peach-gold for cores, canals, glints and beads in every mood
const ACC = vec3f(1.0, 0.66, 0.36);
fn smoother(a: f32, b: f32, x: f32) -> f32 {
 let t = clamp((x - a) / (b - a), 0.0, 1.0);
 return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}
fn pulseEnv(ph: f32) -> f32 {
 let x = fract(ph);
 return smoother(0.0, 0.3, x) * (1.0 - smoother(0.3, 0.7, x));
}
// A chord strike as a FORCE: the rig's strike age drives a short impulse through a chain of hero
// lag nodes; k.x (lag_herokick2) is the response at the bell, k.y (4) later and wider, k.z (5) later
// still, kS (7) a very slow mean of the same impulse. The RIPPLE is what is new: each response minus
// the slow mean, normalised so one isolated strike peaks near 1, softly limited, so a train of strikes
// does not hold the appendages splayed: each new strike still adds a travelling ripple, and the
// sustained part becomes a small, saturating STEADY opening.
fn kickRipple(k: vec3f, kS: f32) -> vec3f {
 let g = vec3f(2.0, 4.0, 5.5);
 let x = (k - vec3f(kS)) * g;
 return x / sqrt(vec3f(1.0) + x * x);
}
fn kickSteady(kS: f32) -> f32 { return 0.35 * (1.0 - exp(-2.5 * kS)); }
// positive part, smoothly (light and flares only grow)
fn softPos(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.0004)); }
// the margin flares a little with the strike (bell and tentacle roots must agree)
fn marginFlare(lp: vec3f, v: f32, k0: f32) -> vec3f {
 let g = 1.0 + 0.035 * k0 * smoothstep(0.75, 1.0, v);
 return vec3f(lp.x * g, lp.y, lp.z * g);
}

// Soft swim pressure: a raised cosine at the swim frequency, peaking with the contraction (phase 0.28).
// Lagged copies of it run down arms and tentacles as a gentle pressure wave, never a wiggle.
fn gaussK(x: f32) -> f32 { return exp(-x * x); }
// the strike ripple as felt at s along anything (0 the bell, 1 the tips), continuous in time and space
fn rippleAt(r: vec3f, s: f32) -> f32 {
 return mix(mix(r.x, r.y, smoother(0.0, 0.5, s)), r.z, smoother(0.5, 1.0, s));
}
fn pres(ph: f32) -> f32 { return 0.5 + 0.5 * cos(TAU * (ph - 0.28)); }
// Contraction felt at bell parameter v (0 apex, 1 lappet tips): the body follows pulse, the margin
// lags 0.06 of a cycle, the lappets 0.1, so the rim trails the squeeze and re-opens late.
// D is the stroke depth (fuller with louder music, set slowly).
fn bellPulseAt(v: f32, pl: f32, ph: f32, D: f32) -> f32 {
 let pm = pulseEnv(ph - 0.06) * D;
 let plap = pulseEnv(ph - 0.1) * D;
 return mix(pl, mix(pm, plap, smoothstep(0.86, 1.0, v)), smoothstep(0.55, 1.0, v));
}
fn strokeDepth(es: f32) -> f32 { return 0.75 + 0.4 * es; }

fn bellSqueeze(v: f32, pm: f32) -> f32 {
 return 1.0 - 0.2 * pm * pow(smoothstep(0.12, 1.0, v), 1.3);
}
// Exumbrella point. p: body contraction, pm: (lagged) margin contraction, te: tension.
// the dome's height profile, 1 at the apex and 0 at the rim (slightly flattened top)
fn domeY(th: f32) -> f32 {
 let cm = pow(cos(BELL_THMAX), 0.88);
 return (pow(max(cos(th), 0.0), 0.88) - cm) / (1.0 - cm);
}
fn bellExo(phi: f32, v: f32, p: f32, pm: f32, te: f32) -> vec3f {
 let vd = min(v / BELL_VM, 1.0);
 let th = vd * BELL_THMAX;
 // a contraction closes the rim and lengthens the dome a little: it stays a dome (h/w under 0.6)
 let h = BELL_H * (1.0 + 0.12 * p + 0.06 * te);
 let rib = 1.0 + 0.022 * (0.5 + 0.5 * cos(16.0 * phi)) * smoothstep(0.08, 0.5, vd) * (1.0 - smoothstep(0.8, 0.95, vd));
 let wave = (0.025 * sin(8.0 * phi + 0.7) + 0.01 * sin(13.0 * phi + 2.0)) * smoothstep(0.6, 1.0, vd);
 var r = sin(th) / sin(BELL_THMAX) * bellSqueeze(vd, pm) * rib;
 var y = BELL_Y0 - 0.04 * pm * smoothstep(0.5, 1.0, vd) + h * domeY(th);
 if (v > BELL_VM) {
  // the lappets hang from the rim: flared a little outward at rest, curled in by the squeeze
  let s = (v - BELL_VM) / (1.0 - BELL_VM);
  r = r + s * LAP_LEN * (0.45 - 0.9 * pm) * bellSqueeze(1.0, pm);
  y = y - s * LAP_LEN * (0.9 + 0.2 * pm);
 }
 return vec3f(cos(phi) * r, y + wave, sin(phi) * r);
}

// Frame-independent per-id random in [0, 1). The built-in pointRand re-rolls EVERY FRAME (it hashes the
// frame index), so it must never shape geometry: that reads as high-frequency jitter in playback.
fn stableRand(id: u32, salt: u32) -> f32 {
 var x = id * 747796405u + salt * 2891336453u + 12345u;
 x = (x ^ (x >> 15u)) * 2246822519u;
 x = (x ^ (x >> 13u)) * 3266489917u;
 x = x ^ (x >> 16u);
 return f32(x >> 8u) * (1.0 / 16777216.0);
}
// ---- hero appendages in water (shared by tentacle beams, beads and oral arms) ----
// They HANG: almost passive, a slow curtain dragged behind the swim and swaying over many seconds.
// Point s = the root on the bell (rigidly attached, in the bell's own frame) + a hanging shape
// (gravity and a slow down-left current, leaning with the path) + a slow DRAG opposite the bell's
// mean velocity, growing toward the tip. The mean velocity is taken over one swim period (the bell
// now vs where it was one period, about 1.76 s, ago), so the surge of each thrust cancels out and
// is never replayed down the appendages; it is used as a vector that shrinks to nothing as the bell
// slows (never normalised), so the trail eases back to the rest hang. Each contraction sends one
// soft, slow bulge down them; chord strikes change only their light. Nothing may rise above its
// own root along the bell's axis (keepBelow).
const NT = 48u;            // tentacles
const DRAG_T = 4.0;        // tentacles: seconds of mean drift by which a tip trails
const ARM_DRAG_T = 5.5;    // oral arms: broad veils catch more water
struct TC { f: HF, fP: HF, h0: vec3f, vbar: vec3f, droop: vec3f, side: vec3f, side2: vec3f, pl: f32, ph: f32, te: f32, de: f32, t: f32, kick: vec3f, es: f32, steady: f32, act: f32, };

// the bell's path u steps of 0.7 s ago (u in 1..3), straight between the rig's samples (no overshoot)
fn pathBack(h1: vec3f, h2: vec3f, h3: vec3f, u: f32) -> vec3f {
 if (u < 2.0) { return mix(h1, h2, clamp(u - 1.0, 0.0, 1.0)); }
 return mix(h2, h3, clamp(u - 2.0, 0.0, 1.0));
}

fn tcMake(f: HF, h1: vec3f, h2: vec3f, h3: vec3f, rate: f32, tx: f32, tz: f32, pl: f32, ph: f32, te: f32, de: f32, t: f32, kick: vec3f, es: f32, kS: f32, rl: f32) -> TC {
 // mean velocity: the least-squares slope through the four samples (now, 0.7, 1.4, 2.1 s ago), far
 // less sensitive to the surge inside a stroke than a two-point difference
 let vbar = (1.5 * f.o + 0.5 * h1 - 0.5 * h2 - 1.5 * h3) / (5.0 * 0.7);
 // the bell's own axis with the per-stroke rocking taken out: the rig leans the bell by its 0.7 s
 // velocity; swap that for the period-mean velocity (same lean law), keep everything else it does
 // (with rigLean = 1 the rig's tilt already is that smooth lean, and everything hangs along it as is)
 let v07 = (f.o - h1) / 0.7;
 let swap = select(1.0, 0.0, rl > 0.5);
 let fP = hfMake(f.o.x, f.o.y, f.o.z, tx - 0.5 * (v07.z - vbar.z) * swap, tz + 1.6 * (v07.x - vbar.x) * swap, f.k);
 // appendages hang along that axis (no sideways current of their own)
 let droop = hfDir(fP, vec3f(0.0, -1.0, 0.0));
 let side = normalize(cross(droop, vec3f(0.0, 0.0, 1.0)));
 let side2 = normalize(cross(droop, side));
 // activity: slow musical energy plus how busy the strikes have been (both eased), 0 calm .. 1 full
 let steady = kickSteady(kS);
 let act = clamp(0.75 * es + 1.2 * steady, 0.0, 1.0);
 return TC(f, fP, f.o, vbar, droop, side, side2, pl, ph, te, de, t, kickRipple(kick, kS), es, steady, act);
}
// trail opposite the mean velocity, growing toward the tip, softly limited (no normalising)
fn dragAt(c: TC, s: f32, len: f32, secs: f32) -> vec3f {
 let d = -c.vbar * secs * pow(s, 1.5);
 let limit = 0.35 * len;
 return d / sqrt(1.0 + dot(d, d) / (limit * limit));
}
// never above the root along the bell's axis: a point at s hangs at least 10 % of its arclength below
fn keepBelow(c: TC, root: vec3f, p: vec3f, s: f32, len: f32) -> vec3f {
 let up = hfDir(c.f, vec3f(0.0, 1.0, 0.0));
 let along = dot(p - root, up);
 let floorA = -0.1 * s * len;
 let w = 0.08 * len * s + 1e-4;
 let hh = clamp(0.5 + 0.5 * (floorA - along) / w, 0.0, 1.0);
 let sm = mix(floorA, along, hh) - w * hh * (1.0 - hh);
 return p + up * (sm - along);
}
fn tentPhi(ti: u32) -> f32 {
 return (f32(ti) + 0.5 + 0.55 * (stableRand(ti, 11u) - 0.5)) / f32(NT) * TAU;
}
// active share of the tentacles: about 24 at density 0, all 48 at density 1 (unused ones fade)
fn tentActive(ti: u32, de: f32) -> f32 {
 let rank = stableRand(ti, 17u);
 return 1.0 - smoothstep(0.5 + 0.5 * de - 0.06, 0.5 + 0.5 * de + 0.02, rank);
}
fn tentLength(c: TC, ti: u32) -> f32 {
 return (1.2 + 3.0 * pow(stableRand(ti, 13u), 1.4)) * (0.85 + 0.3 * c.de) * (1.0 + 0.12 * c.te) * c.f.k;
}
// the bell's contraction as felt at s along an appendage: exact at the root, then the same envelope at
// a later phase, damped (a soft pressure wave). Returns (body pulse, margin pulse, phase used).
fn pulseAlong(c: TC, s: f32) -> vec3f {
 let lagc = 0.6 * s;
 let att = exp(-1.8 * s);
 let D = strokeDepth(c.es);
 let k0 = (c.kick.x + c.steady) * att;
 let ps = min(pulseEnv(c.ph - lagc) * D * (1.0 + 0.2 * k0), 1.0) * att;
 let pm = bellPulseAt(0.9, ps, c.ph - lagc, D) * att;
 return vec3f(ps, pm, c.ph - lagc);
}
// the slow sweep of the whole hanging bundle (shared by tentacles and arms), travelling tipward
fn sweepAt(c: TC, s: f32) -> vec3f {
 let a = TAU * (0.05 * c.t - 0.35 * s);
 return (c.side * sin(a) + c.side2 * 0.5 * sin(a * 0.7 + 1.9)) * (0.12 + 0.14 * c.act) * s * s;
}
// the strike as felt at s: the bell's response at the root, later and wider responses toward the tip
fn kickAt(c: TC, s: f32) -> f32 { return rippleAt(c.kick, s) + c.steady; }
fn tentRoot(c: TC, phi: f32, s: f32) -> vec3f {
 let pa = pulseAlong(c, s);
 let k0 = (c.kick.x + c.steady) * exp(-1.8 * s);
 return hfPos(c.f, marginFlare(bellExo(phi, 0.9, pa.x, pa.y, c.te), 0.9, k0) * vec3f(0.965, 1.0, 0.965));
}
fn tentPoint(c: TC, ti: u32, s: f32) -> vec3f {
 let phi = tentPhi(ti);
 let h1 = stableRand(ti, 12u);
 let h2 = stableRand(ti, 14u);
 // root on the margin, squeezing with it (the squeeze reaches further points later and weaker)
 let anchor = tentRoot(c, phi, s);
 let outL = vec3f(cos(phi), 0.0, sin(phi));
 // one soft slow bulge per contraction, travelling down
 let pp = pres(c.ph - 0.1 - 0.6 * s);
 // loud passages open the whole curtain, quiet ones draw it in (slow)
 let spread = (0.16 + 0.2 * h1) * (0.7 + 0.7 * c.act) - 0.04 * pp;
 let d0 = hfDir(c.fP, normalize(vec3f(outL.x * spread, -1.0, outL.z * spread)));
 let len = tentLength(c, ti);
 let bendL = vec3f(cos(phi + 1.6 * (h2 - 0.5)), 0.0, sin(phi + 1.6 * (h2 - 0.5)));
 let b1 = d0 * 0.22 * len + hfDir(c.fP, bendL) * (0.04 + 0.08 * h2) * len;
 let b2 = b1 + normalize(c.droop + hfDir(c.fP, outL) * (0.05 + 0.12 * h1)) * 0.78 * len;
 var pos = anchor + 2.0 * s * (1.0 - s) * b1 + s * s * b2;
 // slow drag behind the mean swim
 pos += dragAt(c, s, len, DRAG_T * (0.8 + 0.4 * h2) * (0.8 + 0.4 * c.es));
 // always alive: a long slow undulation (about one wave every 9 s), larger when the music is fuller,
 // under a slower sweep the whole curtain shares (one every 20 s), travelling down it
 // the music shapes it through amplitude and (a little) wavelength, never its rate: calm = long lazy
 // waves, busy = fuller and livelier
 let w = TAU * ((0.55 + 0.35 * c.act) * s - 0.11 * c.t) + phi * 3.0 + h1 * 6.0;
 let amp = (0.06 + 0.1 * c.act) * len * pow(s, 1.5);
 pos += (c.side * sin(w) + c.side2 * 0.6 * cos(0.8 * w + 1.3)) * amp;
 pos += sweepAt(c, s) * len;
 // the bulge: the bundle breathes out a hair as it passes
 pos += hfDir(c.fP, outL) * 0.012 * len * sin(3.14159 * s) * pp;
 // a strike: the filaments flare outward and stretch back along the trail, as a slow wave tipward
 pos += (hfDir(c.fP, outL) * 0.7 + c.droop * 0.5) * 0.11 * len * sin(3.14159 * min(s * 1.1, 1.0) * 0.5) * kickAt(c, s);
 return keepBelow(c, tentRoot(c, phi, 0.0), pos, s, len);
}
// ---- SILK (pass 6): five DISTINCT aerial ribbons on the appendage family's closed-form base. ----
// Shared by kernel_silk, kernel_silkthreads and kernel_silkbeads; build.sh prepends the hero's
// common.wgsl and tent.common.wgsl VERBATIM, so the silk hangs, drags and undulates on the same model
// and clock as the hero's tentacles and oral arms: root rigid in the bell's frame (hfPos), hang along
// the bell's period-mean axis (c.droop), slow drag behind the mean velocity (dragAt), the shared slow
// undulation and sweep (sweepAt), the bell's strike (kickAt), keepBelow.
// What makes five separate ribbons (pass 6):
//   - roots on a fixed pentagon of radius 0.6 under the bell, ordered across the picture;
//   - each ribbon has its own LANE: a heading in the picture plane (from straight down toward the trail
//     side) that it turns into over a fixed bend, plus a slow drift in depth; the lanes fan out, wider with
//     density;
//   - each ribbon carries its own big S-curve (wavelength 9 to 18 bell radii), with its own phase; chord
//     tones lock to the chord's phase, thirds sit half a wave off it so they cross the root's ribbon and
//     pass in front of / behind it (a braid), the others run free;
//   - curvature budget: S amplitude is a fixed fraction of its wavelength and the width is capped at half a
//     bell diameter, so no ribbon folds over its own edge (no cusps, no hood);
//   - the width faces the camera at the root and rolls at most a half turn per 7 bell radii.
// The READABLE music layer (unchanged in kind): one swell per strike rolls down that voice's ribbon
// (sideways, wider, brighter); slow activity sets the S size and wavelength; density the lit length,
// width and the fan. Every temporal frequency is a constant.

struct Params {
 lum: f32, // @default 0.5 Rig illumination 0.12..1 (light only).
 mood: f32, // @default 0 Rig palette position 0..4 (colour only).
 hit: f32, // @default 0 Rig chord-strike pulse, continuous (light only).
 pulsePhase: f32, // @default 0 Rig swim phase 0..1 (the stroke felt along the silk, as in the hero's appendages).
 swimRate: f32, // @default 0.567 Rig swim cycles per second.
 heroX: f32, // @default 1.1 Rig hero X.
 heroY: f32, // @default 1.45 Rig hero Y.
 heroZ: f32, // @default 0 Rig hero Z.
 tiltX: f32, // @default 0 Rig heroTiltX.
 tiltZ: f32, // @default -0.22 Rig heroTiltZ.
 scale: f32, // @default 1 Rig heroScale.
 heroX1: f32, // @default 1.1 Rig: hero X 0.7 s ago.
 heroY1: f32, // @default 1.45 Rig: hero Y 0.7 s ago.
 heroZ1: f32, // @default 0 Rig: hero Z 0.7 s ago.
 heroX2: f32, // @default 1.1 Rig: hero X 1.4 s ago.
 heroY2: f32, // @default 1.45 Rig: hero Y 1.4 s ago.
 heroZ2: f32, // @default 0 Rig: hero Z 1.4 s ago.
 heroX3: f32, // @default 1.1 Rig: hero X 2.1 s ago.
 heroY3: f32, // @default 1.45 Rig: hero Y 2.1 s ago.
 heroZ3: f32, // @default 0 Rig: hero Z 2.1 s ago.
 tension: f32, // @default 0.3 Slow tension (lag_heroslow2), as the hero's appendages.
 energyS: f32, // @default 0.5 Slow energy (lag_heroslow2): undulation size, as the hero's appendages.
 density: f32, // @default 0.5 Density through the silk's own 2nd-order lag (lag_silkid gD, ~4 s): presence, width, lit length.
 act: f32, // @default 0.2 Slow note activity: the mean voice envelope through lag_silkid (~4 s): undulation fullness.
 kick0: f32, // @default 0 The bell's strike force at the root (lag_herokick2 imp x 0.2), shared with every appendage.
 kick1: f32, // @default 0 Bell strike force mid-length (lag_herokick4 imp x 0.2).
 kick2: f32, // @default 0 Bell strike force at the tip (lag_herokick5 imp).
 kickS: f32, // @default 0 Steady strike activity (lag_herokick7 imp), as the hero's appendages.
 rigLean: f32, // @default 1 As the hero (hero pass 5): 1 = the rig's tilt already is the smooth travel lean; hang along it.
 rootC: f32, // @default 1 Chord root on the circle of fifths, cosine (lag_silkid).
 rootS: f32, // @default 0 Chord root, fifths sine (lag_silkid).
 rootCS: f32, // @default 1 Chord root, fifths cosine, slow (lag_silkidslow): the far half.
 rootSS: f32, // @default 0 Chord root, fifths sine, slow.
 id0c: f32, // @default 1 Voice 0 pitch class on the circle of fifths, cosine (lag_silkid).
 id0s: f32, // @default 0 Voice 0 fifths sine.
 anchor0: f32, // @default 1 Voice 0 role: rides the chord's character.
 mirror0: f32, // @default 0 Voice 0 role: mirrors it (fifth).
 braid0: f32, // @default 0 Voice 0 role: braids with it (third).
 fan0: f32, // @default 0 Voice 0 role: sideways lean.
 need0: f32, // @default 0.3 Voice 0 role: density at which its ribbon enters (lag_silkidslow).
 glow0: f32, // @default 0 Voice 0 note light (lag_silkglow then lag_silkglow2: S-shaped onset, long release).
 sa0: f32, // @default 0 Voice 0 strike swell at the root (lag_compimp3 k0: peak ~0.8 s).
 sb0: f32, // @default 0 Voice 0 strike swell, a quarter down (lag_compimp5 k0: ~1.6 s).
 sc0: f32, // @default 0 Voice 0 strike swell, half way (lag_silkswell2 k0: ~3.6 s).
 sd0: f32, // @default 0 Voice 0 strike swell near the tip (lag_silkswell4 k0: ~5.6 s).
 id0cS: f32, // @default 1 Voice 0 fifths cosine, slow.
 id0sS: f32, // @default 0 Voice 0 fifths sine, slow.
 anchor0S: f32, // @default 1 Voice 0 anchor, slow.
 mirror0S: f32, // @default 0 Voice 0 mirror, slow.
 braid0S: f32, // @default 0 Voice 0 braid, slow.
 fan0S: f32, // @default 0 Voice 0 lean, slow.
 id1c: f32, // @default 1 Voice 1 pitch class on the circle of fifths, cosine (lag_silkid).
 id1s: f32, // @default 0 Voice 1 fifths sine.
 anchor1: f32, // @default 1 Voice 1 role: rides the chord's character.
 mirror1: f32, // @default 0 Voice 1 role: mirrors it (fifth).
 braid1: f32, // @default 0 Voice 1 role: braids with it (third).
 fan1: f32, // @default 0 Voice 1 role: sideways lean.
 need1: f32, // @default 0.3 Voice 1 role: density at which its ribbon enters (lag_silkidslow).
 glow1: f32, // @default 0 Voice 1 note light (lag_silkglow then lag_silkglow2: S-shaped onset, long release).
 sa1: f32, // @default 0 Voice 1 strike swell at the root (lag_compimp3 k1: peak ~0.8 s).
 sb1: f32, // @default 0 Voice 1 strike swell, a quarter down (lag_compimp5 k1: ~1.6 s).
 sc1: f32, // @default 0 Voice 1 strike swell, half way (lag_silkswell2 k1: ~3.6 s).
