 anchor0: f32, // @default 1 Voice 0 role: rides the chord's character.
 mirror0: f32, // @default 0 Voice 0 role: mirrors it (fifth).
 braid0: f32, // @default 0 Voice 0 role: braids with it (third).
 fan0: f32, // @default 0 Voice 0 role: sideways lean.
 need0: f32, // @default 0.3 Voice 0 role: density at which its ribbon enters (lag_silkidslow).
 glow0: f32, // @default 0 Voice 0 note light (lag_silkglow then lag_silkglow2: S-shaped onset, long release).
 sa0: f32, // @default 0 Voice 0 strike swell at the root (lag_compimp3 k0: peak ~0.8 s).
 sb0: f32, // @default 0 Voice 0 strike swell, a quarter down (lag_compimp5 k0: ~1.6 s).
 sc0: f32, // @default 0 Voice 0 strike swell, half way (lag_silkswell2 k0: ~3.6 s).
 sd0: f32, // @default 0 Voice 0 strike swell near the tip (lag_silkswell4 k0: ~5.6 s).
 id0cS: f32, // @default 1 Voice 0 fifths cosine, slow.
 id0sS: f32, // @default 0 Voice 0 fifths sine, slow.
