 mirror0S: f32, // @default 0 Voice 0 mirror, slow.
 braid0S: f32, // @default 0 Voice 0 braid, slow.
 fan0S: f32, // @default 0 Voice 0 lean, slow.
 id1c: f32, // @default 1 Voice 1 pitch class on the circle of fifths, cosine (lag_silkid).
 id1s: f32, // @default 0 Voice 1 fifths sine.
 anchor1: f32, // @default 1 Voice 1 role: rides the chord's character.
 mirror1: f32, // @default 0 Voice 1 role: mirrors it (fifth).
 braid1: f32, // @default 0 Voice 1 role: braids with it (third).
 fan1: f32, // @default 0 Voice 1 role: sideways lean.
 need1: f32, // @default 0.3 Voice 1 role: density at which its ribbon enters (lag_silkidslow).
 glow1: f32, // @default 0 Voice 1 note light (lag_silkglow then lag_silkglow2: S-shaped onset, long release).
