const PI: f32 = 3.14159265;
// study switches (build.sh SILK_OFF="DRAG S ..." sets them to 0 in a -dbg copy); all 1 in the real build
const SILK_K_DRAG: f32 = 1.0;
const SILK_K_SWAY: f32 = 1.0;
const SILK_K_S: f32 = 1.0;
const SILK_K_FLOOR: f32 = 1.0;
const SILK_K_DEPTH: f32 = 1.0;
const SILK_COLS: u32 = 288u;
const SILK_ROWS: u32 = 12u;

struct Voice { c: f32, s: f32, anchor: f32, mirror: f32, braid: f32, fan: f32, };

fn silkVoice(P: Params, v: u32) -> Voice {
 if (v == 0u) { return Voice(P.id0c, P.id0s, P.anchor0, P.mirror0, P.braid0, P.fan0); }
 if (v == 1u) { return Voice(P.id1c, P.id1s, P.anchor1, P.mirror1, P.braid1, P.fan1); }
 if (v == 2u) { return Voice(P.id2c, P.id2s, P.anchor2, P.mirror2, P.braid2, P.fan2); }
 if (v == 3u) { return Voice(P.id3c, P.id3s, P.anchor3, P.mirror3, P.braid3, P.fan3); }
 return Voice(P.id4c, P.id4s, P.anchor4, P.mirror4, P.braid4, P.fan4);
}
fn silkVoiceS(P: Params, v: u32) -> Voice {
 if (v == 0u) { return Voice(P.id0cS, P.id0sS, P.anchor0S, P.mirror0S, P.braid0S, P.fan0S); }
 if (v == 1u) { return Voice(P.id1cS, P.id1sS, P.anchor1S, P.mirror1S, P.braid1S, P.fan1S); }
 if (v == 2u) { return Voice(P.id2cS, P.id2sS, P.anchor2S, P.mirror2S, P.braid2S, P.fan2S); }
 if (v == 3u) { return Voice(P.id3cS, P.id3sS, P.anchor3S, P.mirror3S, P.braid3S, P.fan3S); }
 return Voice(P.id4cS, P.id4sS, P.anchor4S, P.mirror4S, P.braid4S, P.fan4S);
}
fn silkStrikeTaps(P: Params, v: u32) -> vec4f {
 if (v == 0u) { return vec4f(P.sa0, P.sb0, P.sc0, P.sd0); }
 if (v == 1u) { return vec4f(P.sa1, P.sb1, P.sc1, P.sd1); }
 if (v == 2u) { return vec4f(P.sa2, P.sb2, P.sc2, P.sd2); }
 if (v == 3u) { return vec4f(P.sa3, P.sb3, P.sc3, P.sd3); }
 return vec4f(P.sa4, P.sb4, P.sc4, P.sd4);
}
fn silkGlow(P: Params, v: u32) -> f32 {
 if (v == 0u) { return P.glow0; }
 if (v == 1u) { return P.glow1; }
 if (v == 2u) { return P.glow2; }
 if (v == 3u) { return P.glow3; }
 return P.glow4;
}
fn mixVoice(a: Voice, b: Voice, t: f32) -> Voice {
 return Voice(mix(a.c, b.c, t), mix(a.s, b.s, t), mix(a.anchor, b.anchor, t), mix(a.mirror, b.mirror, t),
  mix(a.braid, b.braid, t), mix(a.fan, b.fan, t));
}

// THE FINGERPRINT GRAMMAR. A pitch class sits on the circle of fifths at angle th (C = 0, G = 30 deg, ...),
// handed in as (c, s) = (cos th, sin th) through slow lags, so a new note cross-fades. Traits are
// low-order trigonometric polynomials of th, so neighbours are related:
//  c  (1st): openness. F C G: long open S-curves; B F# C#: shorter, curlier S-curves.
//  s  (1st): hand. The S-curve's corkscrew: sharp side right-handed, flat side left-handed, C planar.
//  c2 (2nd): roll. C, F# roll face-on/edge-on more; A, Eb hold their face.
//  s2 (2nd): lilt: a long-short skew in the S-curve.
//  c3 (3rd): texture (material): thread fineness and glint spacing.
struct Char { hand: f32, coil: f32, roll: f32, lilt: f32, phase: f32, tex: f32, };
fn silkChar(c: f32, s: f32) -> Char {
 let c2 = c * c - s * s;
 let s2 = 2.0 * c * s;
 let c3 = c * (c * c - 3.0 * s * s);
 return Char(s, clamp(0.5 - 0.5 * c, 0.0, 1.0), 0.5 + 0.5 * c2, 0.5 * s2, 1.7 * c + 2.3 * s, 0.5 + 0.5 * c3);
}
fn mixChar(a: Char, b: Char, t: f32) -> Char {
 return Char(mix(a.hand, b.hand, t), mix(a.coil, b.coil, t), mix(a.roll, b.roll, t), mix(a.lilt, b.lilt, t),
  mix(a.phase, b.phase, t), mix(a.tex, b.tex, t));
}

// The character a voice's silk wears at s: its own, or the chord's (the root's) by its role, mirrored for
// the fifth; the near half reads the lag_silkid targets, the far half the slower ones.
fn silkCharAt(P: Params, v: u32, s: f32) -> Char {
 let w = smoothstep(0.2, 0.9, s);
 let V = mixVoice(silkVoice(P, v), silkVoiceS(P, v), w);
 let own = silkChar(V.c, V.s);
 var rc = silkChar(mix(P.rootC, P.rootCS, w), mix(P.rootS, P.rootSS, w));
 let ms = 1.0 - 2.0 * clamp(V.mirror, 0.0, 1.0);
 rc.hand = rc.hand * ms; rc.lilt = rc.lilt * ms;
 return mixChar(own, rc, clamp(V.anchor, 0.0, 1.0));
}

// Roots: a fixed regular pentagon of radius 0.6 under the bell, numbered so a root's place across the
// picture (bell-local -x is the trail side) matches its lane: no two ribbons cross at the bell.
fn silkRootAngle(v: u32) -> f32 {
 var a = array<f32, 5>(1.5708, -0.9425, -2.1991, 0.3142, 2.8274);
 return a[v];
}
fn silkRootLocal(v: u32) -> vec3f {
 let psi = silkRootAngle(v);
 return vec3f(cos(psi) * 0.6, BELL_Y0 + 0.02, sin(psi) * 0.6);
}
fn silkRoot(c: TC, v: u32) -> vec3f { return hfPos(c.f, silkRootLocal(v)); }

// A ribbon's lane, one per ribbon (read at a fixed mix of the near and far lags, so it is constant along
// the ribbon): the heading it hangs from (th0) and turns into (thf) in the picture plane, measured from the
// bell's period-mean axis toward the trail side; its drift in depth; the hang's outward lean; its role.
//   root: its own lane, the chord's phase.          fifth: lane pulled toward the column, mirrored hand.
//   thirds: lane pulled toward the middle, the chord's phase plus half a wave: they cross the root's ribbon.
//   sevenths, extensions: lane opened outward and toward the camera, their own phase.
//   tensions: lane pulled inward, flare in depth, their own phase.
struct Lane { th0: f32, thf: f32, depth: f32, lean: f32, spread: f32, braid: f32, flare: f32, third: f32, reach: f32, mir: f32, };
fn silkLane(P: Params, c: TC, v: u32) -> Lane {
 let V = mixVoice(silkVoice(P, v), silkVoiceS(P, v), 0.6);
 let own = silkChar(V.c, V.s);
 let rc = silkChar(mix(P.rootC, P.rootCS, 0.6), mix(P.rootS, P.rootSS, 0.6));
 let mir = clamp(V.mirror, 0.0, 1.0);
 let anc = clamp(V.anchor, 0.0, 1.0);
 let br = clamp(V.braid, 0.0, 1.0);
 let flare = 1.0 - anc;
 let rh = rc.hand * (1.0 - 2.0 * mir);
 let fixed = -cos(silkRootAngle(v));            // -0.95 .. 0.95 across the picture
 let h = stableRand(v, 71u);
 let reach = smoothstep(0.1, 0.8, P.density);
 let laneRaw = fixed * (1.0 - 0.5 * br) + 0.5 * V.fan - 0.6 * mir + 0.4 * flare * own.hand;
 // calm: about 9 deg from the axis (a lazy S hanging down-left), peak about 30 deg, fanned to +-29 deg (the
 // bell's own lean adds about 20 deg on screen: down-left, as the boards); a slow
 // whole-ribbon gesture (0.045 Hz)
 let thb = 0.15 + 0.37 * reach + tanh(laneRaw / 1.2) * (0.15 + 0.35 * reach) + 0.08 * sin(TAU * 0.045 * c.t + 6.0 * h);
 // soft ceiling at about 50 deg: the far part keeps going down the bell axis, its S-curve never lifts it
 // above the margin (the upper left stays empty)
 let e = max(thb - 0.8, 0.0);
 let thf = thb - e + 0.12 * tanh(e / 0.12);
 // the ribbons already fan as they leave the bell (a third of the way to their lane, spread by it)
 let th0 = 0.3 * thf + 0.1 * tanh(laneRaw / 1.2);
 let depthRaw = -0.35 + 0.25 * rh + 0.6 * V.fan - 0.9 * mir * (0.35 + 0.25 * rh) + 0.8 * flare * own.hand + 0.5 * fixed;
 let depth = 0.3 * tanh(depthRaw / 1.2) * (0.5 + 0.5 * reach);
 let leanRaw = 0.55 * V.fan + 0.6 * flare * own.hand + 0.35 * mir;
 return Lane(th0, thf, depth, 0.8 * tanh(leanRaw / 0.8), 0.1 + 0.1 * flare + 0.06 * P.density, br, flare,
  smoothstep(0.4, 0.9, br), reach, mir);
}

// The lane's centre line in closed form: straight along th0 to xb0, a constant-curvature bend of fixed
// length Lb into thf, then straight (position and heading continuous; the bend's curvature is the angle
// over Lb, at most 0.3 per bell radius). Returned as (along the axis, toward the trail side).
fn headInt(th0: f32, k: f32, u: f32) -> vec2f {
 let hu = 0.5 * k * u;
 let sc = select(sin(hu) / hu, 1.0 - hu * hu / 6.0, abs(hu) < 1e-3);
 return u * sc * vec2f(cos(th0 + hu), sin(th0 + hu));
}
fn silkLaneXY(L: Lane, x: f32, xb0: f32, Lb: f32) -> vec2f {
 let k = (L.thf - L.th0) / Lb;
 let u1 = min(x, xb0);
 let u2 = clamp(x - xb0, 0.0, Lb);
 let u3 = max(x - xb0 - Lb, 0.0);
 return u1 * vec2f(cos(L.th0), sin(L.th0)) + headInt(L.th0, k, u2) + u3 * vec2f(cos(L.thf), sin(L.thf));
}
fn silkHeadAngle(L: Lane, x: f32, xb0: f32, Lb: f32) -> f32 { return L.th0 + (L.thf - L.th0) * clamp((x - xb0) / Lb, 0.0, 1.0); }

// Presence by harmonic role (melody first, then root, third, fifth, seventh, extensions, tensions).
fn silkPresence(P: Params, v: u32) -> f32 {
 var need = array<f32, 5>(P.need0 - 0.1, P.need1, P.need2, P.need3, -0.2);
 let t = need[v];
 return smoothstep(t, t + 0.3, P.density);
}

// The geometric length is fixed (scaled with the bell); density decides how much of it is lit, so the tip
// never retracts. Lit length in bell radii: calm 10, medium about 14, peak about 17. Never a stub.
fn silkLen(P: Params) -> f32 { return 17.5 * P.scale; }
fn silkLitLen(P: Params, pres: f32) -> f32 { return P.scale * (10.0 + 7.0 * pow(max(P.density, 1e-4), 0.9)) * (0.85 + 0.15 * pres); }
fn silkLit(P: Params, pres: f32) -> f32 { return min(silkLitLen(P, pres) / silkLen(P), 1.0); }

// A voice's strike as felt at s: the four response taps blended down the ribbon (each later and
// wider), normalised to about 1 per strike near the root and fading with distance; soft-saturated.
fn silkSwell(P: Params, v: u32, s: f32) -> f32 {
 let u = s / max(silkLit(P, silkPresence(P, v)), 0.15);
 let k = silkStrikeTaps(P, v) * vec4f(1.5, 1.9, 3.2, 4.2);
 var x = k.x;
 x = mix(x, k.y, smoother(0.06, 0.25, u));
 x = mix(x, k.z, smoother(0.25, 0.5, u));
 x = mix(x, k.w, smoother(0.5, 0.85, u));
 x = x * (1.0 - 0.25 * min(u, 1.0)) * smoothstep(0.0, 0.08, u);
 return x / (1.0 + 0.8 * x);
}

// The ribbon's width at s: gathered at the root, constant from 10 to 85 % of the lit length, tapering
// to nothing by 110 % (and by the geometry's end). Grows with density and presence, a little with the
// swell, softly capped at half a bell diameter (a band, never a balloon).
fn silkWidth(P: Params, v: u32, s: f32, pres: f32, sw: f32) -> f32 {
 var wv = array<f32, 5>(1.1, 0.85, 0.95, 0.9, 1.2);
 let u = s / silkLit(P, pres);
 let x = s * silkLen(P);
 let raw = (0.3 + 0.65 * P.density) * P.scale * wv[v] * (0.4 + 0.6 * pres) * pres * (1.0 + 0.35 * sw);
 let cap = 1.0 * P.scale;
 let r = raw / cap;
 let wf = cap * r / sqrt(sqrt(1.0 + r * r * r * r));
 let prof = mix(0.2, 1.0, smoother(0.0, 1.0, x / (1.2 * P.scale))) * (1.0 - smoother(0.85, 1.1, u)) * (1.0 - smoothstep(0.85, 1.0, s));
 return wf * prof;
}

// The silk's centre line at s (0 root .. 1 tip) for voice v and its lane L.
fn silkSpineL(P: Params, c: TC, L: Lane, v: u32, s: f32, len: f32) -> vec3f {
 let psi = silkRootAngle(v);
 let h = stableRand(v, 71u);
 let ch = silkCharAt(P, v, s);
 let x = s * len;
 let near = min(len, 7.0 * P.scale);
 // the family's own 0..1 along the hang, saturating SMOOTHLY (zero slope where it reaches 1): a hard
 // min() here put a knee in the silk where the drag, sway and sweep stop growing
 let un = min(x / (1.3 * near), 1.0);
 let sn = un * (2.0 - un);
 let xb0 = 0.3 * P.scale;
 let Lb = 2.8 * P.scale;
 // the lane: down the period-mean axis, turning toward the trail side, drifting in depth; the hang
 // leans a little outward from its root
 let b = silkLaneXY(L, x, xb0, Lb);
 let outL = vec3f(cos(psi + L.lean), 0.0, sin(psi + L.lean));
 let xo = 1.5 * P.scale;
 var pos = silkRoot(c, v) + c.droop * b.x + c.side * b.y + c.side2 * (L.depth * x * smoother(0.02, 0.35, s) * SILK_K_DEPTH)
  + hfDir(c.fP, outL) * (L.spread * xo * tanh(x / xo));
 // drag, undulation and sweep, as the hero's appendages (on the hang's own scale)
 // (the silk trails behind the swim but does not float up when the bell sinks: most of the drag's
 // upward part along the period-mean axis is taken out, smoothly)
 // (at calm the long silk trails at about half the drag, so the calm trail hangs rather than streams)
 var dr = dragAt(c, sn, near, ARM_DRAG_T * 1.1 * (0.85 + 0.3 * h) * (0.8 + 0.4 * c.es)) * (0.55 + 0.45 * L.reach + 0.5 * L.reach * smoother(0.3, 1.0, s));
 dr = dr + c.droop * (0.85 * softPos(-dot(dr, c.droop)));
 pos += dr * SILK_K_DRAG;
 let sway = normalize(c.side * cos(psi + h) + c.side2 * sin(psi + h));
 let sway2 = normalize(cross(c.droop, sway));
 let w = TAU * (0.5 * sn - 0.09 * c.t) + psi * 1.7 + h * 5.0;
 let amp = (0.08 + 0.06 * c.es) * near * pow(sn, 1.3);
 pos += ((sway * sin(w) + sway2 * 0.5 * cos(0.8 * w + 0.6)) * amp + sweepAt(c, sn) * near) * SILK_K_SWAY;
 // the ribbon's own big S-curve, across its lane in the picture plane and (by its hand) in depth: a
 // corkscrew whose handedness is the note's. Amplitude a share of the wavelength, 8 % calm to 18 % busy (the curvature
 // budget). Busy notes: fuller, shorter waves; calm: long lazy ones. Never the temporal frequency.
 let env = smoother(0.0, 4.5 * P.scale, x);
 let busy = clamp(0.5 * P.act + 0.2 * P.energyS + 0.3 * c.act, 0.0, 1.0);
 let vf = f32(v) - 2.0;
 let lam = mix(15.0, 10.5, ch.coil) * P.scale * (1.1 - 0.25 * busy) * (1.0 + 0.06 * vf * (1.0 - L.braid));
 // phases: chord tones lock to the chord's phase (the fifth a quarter wave on, thirds half a wave: they
 // cross the root's ribbon), the rest run free; a small fixed offset per ribbon so none run parallel
 let ph = 0.8 * ch.phase + 0.6 * vf + (0.7 * vf + 2.0 * h) * L.flare + PI * L.third + 0.5 * PI * L.mir;
 let ws = TAU * (x / lam - 0.04 * c.t) + ph;
 let th = silkHeadAngle(L, x, xb0, Lb);
 let nS = c.side * cos(th) - c.droop * sin(th);
 let As = (0.08 + 0.1 * busy) * lam * env * SILK_K_S;
 let hd = tanh(1.5 * ch.hand);
 let Ad = (0.04 + 0.06 * abs(hd)) * lam * env * SILK_K_S;
 pos += nS * (As * (sin(ws) + 0.2 * ch.lilt * sin(2.0 * ws + 0.9)));
 pos += c.side2 * (Ad * (0.85 * hd * cos(ws) + 0.45 * sin(0.7 * ws + 1.3 + 4.0 * h)));
 // the bell's own strike, felt as by every appendage
 pos += (hfDir(c.fP, outL) * 0.7 + c.droop * 0.5) * 0.08 * near * sin(PI * sn * 0.5) * kickAt(c, sn);
 // this voice's strike: one swell rolling down its ribbon, across its lane and in depth, growing with
 // distance from the root so it reads all the way down
 let sw = silkSwell(P, v, s);
 pos += (nS * 0.55 + c.side2 * 0.8) * ((0.25 + 0.045 * x / P.scale) * P.scale * sw);
 // the silk's own floor, softer and deeper than the family's: a point hangs at least 30 % of its arc
 // length below its root along the bell's axis (rarely reached; it only flattens a crest)
 return mix(pos, keepBelow(c, silkRoot(c, v), pos, s, 3.0 * len), SILK_K_FLOOR);
}
fn silkSpine(P: Params, c: TC, v: u32, s: f32, len: f32) -> vec3f { return silkSpineL(P, c, silkLane(P, c, v), v, s, len); }

// minimal rotation carrying a vector from direction a to direction T
fn silkCarryA(a: vec3f, T: vec3f, v: vec3f) -> vec3f {
 let k = cross(a, T);
 let co = dot(a, T);
 return v + cross(k, v) + cross(k, cross(k, v)) / max(1.0 + co, 0.05);
}

fn silkTC(P: Params, t: f32) -> TC {
 let f = hfMake(P.heroX, P.heroY, P.heroZ, P.tiltX, P.tiltZ, P.scale);
 return tcMake(f, vec3f(P.heroX1, P.heroY1, P.heroZ1), vec3f(P.heroX2, P.heroY2, P.heroZ2), vec3f(P.heroX3, P.heroY3, P.heroZ3),
  P.swimRate, P.tiltX, P.tiltZ, pulseEnv(P.pulsePhase), P.pulsePhase, P.tension, P.density, t, vec3f(P.kick0, P.kick1, P.kick2), P.energyS, P.kickS, P.rigLean);
}

// The silk's frame at s, unrolled: position, tangent, and the width direction: across the lane in the
// picture plane (the ribbon shows its face), carried onto the true tangent by the minimal rotation from
// the lane's heading (never more than about 60 deg apart, so it never flips).
struct SFr { p: vec3f, t: vec3f, w: vec3f, n: vec3f, };
fn silkFrame0(P: Params, c: TC, v: u32, s: f32, len: f32) -> SFr {
 let L = silkLane(P, c, v);
 let ds = 0.01;
 let p = silkSpineL(P, c, L, v, s, len);
 let T = normalize(silkSpineL(P, c, L, v, min(s + ds, 1.0), len) - silkSpineL(P, c, L, v, max(s - ds, 0.0), len) + vec3f(0.0, -1e-5, 0.0));
 let th = silkHeadAngle(L, s * len, 0.3 * P.scale, 2.8 * P.scale);
 let Hb = c.droop * cos(th) + c.side * sin(th);
 let nS = c.side * cos(th) - c.droop * sin(th);
 let wc = silkCarryA(Hb, T, nS);
 let W0 = normalize(wc - T * dot(wc, T));
 return SFr(p, T, W0, cross(T, W0));
}
// ... and rolled: a half turn per 6 to 10 bell radii at peak, 4 to 6.5 for the narrow calm band (rolling
// notes and tension roll faster), so an edge-on passage always spans at least 0.75 bell radius of length
// (about 0.4 bell diameter: no pinch), plus a slow drift; zero at the root
fn silkFrame(P: Params, c: TC, v: u32, s: f32, len: f32) -> SFr {
 let F = silkFrame0(P, c, v, s, len);
 let ch = silkCharAt(P, v, s);
 let h = stableRand(v, 71u);
 let tw = PI * s * len / (mix(10.0, 6.0, clamp(0.6 * ch.roll + 0.4 * P.tension, 0.0, 1.0)) * (0.65 + 0.35 * P.density) * P.scale) * smoother(0.0, 0.2, s) + 0.35 * sin(0.25 * c.t + h * 6.0) * s;
 let Wd = F.w * cos(tw) + F.n * sin(tw);
 return SFr(F.p, F.t, Wd, cross(F.t, Wd));
}

// A soft breath of light down the silk with each stroke (periodic in the swim phase only).
fn silkBreath(P: Params, s: f32) -> f32 { return pres(P.pulsePhase - 0.12 - 0.6 * s) * smoothstep(0.05, 0.3, s); }

// A filament: tied to its ribbon by a FIXED offset in the ribbon's UNROLLED frame (the roll would wind
// it round the spine and kink it), an edge side and a peel that grows smoothly with arc length.
fn silkThreadPos(P: Params, c: TC, v: u32, j: u32, s: f32, len: f32, pres: f32) -> vec3f {
 let F = silkFrame0(P, c, v, s, len);
 let side = select(-1.0, 1.0, j == 0u);
 let wd = silkWidth(P, v, s, pres, 0.0);
 let peel = (0.2 + 0.18 * f32(j)) * P.scale * smoother(0.05, 0.6, s);
 let off = F.w * side * (0.45 * wd + peel) + F.n * 0.18 * P.scale * smoother(0.1, 0.6, s) * sin(TAU * (s * len / (8.0 * P.scale) - 0.05 * c.t) + f32(j) * 2.0 + f32(v));
 return keepBelow(c, silkRoot(c, v), F.p + off, s, len);
}
fn silkThreadSpan(j: u32) -> vec2f { return vec2f(0.03 + 0.03 * f32(j), 0.8 + 0.08 * f32(j)); }
// ---- kernel_silkthreads: two hairline filaments per ribbon, 128 segments each (beam: position -> tip,
// width tapering to nothing at both ends). Occasional fine accents, never a net. ----
fn process(p: Point, ctx: PointCtx) -> Point {
 var q = p;
 let P = ctx.params;
 let SEG = 128u;
 let fil = ctx.index / SEG;
 let k = ctx.index % SEG;
 let v = min(fil / 2u, 4u);
 let j = fil % 2u;
 let c = silkTC(P, ctx.absTime);
 let len = silkLen(P);
 let presence = silkPresence(P, v);
 let sp = silkThreadSpan(j);
 let ua = f32(k) / f32(SEG);
 let ub = f32(k + 1u) / f32(SEG);
 let sa = mix(sp.x, sp.y, ua);
 let sb = mix(sp.x, sp.y, ub);
 q.position = silkThreadPos(P, c, v, j, sa, len, presence);
 q.tip = silkThreadPos(P, c, v, j, sb, len, presence);
 let um = 0.5 * (ua + ub);
 let ends = smoothstep(0.0, 0.18, um) * (1.0 - smoothstep(0.7, 1.0, um));
 q.width = ends;
 let lit = silkLit(P, presence) * (1.0 + 0.1 * f32(j));
 let fade = ends * (1.0 - smoothstep(0.6, 1.0, sa / lit));
 let sw = silkSwell(P, v, sa);
 let col = moodColor(P.mood, 0.86 + 0.07 * f32(j));
 // delicate: about a third of the earlier light; the swell and the note glow brighten it a little
 let b = presence * fade * (0.12 + 0.4 * P.lum) * (0.7 + 0.8 * sw / (1.0 + 0.6 * sw) + 0.4 * max(silkGlow(P, v), 0.0));
 q.tint = vec4f(col * b, 1.0);
 return q;
}

struct Params {
 heroX: f32, // @default 1.1 Bell centre x (rig heroX).
 heroY: f32, // @default 1.45 Bell centre y (rig heroY).
 heroZ: f32, // @default 0 Bell centre z (rig heroZ).
 tiltX: f32, // @default 0 Lean about X, radians (rig heroTiltX).
 tiltZ: f32, // @default -0.22 Lean about Z, radians (rig heroTiltZ).
 scale: f32, // @default 1 Size multiplier (rig heroScale).
 pulse: f32, // @default 0 Bell contraction 0..1 (rig pulse).
 pulsePhase: f32, // @default 0 Swim-cycle phase 0..1 (rig pulsePhase); margin, lappets and skirt lag it.
 kick0: f32, // @default 0 Strike force at the bell (lag_herokick2.imp): a fuller stroke and a small flare of the margin.
 kickS: f32, // @default 0 Slow mean of the strikes (lag_herokick7.imp): only what is new reaches the bell.
 energyS: f32, // @default 0.5 Slow musical energy (lag_heroslow2.energy): calm strokes gentle, loud ones full.
 tension: f32, // @default 0.3 Stretch and twist (lag_heroslow2.tension).
 nt0: f32, // @default 0 Note place 0 (pitch class 0, circle-of-fifths order) now (lag_heronote2.s0): its lappets curl in.
 nt1: f32, // @default 0 Note place 1 (pitch class 7, circle-of-fifths order) now (lag_heronote2.s1): its lappets curl in.
 nt2: f32, // @default 0 Note place 2 (pitch class 2, circle-of-fifths order) now (lag_heronote2.s2): its lappets curl in.
 nt3: f32, // @default 0 Note place 3 (pitch class 9, circle-of-fifths order) now (lag_heronote2.s3): its lappets curl in.
 nt4: f32, // @default 0 Note place 4 (pitch class 4, circle-of-fifths order) now (lag_heronote2.s4): its lappets curl in.
 nt5: f32, // @default 0 Note place 5 (pitch class 11, circle-of-fifths order) now (lag_heronote2.s5): its lappets curl in.
 nt6: f32, // @default 0 Note place 6 (pitch class 6, circle-of-fifths order) now (lag_heronote2.s6): its lappets curl in.
 nt7: f32, // @default 0 Note place 7 (pitch class 1, circle-of-fifths order) now (lag_heronote2.s7): its lappets curl in.
 nt8: f32, // @default 0 Note place 8 (pitch class 8, circle-of-fifths order) now (lag_heronote2.s8): its lappets curl in.
 nt9: f32, // @default 0 Note place 9 (pitch class 3, circle-of-fifths order) now (lag_heronote2.s9): its lappets curl in.
 nt10: f32, // @default 0 Note place 10 (pitch class 10, circle-of-fifths order) now (lag_heronote2.s10): its lappets curl in.
 nt11: f32, // @default 0 Note place 11 (pitch class 5, circle-of-fifths order) now (lag_heronote2.s11): its lappets curl in.
 qMaj: f32, // @default 0 The chord is major (lag_herochord2.qMaj): the gonad loops open out round and smooth.
 qMin: f32, // @default 0 The chord is minor (lag_herochord2.qMin): the loops draw in, more frilled.
 teS: f32, // @default 0.3 Tension, slow mean (lag_herotens.tension): above it the bell stretches and twists, below it (a release) the lappets unfurl.
 noteGain: f32, // @default 1 How strongly a note curls its lappets (0 = off).
 tensionGain: f32, // @default 1 How strongly tension stretches and a release unfurls.
 chordGain: f32, // @default 1 How strongly the chord quality re-forms the gonads.
 react: f32, // @default 1 The owner's music reaction strength (rig reactGain, 0..2, eased): multiplies every gain above.
};
// Four sheets of one 160 x 56 grid: 0 exumbrella with lappets, 1 subumbrella + frill skirt,
// 2 the four gonad loops (frilled horseshoe tubes), 3 the core glow (a soft ellipsoid at the manubrium).
// uv = (around, along); tint.x = sheet.
const C = 160u;
const R = 56u;
const VS = 0.74;   // subumbrella: margin; skirt runs VS..1

fn bellSub(phi: f32, v: f32, p: f32, pm: f32, psk: f32, te: f32) -> vec3f {
 // the subumbrella: a smaller, lower dome inside, meeting the rim; then the frill skirt
 let h = BELL_H * 0.58 * (1.0 + 0.2 * p + 0.06 * te);
 let w = min(v / VS, 1.0);
 let th = w * BELL_THMAX;
 let sq = bellSqueeze(w, mix(p, pm, 0.5));
 let pleat = 1.0 + 0.03 * (0.5 + 0.5 * cos(16.0 * phi)) * sin(w * 3.14159);
 let r = sin(th) / sin(BELL_THMAX) * mix(0.8, 0.965, smoothstep(0.3, 1.0, w)) * sq * pleat;
 let y = BELL_Y0 + 0.01 - 0.03 * pm + h * domeY(th);
 if (v <= VS) { return vec3f(cos(phi) * r, y, sin(phi) * r); }
 // the frill skirt: hangs from the subumbrella margin, ruffled, and trails the squeeze (psk lags it)
 let s = (v - VS) / (1.0 - VS);
 let ruffle = 0.04 * s * sin(30.0 * phi + 2.0 * sin(5.0 * phi) + 1.5 * s);
 let rr = r * (1.0 - 0.08 * s - 0.08 * s * psk + 0.08 * s * pm) + ruffle;
 let yy = y - 0.18 * s * (1.0 + 0.2 * sin(7.0 * phi + 0.4)) * (1.0 + 0.15 * pm - 0.3 * psk);
 return vec3f(cos(phi) * rr, yy, sin(phi) * rr);
}

// The gonads: four frilled horseshoe loops round the manubrium (the moon jelly's four rings), each open
// toward the centre. The grid runs through the four in turn; the tube closes to nothing at each end,
// so the stretch between two loops has no area and draws nothing.
// pass 6: the chord's quality re-forms them (qMaj, qMin eased over about a second): a major chord opens
// the loops round and smooth and stands them up; a minor one draws them in, tighter and more frilled;
// anything else (neither third) leaves them between, with the frill turned a little along the loop.
fn gonad(u: f32, v: f32, p: f32, qMaj: f32, qMin: f32) -> vec3f {
 let k = floor(u * 4.0);
 let t = fract(u * 4.0);
 let psi = (k + 0.5) / 4.0 * TAU + 0.3927;
 let ctr = vec2f(cos(psi), sin(psi)) * 0.21;
 // each loop stands up out of the horizontal by about 50 degrees, so it reads as a ring from the side
 let a0 = 3.14159 + 0.15 * TAU + t * 0.7 * TAU;               // round the loop, the gap facing the centre
 let e1 = vec3f(cos(psi), 0.0, sin(psi));                       // radial
 let qO = clamp(1.0 - qMaj - qMin, 0.0, 1.0);
 let e2 = normalize(vec3f(-sin(psi), 0.0, cos(psi)) * (0.64 - 0.2 * qMaj + 0.12 * qMin) + vec3f(0.0, 0.77, 0.0));
 let sq = 1.0 - 0.1 * p;
 let base = vec3f(ctr.x, BELL_Y0 + 0.24 + 0.08 * p, ctr.y);
 let onLoop = e1 * cos(a0) + e2 * sin(a0);
 let tangent = normalize(-e1 * sin(a0) + e2 * cos(a0));
 let nrm = normalize(cross(tangent, onLoop));
 let al = v * TAU;
 let frill = 1.0 + (0.35 - 0.15 * qMaj + 0.2 * qMin) * sin(t * 37.0 + k * 1.7 + 2.0 * qO) * sin(al * 2.0 + t * 11.0) + (0.15 + 0.1 * qMin) * sin(t * 71.0 + k);
 let tr = 0.035 * smoothstep(0.0, 0.08, t) * (1.0 - smoothstep(0.92, 1.0, t)) * frill;
 let pt = base + onLoop * 0.12 * (1.0 + 0.1 * qMaj - 0.12 * qMin) + (onLoop * cos(al) + nrm * sin(al)) * tr;
 return vec3f(pt.x * sq, pt.y, pt.z * sq);
}

fn process(p: Point, ctx: PointCtx) -> Point {
 var q = p;
 let per = C * R;
 let sheet = ctx.index / per;
 let k = ctx.index % per;
 let i = k % C;
 let j = k / C;
 let u = f32(i) / f32(C);
 let v = f32(j) / f32(R - 1u);
 let P = ctx.params;
 // tension against its slow mean: rising stretches the dome and twists it, a release lets it settle
 let rr = tensionRR(P.tension, P.teS, (P.tensionGain * P.react));
 let te = P.tension + 0.8 * rr.x - 0.3 * rr.y;
 let phi = u * TAU + (0.12 * P.tension + 0.25 * rr.x) * v;
 // the note of this place (light stage, S-shaped, seconds of decay), softly limited
 let nS = (P.noteGain * P.react) * noteSoft(secSum(vec4f(P.nt0, P.nt1, P.nt2, P.nt3), vec4f(P.nt4, P.nt5, P.nt6, P.nt7), vec4f(P.nt8, P.nt9, P.nt10, P.nt11), u * TAU));
 let k0 = kickRipple(vec3f(P.kick0), P.kickS).x + kickSteady(P.kickS);
 let D = strokeDepth(P.energyS);
 let pl = pulseEnv(P.pulsePhase) * strokeAmp(D * (1.0 + 0.2 * k0));   // the stroke shape (common.wgsl), not the rig's pulse
 let ph = P.pulsePhase;
 let pm = pulseEnv(ph - 0.06) * D;
 let psk = pulseEnv(ph - 0.14) * D;
 var lp: vec3f;
 if (sheet == 0u) {
  lp = marginFlare(bellExo(phi, v, pl, bellPulseAt(v, pl, ph, D), te), v, k0);
  // a note curls the lappets of its place in, like a small contraction from that side; a release
  // unfurls them all a little. Lappets only: the ring canal, where filaments hang, stays where it is.
  let sl = max(v - BELL_VM, 0.0) / (1.0 - BELL_VM);
  let curl = 0.35 * nS - 0.25 * rr.y;
  lp += vec3f(cos(phi), 0.0, sin(phi)) * (-0.9 * curl * sl * LAP_LEN) + vec3f(0.0, -0.25 * curl * sl * LAP_LEN, 0.0);
 } else if (sheet == 1u) {
  lp = marginFlare(bellSub(phi, v, pl, pm, psk, te), min(v / VS, 1.0) * 0.95, k0);
  // the frill skirt of a sounding place draws in as well
  let sk = max(v - VS, 0.0) / (1.0 - VS);
  lp = vec3f(lp.x * (1.0 - 0.08 * sk * nS), lp.y, lp.z * (1.0 - 0.08 * sk * nS));
 } else if (sheet == 2u) {
  lp = gonad(u, v, pl, (P.chordGain * P.react) * P.qMaj, (P.chordGain * P.react) * P.qMin);
 } else {
  // core glow: an ellipsoid round the stomach; the material lights it by its thickness
  let th = v * 3.14159;
  let rr = sin(th) * (0.2 + 0.04 * cos(th)) * (1.0 - 0.1 * pl);
  lp = vec3f(cos(phi) * rr, BELL_Y0 + 0.2 + 0.08 * pl + cos(th) * 0.16, sin(phi) * rr);
 }
 let f = hfMake(P.heroX, P.heroY, P.heroZ, P.tiltX, P.tiltZ, P.scale);
 q.position = hfPos(f, lp);
 q.uv = vec2f(u, v);
 q.tint = vec4f(f32(sheet), 0.0, 0.0, 1.0);
 return q;
}
// ---- hero common (kernels): frame, pulse envelope, bell profile, trail ----
const TAU = 6.2831853;
// The bell in its own frame: rim radius 1, up +y, rim (margin) plane at BELL_Y0, apex BELL_H above it.
// World = hero position + rotZ(tiltZ) * rotX(tiltX) * (local * heroScale).
// A flattened dome (the boards: height/width about 0.38 for the dome, 0.45 with the lappets): the profile
// stops at 79 degrees, so the shoulders slope into the rim and never stand as a vertical wall; 16
// rounded lappets hang LAP_LEN below the rim.
const BELL_H = 0.64;
const BELL_Y0 = -0.35;
const BELL_THMAX = 1.38;
const BELL_VM = 0.9;       // exumbrella: v of the rim (ring canal); the lappets hang over VM..1
const LAP_LEN = 0.14;

struct HF { o: vec3f, ca: f32, sa: f32, cb: f32, sb: f32, k: f32, };
fn hfMake(x: f32, y: f32, z: f32, tx: f32, tz: f32, k: f32) -> HF {
 return HF(vec3f(x, y, z), cos(tx), sin(tx), cos(tz), sin(tz), k);
}
fn hfDir(f: HF, d: vec3f) -> vec3f {
 let y1 = d.y * f.ca - d.z * f.sa;
 let z1 = d.y * f.sa + d.z * f.ca;
 return vec3f(d.x * f.cb - y1 * f.sb, d.x * f.sb + y1 * f.cb, z1);
}
fn hfPos(f: HF, p: vec3f) -> vec3f { return f.o + hfDir(f, p * f.k); }

// The stroke, as a periodic function of the swim phase (the cycle is about 3.5 s): a slow full
// contraction over 30 % of it, a release over 40 %, then a 30 % glide at rest. Every geometric use of
// the swim reads this (the bell body too), so the bell and everything lagging it agree.
// the warm accent: one peach-gold for cores, canals, glints and beads in every mood
const ACC = vec3f(1.0, 0.66, 0.36);
fn smoother(a: f32, b: f32, x: f32) -> f32 {
 let t = clamp((x - a) / (b - a), 0.0, 1.0);
 return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}
fn pulseEnv(ph: f32) -> f32 {
 let x = fract(ph);
 return smoother(0.0, 0.3, x) * (1.0 - smoother(0.3, 0.7, x));
}
// A chord strike as a FORCE: the rig's strike age drives a short impulse through a chain of hero
// lag nodes; k.x (lag_herokick2) is the response at the bell, k.y (4) later and wider, k.z (5) later
// still, kS (7) a very slow mean of the same impulse. The RIPPLE is what is new: each response minus
// the slow mean, normalised so one isolated strike peaks near 1, softly limited, so a train of strikes
// does not hold the appendages splayed: each new strike still adds a travelling ripple, and the
// sustained part becomes a small, saturating STEADY opening.
fn kickRipple(k: vec3f, kS: f32) -> vec3f {
 let g = vec3f(2.0, 4.0, 5.5);
 let x = (k - vec3f(kS)) * g;
 return x / sqrt(vec3f(1.0) + x * x);
}
fn kickSteady(kS: f32) -> f32 { return 0.35 * (1.0 - exp(-2.5 * kS)); }
// positive part, smoothly (light and flares only grow)
fn softPos(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.0004)); }
// the margin flares a little with the strike (bell and tentacle roots must agree)
fn marginFlare(lp: vec3f, v: f32, k0: f32) -> vec3f {
 let g = 1.0 + 0.035 * k0 * smoothstep(0.75, 1.0, v);
 return vec3f(lp.x * g, lp.y, lp.z * g);
}

// Soft swim pressure: a raised cosine at the swim frequency, peaking with the contraction (phase 0.28).
// Lagged copies of it run down arms and tentacles as a gentle pressure wave, never a wiggle.
fn gaussK(x: f32) -> f32 { return exp(-x * x); }
// the strike ripple as felt at s along anything (0 the bell, 1 the tips), continuous in time and space
fn rippleAt(r: vec3f, s: f32) -> f32 {
 return mix(mix(r.x, r.y, smoother(0.0, 0.5, s)), r.z, smoother(0.5, 1.0, s));
}
fn pres(ph: f32) -> f32 { return 0.5 + 0.5 * cos(TAU * (ph - 0.28)); }
// Contraction felt at bell parameter v (0 apex, 1 lappet tips): the body follows pulse, the margin
// lags 0.06 of a cycle, the lappets 0.1, so the rim trails the squeeze and re-opens late.
// D is the stroke depth (fuller with louder music, set slowly).
fn bellPulseAt(v: f32, pl: f32, ph: f32, D: f32) -> f32 {
 let pm = pulseEnv(ph - 0.06) * D;
 let plap = pulseEnv(ph - 0.1) * D;
 return mix(pl, mix(pm, plap, smoothstep(0.86, 1.0, v)), smoothstep(0.55, 1.0, v));
}
fn strokeDepth(es: f32) -> f32 { return 0.75 + 0.4 * es; }
// The stroke's amplitude, softly limited to 1 (pass 6). A hard min(.., 1) on depth x strike clipped the
// top of the contraction inside a stroke whenever the music was full: a kink in its speed, seen as a
// light step at the stroke's peak (Clair 70.6 s, 88.1 s). Bell, filament roots and rhopalia all use it.
fn strokeAmp(a: f32) -> f32 { return a / pow(1.0 + pow(max(a, 0.0), 8.0), 0.125); }

fn bellSqueeze(v: f32, pm: f32) -> f32 {
 return 1.0 - 0.2 * pm * pow(smoothstep(0.12, 1.0, v), 1.3);
}
// Exumbrella point. p: body contraction, pm: (lagged) margin contraction, te: tension.
// the dome's height profile, 1 at the apex and 0 at the rim (slightly flattened top)
fn domeY(th: f32) -> f32 {
 let cm = pow(cos(BELL_THMAX), 0.88);
 return (pow(max(cos(th), 0.0), 0.88) - cm) / (1.0 - cm);
}
fn bellExo(phi: f32, v: f32, p: f32, pm: f32, te: f32) -> vec3f {
 let vd = min(v / BELL_VM, 1.0);
 let th = vd * BELL_THMAX;
 // a contraction closes the rim and lengthens the dome a little: it stays a dome (h/w under 0.6)
 let h = BELL_H * (1.0 + 0.12 * p + 0.06 * te);
 let rib = 1.0 + 0.022 * (0.5 + 0.5 * cos(16.0 * phi)) * smoothstep(0.08, 0.5, vd) * (1.0 - smoothstep(0.8, 0.95, vd));
 let wave = (0.025 * sin(8.0 * phi + 0.7) + 0.01 * sin(13.0 * phi + 2.0)) * smoothstep(0.6, 1.0, vd);
 var r = sin(th) / sin(BELL_THMAX) * bellSqueeze(vd, pm) * rib;
 var y = BELL_Y0 - 0.04 * pm * smoothstep(0.5, 1.0, vd) + h * domeY(th);
 if (v > BELL_VM) {
  // the lappets hang from the rim: flared a little outward at rest, curled in by the squeeze
  let s = (v - BELL_VM) / (1.0 - BELL_VM);
  r = r + s * LAP_LEN * (0.45 - 0.9 * pm) * bellSqueeze(1.0, pm);
  y = y - s * LAP_LEN * (0.9 + 0.2 * pm);
 }
 return vec3f(cos(phi) * r, y + wave, sin(phi) * r);
}

// Frame-independent per-id random in [0, 1). The built-in pointRand re-rolls EVERY FRAME (it hashes the
// frame index), so it must never shape geometry: that reads as high-frequency jitter in playback.
fn stableRand(id: u32, salt: u32) -> f32 {
 var x = id * 747796405u + salt * 2891336453u + 12345u;
 x = (x ^ (x >> 15u)) * 2246822519u;
 x = (x ^ (x >> 13u)) * 3266489917u;
 x = x ^ (x >> 16u);
 return f32(x >> 8u) * (1.0 / 16777216.0);
}
// ---- hero only: the music as characters (pass 6). Not part of the shared family. ----
// Twelve places round the bell, one per pitch class in circle-of-fifths order: sector k holds pitch class
// 7k mod 12, so a fifth is a neighbour and a triad is always the same small shape (root, its neighbour,
// and the third four places round). A note lights and moves its own place; a chord shows as the set of
// places its tones hold. The values per sector come from expression_herochord through lags (two 0.3 s
// stages with a four times slower release: S-shaped onset, seconds of decay; one more 0.8 s stage for
// the tips), so nothing here can step.
fn noteSecW(x: f32, k: f32) -> f32 {
 let d = abs(fract((x - k) / 12.0 + 0.5) - 0.5) * 12.0;   // distance in sectors, wrapped
 return 1.0 - smoother(0.3, 0.7, d);                       // a plateau per sector, soft 0.4-sector seams
}
fn secW4(x: f32, k0: f32) -> vec4f {
 return vec4f(noteSecW(x, k0), noteSecW(x, k0 + 1.0), noteSecW(x, k0 + 2.0), noteSecW(x, k0 + 3.0));
}
// the twelve sector values (a = sectors 0..3, b = 4..7, c = 8..11) as felt at bell azimuth phi
fn secSum(a: vec4f, b: vec4f, c: vec4f, phi: f32) -> f32 {
 let x = fract(phi / TAU) * 12.0;
 return dot(a, secW4(x, 0.0)) + dot(b, secW4(x, 4.0)) + dot(c, secW4(x, 8.0));
}
// where in its sector an azimuth lies, -0.5 .. 0.5 (a sector's filaments fan apart from its centre)
fn secOffset(phi: f32) -> f32 { return fract(fract(phi / TAU) * 12.0 + 0.5) - 0.5; }
// soft limit: many notes on one place never add up to more than about one
fn noteSoft(x: f32) -> f32 { return x / sqrt(1.0 + x * x); }
// melodic motion: the top voice's pitch through a quick and a slow lag; their difference (semitones)
// is a damped force, up > 0. Returns (rising, falling), each 0..1, softly limited.
fn melodyUD(melF: f32, melS: f32, g: f32) -> vec2f {
 let m = g * (melF - melS) / 4.0;
 return vec2f(noteSoft(softPos(m)), noteSoft(softPos(-m)));
}
// tension against its own slow mean: (rising, releasing), each 0..1. A release is the exhale.
fn tensionRR(teF: f32, teS: f32, g: f32) -> vec2f {
 let d = g * 5.0 * (teF - teS);
 return vec2f(noteSoft(softPos(d)), noteSoft(softPos(-d)));
}
// the chord root on the circle of fifths leans the palette (a hue change of the whole animal); the lean
// reaches the heart first and the margin, then the tips, later (lag_herochord2, 3, 4)
fn chordLean(r: vec2f, g: f32) -> f32 { return g * (0.25 * r.x + 0.15 * r.y); }
// A chord change as a wave with duration: differences of successive stages of the strike response
// (lag_herokick2 - 4, 4 - 5, 5 - 7; every stage is at least second order, so every difference starts
// with zero slope), normalised so one strike peaks near 1 at the heart (about 0.6 s after it), half way
// out (1.3 s) and at the margin and down the appendages (2.4 s). A train of strikes overlaps into a
// gentle shimmer, never a sum. (A first-order stage here, lag_herokick6, dropped the margin's light the
// instant a strike began and then stopped dead at zero: a light step 0.1 s after every strike.)
fn softKnee(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.01)); }
fn chordWave(k0: f32, k1: f32, k2: f32, kS: f32, g: f32) -> vec3f {
 let w = vec3f(3.0 * (k0 - k1), 10.0 * (k1 - k2), 15.0 * (k2 - kS));
 return g * vec3f(noteSoft(softKnee(w.x)), noteSoft(softKnee(w.y)), noteSoft(softKnee(w.z)));
}

parameters.expressions:
env0 = voice0Envelope;
env1 = voice1Envelope;
env2 = voice2Envelope;
env3 = voice3Envelope;
env4 = voice4Envelope

parameters.source:
// WORLD BLOOM SOURCE, pass 13 (Silk Medusa): one full-resolution pass ahead of the Bloom Pyramid.
// The pyramid's own bright pass uses a quadratic soft knee: continuous in value and slope but not in
// curvature at threshold +- knee. When a bright creature's lines cross that knee together (the bell at full
// contraction) a smooth turn of its light becomes a step in total light (hero worker, pass 7: with the bloom
// off the bell-alone break drops from 2.6x to 1.6x). This pass does the thresholding instead with a C2 knee
// over the same span: below threshold - knee nothing (so no glow is added at calm), above threshold + knee
// exactly brightness - threshold (as before), and between them the blend
//   f = 2 knee (x^3 - x^4 / 2),  x = (b - threshold + knee) / (2 knee)
// whose value, slope and curvature all meet the straight lines at both ends. The pyramid then runs with
// threshold 0 and a vanishing knee: its bright pass passes this through unchanged.
struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
struct Params {
 threshold: f32, // @default 1 Linear radiance (brightest channel) where bloom starts (was the pyramid's threshold).
 knee: f32, // @default 0.9 Half-width of the soft region (was the pyramid's knee).
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

@fragment fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
 let c = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
 let b = max(c.r, max(c.g, c.b));
 let k = max(params.knee, 1e-3);
 let x = clamp((b - params.threshold + k) / (2.0 * k), 0.0, 1.0);
 var f = 2.0 * k * (x * x * x - 0.5 * x * x * x * x);
 if (b > params.threshold + k) { f = b - params.threshold; }
 return vec4f(c.rgb * (f / max(b, 1e-4)), 1.0);
}

// @use hash
// Companion oral arms: translucent ruffled veils, a crinkled lit lip, warm at the root, thin film.
struct Params {
 lum: f32, // @default 0.5 Illumination (rig lum).
 mood: f32, // @default 0 Palette position (rig mood).
 tension: f32, // @default 0.3 Thin-film phase shift (rig tension).
};
const TAU = 6.2831853;
// a warm accent that survives every mood (review item 8): peach-gold, about #ffc890
const ACCENT = vec3f(1.0, 0.66, 0.36);   // the hero's warm accent

fn vnoise(p: vec2f, seed: u32) -> f32 {
 let i = floor(p);
 let f = p - i;
 let w = f * f * (3.0 - 2.0 * f);
 let ii = vec2i(i);
 let a = unitFloat(hash2i(ii, seed));
 let b = unitFloat(hash2i(ii + vec2i(1, 0), seed));
 let c = unitFloat(hash2i(ii + vec2i(0, 1), seed));
 let d = unitFloat(hash2i(ii + vec2i(1, 1), seed));
 return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}
fn film(ph: f32) -> vec3f { return 0.5 + 0.5 * cos(TAU * (vec3f(0.0, 0.33, 0.67) + ph)); }
fn aaLine(d: f32, w: f32, aa: f32) -> f32 { return 1.0 - smoothstep(w, w + aa, d); }
fn atmos(e: vec3f, fog: f32, mood: f32) -> vec3f {
 let sh = moodColor(mood, 0.06);
 let tone = mix(vec3f(1.0), sh / max(dot(sh, vec3f(0.3, 0.5, 0.2)), 0.05), 0.75);
 return mix(e, tone * dot(e, vec3f(0.3, 0.5, 0.2)), 0.8 * fog);
}

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
 var o = surfaceDefaults(s);
 o.albedo = vec4f(0.0, 0.0, 0.0, 1.0);
 let idf = floor(s.tint.x + 1e-3);
 let id = i32(idf);
 let gl = clamp((s.tint.x - idf) / 0.45, 0.0, 1.0);
 let comp = id / 4;
 let arm = f32(id % 4) + f32(comp) * 4.0;
 let gain = s.tint.y;
 let fog = s.tint.z;
 let travel = s.tint.w;
 let soft = select(1.0, 1.5, comp >= 7);
 let uv = s.uv;
 let du = max(fwidth(uv.x), 1e-5) * soft;
 let N = normalize(s.normal);
 let V = normalize(s.eye - s.world);
 let nv = abs(dot(N, V));
 let fres = 1.0 - nv;
 let L = p.lum;
 let warm = moodColor(p.mood, 0.93);
 let hot = moodColor(p.mood, 1.0);
 let gold = mix(hot, hot * hot, 0.6);
 let body = moodColor(p.mood, 0.4);
 let lilac = moodColor(p.mood, 0.55);
 let a = uv.x * 2.0 - 1.0;
 let sAlong = uv.y;
 let rootWarm = exp(-sAlong * 3.0);
 let crink = vnoise(vec2f(sAlong * 90.0, arm * 7.0), 51u);
 let edgeD = 1.0 - abs(a) - 0.05 * crink;
 let lip = 0.3 + 0.7 * smoothstep(-0.2, 0.2, a);
 let rim = aaLine(abs(edgeD - 0.04), 0.03 * soft, du * 2.0) * lip;
 let cut = smoothstep(-0.005, 0.03, edgeD);
 let rimSoft = fres * fres;
 let thick = 0.45 + 0.3 * crink + 0.35 * p.tension + arm * 0.13;
 let cosT = sqrt(max(1.0 - (1.0 - nv * nv) / 1.77, 0.0));
 let fc = film(thick * 2.0 * cosT + sAlong * 0.6);
 let tip = 1.0 - smoothstep(0.65, 1.0, sAlong);
 let head = smoothstep(0.0, 0.08, sAlong);
 var e = vec3f(0.0);
 e += mix(mix(body, fc, 0.4), fc * mix(lilac, vec3f(1.0), 0.5), L) * (0.03 + 0.18 * rimSoft) * (0.5 + 0.8 * L);
 e += mix(ACCENT, warm, 0.3) * rootWarm * rootWarm * (0.05 + 0.3 * L);
 e += mix(mix(lilac, ACCENT, 0.35 + 0.65 * rootWarm), ACCENT, min(L * (0.4 + 0.6 * rootWarm), 1.0)) * rim * (0.1 + 0.5 * L) * (0.4 + 0.6 * rootWarm + 0.4 * travel);
 // the note's glow travelling down the arm: along its lip and middle, not a flash of the whole veil
 e += ACCENT * gl * (rim * 0.8 + 0.15 * sqrt(max(1.0 - abs(a), 0.0))) * (0.35 + 0.5 * L) * (1.0 - 0.5 * sAlong);
 let seam = 0.3 + 0.7 * smoothstep(-1.0, -0.2, a);
 o.emissive = atmos(e * cut * tip * head * seam, fog, p.mood) * gain;
 return o;
}
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}

