parameters.expressions:
swimBpm = bpm * 0.5;
age = max(abstime - voice0Start, 0);
hit = clamp(strikeL * 6 * react, 0, 1);
energy = clamp(auto * (sectE) + (1 - auto) * state + energyTrim, 0, 1);
