pulsePhase = fract(abstime * swimBpm / 120);
pulse = smoothstep(0, 0.28, pulsePhase) * (1 - smoothstep(0.28, 1, pulsePhase));
pu = (abstime - 0) * swimBpm / 120;
U = pu + 0.06 * sin(6.2831853 * (fract(pu) - 0.3));
heroX = 1.0 + roam * (1.3 * sin(0.11 * U) + 0.3 * sin(0.23 * U + 2));
heroY = 1.2 + roam * 0.55 * sin(0.17 * U + 1);
heroZ = roam * 0.5 * sin(0.07 * U) + 0.3 * density;
pu1 = (abstime - 0.7) * swimBpm / 120;
U1 = pu1 + 0.06 * sin(6.2831853 * (fract(pu1) - 0.3));
heroX1 = 1.0 + roam * (1.3 * sin(0.11 * U1) + 0.3 * sin(0.23 * U1 + 2));
heroY1 = 1.2 + roam * 0.55 * sin(0.17 * U1 + 1);
heroZ1 = roam * 0.5 * sin(0.07 * U1) + 0.3 * density;
pu2 = (abstime - 1.4) * swimBpm / 120;
U2 = pu2 + 0.06 * sin(6.2831853 * (fract(pu2) - 0.3));
heroX2 = 1.0 + roam * (1.3 * sin(0.11 * U2) + 0.3 * sin(0.23 * U2 + 2));
heroY2 = 1.2 + roam * 0.55 * sin(0.17 * U2 + 1);
heroZ2 = roam * 0.5 * sin(0.07 * U2) + 0.3 * density;
pu3 = (abstime - 2.1) * swimBpm / 120;
U3 = pu3 + 0.06 * sin(6.2831853 * (fract(pu3) - 0.3));
heroX3 = 1.0 + roam * (1.3 * sin(0.11 * U3) + 0.3 * sin(0.23 * U3 + 2));
heroY3 = 1.2 + roam * 0.55 * sin(0.17 * U3 + 1);
heroZ3 = roam * 0.5 * sin(0.07 * U3) + 0.3 * density;
travel = U * 0.12;
heroVX = (heroX - heroX1) / 0.7;
heroVY = (heroY - heroY1) / 0.7;
heroVZ = (heroZ - heroZ1) / 0.7;
vbX = roam * (0.143 * cos(0.11 * pu) + 0.069 * cos(0.23 * pu + 2)) * swimBpm / 120;
