camTX = 0.5 * heroX2 - 0.5 - 1.5 * density + camMove * (1.5 * sin(abstime * 0.027) + 0.6 * sin(abstime * 0.061 + 2) + 1.1 * sin(abstime * 0.071 + 0.5));
camTY = 0.6 * heroY2 - 0.55 - 1.3 * density + camMove * 0.7 * sin(abstime * 0.039 + 1);
camTZ = 0.5 * (heroZ2 - 0.3 * density);
