camY = camTY + 0.4 + camMove * 1.5 * sin(abstime * 0.053);
camZ = camTZ + camDist * cos(camAz);
camFov = 38;
camRoll = camMove * 3.5 * sin(abstime * 0.047 + 0.7);
travel1 = U1 * 0.12;
travel2 = U2 * 0.12;
travel3 = U3 * 0.12;
swimRate = swimBpm / 120;
swimDirX = -cos(heroTiltX) * sin(heroTiltZ);
swimDirY = cos(heroTiltX) * cos(heroTiltZ);
swimDirZ = sin(heroTiltX);
