parameters.source:
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}
// WORLD MEDIUM, pass 10 (Silk Medusa): half-resolution pass, composited by the sky pass. Camera-aware.
// Pass 10: the water is LIT by the creatures (single scattering of a point light in a uniform medium,
// closed form, for the hero and the nine companions), light comes from ABOVE (shaft curtains anchored
// on two world planes, so they parallax, with a slow shimmer), far off bioluminescent BLOOMS answer
// the chord changes at five places that keep station in the water, and once in a while a GIANT (a
// whale shark's silhouette) passes far off, dark against the veils, its back rimmed by the light.
// RGB = the light of the medium; ALPHA = its transmittance (near dust clouds dim what lies behind:
// the far veils here, and the stars and horizon haze in the sky pass).
//  - FAR veils on a plane 60 units beyond the hero's water, MID wisps and dark dust clouds on a
//    plane 22 units out: real planes, so the camera's orbit and dolly give them parallax (mid moves
//    more than far), and both creep downstream with the integrated flow (mid faster).
//    Multi-scale: large soft masses (warped fbm), fine ridged filaments, luminous edges and soft
//    bright cores, dark lanes. Calm: almost no veils, only soft dark cloud banks low in the frame.
//  - light shafts (pass 10: curtains on two world planes, see below), dimmed by the dust clouds.
//  - faint volumetric fog bands, and the water lit by the creature (halo + wake glow).
struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
struct Params {
 lum: f32, // @default 0.45 Rig illumination.
 density: f32, // @default 0.5 Rig density: veil coverage and shafts.
 tension: f32, // @default 0.3 Slow tension (lag_slow tensionSlow): warms the veils' lit edges.
 mood: f32, // @default 0 Rig palette position 0..4.
 pulse: f32, // @default 0 Rig pulse: the creature's halo breathes.
 hit: f32, // @default 0 Chord accent smoothed again by the world (lag_worldhit2, S-shaped, ~1 s to peak): lifts only the halo, at most +20 %.
 heroX: f32, // @default 1 Hero x.
 heroY: f32, // @default 1.2 Hero y.
 heroZ: f32, // @default 0 Hero z.
 heroScale: f32, // @default 1 Hero size.
 swimDirX: f32, // @default 0.22 The bell's up axis (rig swimDirX): the wake glow runs the other way.
 swimDirY: f32, // @default 0.97 Rig swimDirY.
 swimDirZ: f32, // @default 0 Rig swimDirZ.
 flowX: f32, // @default 0 Integrated swim x (speed_worldflow): the far veils creep downstream with it.
 flowY: f32, // @default 0 Integrated swim y.
 camX: f32, // @default 0 Camera eye x.
 camY: f32, // @default 0.4 Camera eye y.
 camZ: f32, // @default 9 Camera eye z.
 camTX: f32, // @default 0 Camera target x.
 camTY: f32, // @default 0.2 Camera target y.
 camTZ: f32, // @default 0 Camera target z.
 camFov: f32, // @default 38 Camera vertical fov, degrees.
 nebula: f32, // @default 1 Veil gain.
 shafts: f32, // @default 1 Light shaft gain.
 glow: f32, // @default 1 Creature halo gain.
 fog: f32, // @default 1 Fog band and dust cloud gain.
 blooms: f32, // @default 1 Far bloom gain.
 kb1: f32, // @default 0 Kick, second lag stage (lag_worldbeat2 bioKick: two lags, so its onset has no corner): the lit water breathes with it.
 kb2: f32, // @default 0 Kick, third lag stage (lag_worldbeat3): the companions' glow, a little later.
 react: f32, // @default 1 Reaction amount (rig reactGain, owner's slider): scales every music response here.
 env: f32, // @default 1 Environment amount (rig envGain, owner's slider, 0..2): 0 = only the creatures in black water, 2 = rich.
 backdrop: f32, // @default 1 Backdrop amount (rig backdropGain, owner's slider, 0..1): 0 = the far backdrop is black; the creatures and the water they light are untouched.
 lit: f32, // @default 1 Gain of the light the creatures cast into the water.
 c3x: f32, // @default 0 Companion 3 world x (expression_compworld wx3).
 c3y: f32, // @default 0 Companion 3 world y (wy3).
 c3z: f32, // @default -30 Companion 3 world z (wz3).
 c3v: f32, // @default 0 Companion 3 visibility (vis3).
 c4x: f32, // @default 0 Companion 4 world x (expression_compworld wx4).
 c4y: f32, // @default 0 Companion 4 world y (wy4).
 c4z: f32, // @default -30 Companion 4 world z (wz4).
 c4v: f32, // @default 0 Companion 4 visibility (vis4).
 c5x: f32, // @default 0 Companion 5 world x (expression_compworld wx5).
 c5y: f32, // @default 0 Companion 5 world y (wy5).
 c5z: f32, // @default -30 Companion 5 world z (wz5).
 c5v: f32, // @default 0 Companion 5 visibility (vis5).
 c6x: f32, // @default 0 Companion 6 world x (expression_compworld wx6).
 c6y: f32, // @default 0 Companion 6 world y (wy6).
 c6z: f32, // @default -30 Companion 6 world z (wz6).
 c6v: f32, // @default 0 Companion 6 visibility (vis6).
 c7x: f32, // @default 0 Companion 7 world x (expression_compworld wx7).
 c7y: f32, // @default 0 Companion 7 world y (wy7).
 c7z: f32, // @default -30 Companion 7 world z (wz7).
 c7v: f32, // @default 0 Companion 7 visibility (vis7).
 c8x: f32, // @default 0 Companion 8 world x (expression_compworld wx8).
 c8y: f32, // @default 0 Companion 8 world y (wy8).
 c8z: f32, // @default -30 Companion 8 world z (wz8).
 c8v: f32, // @default 0 Companion 8 visibility (vis8).
 bA0: f32, // @default 0 Bloom site 0, first stage (lag_worldbloom1 b0): the core lights.
 bB0: f32, // @default 0 Bloom site 0, second stage (lag_worldbloom2 b0): the light spreads.
 bC0: f32, // @default 0 Bloom site 0, third stage (lag_worldbloom3 b0): the outer ring.
 bA1: f32, // @default 0 Bloom site 1, first stage (lag_worldbloom1 b1): the core lights.
 bB1: f32, // @default 0 Bloom site 1, second stage (lag_worldbloom2 b1): the light spreads.
 bC1: f32, // @default 0 Bloom site 1, third stage (lag_worldbloom3 b1): the outer ring.
 bA2: f32, // @default 0 Bloom site 2, first stage (lag_worldbloom1 b2): the core lights.
 bB2: f32, // @default 0 Bloom site 2, second stage (lag_worldbloom2 b2): the light spreads.
 bC2: f32, // @default 0 Bloom site 2, third stage (lag_worldbloom3 b2): the outer ring.
 bA3: f32, // @default 0 Bloom site 3, first stage (lag_worldbloom1 b3): the core lights.
 bB3: f32, // @default 0 Bloom site 3, second stage (lag_worldbloom2 b3): the light spreads.
 bC3: f32, // @default 0 Bloom site 3, third stage (lag_worldbloom3 b3): the outer ring.
 bA4: f32, // @default 0 Bloom site 4, first stage (lag_worldbloom1 b4): the core lights.
 bB4: f32, // @default 0 Bloom site 4, second stage (lag_worldbloom2 b4): the light spreads.
 bC4: f32, // @default 0 Bloom site 4, third stage (lag_worldbloom3 b4): the outer ring.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;


fn nHash(p: vec2f) -> f32 {
 var v = vec3u(bitcast<vec2u>(vec2i(p)), 913u) * 1664525u + 1013904223u;
 v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
 v = v ^ (v >> vec3u(16u));
 v.x += v.y * v.z;
 return f32(v.x >> 8u) * (1.0 / 16777216.0);
}
fn vnoise(p: vec2f) -> f32 {
 let i = floor(p); let f = p - i; let u = f * f * (3.0 - 2.0 * f);
 return mix(mix(nHash(i), nHash(i + vec2f(1.0, 0.0)), u.x), mix(nHash(i + vec2f(0.0, 1.0)), nHash(i + vec2f(1.0, 1.0)), u.x), u.y);
}
fn fbm3(p0: vec2f) -> f32 {
 var p = p0; var a = 0.5; var s = 0.0;
 for (var i = 0; i < 3; i = i + 1) { s = s + a * vnoise(p); p = p * 2.03 + vec2f(1.7, 9.2); a = a * 0.5; }
 return s / 0.875;
}
fn fbm4(p0: vec2f) -> f32 {
 var p = p0; var a = 0.5; var s = 0.0;
 for (var i = 0; i < 4; i = i + 1) { s = s + a * vnoise(p); p = p * 2.07 + vec2f(5.3, 2.8); a = a * 0.5; }
 return s / 0.9375;
}

fn ridged(p0: vec2f) -> f32 {
 var p = p0; var a = 0.5; var s = 0.0;
 for (var i = 0; i < 3; i = i + 1) { s = s + a * (1.0 - abs(2.0 * vnoise(p) - 1.0)); p = p * 2.11 + vec2f(3.7, 1.9); a = a * 0.5; }
 return s / 0.875;
}

// The light a point source at p scatters toward the eye along the whole view ray (single scattering
// in a uniform medium): the integral of 1 / distance^2 along the ray, with a soft core r0 and a range
// R (beyond it the source's light is absorbed). Closed form, no marching.
fn airlight(eye: vec3f, d: vec3f, p: vec3f, r0: f32, R: f32) -> f32 {
 let v = p - eye;
 let tc = dot(v, d);
 let h2 = max(dot(v, v) - tc * tc, 0.0);
 let h = sqrt(h2 + r0 * r0);
 return (1.5707963 + atan(tc / h)) / h * exp(-sqrt(h2) / R);
}
struct Cam3 { eye: vec3f, fwd: vec3f, right: vec3f, up: vec3f, tanH: f32, };
// One far bloom site: base position (relative to the hero's mean), three lag stages.
fn bloomAt(q: vec2f, c: Cam3, fk: f32, base: vec3f, st: vec3f, t: f32) -> vec3f {
 if (st.x + st.y + st.z < 0.002) { return vec3f(0.0); }
 let S = vec3f(1.0, 1.2, 0.0) + base + 1.5 * vec3f(sin(0.021 * t + fk), 0.6 * sin(0.017 * t + 2.0 * fk), sin(0.019 * t + 3.0 * fk));
 let v = S - c.eye;
 let z = dot(v, c.fwd);
 if (z < 2.0) { return vec3f(0.0); }
 let sp = vec2f(dot(v, c.right), dot(v, c.up)) / (z * 2.0 * c.tanH);
 let rs = 3.0 / (z * 2.0 * c.tanH);
 let lq0 = (q - sp) / rs;
 if (length(lq0) > 2.4) { return vec3f(0.0); }
 // An irregular plankton cloud, not a disc: the radius is warped by slow noise.
 let lq = lq0 * (0.8 + 0.45 * vnoise(lq0 * 1.3 + vec2f(fk * 3.7, t * 0.015)));
 let rq = length(lq);
 let tex = 0.35 + 0.95 * fbm3(lq * 2.2 + vec2f(fk * 7.1, t * 0.02));
 // A glow that grows outward: the core, then a wider filled cloud, then a still wider one whose
 // middle has begun to fade (no dark hole: never a smoke ring).
 let e = st.x * exp(-pow(rq / 0.35, 2.0)) + st.y * 1.3 * exp(-pow(rq / 0.75, 2.0)) + st.z * 1.6 * exp(-pow(rq / 1.25, 2.0)) * (0.55 + 0.45 * smoothstep(0.2, 1.1, rq));
 let odd = fk - 2.0 * floor(fk / 2.0);
 let bio = mix(moodColor(params.mood, 0.7), vec3f(0.55, 0.85, 1.0), 0.35);
 return mix(bio, moodColor(params.mood + 0.5, 0.75), 0.3 * odd) * e * tex * smoothstep(2.3, 1.6, length(lq0));
}

// The large form passing far off once in a while: a whale shark's side silhouette on the world plane
// z = -45 (in front of the far veils, behind the shaft curtains), crossing in 75 s every 180 s (from
// 25 s on). Signed distance in body units (length 2 = 20 world units); its tail beats at a fixed slow
// rate. Returns (distance, opacity, upward-facing share for the rim light from above).
fn segD(p: vec2f, a: vec2f, b: vec2f) -> f32 {
 let pa = p - a; let ba = b - a;
 return length(pa - ba * clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0));
}
fn giant(X: vec2f, t: f32) -> vec3f {
 let tau = (t - 25.0) - floor((t - 25.0) / 180.0) * 180.0;
 if (tau > 75.0) { return vec3f(1.0, 0.0, 0.0); }
 let vis = smoothstep(0.0, 12.0, tau) * (1.0 - smoothstep(63.0, 75.0, tau));
 let C = vec2f(1.0 - 36.0 + 72.0 * tau / 75.0, -2.0 + 2.5 * sin(0.04 * tau));
 let p = (X - C) / 10.0;
 if (abs(p.x) > 1.4 || abs(p.y) > 0.5) { return vec3f(1.0, 0.0, 0.0); }
 let x = clamp(p.x, -1.0, 1.0);
 let yc = 0.05 * sin(6.2831853 * 0.12 * t - 2.5 * x) * smoothstep(0.3, -1.0, x);
 let h = 0.15 * sqrt(max(1.0 - x * x, 0.0)) * (0.5 + 0.5 * smoothstep(-1.0, 0.3, x)) + 0.004;
 var sd = abs(p.y - yc) - h;
 if (abs(p.x) > 1.0) { sd = max(sd, length(vec2f(abs(p.x) - 1.0, p.y - yc))); }
 let tail = vec2f(-1.0, yc);
 let fl = 0.05 * sin(6.2831853 * 0.12 * t - 2.7);
 sd = min(sd, segD(p, tail, tail + vec2f(-0.17, 0.2 + fl)) - 0.03);
 sd = min(sd, segD(p, tail, tail + vec2f(-0.13, -0.13 + fl)) - 0.025);
 sd = min(sd, segD(p, vec2f(0.35, -0.06), vec2f(0.12, -0.28)) - 0.025);
 sd = min(sd, segD(p, vec2f(-0.2, 0.1), vec2f(-0.36, 0.21)) - 0.02);
 let upF = smoothstep(-0.2, 0.8, (p.y - yc) / max(h, 0.02));
 return vec3f(sd, vis, upF);
}

// Where the view ray meets the plane z = zp (world), in that plane's x, y.
fn onPlane(eye: vec3f, d: vec3f, zp: f32) -> vec2f {
 let tz = (zp - eye.z) / min(d.z, -0.05);
 return (eye + d * max(tz, 0.0)).xy;
}

@fragment fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
 let res = frameU.resolution;
 let aspect = res.x / res.y;
 let q = vec2f((uv.x - 0.5) * aspect, 0.5 - uv.y);
 let t = frameU.absTime;
 let eye = vec3f(params.camX, params.camY, params.camZ);
 let fwd = normalize(vec3f(params.camTX, params.camTY, params.camTZ) - eye);
 let right = normalize(cross(fwd, vec3f(0.0, 1.0, 0.0)));
 let up = cross(right, fwd);
 let tanH = tan(radians(params.camFov) * 0.5);
 let d = normalize(fwd + 2.0 * tanH * (q.x * right + q.y * up));
 let ll = vec2f(atan2(d.x, -d.z), asin(clamp(d.y, -1.0, 1.0)));
 let flow = vec2f(params.flowX, params.flowY);
 var col = vec3f(0.0);

 // ---- The water lit by the creature: halo at the hero, glow down the wake.
 let hero = vec3f(params.heroX, params.heroY, params.heroZ);
 let hv = hero - eye;
 let hz = max(dot(hv, fwd), 0.5);
 let hq = vec2f(dot(hv, right), dot(hv, up)) / (hz * 2.0 * tanH);
 let unit = params.heroScale / (hz * 2.0 * tanH);
 let hr = length(q - hq) / max(unit, 0.02);
 // The strike only warms the water right round the hero (within about two bell radii), +20 % at most.
 let near2 = exp(-pow(hr / 2.0, 2.0));
 let breathe = 1.0 + 0.1 * params.pulse + 0.2 * params.hit * params.react * near2;
 let wv = hero - normalize(vec3f(params.swimDirX, params.swimDirY, params.swimDirZ) + vec3f(0.0, 1e-4, 0.0)) * 5.0 - eye;
 let wq = vec2f(dot(wv, right), dot(wv, up)) / (max(dot(wv, fwd), 0.5) * 2.0 * tanH);
 let seg = wq - hq;
 let hseg = clamp(dot(q - hq, seg) / max(dot(seg, seg), 1e-5), 0.0, 1.0);
 let wd = length(q - hq - seg * hseg) / max(unit, 0.02);
 // The hero lights the water round it (closed-form single scattering), plus a faint glow down the wake.
 let hs = params.heroScale;
 let litW = (0.45 + 0.55 * params.lum) * params.lit;
 // The hero's own glow stays at calm (darkness comes from the rest of the water): 0.95..1 with lum.
 let heroAir = airlight(eye, d, hero, 0.55 * hs, 3.8 * hs);
 let halo = heroAir * 0.19 * (0.95 + 0.05 * params.lum) * (1.0 + 0.12 * params.kb1) * params.lit + exp(-wd / 1.8) * 0.01 * (1.0 - hseg) * (0.35 + 0.65 * params.lum);
 col = col + moodColor(params.mood, 0.5) * halo * breathe * params.glow;
 // The near and mid companions light the water round them too, the mid ones less (their light crosses
 // more water; the far tier's glow is too small to matter). Tiers as in M/companions/tools/gen.py TIER:
 // near 4, 5, 7; mid 3, 6, 8.
 let cAir = (airlight(eye, d, vec3f(params.c4x, params.c4y, params.c4z), 0.4, 1.6) * params.c4v
   + airlight(eye, d, vec3f(params.c5x, params.c5y, params.c5z), 0.4, 1.6) * params.c5v
   + airlight(eye, d, vec3f(params.c7x, params.c7y, params.c7z), 0.4, 1.6) * params.c7v) * 0.42
  + (airlight(eye, d, vec3f(params.c3x, params.c3y, params.c3z), 0.4, 1.6) * params.c3v
   + airlight(eye, d, vec3f(params.c6x, params.c6y, params.c6z), 0.4, 1.6) * params.c6v
   + airlight(eye, d, vec3f(params.c8x, params.c8y, params.c8z), 0.4, 1.6) * params.c8v) * 0.3;
 col = col + mix(moodColor(params.mood, 0.6), moodColor(params.mood, 0.85), 0.3) * cAir * 0.07 * litW * (1.0 + 0.1 * params.kb2);
 // The hero's own light on the medium: steady (no strike, no stroke), so the background never flashes.
 let heroLight = 1.0 + 0.9 * exp(-length(q - hq) / 0.55);

 // ---- MID plane: dark dust clouds (occluders) and thin wisps; parallax and downstream creep.
 let pm = onPlane(eye, d, -22.0) * 0.11 + flow * 0.05 + vec2f(t * 0.003, 0.0);
 let wm = vec2f(fbm3(pm * 0.9 + vec2f(1.3, 4.1)), fbm3(pm * 0.9 + vec2f(7.7, 2.2)));
 let pmw = pm + 0.8 * (wm - 0.5);
 let low = smoothstep(0.25, -0.45, ll.y);
 // Large shapes: low frequency, few octaves (two or three masses in view), pushed to the frame edges.
 let dustN = fbm3(pmw * 0.45 + vec2f(0.0, 5.0)) * 0.8 + vnoise(pmw * 1.6) * 0.2;
 let edgeW = smoothstep(0.25, 0.85, length(q * vec2f(0.75, 1.0)) * 1.6);
 // Calm: soft dark banks low in the frame; fuller music opens more of them across the sky.
 let dust = smoothstep(0.5, 0.66, dustN) * mix(0.35 + 0.65 * low, 1.0, 0.5) * edgeW * params.fog;
 let trans = 1.0 - 0.82 * dust;
 // ---- The giant passing far off: its silhouette hides the far veils, the stars and the haze behind
 // it; a thin rim on its back catches the light from above. Mid dust clouds still pass in front.
 let tzg = (-45.0 - eye.z) / min(d.z, -0.05);
 let g = giant((eye + d * max(tzg, 0.0)).xy, t);
 // Far off: soft (the lens's far circle is wide, about 25 px here) and only partly dark (the water
 // between holds light of its own), so it reads as a presence, never as a cut-out.
 let occ = 1.0 - 0.75 * g.y * (1.0 - smoothstep(-0.05, 0.05, g.x));
 let rimG = exp(-pow((g.x - 0.03) / 0.05, 2.0)) * g.z * g.y;
 col = col + mix(moodColor(params.mood, 0.6), vec3f(0.78, 0.88, 1.0), 0.35) * rimG * 0.03 * (0.4 + 0.6 * params.lum) * trans * params.backdrop;
 let wispR = ridged(pmw * vec2f(2.2, 0.9) + vec2f(t * 0.004, 0.0));
 let wisps = pow(wispR, 8.0) * (1.0 - dust) * smoothstep(0.25, 0.75, 0.5 * params.lum + 0.5 * params.density);
 // Lit rims on the dark masses, and two to four small warm pockets sitting on those rims.
 let rimD = smoothstep(0.42, 0.5, dustN) * (1.0 - smoothstep(0.5, 0.6, dustN)) * edgeW;
 // Warm light glowing from INSIDE the masses just behind their rims: a soft, irregular, low-contrast
 // band on the cloud side of the edge, broken up by large-scale noise; never on open sky, none at calm.
 let inside = smoothstep(0.5, 0.56, dustN) * (1.0 - smoothstep(0.58, 0.72, dustN)) * edgeW;
 let pocketN = fbm3(pmw * 0.9 + vec2f(13.0, 2.0));
 let pocket = smoothstep(0.55, 0.85, pocketN) * inside * smoothstep(0.35, 0.7, params.lum);
 let litM = 0.35 + 0.65 * params.lum;
 let warmIn = mix(moodColor(params.mood, 0.9), vec3f(1.0, 0.578, 0.278), 0.5);
 col = col + (mix(moodColor(params.mood, 0.7), vec3f(0.9, 0.9, 1.0), 0.3) * rimD * 0.03 + warmIn * pocket * 0.045) * litM * params.backdrop;

 // ---- FAR plane: the veils.
 var far = vec3f(0.0);
 let amt = smoothstep(0.22, 0.7, 0.5 * params.lum + 0.5 * params.density + 0.15 * max(params.env - 1.0, 0.0)) * params.nebula;
 if (amt > 0.001) {
  let pf = onPlane(eye, d, -60.0) * 0.045 + flow * 0.02 + vec2f(t * 0.0015, 0.0);
  let w1 = vec2f(fbm3(pf * 1.2 + vec2f(0.0, t * 0.004)), fbm3(pf * 1.2 + vec2f(5.2, 1.3 - t * 0.003)));
  let p = pf + 0.9 * (w1 - 0.5);
  let w2 = vec2f(fbm3(p * 2.6 + vec2f(9.1, 3.3)), fbm3(p * 2.6 + vec2f(2.4, 8.8)));
  let pp = p + 0.25 * (w2 - 0.5);
  // Large soft masses.
  let m = fbm4(pp * 1.3 + vec2f(3.1, 0.0));
  let cover = mix(0.6, 0.42, params.density);
  let mass = smoothstep(cover, cover + 0.34, m);
  // Fine filaments along the flow of the gas, and their bright cores.
  let rot = mat2x2f(0.8, 0.6, -0.6, 0.8);
  let rf = ridged((rot * pp) * vec2f(1.4, 4.2));
  let fil = pow(rf, 6.0) * smoothstep(cover - 0.12, cover + 0.15, m);
  let core = pow(rf, 16.0) * mass;
  // Luminous edges of the masses, dark lanes through them.
  let edge = mass * (1.0 - mass) * 4.0;
  let lanes = smoothstep(0.55, 0.8, fbm3(pp * 3.4 + vec2f(1.0, 7.0)));
  let peak = smoothstep(0.5, 1.0, params.density);
  let body = moodColor(params.mood, 0.42);
  let deep0 = moodColor(params.mood, 0.18);
  let deep = deep0 * clamp(0.13 / max(dot(deep0, vec3f(0.2126, 0.7152, 0.0722)), 0.05), 0.4, 1.5);
  let hot = mix(moodColor(params.mood, 0.95), moodColor(params.mood + 0.5, 0.6), 0.4);
  let rimC = moodColor(params.mood, 0.9);
  // Hue structure, like the boards: deep shadow-tone masses, body-tone filaments, highlight-tone
  // cores and lit edges (contrast of hue, not just of level, so it never greys out).
  far = deep * mass * (0.06 + 0.12 * peak)
      + body * fil * 0.32
      + hot * core * (0.35 + 0.25 * peak)
      + rimC * edge * fil * (0.1 + 0.1 * params.tension)
      + body * pow(mass, 3.0) * 0.08 * peak;
  // Every mood at the same brightness: teal and gold are far brighter to the eye than violet.
  let pnorm = clamp(0.34 / max(dot(body, vec3f(0.2126, 0.7152, 0.0722)), 0.1), 0.45, 1.4);
  // The sky is the quiet part: far less overall, and only where the large masses are.
  far = far * (1.0 - 0.75 * lanes) * amt * heroLight * pnorm * 0.55 * smoothstep(0.15, 0.7, m) * occ;
 }
 let midC = mix(moodColor(params.mood, 0.35), vec3f(0.7, 0.8, 1.0), 0.3);
 col = col + (far * trans + midC * wisps * 0.07 * amt) * params.backdrop;

 // ---- Light from ABOVE: shaft curtains on two world planes (z = -8 and z = -32), slanting along the
 // light's direction; a slow shimmer (the surface focusing light into each ray) runs down them. Anchored in the water, so the near
 // curtain slides across the far one under the camera's truck. Restrained, and dimmer at calm.
 let shaftAmt = (0.25 + 0.75 * smoothstep(0.15, 0.8, params.lum)) * (0.5 + 0.5 * params.density) * params.shafts;
 let shC = mix(moodColor(params.mood, 0.6), vec3f(0.78, 0.88, 1.0), 0.35);
 var shafts = 0.0;
 for (var c = 0; c < 2; c = c + 1) {
  let zp = select(-8.0, -32.0, c == 1);
  let sc = select(0.55, 0.22, c == 1);
  let tz = (zp - eye.z) / min(d.z, -0.05);
  let X = eye + d * max(tz, 0.0);
  let u = (X.x - 0.18 * X.y) * sc + flow.x * 0.01;
  let bend = 0.6 * (vnoise(vec2f(u * 0.7, X.y * 0.05 * (1.0 + 2.0 * sc) - t * 0.01)) - 0.5);
  let n1 = vnoise(vec2f(0.8 * (u + bend) + t * 0.01, f32(c) * 7.0)) * 0.7 + vnoise(vec2f(1.7 * u + 3.0, 1.5 + t * 0.012)) * 0.3;
  let sh = smoothstep(0.4, 0.85, n1);
  // Each ray brightens and dims slowly, and soft knots of light slide down it.
  let cau = (0.6 + 0.6 * vnoise(vec2f(u * 1.3 + 11.0, t * 0.09))) * (0.75 + 0.5 * vnoise(vec2f(u * 2.5, X.y * 0.12 * (1.0 + sc) - t * 0.06)));
  // Brighter toward the surface above, fading into the deep below.
  let height = smoothstep(-10.0, 16.0, X.y - eye.y) * smoothstep(0.0, 0.25, d.y + 0.25);
  shafts = shafts + sh * cau * height * select(0.7, 1.0, c == 1);
 }
 col = col + shC * shafts * 0.24 * shaftAmt * (0.4 + 0.6 * trans) * params.backdrop;

 // ---- Far BLOOMS: five places in the deep water that keep station; at each chord change one of them
 // lights (the chord's index picks which), through three slow lags: the core first, then the light
 // spreading out in a ring, then a wider faint ring (seconds, never a flash). Plankton-cloud texture.
 let cam = Cam3(eye, fwd, right, up, tanH);
 let bloomC = bloomAt(q, cam, 0.0, vec3f(-14.0, 6.0, -30.0), vec3f(params.bA0, params.bB0, params.bC0), t)
  + bloomAt(q, cam, 1.0, vec3f(12.0, 9.0, -38.0), vec3f(params.bA1, params.bB1, params.bC1), t)
  + bloomAt(q, cam, 2.0, vec3f(-4.0, -6.0, -34.0), vec3f(params.bA2, params.bB2, params.bC2), t)
  + bloomAt(q, cam, 3.0, vec3f(21.0, -1.0, -46.0), vec3f(params.bA3, params.bB3, params.bC3), t)
  + bloomAt(q, cam, 4.0, vec3f(-23.0, 2.0, -42.0), vec3f(params.bA4, params.bB4, params.bC4), t);
 col = col + bloomC * 0.2 * params.blooms * params.react * (0.5 + 0.5 * params.lum) * trans * occ * params.backdrop;

 // ---- Faint fog bands: depth in the water, drifting with it.
 let fb = fbm3(vec2f(ll.y * 5.0 + flow.y * 0.03, ll.x * 0.8 + t * 0.002));
 col = col + moodColor(params.mood, 0.3) * smoothstep(0.55, 0.85, fb) * 0.006 * (0.4 + 0.6 * params.lum) * params.fog * params.backdrop;

 // The environment amount scales all of the water's light, and how much its clouds and the giant hide.
 return vec4f(col * params.env, mix(1.0, trans * occ, clamp(params.env, 0.0, 1.0)));
}

// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}
// WORLD SKY, pass 2 (Silk Medusa): one full-resolution pass, camera-aware (rig cam* channels).
// Pass 10: only the deepest gradient lives at infinity (DIRECTION space). The points of light are far
// plankton on three shells round the water (radius 60, 95 and 150 about the hero's mean place) and the
// crescent on a fourth (220): the camera's truck and orbit move the nearest shell most, so the depths
// separate. The foreground flecks moved to kernel_worldlife (marine snow).
// (Before pass 10: things at infinity (gradient, stars, a small far crescent) lived in DIRECTION space.) Things in the water (the hairline traces, the foreground
// flecks) are 3D positions projected through the camera. The nebula, light shafts and the
// creature's glow arrive on `input` (half resolution, sampled bilinearly) and are added underneath.
struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
struct Params {
 lum: f32, // @default 0.45 Rig illumination.
 density: f32, // @default 0.5 Rig density: how many traces are present.
 energy: f32, // @default 0.5 Rig energy: foreground flecks.
 fringe: f32, // @default 0.3 Slow tension (lag_slow tensionSlow): spectral fringing on the traces at peak.
 mood: f32, // @default 0 Rig palette position 0..4.
 heroX: f32, // @default 1 Hero x now.
 heroY: f32, // @default 1.2 Hero y now.
 heroZ: f32, // @default 0 Hero z now.
 heroScale: f32, // @default 1 Hero size.
 travel: f32, // @default 0 Rig travel (unused by position; kept for the lead's wiring).
 swimDirX: f32, // @default 0.22 The bell's up axis (rig swimDirX): the water streams the other way.
 swimDirY: f32, // @default 0.97 Rig swimDirY.
 swimDirZ: f32, // @default 0 Rig swimDirZ.
 flowX: f32, // @default 0 Integrated swim (speed_worldflow flowX): the running sum of swimDir * d(travel).
 flowY: f32, // @default 0 Integrated swim, y.
 flowZ: f32, // @default 0 Integrated swim, z.
 flow: f32, // @default 7 Medium speed per unit of travel (same as kernel_worldmotes.flow).
 phrase: f32, // @default 0 Phrase progress: slides the traces' bright stretch.
 pitch0: f32, // @default 50 Voice 0 eased pitch (bass trace).
 pitch4: f32, // @default 69 Voice 4 eased pitch (melody trace).
 env0: f32, // @default 0.1 Voice 0 envelope.
 env4: f32, // @default 0.1 Voice 4 envelope.
 camX: f32, // @default 0 Camera eye x.
 camY: f32, // @default 0.4 Camera eye y.
 camZ: f32, // @default 9 Camera eye z.
 camTX: f32, // @default 0 Camera target x.
 camTY: f32, // @default 0.2 Camera target y.
 camTZ: f32, // @default 0 Camera target z.
 camFov: f32, // @default 38 Camera vertical fov, degrees.
 stars: f32, // @default 1 Star gain.
 traces: f32, // @default 1 Hairline trace gain.
 flecks: f32, // @default 1 Foreground fleck gain.
 sky: f32, // @default 1 Gradient and crescent gain.
 env: f32, // @default 1 Environment amount (rig envGain, owner's slider, 0..2): 0 = only the creatures in black water, 2 = rich.
 backdrop: f32, // @default 1 Backdrop amount (rig backdropGain, owner's slider, 0..1): 0 = the far backdrop is black; the creatures and the water they light are untouched.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

const TAU: f32 = 6.2831853;

struct Cam { eye: vec3f, fwd: vec3f, right: vec3f, up: vec3f, tanH: f32, };
fn camera() -> Cam {
 let eye = vec3f(params.camX, params.camY, params.camZ);
 let fwd = normalize(vec3f(params.camTX, params.camTY, params.camTZ) - eye);
 let right = normalize(cross(fwd, vec3f(0.0, 1.0, 0.0)));
 return Cam(eye, fwd, right, cross(right, fwd), tan(radians(params.camFov) * 0.5));
}
// World point to frame-height coordinates (origin at the frame centre, y up); z = view depth.
fn project(c: Cam, p: vec3f) -> vec3f {
 let v = p - c.eye;
 let z = dot(v, c.fwd);
 return vec3f(vec2f(dot(v, c.right), dot(v, c.up)) / (max(z, 0.05) * 2.0 * c.tanH), z);
}

fn skyHash(p: vec3u) -> vec3f {
 var v = p * 1664525u + 1013904223u;
 v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
 v = v ^ (v >> vec3u(16u));
 v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
 return vec3f(v >> vec3u(8u)) * (1.0 / 16777216.0);
}
fn cellHash(id: vec2f, salt: u32) -> vec3f { return skyHash(vec3u(bitcast<vec2u>(vec2i(id)), salt)); }
fn vnoise(p: vec2f) -> f32 {
 let i = floor(p); let f = p - i; let u = f * f * (3.0 - 2.0 * f);
 return mix(mix(cellHash(i, 7u).x, cellHash(i + vec2f(1.0, 0.0), 7u).x, u.x), mix(cellHash(i + vec2f(0.0, 1.0), 7u).x, cellHash(i + vec2f(1.0, 1.0), 7u).x, u.x), u.y);
}
fn dirOf(lonlat: vec2f) -> vec3f {
 let cl = cos(lonlat.y);
 return vec3f(cl * sin(lonlat.x), sin(lonlat.y), -cl * cos(lonlat.x));
}

// Where the view ray leaves a sphere of radius R about C (the eye is inside it): the direction from C,
// and the distance from the eye (for the angular size of a pixel there).
fn shell(c: Cam, d: vec3f, C: vec3f, R: f32) -> vec4f {
 let o = c.eye - C;
 let b = dot(o, d);
 let t = -b + sqrt(max(b * b - (dot(o, o) - R * R), 0.0));
 return vec4f(normalize(o + d * t), t);
}
fn llOf(d: vec3f) -> vec2f { return vec2f(atan2(d.x, -d.z), asin(clamp(d.y, -1.0, 1.0))); }

// Stars at infinity: cells in (longitude, latitude), each star a sub-pixel point spread.
fn starLayer(d: vec3f, ll: vec2f, cell: f32, prob: f32, salt: u32, bLo: f32, bHi: f32, glow: f32, dens: f32, pxAng: f32, t: f32, c: Cam) -> vec3f {
 let g = ll / cell;
 let id = floor(g);
 let h = cellHash(id, salt);
 if (h.x > prob * dens) { return vec3f(0.0); }
 let k = cellHash(id, salt + 977u);
 let sd = dirOf((id + vec2f(0.2) + 0.6 * h.yz) * cell);
 let dv = d - sd;
 let dpx = length(dv) / pxAng;
 if (dpx > 40.0) { return vec3f(0.0); }
 // Magnitudes: a steep power law (many faint, very few bright), and the bright ones a little larger.
 let w = pow(k.x, 4.0);
 let b = bLo * pow(bHi / bLo, w);
 // Pass 14: `dpx` is in FULL-resolution pixels (frameU.resolution is the project's) but this pass is sampled on
 // its own, coarser grid; a spread narrower than that grid lit one block of pixels or none. So the spread is
 // never under 0.72 of this pass's own texel, and the light it spreads is (mostly) kept.
 let sigma0 = 0.45 + 0.45 * w;
 let sigma = max(sigma0, 0.72 * frameU.resolution.y / f32(textureDimensions(inputTexture).y));
 var e = exp(-dpx * dpx / (2.0 * sigma * sigma)) * pow(sigma0 / sigma, 1.5);
 // The brightest: a soft glow and a faint four-point diffraction cross along the lens axes.
 e = e + glow * w * (0.05 * exp(-dpx / 2.5) + 0.012 * exp(-dpx / 9.0));
 let tw = 1.0 + 0.25 * smoothstep(0.35, 1.0, k.y) * sin(t * (0.3 + 0.5 * k.z) + TAU * k.y);
 // Colour temperature: deep orange through white to blue-white.
 let temp = k.z;
 var col = mix(mix(vec3f(1.0, 0.58, 0.32), vec3f(1.0, 0.95, 0.88), smoothstep(0.0, 0.45, temp)), vec3f(0.62, 0.74, 1.0), smoothstep(0.55, 1.0, temp));
 // The brightest stars carry the fixed warm accent (#ffc890) in every mood.
 col = mix(col, vec3f(1.0, 0.578, 0.278), smoothstep(0.6, 0.95, k.x) * 0.7);
 return col * b * tw * e;
}

// Star dust in clusters: a dense layer of tiny points that only exists inside patchy regions, the
// glitter of the peak panels; prismatic and twinkling slowly.
fn glitter(d: vec3f, ll: vec2f, pxAng: f32, amt: f32, t: f32) -> vec3f {
 if (amt <= 0.001) { return vec3f(0.0); }
 let mask = smoothstep(0.55, 0.82, vnoise(ll * 4.0 + vec2f(11.0, 3.0)) * 0.65 + vnoise(ll * 11.0 + vec2f(2.0, 9.0)) * 0.35);
 if (mask <= 0.0) { return vec3f(0.0); }
 let cell = 0.0042;
 let g = ll / cell;
 let id = floor(g);
 let h = cellHash(id, 51u);
 if (h.x > 0.55 * mask) { return vec3f(0.0); }
 let k = cellHash(id, 52u);
 let sd = dirOf((id + vec2f(0.15) + 0.7 * h.yz) * cell);
 let dpx = length(d - sd) / pxAng;
 let sg = max(0.59, 0.72 * frameU.resolution.y / f32(textureDimensions(inputTexture).y)); // pass 14, as starLayer
 let e = exp(-dpx * dpx / (2.0 * sg * sg)) * pow(0.59 / sg, 1.5);
 let b = 0.15 + 2.2 * pow(k.x, 4.0);
 let tw = 0.55 + 0.45 * sin(t * (0.4 + 0.5 * k.y) + TAU * k.z);
 let col = mix(vec3f(1.0), hue(fract(k.z * 3.0 + t * 0.02)), 0.55);
 return col * b * tw * tw * e * amt;
}

fn hue(h: f32) -> vec3f {
 return clamp(abs(fract(h + vec3f(0.0, 0.667, 0.333)) * 6.0 - 3.0) - 1.0, vec3f(0.0), vec3f(1.0));
}

// A hairline trace: the arc through p0 with tangent tg and signed curvature k (1 / frame heights),
// from along-distance s0 to s1. Stable through k = 0 (implicit form). Returns light, already coloured.
fn trace(q: vec2f, p0: vec2f, tg: vec2f, k: f32, s0: f32, s1: f32, amt: f32, hotAt: f32, beadSeed: f32, gold: vec3f, fr: f32, t: f32) -> vec3f {
 if (amt <= 0.001) { return vec3f(0.0); }
 let n = vec2f(-tg.y, tg.x);
 let v = q - p0;
 let g = dot(v, n) - 0.5 * k * dot(v, v);
 let grad = length(n - k * v);
 let res = frameU.resolution.y;
 let dpx = g / max(grad, 1e-4) * res;
 if (abs(dpx) > 26.0 || k * dot(v, n) > 1.0) { return vec3f(0.0); }
 let s = dot(v, tg);
 let span = s1 - s0;
 let u = (s - s0) / span;
 if (u < 0.0 || u > 1.0) { return vec3f(0.0); }
 let ends = smoothstep(0.0, 0.3, u) * smoothstep(1.0, 0.55, u);
 // Hairline core, a thin glow, and at peak a thin spectral fringe either side (thin-film, not a rainbow).
 let core = exp(-dpx * dpx / 0.55) + 0.05 * exp(-abs(dpx) / 3.0);
 let fx = clamp(dpx / 7.0, -1.0, 1.0);
 let film = hue(0.72 * (0.5 + 0.5 * fx)) * exp(-pow(abs(dpx) - 2.6, 2.0) / 3.0) * 0.6 * fr;
 let hot = 0.6 + 1.2 * exp(-pow((u - hotAt) / 0.12, 2.0));
 var light = gold * core * hot + film;
 // Two tiny beads sliding slowly along; prismatic sparkle at peak.
 for (var j = 0; j < 2; j = j + 1) {
  let ub = fract(beadSeed + 0.5 * f32(j) + t * 0.012);
  let al = (u - ub) * span * res;
  let r2 = al * al + dpx * dpx;
  let bead = exp(-r2 / 2.2) * 4.0 + exp(-sqrt(r2) / 5.0) * 0.25;
  let ang = atan2(dpx, al);
  let spark = fr * pow(abs(cos(2.0 * ang)), 30.0) * exp(-sqrt(r2) / 9.0) * 1.5;
  let bw = smoothstep(0.1, 0.3, ub) * smoothstep(0.9, 0.6, ub);
  light = light + (mix(gold, vec3f(1.0), 0.5) * bead + hue(fract(ub * 3.0 + t * 0.03)) * spark) * bw;
 }
 return light * ends * amt;
}

// Out-of-focus flecks drifting past close to the lens: 3D positions in the streaming medium.
fn flecks(c: Cam, q: vec2f, t: f32) -> vec3f {
 var acc = vec3f(0.0);
 let res = frameU.resolution.y;
 let centre = c.eye + c.fwd * 2.4;
 let bs = vec3f(4.4, 2.7, 3.2);
 let drift = -vec3f(params.flowX, params.flowY, params.flowZ) * params.flow;
 let focus = max(length(vec3f(params.heroX, params.heroY, params.heroZ) - c.eye), 2.0);
 for (var k = 0; k < 14; k = k + 1) {
  let h = cellHash(vec2f(f32(k), 11.0), 81u);
  let g = cellHash(vec2f(f32(k), 13.0), 82u);
  let vis = smoothstep(f32(k) / 14.0 - 0.2, f32(k) / 14.0, 0.3 + 0.7 * params.energy);
  if (vis <= 0.0) { continue; }
  let w3 = 0.4 * vec3f(sin(t * 0.05 + g.x * TAU), sin(t * 0.04 + g.y * TAU), sin(t * 0.045 + g.z * TAU));
  let f = fract((h * bs * 7.1 + drift + w3 - centre) / bs) - 0.5;
  let pw = centre + f * bs;
  let pr = project(c, pw);
  if (pr.z < 0.45) { continue; }
  let fade = smoothstep(0.5, 0.36, abs(f.x)) * smoothstep(0.5, 0.36, abs(f.y)) * smoothstep(0.5, 0.36, abs(f.z)) * smoothstep(0.45, 1.0, pr.z);
  let rad = clamp(15.0 * (focus / pr.z - 1.0), 22.0, 170.0) / res;
  let d = length(q - pr.xy) / rad;
  if (d > 1.15) { continue; }
  let disc = smoothstep(1.0, 0.35, d);
  let rim = vec3f(0.0);
  // Cool and neutral (no warm blobs): the water's body tone, desaturated.
  let col = mix(moodColor(params.mood, 0.35 + 0.2 * g.z), vec3f(0.8, 0.85, 1.0), 0.5);
  acc = acc + (col * disc + rim) * (0.05 + 0.06 * h.x) * fade * vis * sqrt(14.0 / max(rad * res, 14.0));
 }
 return acc * (0.4 + 0.6 * params.lum);
}

@fragment fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
 let res = frameU.resolution;
 let aspect = res.x / res.y;
 let q = vec2f((uv.x - 0.5) * aspect, 0.5 - uv.y);
 let t = frameU.absTime;
 let c = camera();
 let d = normalize(c.fwd + 2.0 * c.tanH * (q.x * c.right + q.y * c.up));
 let ll = vec2f(atan2(d.x, -d.z), asin(clamp(d.y, -1.0, 1.0)));
 let pxAng = 2.0 * c.tanH / res.y;
 let neb = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb;

 // Gradient at infinity: the water is a little lighter toward the surface above, and hazy below.
 let mc = moodColor(params.mood, 0.0);
 // Charcoal navy, not saturated blue: the grade's saturation would crush a pure blue floor's R and G.
 let shadow = mix(vec3f(0.62, 0.8, 1.0), mc / max(mc.r, max(mc.g, mc.b)), 0.25);
 // A faint horizon-like haze low in the view (the reference's lower sky), which the medium's dark
 // cloud banks cut into silhouettes.
 let grad = shadow * (0.03 + 0.004 * smoothstep(-0.1, 0.6, ll.y) + 0.03 * smoothstep(0.15, -0.38, ll.y)) * params.sky;
 // The floor recedes as the creatures light up (darkness is a parameter): about -30 % at peak.
 let gradK = 1.15 - 0.45 * params.lum;

 // A small far crescent, upper left of the usual view: a thin lit rim only (no dark disc).
 let pc = dirOf(vec2f(-0.4, 0.3));
 let sh4 = shell(c, d, vec3f(1.0, 1.2, 0.0), 220.0);
 let pang = acos(clamp(dot(sh4.xyz, pc), -1.0, 1.0));
 let pr = 0.042;
 let pd = (pang - pr) / pxAng;
 let tanv = normalize(sh4.xyz - pc * dot(sh4.xyz, pc) + vec3f(1e-6));
 let lightDir = normalize(c.right * 0.7 - c.up * 0.6);
 let facing = dot(tanv, lightDir);
 var planet = exp(-pd * pd / 1.4) * smoothstep(-0.1, 0.8, facing) * 0.35;
 let occlude = smoothstep(-1.0, 1.5, pd);
 let pcol = mix(moodColor(params.mood, 0.55), vec3f(0.78, 0.84, 1.0), 0.55);

 // The points of light: far plankton on three shells (fine and many far, few and bright nearer).
 let C0 = vec3f(1.0, 1.2, 0.0);
 let sh1 = shell(c, d, C0, 150.0); let ll1 = llOf(sh1.xyz);
 let sh2 = shell(c, d, C0, 95.0); let ll2 = llOf(sh2.xyz);
 let sh3 = shell(c, d, C0, 60.0); let ll3 = llOf(sh3.xyz);
 let dens = 0.25 + 1.1 * smoothstep(0.25, 0.85, vnoise(ll2 * 3.5 + vec2f(3.1, 7.7))) + 0.9 * exp(-pow((ll2.x * 0.5 + ll2.y * 0.866 + 0.05) / 0.22, 2.0));
 var stars = starLayer(sh1.xyz, ll1, 0.0072, 0.04, 11u, 0.015, 0.5, 0.0, dens, pxAng * sh1.w / 150.0, t, c);
 stars = stars + starLayer(sh2.xyz, ll2, 0.024, 0.08, 23u, 0.1, 1.8, 1.0, dens, pxAng * sh2.w / 95.0, t, c);
 stars = stars + starLayer(sh3.xyz, ll3, 0.08, 0.11, 37u, 0.5, 7.0, 3.0, dens, pxAng * sh3.w / 60.0, t, c);
 stars = stars + glitter(sh2.xyz, ll2, pxAng * sh2.w / 95.0, smoothstep(0.45, 1.0, params.density) * (0.4 + 0.6 * params.lum), t);
 // Each mood its own water: the points take a share of the mood's highlight tone.
 let starY = dot(stars, vec3f(0.2126, 0.7152, 0.0722));
 stars = mix(stars, moodColor(params.mood, 0.8) * starY / max(dot(moodColor(params.mood, 0.8), vec3f(0.2126, 0.7152, 0.0722)), 0.05), 0.3) * params.stars;

 // Hairline traces: the path the hero has swum, and two voice currents along the wake.
 let hero = vec3f(params.heroX, params.heroY, params.heroZ);
 let q0 = project(c, hero).xy;
 let qw = project(c, hero - normalize(vec3f(params.swimDirX, params.swimDirY, params.swimDirZ) + vec3f(0.0, 1e-4, 0.0)) * 4.0).xy - q0;
 let lumF = (0.3 + 0.7 * params.lum) * params.traces;
 let fr = smoothstep(0.55, 0.95, params.lum) * smoothstep(0.2, 0.6, params.fringe);
 let gold = mix(moodColor(params.mood, 0.92), vec3f(1.0, 0.78, 0.45), 0.55);
 // (The orbit arc over the bell is gone: it read as a circle drawn around the subject.)
 var lines = vec3f(0.0);
 // Melody and bass currents: along the wake, bent by their pitch on the chromatic circle.
 let tgW = normalize(qw + vec2f(1e-4, 0.0));
 let nW = vec2f(-tgW.y, tgW.x);
 let th4 = TAU * params.pitch4 / 12.0;
 let th0 = TAU * params.pitch0 / 12.0;
 let e4 = clamp(params.env4 / 0.4, 0.0, 1.0);
 let e0 = clamp(params.env0 / 0.4, 0.0, 1.0);
 let amtB = (0.04 + 0.96 * smoothstep(0.1, 0.5, params.density)) * (0.45 + 0.55 * e4) * lumF;
 lines = lines + trace(q, q0 + tgW * 0.4 + nW * (0.14 + 0.08 * sin(th4)), tgW, 1.9 + 0.6 * cos(th4), 0.02, 0.95, amtB, fract(params.phrase + 0.4), 0.61, gold, fr, t);
 let amtC = smoothstep(0.35, 0.75, params.density) * (0.45 + 0.55 * e0) * lumF;
 lines = lines + trace(q, q0 + tgW * 0.55 - nW * (0.24 + 0.08 * cos(th0)), tgW, -(1.5 + 0.5 * sin(th0)), 0.05, 1.1, amtC, fract(params.phrase + 0.75), 0.37, gold, fr, t);

 var fl = vec3f(0.0);
 if (params.flecks > 0.001) { fl = flecks(c, q, t) * params.flecks; }
 // The medium's dust clouds (alpha of the medium pass) hide the stars and the horizon haze behind them.
 let trans = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).a;
 // (the medium arrives already scaled by the environment amount)
 let col = neb + ((grad * gradK * mix(0.25, 1.0, trans) + planet * pcol * params.sky * trans + stars * trans + lines) * params.backdrop + fl) * params.env;
 return vec4f(col, 1.0);
}

parameters.kernel:
struct Params {
 heroX: f32, // @default 1.1 Bell centre now (rig heroX).
 heroY: f32, // @default 1.45 Bell centre now (rig heroY).
 heroZ: f32, // @default 0 Bell centre now (rig heroZ).
 heroX1: f32, // @default 1.1 Where the bell was 0.7 s ago (rig heroX1).
 heroY1: f32, // @default 1.45 (rig heroY1).
 heroZ1: f32, // @default 0 (rig heroZ1).
 heroX2: f32, // @default 1.1 Where the bell was 1.4 s ago (rig heroX2).
 heroY2: f32, // @default 1.45 (rig heroY2).
 heroZ2: f32, // @default 0 (rig heroZ2).
 heroX3: f32, // @default 1.1 Where the bell was 2.1 s ago (rig heroX3).
 heroY3: f32, // @default 1.45 (rig heroY3).
 heroZ3: f32, // @default 0 (rig heroZ3).
 tiltX: f32, // @default 0 Bell lean about X, radians (rig heroTiltX); shapes only the roots.
 tiltZ: f32, // @default -0.22 Bell lean about Z, radians (rig heroTiltZ); shapes only the roots.
 scale: f32, // @default 1 Size multiplier (rig heroScale).
 pulse: f32, // @default 0 Bell contraction 0..1 (rig pulse).
 pulsePhase: f32, // @default 0 Swim-cycle phase 0..1 (rig pulsePhase); only periodic functions of it are used.
 swimRate: f32, // @default 0.567 Swim cycles per second (rig swimRate): one period sets the mean-velocity window.
 tension: f32, // @default 0.3 Stretch and twist (rig tension).
 density: f32, // @default 0.5 How much is present: arm and tentacle count, length, veil width (rig density).
 lum: f32, // @default 0.5 Illumination (rig lum).
 mood: f32, // @default 0 Palette position (rig mood).
 kick0: f32, // @default 0 Strike force at the bell (lag_herokick2.imp).
 kick1: f32, // @default 0 The same a little later and wider (lag_herokick4.imp).
 kick2: f32, // @default 0 Later still (lag_herokick5.imp): reaches the tips.
 kickS: f32, // @default 0 Slow mean of the strikes (lag_herokick7.imp): what is sustained, not new.
 rigLean: f32, // @default 0 1 = the rig's heroTiltX/Z is already the smooth travel lean: hang everything along it.
 env4: f32, // @default 0 Melody envelope (lag_env.env4): beads and rhopalia twinkle with it.
 energyS: f32, // @default 0.5 Slow musical energy (rig energy through two 1.2 s lags) plus a share of the bass envelope (lag_heronote2.bs): how deep the strokes, how open, how far they trail, how alive.
 hitAge: f32, // @default 9 Seconds since the last chord strike (rig age): a soft swell of light runs down from the root.
 nt0: f32, // @default 0 Note place 0 (pitch class 0, circle-of-fifths order) now (lag_heronote2.s0).
 nt1: f32, // @default 0 Note place 1 (pitch class 7, circle-of-fifths order) now (lag_heronote2.s1).
 nt2: f32, // @default 0 Note place 2 (pitch class 2, circle-of-fifths order) now (lag_heronote2.s2).
 nt3: f32, // @default 0 Note place 3 (pitch class 9, circle-of-fifths order) now (lag_heronote2.s3).
 nt4: f32, // @default 0 Note place 4 (pitch class 4, circle-of-fifths order) now (lag_heronote2.s4).
 nt5: f32, // @default 0 Note place 5 (pitch class 11, circle-of-fifths order) now (lag_heronote2.s5).
 nt6: f32, // @default 0 Note place 6 (pitch class 6, circle-of-fifths order) now (lag_heronote2.s6).
 nt7: f32, // @default 0 Note place 7 (pitch class 1, circle-of-fifths order) now (lag_heronote2.s7).
 nt8: f32, // @default 0 Note place 8 (pitch class 8, circle-of-fifths order) now (lag_heronote2.s8).
 nt9: f32, // @default 0 Note place 9 (pitch class 3, circle-of-fifths order) now (lag_heronote2.s9).
 nt10: f32, // @default 0 Note place 10 (pitch class 10, circle-of-fifths order) now (lag_heronote2.s10).
 nt11: f32, // @default 0 Note place 11 (pitch class 5, circle-of-fifths order) now (lag_heronote2.s11).
 nu0: f32, // @default 0 Note place 0 later, for the tips (lag_heronote3.s0).
 nu1: f32, // @default 0 Note place 1 later, for the tips (lag_heronote3.s1).
 nu2: f32, // @default 0 Note place 2 later, for the tips (lag_heronote3.s2).
 nu3: f32, // @default 0 Note place 3 later, for the tips (lag_heronote3.s3).
 nu4: f32, // @default 0 Note place 4 later, for the tips (lag_heronote3.s4).
 nu5: f32, // @default 0 Note place 5 later, for the tips (lag_heronote3.s5).
 nu6: f32, // @default 0 Note place 6 later, for the tips (lag_heronote3.s6).
 nu7: f32, // @default 0 Note place 7 later, for the tips (lag_heronote3.s7).
 nu8: f32, // @default 0 Note place 8 later, for the tips (lag_heronote3.s8).
 nu9: f32, // @default 0 Note place 9 later, for the tips (lag_heronote3.s9).
 nu10: f32, // @default 0 Note place 10 later, for the tips (lag_heronote3.s10).
 nu11: f32, // @default 0 Note place 11 later, for the tips (lag_heronote3.s11).
 leadC: f32, // @default 0 The melody note's place, cosine (lag_herochord2.lC): its filaments carry the melody's gesture.
 leadS: f32, // @default 0 The same, sine (lag_herochord2.lS).
 melF: f32, // @default 60 Top voice pitch, quick (lag_heromel2.mp).
 melS: f32, // @default 60 Top voice pitch, slow (lag_heromel3.mp): melF - melS is the melodic motion.
 teS: f32, // @default 0.3 Tension, slow mean (lag_herotens.tension): above it = rising, below it = a release.
 rC3: f32, // @default 1 Chord root on the circle of fifths, cosine, at the margin's stage (lag_herochord3.rC).
 rS3: f32, // @default 0 The same, sine (lag_herochord3.rS).
 rC4: f32, // @default 1 The same, later, for the tips (lag_herochord4.rC).
 rS4: f32, // @default 0 (lag_herochord4.rS).
 noteGain: f32, // @default 1 How strongly notes light and move their places (0 = off).
 melodyGain: f32, // @default 1 How strongly the melody's rise and fall bend the arms and lead filaments.
 tensionGain: f32, // @default 1 How strongly tension stretches and a release spreads.
 chordGain: f32, // @default 1 How far the chord root leans the colour.
 react: f32, // @default 1 The owner's music reaction strength (rig reactGain, 0..2, eased): multiplies every gain above.
};
// Oral arms: 8 sheets of a 12 x 192 grid. Sheets 0..3 are four broad frilled veils, each hanging
// from its own corner of the manubrium, billowing like a sail and fanning apart a little so they
// overlap softly instead of braiding; sheets 4..7 are narrow lace frills between them that fade in
// with density. Every veil hangs and drags slowly behind the mean swim (tent.common.wgsl). uv = (across 0..1, along 0..1). tint = (arm, presence, swell, 1).
const AC = 12u;
const AR = 192u;

// One breath per stroke, root to tip, a periodic function of the swim phase: the jet draws the arms
// together, longer and narrower just after the squeeze; in the glide they spread, shorten a little
// and billow as water refills the bell.
fn breath(c: TC, s: f32) -> f32 { return pres(c.ph - 0.12 - 0.5 * s); }
fn veilRoot(c: TC, s: f32, psi: f32) -> vec3f {
 let pa = pulseAlong(c, s);
 let r = 0.12 * (1.0 - 0.25 * breath(c, 0.0));
 return hfPos(c.f, vec3f(cos(psi) * r, BELL_Y0 + 0.16 + 0.1 * pa.x, sin(psi) * r));
}
// the notes a veil answers to: its own place and the two beside it (a veil is broad)
fn armNote(P: Params, psi: f32, s: f32) -> f32 {
 return 0.5 * (noteAt(P, psi - 0.5236, s) + noteAt(P, psi, s) + noteAt(P, psi + 0.5236, s));
}
fn veilSpine(c: TC, P: Params, k: u32, s: f32, len: f32, psi: f32, h: f32, fan: f32) -> vec3f {
 let root = veilRoot(c, s, psi);
 let br = breath(c, s);
 let kk = kickAt(c, s);
 let outL = vec3f(cos(psi), 0.0, sin(psi));
 // pass 6: the notes of its places open the veil out; a rising melody opens all four (an inhale), a
 // falling one gathers them and lets them sink; tension draws them long, a release lets them spread
 let xn = armNote(P, psi, s);
 let ud = melodyUD(P.melF, P.melS, (P.melodyGain * P.react));
 let rr = tensionRR(P.tension, P.teS, (P.tensionGain * P.react));
 // open with fuller music (slow), close a little on each stroke, open out on a strike
 // (pass 7: the melody and tension terms about doubled; at the pass-6 sizes they moved the veils by
 // about 3 % in clips and did not read)
 let fanB = fan * (0.55 + 0.9 * c.act + 0.3 * c.te) * (1.0 - 0.3 * br) * (1.0 + 0.6 * kk)
   * (1.0 + 0.5 * xn + 1.0 * ud.x - 0.45 * ud.y + 0.7 * rr.y - 0.2 * rr.x);
 let lenB = len * (1.0 + 0.02 * br + 0.04 * kk + 0.1 * ud.y - 0.06 * ud.x + 0.1 * rr.x - 0.04 * rr.y);
 let d0 = hfDir(c.fP, normalize(vec3f(outL.x * fanB, -1.0, outL.z * fanB)));
 let b1 = d0 * 0.25 * lenB;
 let b2 = b1 + normalize(c.droop + hfDir(c.fP, outL) * fanB) * 0.75 * lenB;
 var pos = root + 2.0 * s * (1.0 - s) * b1 + s * s * b2;
 // heavier than a filament: the veil drags further behind the mean swim
 pos += dragAt(c, s, len, ARM_DRAG_T * (0.85 + 0.3 * h) * (0.8 + 0.4 * c.es));
 // each veil sways in its own plane: one long lazy wave (about 0.07 Hz), growing toward the hem
 let sway = normalize(c.side * cos(psi + h) + c.side2 * sin(psi + h));
 let sway2 = normalize(cross(c.droop, sway));
 let w = TAU * ((0.45 + 0.3 * c.act) * s - 0.09 * c.t) + psi * 1.7 + h * 5.0;
 let amp = (0.09 + 0.08 * c.act) * len * pow(s, 1.3);
 pos += (sway * sin(w) + sway2 * 0.5 * cos(0.8 * w + 0.6)) * amp;
 pos += sweepAt(c, s) * len;
 return keepBelow(c, veilRoot(c, 0.0, psi), pos, s, len);
}

fn process(p: Point, ctx: PointCtx) -> Point {
 var q = p;
 let P = ctx.params;
 let per = AC * AR;
 let k = ctx.index / per;
 let r = ctx.index % per;
 let i = r % AC;
 let j = r / AC;
 let a = f32(i) / f32(AC - 1u) * 2.0 - 1.0;
 let s = f32(j) / f32(AR - 1u);
 let f = hfMake(P.heroX, P.heroY, P.heroZ, P.tiltX, P.tiltZ, P.scale);
 let c = tcMake(f, vec3f(P.heroX1, P.heroY1, P.heroZ1), vec3f(P.heroX2, P.heroY2, P.heroZ2), vec3f(P.heroX3, P.heroY3, P.heroZ3), P.swimRate, P.tiltX, P.tiltZ, pulseEnv(P.pulsePhase), P.pulsePhase, P.tension, P.density, ctx.absTime, vec3f(P.kick0, P.kick1, P.kick2), P.energyS, P.kickS, P.rigLean);
 let primary = k < 4u;
 let h = stableRand(k, 43u);
 // veils at four corners turned off the camera axis so none hangs edge-on; frills between them
 let psi = f32(k % 4u) / 4.0 * TAU + select(TAU / 8.0 + 0.6, 0.6, primary) + 0.3 * (h - 0.5);
 let len = select(1.7, 2.6, primary) * (0.8 + 0.4 * P.density) * (0.85 + 0.3 * h) * (1.0 + 0.15 * P.tension) * f.k;
 let fan = select(0.1, 0.18, primary);
 let ds = 0.01;
 let spine = veilSpine(c, P, k, s, len, psi, h, fan);
 let T = normalize(veilSpine(c, P, k, min(s + ds, 1.0), len, psi, h, fan) - veilSpine(c, P, k, max(s - ds, 0.0), len, psi, h, fan));
 // width runs round the bell axis (the veil faces outward), turning a quarter-turn or so down its
 // length and drifting slowly, so its broad face catches the eye
 let tang = hfDir(c.fP, vec3f(-sin(psi), 0.0, cos(psi)));
 let W0 = normalize(tang - T * dot(tang, T));
 let N0 = cross(T, W0);
 // tension twists the veils further as it rises (pass 6)
 let tw = (0.45 + 0.6 * P.tension + 0.5 * tensionRR(P.tension, P.teS, (P.tensionGain * P.react)).x) * s + 0.25 * sin(ctx.absTime * 0.25 + h * 6.0) * s;
 let W = W0 * cos(tw) + N0 * sin(tw);
 let Nn = cross(T, W);
 // broad at medium and peak: a veil about half a bell wide, opening below the manubrium
 let width = select(0.07, 0.21 + 0.16 * P.density, primary) * f.k
   * (0.45 + 0.55 * smoothstep(0.0, 0.25, s)) * (1.0 - 0.35 * s) * (1.0 + 0.12 * sin(s * 7.0 + h * 9.0));
 // billow: the veil cups like a sail, flattening as each pressure wave passes down it
 let br = breath(c, s);
 let billow = width * 0.34 * (1.0 - a * a) * (0.6 + 0.25 * (1.0 - br) + 0.4 * c.act + 0.3 * kickAt(c, s));
 // lettuce hems: the edge is longer than the middle, so it waves (shape only; it moves slowly)
 let edge = smoothstep(0.3, 1.0, abs(a));
 let sl = s * len;
 let rw = TAU * sl + a * 2.0 + h * 7.0 - ctx.absTime * 0.2;
 let ramp = 0.3 + 0.7 * (0.5 + 0.5 * sin(sl * 1.3 + h * 5.0) * sin(sl * 0.71 + h * 2.0 + 1.0));
 let ruffle = width * ramp * (0.07 * pow(edge, 3.0) * sin(rw * 3.1) + 0.05 * pow(edge, 2.5) * sin(rw * 5.3 + 2.1 + h * 3.0)
   + 0.035 * pow(edge, 2.0) * sin(rw * 8.9 + 0.7 + a * 1.3));
 // two soft pleats across the veil that drift slowly
 let pleat = width * 0.08 * sin(a * 3.6 + s * 4.0 + h * 4.0 - ctx.absTime * 0.2);
 q.position = spine + W * a * width * (1.0 - 0.12 * br) + Nn * (billow + ruffle + pleat);
 q.uv = vec2f(a * 0.5 + 0.5, s);
 let presence = select(smoothstep(0.15, 0.65, P.density), 1.0, primary);
 // light swell: the swim pressure and each chord strike run down from the root
 let swell = 0.4 * pres(P.pulsePhase - 0.12 - 0.6 * s) + 1.3 * softPos(rippleAt(c.kick, s)) + 1.0 * armNote(P, psi, s);
 // w: the chord change's ripple here, for its colour in the material
 q.tint = vec4f(f32(k), presence, swell, waveAt(P, s));
 return q;
}
// ---- hero common (kernels): frame, pulse envelope, bell profile, trail ----
const TAU = 6.2831853;
// The bell in its own frame: rim radius 1, up +y, rim (margin) plane at BELL_Y0, apex BELL_H above it.
// World = hero position + rotZ(tiltZ) * rotX(tiltX) * (local * heroScale).
// A flattened dome (the boards: height/width about 0.38 for the dome, 0.45 with the lappets): the profile
// stops at 79 degrees, so the shoulders slope into the rim and never stand as a vertical wall; 16
// rounded lappets hang LAP_LEN below the rim.
const BELL_H = 0.64;
const BELL_Y0 = -0.35;
const BELL_THMAX = 1.38;
const BELL_VM = 0.9;       // exumbrella: v of the rim (ring canal); the lappets hang over VM..1
const LAP_LEN = 0.14;

struct HF { o: vec3f, ca: f32, sa: f32, cb: f32, sb: f32, k: f32, };
fn hfMake(x: f32, y: f32, z: f32, tx: f32, tz: f32, k: f32) -> HF {
 return HF(vec3f(x, y, z), cos(tx), sin(tx), cos(tz), sin(tz), k);
}
fn hfDir(f: HF, d: vec3f) -> vec3f {
 let y1 = d.y * f.ca - d.z * f.sa;
 let z1 = d.y * f.sa + d.z * f.ca;
 return vec3f(d.x * f.cb - y1 * f.sb, d.x * f.sb + y1 * f.cb, z1);
}
fn hfPos(f: HF, p: vec3f) -> vec3f { return f.o + hfDir(f, p * f.k); }

// The stroke, as a periodic function of the swim phase (the cycle is about 3.5 s): a slow full
// contraction over 30 % of it, a release over 40 %, then a 30 % glide at rest. Every geometric use of
// the swim reads this (the bell body too), so the bell and everything lagging it agree.
// the warm accent: one peach-gold for cores, canals, glints and beads in every mood
const ACC = vec3f(1.0, 0.66, 0.36);
fn smoother(a: f32, b: f32, x: f32) -> f32 {
 let t = clamp((x - a) / (b - a), 0.0, 1.0);
 return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}
fn pulseEnv(ph: f32) -> f32 {
 let x = fract(ph);
 return smoother(0.0, 0.3, x) * (1.0 - smoother(0.3, 0.7, x));
}
// A chord strike as a FORCE: the rig's strike age drives a short impulse through a chain of hero
// lag nodes; k.x (lag_herokick2) is the response at the bell, k.y (4) later and wider, k.z (5) later
// still, kS (7) a very slow mean of the same impulse. The RIPPLE is what is new: each response minus
// the slow mean, normalised so one isolated strike peaks near 1, softly limited, so a train of strikes
// does not hold the appendages splayed: each new strike still adds a travelling ripple, and the
// sustained part becomes a small, saturating STEADY opening.
fn kickRipple(k: vec3f, kS: f32) -> vec3f {
 let g = vec3f(2.0, 4.0, 5.5);
 let x = (k - vec3f(kS)) * g;
 return x / sqrt(vec3f(1.0) + x * x);
}
fn kickSteady(kS: f32) -> f32 { return 0.35 * (1.0 - exp(-2.5 * kS)); }
// positive part, smoothly (light and flares only grow)
fn softPos(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.0004)); }
// the margin flares a little with the strike (bell and tentacle roots must agree)
fn marginFlare(lp: vec3f, v: f32, k0: f32) -> vec3f {
 let g = 1.0 + 0.035 * k0 * smoothstep(0.75, 1.0, v);
 return vec3f(lp.x * g, lp.y, lp.z * g);
}

// Soft swim pressure: a raised cosine at the swim frequency, peaking with the contraction (phase 0.28).
// Lagged copies of it run down arms and tentacles as a gentle pressure wave, never a wiggle.
fn gaussK(x: f32) -> f32 { return exp(-x * x); }
// the strike ripple as felt at s along anything (0 the bell, 1 the tips), continuous in time and space
fn rippleAt(r: vec3f, s: f32) -> f32 {
 return mix(mix(r.x, r.y, smoother(0.0, 0.5, s)), r.z, smoother(0.5, 1.0, s));
}
fn pres(ph: f32) -> f32 { return 0.5 + 0.5 * cos(TAU * (ph - 0.28)); }
// Contraction felt at bell parameter v (0 apex, 1 lappet tips): the body follows pulse, the margin
// lags 0.06 of a cycle, the lappets 0.1, so the rim trails the squeeze and re-opens late.
// D is the stroke depth (fuller with louder music, set slowly).
fn bellPulseAt(v: f32, pl: f32, ph: f32, D: f32) -> f32 {
 let pm = pulseEnv(ph - 0.06) * D;
 let plap = pulseEnv(ph - 0.1) * D;
 return mix(pl, mix(pm, plap, smoothstep(0.86, 1.0, v)), smoothstep(0.55, 1.0, v));
}
fn strokeDepth(es: f32) -> f32 { return 0.75 + 0.4 * es; }
// The stroke's amplitude, softly limited to 1 (pass 6). A hard min(.., 1) on depth x strike clipped the
// top of the contraction inside a stroke whenever the music was full: a kink in its speed, seen as a
// light step at the stroke's peak (Clair 70.6 s, 88.1 s). Bell, filament roots and rhopalia all use it.
fn strokeAmp(a: f32) -> f32 { return a / pow(1.0 + pow(max(a, 0.0), 8.0), 0.125); }

fn bellSqueeze(v: f32, pm: f32) -> f32 {
 return 1.0 - 0.2 * pm * pow(smoothstep(0.12, 1.0, v), 1.3);
}
// Exumbrella point. p: body contraction, pm: (lagged) margin contraction, te: tension.
// the dome's height profile, 1 at the apex and 0 at the rim (slightly flattened top)
fn domeY(th: f32) -> f32 {
 let cm = pow(cos(BELL_THMAX), 0.88);
 return (pow(max(cos(th), 0.0), 0.88) - cm) / (1.0 - cm);
}
fn bellExo(phi: f32, v: f32, p: f32, pm: f32, te: f32) -> vec3f {
 let vd = min(v / BELL_VM, 1.0);
 let th = vd * BELL_THMAX;
 // a contraction closes the rim and lengthens the dome a little: it stays a dome (h/w under 0.6)
 let h = BELL_H * (1.0 + 0.12 * p + 0.06 * te);
 let rib = 1.0 + 0.022 * (0.5 + 0.5 * cos(16.0 * phi)) * smoothstep(0.08, 0.5, vd) * (1.0 - smoothstep(0.8, 0.95, vd));
 let wave = (0.025 * sin(8.0 * phi + 0.7) + 0.01 * sin(13.0 * phi + 2.0)) * smoothstep(0.6, 1.0, vd);
 var r = sin(th) / sin(BELL_THMAX) * bellSqueeze(vd, pm) * rib;
 var y = BELL_Y0 - 0.04 * pm * smoothstep(0.5, 1.0, vd) + h * domeY(th);
 if (v > BELL_VM) {
  // the lappets hang from the rim: flared a little outward at rest, curled in by the squeeze
  let s = (v - BELL_VM) / (1.0 - BELL_VM);
  r = r + s * LAP_LEN * (0.45 - 0.9 * pm) * bellSqueeze(1.0, pm);
  y = y - s * LAP_LEN * (0.9 + 0.2 * pm);
 }
 return vec3f(cos(phi) * r, y + wave, sin(phi) * r);
}

// Frame-independent per-id random in [0, 1). The built-in pointRand re-rolls EVERY FRAME (it hashes the
// frame index), so it must never shape geometry: that reads as high-frequency jitter in playback.
fn stableRand(id: u32, salt: u32) -> f32 {
 var x = id * 747796405u + salt * 2891336453u + 12345u;
 x = (x ^ (x >> 15u)) * 2246822519u;
 x = (x ^ (x >> 13u)) * 3266489917u;
 x = x ^ (x >> 16u);
 return f32(x >> 8u) * (1.0 / 16777216.0);
}
// ---- hero appendages in water (shared by tentacle beams, beads and oral arms) ----
// They HANG: almost passive, a slow curtain dragged behind the swim and swaying over many seconds.
// Point s = the root on the bell (rigidly attached, in the bell's own frame) + a hanging shape
// (gravity and a slow down-left current, leaning with the path) + a slow DRAG opposite the bell's
// mean velocity, growing toward the tip. The mean velocity is taken over one swim period (the bell
// now vs where it was one period, about 1.76 s, ago), so the surge of each thrust cancels out and
// is never replayed down the appendages; it is used as a vector that shrinks to nothing as the bell
// slows (never normalised), so the trail eases back to the rest hang. Each contraction sends one
// soft, slow bulge down them; chord strikes change only their light. Nothing may rise above its
// own root along the bell's axis (keepBelow).
const NT = 48u;            // tentacles
const DRAG_T = 4.0;        // tentacles: seconds of mean drift by which a tip trails
const ARM_DRAG_T = 5.5;    // oral arms: broad veils catch more water
struct TC { f: HF, fP: HF, h0: vec3f, vbar: vec3f, droop: vec3f, side: vec3f, side2: vec3f, pl: f32, ph: f32, te: f32, de: f32, t: f32, kick: vec3f, es: f32, steady: f32, act: f32, };

// the bell's path u steps of 0.7 s ago (u in 1..3), straight between the rig's samples (no overshoot)
fn pathBack(h1: vec3f, h2: vec3f, h3: vec3f, u: f32) -> vec3f {
 if (u < 2.0) { return mix(h1, h2, clamp(u - 1.0, 0.0, 1.0)); }
 return mix(h2, h3, clamp(u - 2.0, 0.0, 1.0));
}

fn tcMake(f: HF, h1: vec3f, h2: vec3f, h3: vec3f, rate: f32, tx: f32, tz: f32, pl: f32, ph: f32, te: f32, de: f32, t: f32, kick: vec3f, es: f32, kS: f32, rl: f32) -> TC {
 // mean velocity: the least-squares slope through the four samples (now, 0.7, 1.4, 2.1 s ago), far
 // less sensitive to the surge inside a stroke than a two-point difference
 let vbar = (1.5 * f.o + 0.5 * h1 - 0.5 * h2 - 1.5 * h3) / (5.0 * 0.7);
 // the bell's own axis with the per-stroke rocking taken out: the rig leans the bell by its 0.7 s
 // velocity; swap that for the period-mean velocity (same lean law), keep everything else it does
 // (with rigLean = 1 the rig's tilt already is that smooth lean, and everything hangs along it as is)
 let v07 = (f.o - h1) / 0.7;
 let swap = select(1.0, 0.0, rl > 0.5);
 let fP = hfMake(f.o.x, f.o.y, f.o.z, tx - 0.5 * (v07.z - vbar.z) * swap, tz + 1.6 * (v07.x - vbar.x) * swap, f.k);
 // appendages hang along that axis (no sideways current of their own)
 let droop = hfDir(fP, vec3f(0.0, -1.0, 0.0));
 let side = normalize(cross(droop, vec3f(0.0, 0.0, 1.0)));
 let side2 = normalize(cross(droop, side));
 // activity: slow musical energy plus how busy the strikes have been (both eased), 0 calm .. 1 full
 let steady = kickSteady(kS);
 let act = clamp(0.75 * es + 1.2 * steady, 0.0, 1.0);
 return TC(f, fP, f.o, vbar, droop, side, side2, pl, ph, te, de, t, kickRipple(kick, kS), es, steady, act);
}
// trail opposite the mean velocity, growing toward the tip, softly limited (no normalising)
fn dragAt(c: TC, s: f32, len: f32, secs: f32) -> vec3f {
 let d = -c.vbar * secs * pow(s, 1.5);
 let limit = 0.35 * len;
 return d / sqrt(1.0 + dot(d, d) / (limit * limit));
}
// never above the root along the bell's axis: a point at s hangs at least 10 % of its arclength below
fn keepBelow(c: TC, root: vec3f, p: vec3f, s: f32, len: f32) -> vec3f {
 let up = hfDir(c.f, vec3f(0.0, 1.0, 0.0));
 let along = dot(p - root, up);
 let floorA = -0.1 * s * len;
 let w = 0.08 * len * s + 1e-4;
 let hh = clamp(0.5 + 0.5 * (floorA - along) / w, 0.0, 1.0);
 let sm = mix(floorA, along, hh) - w * hh * (1.0 - hh);
 return p + up * (sm - along);
}
fn tentPhi(ti: u32) -> f32 {
 return (f32(ti) + 0.5 + 0.55 * (stableRand(ti, 11u) - 0.5)) / f32(NT) * TAU;
}
// active share of the tentacles: about 24 at density 0, all 48 at density 1 (unused ones fade)
fn tentActive(ti: u32, de: f32) -> f32 {
 let rank = stableRand(ti, 17u);
 return 1.0 - smoothstep(0.5 + 0.5 * de - 0.06, 0.5 + 0.5 * de + 0.02, rank);
}
fn tentLength(c: TC, ti: u32) -> f32 {
 return (1.2 + 3.0 * pow(stableRand(ti, 13u), 1.4)) * (0.85 + 0.3 * c.de) * (1.0 + 0.12 * c.te) * c.f.k;
}
// the bell's contraction as felt at s along an appendage: exact at the root, then the same envelope at
// a later phase, damped (a soft pressure wave). Returns (body pulse, margin pulse, phase used).
fn pulseAlong(c: TC, s: f32) -> vec3f {
 let lagc = 0.6 * s;
 let att = exp(-1.8 * s);
 let D = strokeDepth(c.es);
 let k0 = (c.kick.x + c.steady) * att;
 let ps = pulseEnv(c.ph - lagc) * strokeAmp(D * (1.0 + 0.2 * k0)) * att;
 let pm = bellPulseAt(0.9, ps, c.ph - lagc, D) * att;
 return vec3f(ps, pm, c.ph - lagc);
}
// the slow sweep of the whole hanging bundle (shared by tentacles and arms), travelling tipward
fn sweepAt(c: TC, s: f32) -> vec3f {
 let a = TAU * (0.05 * c.t - 0.35 * s);
 return (c.side * sin(a) + c.side2 * 0.5 * sin(a * 0.7 + 1.9)) * (0.12 + 0.14 * c.act) * s * s;
}
// the strike as felt at s: the bell's response at the root, later and wider responses toward the tip
fn kickAt(c: TC, s: f32) -> f32 { return rippleAt(c.kick, s) + c.steady; }
fn tentRoot(c: TC, phi: f32, s: f32) -> vec3f {
 let pa = pulseAlong(c, s);
 let k0 = (c.kick.x + c.steady) * exp(-1.8 * s);
 return hfPos(c.f, marginFlare(bellExo(phi, 0.9, pa.x, pa.y, c.te), 0.9, k0) * vec3f(0.965, 1.0, 0.965));
}
fn tentPoint(c: TC, ti: u32, s: f32) -> vec3f {
 let phi = tentPhi(ti);
 let h1 = stableRand(ti, 12u);
 let h2 = stableRand(ti, 14u);
 // root on the margin, squeezing with it (the squeeze reaches further points later and weaker)
 let anchor = tentRoot(c, phi, s);
 let outL = vec3f(cos(phi), 0.0, sin(phi));
 // one soft slow bulge per contraction, travelling down
 let pp = pres(c.ph - 0.1 - 0.6 * s);
 // loud passages open the whole curtain, quiet ones draw it in (slow)
 let spread = (0.16 + 0.2 * h1) * (0.7 + 0.7 * c.act) - 0.04 * pp;
 let d0 = hfDir(c.fP, normalize(vec3f(outL.x * spread, -1.0, outL.z * spread)));
 let len = tentLength(c, ti);
 let bendL = vec3f(cos(phi + 1.6 * (h2 - 0.5)), 0.0, sin(phi + 1.6 * (h2 - 0.5)));
 let b1 = d0 * 0.22 * len + hfDir(c.fP, bendL) * (0.04 + 0.08 * h2) * len;
 let b2 = b1 + normalize(c.droop + hfDir(c.fP, outL) * (0.05 + 0.12 * h1)) * 0.78 * len;
 var pos = anchor + 2.0 * s * (1.0 - s) * b1 + s * s * b2;
 // slow drag behind the mean swim
 pos += dragAt(c, s, len, DRAG_T * (0.8 + 0.4 * h2) * (0.8 + 0.4 * c.es));
 // always alive: a long slow undulation (about one wave every 9 s), larger when the music is fuller,
 // under a slower sweep the whole curtain shares (one every 20 s), travelling down it
 // the music shapes it through amplitude and (a little) wavelength, never its rate: calm = long lazy
 // waves, busy = fuller and livelier
 let w = TAU * ((0.55 + 0.35 * c.act) * s - 0.11 * c.t) + phi * 3.0 + h1 * 6.0;
 let amp = (0.06 + 0.1 * c.act) * len * pow(s, 1.5);
 pos += (c.side * sin(w) + c.side2 * 0.6 * cos(0.8 * w + 1.3)) * amp;
 pos += sweepAt(c, s) * len;
 // the bulge: the bundle breathes out a hair as it passes
 pos += hfDir(c.fP, outL) * 0.012 * len * sin(3.14159 * s) * pp;
 // a strike: the filaments flare outward and stretch back along the trail, as a slow wave tipward
 pos += (hfDir(c.fP, outL) * 0.7 + c.droop * 0.5) * 0.11 * len * sin(3.14159 * min(s * 1.1, 1.0) * 0.5) * kickAt(c, s);
 return keepBelow(c, tentRoot(c, phi, 0.0), pos, s, len);
}
// ---- hero only: the music as characters (pass 6). Not part of the shared family. ----
// Twelve places round the bell, one per pitch class in circle-of-fifths order: sector k holds pitch class
// 7k mod 12, so a fifth is a neighbour and a triad is always the same small shape (root, its neighbour,
// and the third four places round). A note lights and moves its own place; a chord shows as the set of
// places its tones hold. The values per sector come from expression_herochord through lags (two 0.3 s
// stages with a four times slower release: S-shaped onset, seconds of decay; one more 0.8 s stage for
// the tips), so nothing here can step.
fn noteSecW(x: f32, k: f32) -> f32 {
 let d = abs(fract((x - k) / 12.0 + 0.5) - 0.5) * 12.0;   // distance in sectors, wrapped
 return 1.0 - smoother(0.3, 0.7, d);                       // a plateau per sector, soft 0.4-sector seams
}
fn secW4(x: f32, k0: f32) -> vec4f {
 return vec4f(noteSecW(x, k0), noteSecW(x, k0 + 1.0), noteSecW(x, k0 + 2.0), noteSecW(x, k0 + 3.0));
}
// the twelve sector values (a = sectors 0..3, b = 4..7, c = 8..11) as felt at bell azimuth phi
fn secSum(a: vec4f, b: vec4f, c: vec4f, phi: f32) -> f32 {
 let x = fract(phi / TAU) * 12.0;
 return dot(a, secW4(x, 0.0)) + dot(b, secW4(x, 4.0)) + dot(c, secW4(x, 8.0));
}
// where in its sector an azimuth lies, -0.5 .. 0.5 (a sector's filaments fan apart from its centre)
fn secOffset(phi: f32) -> f32 { return fract(fract(phi / TAU) * 12.0 + 0.5) - 0.5; }
// soft limit: many notes on one place never add up to more than about one
fn noteSoft(x: f32) -> f32 { return x / sqrt(1.0 + x * x); }
// melodic motion: the top voice's pitch through a quick and a slow lag; their difference (semitones)
// is a damped force, up > 0. Returns (rising, falling), each 0..1, softly limited.
fn melodyUD(melF: f32, melS: f32, g: f32) -> vec2f {
 let m = g * (melF - melS) / 4.0;
 return vec2f(noteSoft(softPos(m)), noteSoft(softPos(-m)));
}
// tension against its own slow mean: (rising, releasing), each 0..1. A release is the exhale.
fn tensionRR(teF: f32, teS: f32, g: f32) -> vec2f {
 let d = g * 5.0 * (teF - teS);
 return vec2f(noteSoft(softPos(d)), noteSoft(softPos(-d)));
}
// the chord root on the circle of fifths leans the palette (a hue change of the whole animal); the lean
// reaches the heart first and the margin, then the tips, later (lag_herochord2, 3, 4)
fn chordLean(r: vec2f, g: f32) -> f32 { return g * (0.25 * r.x + 0.15 * r.y); }
// A chord change as a wave with duration: differences of successive stages of the strike response
// (lag_herokick2 - 4, 4 - 5, 5 - 7; every stage is at least second order, so every difference starts
// with zero slope), normalised so one strike peaks near 1 at the heart (about 0.6 s after it), half way
// out (1.3 s) and at the margin and down the appendages (2.4 s). A train of strikes overlaps into a
// gentle shimmer, never a sum. (A first-order stage here, lag_herokick6, dropped the margin's light the
// instant a strike began and then stopped dead at zero: a light step 0.1 s after every strike.)
fn softKnee(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.01)); }
fn chordWave(k0: f32, k1: f32, k2: f32, kS: f32, g: f32) -> vec3f {
 let w = vec3f(3.0 * (k0 - k1), 10.0 * (k1 - k2), 15.0 * (k2 - kS));
 return g * vec3f(noteSoft(softKnee(w.x)), noteSoft(softKnee(w.y)), noteSoft(softKnee(w.z)));
}
// ---- hero appendages only (pass 6): notes, melody and tension as forces on the hanging curtain ----
// The twelve note places at the root stage (lag_heronote2) and the later tip stage (lag_heronote3).
fn ntNow(P: Params, phi: f32) -> f32 {
 return secSum(vec4f(P.nt0, P.nt1, P.nt2, P.nt3), vec4f(P.nt4, P.nt5, P.nt6, P.nt7), vec4f(P.nt8, P.nt9, P.nt10, P.nt11), phi);
}
fn ntLate(P: Params, phi: f32) -> f32 {
 return secSum(vec4f(P.nu0, P.nu1, P.nu2, P.nu3), vec4f(P.nu4, P.nu5, P.nu6, P.nu7), vec4f(P.nu8, P.nu9, P.nu10, P.nu11), phi);
}
// the note force at s along an appendage hanging at azimuth phi: the root feels the first stage, the
// tip the later one, so a strike travels down (0..about 1)
fn noteAt(P: Params, phi: f32, s: f32) -> f32 {
 return (P.noteGain * P.react) * noteSoft(mix(ntNow(P, phi), ntLate(P, phi), smoother(0.1, 0.9, s)));
}
// the palette lean of the chord root along an appendage: the margin's stage at the root, later at the tip
fn leanAt(P: Params, s: f32) -> f32 {
 return chordLean(mix(vec2f(P.rC3, P.rS3), vec2f(P.rC4, P.rS4), smoother(0.0, 1.0, s)), (P.chordGain * P.react));
}
// the chord's own colour: the root's place on the circle of fifths picks among four hues of the next
// two palettes, all cool against the warm body and lines (deep-blue mood: aqua, cyan, teal, blue), so
// neighbouring chords differ and the
// same root always returns in the same colour (as on the bell)
fn hl(c: vec3f) -> vec3f { return c / max(max(c.r, c.g), max(c.b, 0.05)); }
fn chordHue(md: f32, r: vec2f) -> vec3f {
 let w = max(vec4f(r.x, r.y, -r.x, -r.y), vec4f(0.0));
 let a = hl(moodColor(md + 1.0, 0.5));
 let b = hl(moodColor(md + 2.0, 0.95));
 let c = hl(moodColor(md + 1.0, 0.25));
 let d = hl(moodColor(md + 2.0, 0.6));
 // while a far root change passes the lagged direction through the centre, ease to the mean hue (pass 7)
 let sw = w.x + w.y + w.z + w.w;
 return (w.x * a + w.y * b + w.z * c + w.w * d + max(0.6 - sw, 0.0) * 0.25 * (a + b + c + d)) / max(sw, 0.6);
}
fn waveColAt(P: Params, s: f32) -> vec3f {
 return chordHue(P.mood + leanAt(P, s), mix(vec2f(P.rC3, P.rS3), vec2f(P.rC4, P.rS4), smoother(0.0, 1.0, s)));
}
// the chord-change wave at s along an appendage: the half-way stage at the root, the margin's stage below
fn waveAt(P: Params, s: f32) -> f32 {
 let w = chordWave(P.kick0, P.kick1, P.kick2, P.kickS, (P.chordGain * P.react));
 return mix(w.y, w.z, smoother(0.0, 0.6, s));
}
// A tentacle point with the music's gestures (the tentacle beams and the beads on them share it). All
// offsets are outward, sideways or down and grow from nothing at the root; keepBelow holds again.
fn heroTentPoint(c: TC, P: Params, ti: u32, s: f32) -> vec3f {
 let phi = tentPhi(ti);
 let len = tentLength(c, ti);
 var pos = tentPoint(c, ti, s);
 let out = hfDir(c.fP, vec3f(cos(phi), 0.0, sin(phi)));
 let tang = hfDir(c.fP, vec3f(-sin(phi), 0.0, cos(phi)));
 // a note: the filaments of its place flare out and fan apart from the place's centre
 let x = noteAt(P, phi, s);
 pos += (out * 0.08 + tang * 0.1 * secOffset(phi) + c.droop * 0.02) * len * sin(1.5708 * s) * x;
 // the melody: the filaments at the melody note's place curl out as the line rises, in as it falls
 let ud = melodyUD(P.melF, P.melS, (P.melodyGain * P.react));
 let lead = smoothstep(0.6, 1.0, dot(vec2f(cos(phi), sin(phi)), vec2f(P.leadC, P.leadS)));
 pos += out * (0.22 * ud.x - 0.14 * ud.y) * len * s * s * lead;
 // tension draws the curtain long; a release lets it spread (the exhale)
 let rr = tensionRR(P.tension, P.teS, (P.tensionGain * P.react));
 pos += (c.droop * 0.1 * rr.x - out * 0.04 * rr.x + out * 0.13 * rr.y) * len * s;
 return keepBelow(c, tentRoot(c, phi, 0.0), pos, s, len);
}
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}

