// @use hash
// Companion bell: the hero's bell material (M/hero/bell.material.wgsl, pass 5) at lower detail, so a companion is the
// same animal: a filled saturated glass dome ("jewel" body, brightest at the shoulders), a thin rim in the glass colour,
// a thin film tied to the palette (no rainbow), 16 canals that branch toward peak, the ring canal, 16 lappets with
// warm edges, a warm crown scatter, four warm lace gonad loops and a small hot heart; the lines carry the music, the
// panels barely brighten. A note's light is the travelling glow (packed in tint.x's fraction), never a whole-body flash.
// Then the companions' own distance: atmospheric depth toward the palette's shadow tone and the gain (tint.y).
// tint = (sheet + 4 * companion + 0.45 * glow, gain, fog, contraction).
struct Params {
 lum: f32, // @default 0.5 Illumination (rig lum).
 mood: f32, // @default 0 Palette position (rig mood).
 tension: f32, // @default 0.3 Thin-film phase shift (rig tension).
};
const TAU = 6.2831853;
const VM = 0.9;

fn vnoise(p: vec2f, px: i32, seed: u32) -> f32 {
 let i = floor(p);
 let f = p - i;
 let w = f * f * (3.0 - 2.0 * f);
 let ix = i32(i.x);
 let iy = i32(i.y);
 let x0 = ((ix % px) + px) % px;
 let x1 = (((ix + 1) % px) + px) % px;
 let a = unitFloat(hash2i(vec2i(x0, iy), seed));
 let b = unitFloat(hash2i(vec2i(x1, iy), seed));
 let c = unitFloat(hash2i(vec2i(x0, iy + 1), seed));
 let d = unitFloat(hash2i(vec2i(x1, iy + 1), seed));
 return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}
fn gauss(x: f32) -> f32 { return exp(-x * x); }
fn satn(c: vec3f) -> vec3f { return c / max(max(c.r, c.g), max(c.b, 0.05)); }
fn vivid(c: vec3f, k: f32) -> vec3f { let y = dot(c, vec3f(0.2126, 0.7152, 0.0722)); return max(mix(vec3f(y), c, k), vec3f(0.0)); }
fn filmPal(m: f32, ph: f32) -> vec3f {
 let c = cos(TAU * ph);
 return satn(mix(moodColor(m, 0.5 + 0.5 * c), moodColor(m + 1.0, 0.6 + 0.4 * cos(TAU * ph + 2.1)), 0.28));
}
fn aaLine(d: f32, w: f32, aa: f32) -> f32 { return 1.0 - smoothstep(w, w + aa, d); }
fn radial(x: f32) -> f32 { return abs(fract(x + 0.5) - 0.5); }
fn atmos(e: vec3f, fog: f32, mood: f32) -> vec3f {
 let sh = moodColor(mood, 0.06);
 let tone = mix(vec3f(1.0), sh / max(dot(sh, vec3f(0.3, 0.5, 0.2)), 0.05), 0.75);
 return mix(e, tone * dot(e, vec3f(0.3, 0.5, 0.2)), 0.8 * fog);
}

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
 var o = surfaceDefaults(s);
 o.albedo = vec4f(0.0, 0.0, 0.0, 1.0);
 let idf = floor(s.tint.x + 1e-3);
 let id = i32(idf);
 let sheet = id % 4;
 let gl = clamp((s.tint.x - idf) / 0.45, 0.0, 1.0);
 let gain = s.tint.y;
 let fog = s.tint.z;
 let pl = s.tint.w;
 let uv = s.uv;
 let du = max(fwidth(uv.x), 1e-5);
 let dv = max(fwidth(uv.y), 1e-5);
 let N = normalize(s.normal);
 let V = normalize(s.eye - s.world);
 let ndv = dot(N, V);
 let front = ndv > 0.0;
 let Nf = select(-N, N, front);
 let nv = abs(ndv);
 let fres = 1.0 - nv;
 let L = p.lum;
 let md = p.mood;
 let ACC = vec3f(1.0, 0.66, 0.36);
 let warm = mix(ACC, moodColor(md, 0.92), 0.2);
 let gold = mix(ACC, ACC * ACC, 0.5);
 let ember = gold * gold;
 let body = moodColor(md, 0.32);
 let lilac = moodColor(md, 0.5);
 let deep = moodColor(md, 0.1);
 let jewel = satn(mix(body, lilac, 0.25));
 let t = s.absTime;
 var e = vec3f(0.0);
 if (sheet == 0) {
  // ---- exumbrella: a filled glassy dome (the hero's, lower detail) ----
  let vd = min(uv.y / VM, 1.0);
  let mott = vnoise(vec2f(uv.x * 32.0, uv.y * 10.0 + f32(id)), 32, 3u);
  let rimThin = pow(fres, 6.0);
  let rimSoft = pow(fres, 2.6);
  let thick = 0.5 + 0.3 * mott + 0.4 * p.tension + 0.25 * uv.y + 0.07 * f32(id / 4);
  let cosT = sqrt(max(1.0 - (1.0 - nv * nv) / 1.77, 0.0));
  let fc = mix(filmPal(md, thick * 2.0 * cosT), vec3f(1.0), 0.12);
  let Rf = reflect(-V, Nf);
  let band = gauss((Rf.y - 0.25) / 0.22);
  let win = pow(max(dot(Rf, normalize(vec3f(-0.55, 0.8, -0.1))), 0.0), 30.0);
  let env = 0.06 + 0.3 * smoothstep(-0.2, 1.0, Rf.y) + 0.5 * band + 2.2 * win;
  let mean = 0.03 * sin(uv.y * 9.0 + floor(uv.x * 16.0) * 1.7);
  let c1 = aaLine(radial(uv.x * 16.0 + mean), 0.009 + 0.007 * L, du * 16.0) * smoothstep(0.05, 0.22, vd);
  let grow = smoothstep(0.35, 0.9, L);
  let b1w = 0.22 * (vnoise(vec2f(uv.x * 32.0, vd * 3.0), 32, 41u) - 0.5);
  let br1 = aaLine(radial(uv.x * 32.0 + 0.5 + b1w), 0.014, du * 32.0) * smoothstep(0.66, 0.8, vd);
  let ring = aaLine(abs(uv.y - VM), 0.005, dv);
  let canal = max(max(c1, ring), br1 * grow);
  let heat = 0.2 + 0.6 * L + 0.9 * L * L;
  // the note's glow, travelling out from the core (core at once, margin a stage later): the hero's hit band
  let hitBand = gl;
  let lx = fract(uv.x * 16.0) * 2.0 - 1.0;
  let lobeH = (1.0 - VM) * 0.88 * (0.9 + 0.2 * vnoise(vec2f(uv.x * 16.0, 0.5 + f32(id)), 16, 29u));
  let edgeV = VM + lobeH * pow(max(1.0 - lx * lx, 0.0), 0.45);
  let inLap = 1.0 - smoothstep(edgeV - dv * 0.7, edgeV + dv * 0.7, uv.y);
  let lapEdge = gauss((uv.y - edgeV) / (0.008 + 1.2 * dv)) * smoothstep(VM - 0.005, VM + 0.01, uv.y);
  let scatter = gauss(vd / 0.3) * (0.4 + 0.6 * nv);
  let wall = select(0.45, 1.0, front);
  let shoulder = smoothstep(0.08, 0.5, vd) * (1.0 - 0.7 * smoothstep(0.75, 1.0, vd));
  var d = vec3f(0.0);
  d += mix(deep, jewel, 0.75) * (0.02 + 0.55 * rimSoft) * (0.6 + 0.8 * mott) * (1.0 + 0.25 * L);
  d += jewel * shoulder * 0.085 * (0.55 + 0.45 * nv) * (0.7 + 0.6 * mott) * (1.0 + 0.2 * L);
  d += mix(jewel, fc, 0.25) * rimThin * (1.6 + 0.4 * L) * wall;
  let gloss = (5.0 * win + 0.4 * band) * (0.4 + 0.6 * mott);
  d += mix(fc, vec3f(0.75, 0.88, 1.0), 0.4) * gloss * (0.3 + 0.1 * L) * select(0.0, 1.0, front);
  d *= (0.6 + 0.6 * smoothstep(-0.3, 0.9, Nf.y)) * (0.6 + 0.6 * smoothstep(-0.5, 0.9, dot(Nf, normalize(vec3f(-0.5, 0.8, 0.3)))));
  d += (mix(jewel, fc, 0.45) * 0.05 * (0.5 + 0.5 * env) + fc * 0.35 * rimSoft) * (0.7 + 0.6 * mott) * select(0.3, 1.0, front);
  d += mix(warm * 0.9, gold, L) * canal * (heat + 2.4 * hitBand) * (0.85 + 0.35 * pl) * (0.7 + 0.6 * mott) * select(0.35, 1.0, front);
  d += warm * hitBand * 0.1 * (1.0 - smoothstep(0.85, 1.0, vd));
  d += mix(warm, ember, L) * scatter * (0.03 + 0.1 * L) * (1.0 + 0.4 * pl);
  d += mix(jewel, warm, 0.35) * smoothstep(0.72, 1.0, vd) * (0.05 + 0.03 * L);
  e = d * select(1.0, inLap, uv.y > VM);
  e += mix(warm, gold, 0.3 + 0.6 * L) * lapEdge * (0.25 + 0.5 * L + 0.6 * L * L + 0.8 * hitBand) * (0.8 + 0.4 * mott) * select(0.5, 1.0, front);
 } else {
  // ---- gonads: four warm lace loops, lit through their thickness (the hero's), and the small hot heart ----
  let gran = vnoise(vec2f(uv.x * 120.0, uv.y * 8.0 + f32(id)), 120, 23u);
  let fil = aaLine(radial(uv.x * 60.0 + 1.5 * sin(uv.y * TAU)), 0.12, du * 60.0);
  let thickness = nv * nv;
  e += mix(warm, gold, L) * thickness * (0.04 + 0.12 * L + 0.3 * L * L) * (0.2 + 0.4 * gran + 1.3 * fil) * (1.0 + 0.5 * pl + 1.0 * gl);
  e += mix(gold, vec3f(1.0), 0.12) * pow(nv, 22.0) * (0.25 + 0.15 * L) * (1.0 + 0.5 * pl + 0.8 * gl);
 }
 o.emissive = atmos(vivid(e, 1.35), fog, md) * gain;
 return o;
}
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}

// WORLD DOF 2b/3, tent (Silk Medusa): HALF resolution, four bilinear taps at half-texel diagonals
// (a 3x3 tent) over the gather, so its sampling grain never reaches the picture.
struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
struct Params {
 spread: f32, // @default 1 Tent offset in half-res texels.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@fragment fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
 let t = params.spread * 0.5 / vec2f(textureDimensions(inputTexture));
 return 0.25 * (textureSampleLevel(inputTexture, inputSampler, uv + vec2f(-t.x, -t.y), 0.0) + textureSampleLevel(inputTexture, inputSampler, uv + vec2f(t.x, -t.y), 0.0)
  + textureSampleLevel(inputTexture, inputSampler, uv + vec2f(-t.x, t.y), 0.0) + textureSampleLevel(inputTexture, inputSampler, uv + vec2f(t.x, t.y), 0.0));
}

// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}
// ---- material_silk: sheer chiffon, additive. Face-on almost clear, grazing and folds bright, hems, threads,
// a thin-film shimmer kept inside the mood's own hue, warm peach-gold glints. tint: x tone, y gain,
// z arc length, w texture (from kernel_silk).
struct Params {
 lum: f32, // @default 0.5 Rig illumination 0.2..1.
 mood: f32, // @default 0 Rig palette position 0..4.
 energy: f32, // @default 0.5 Rig energy: glint brightness.
 tension: f32, // @default 0.3 Rig tension: film shifts toward the highlight.
};

const TAU: f32 = 6.2831853;
// the fixed warm accent (peach-gold #ffc890): glints keep it in every mood
const WARM: vec3f = vec3f(1.0, 0.784, 0.565);

// rotate a colour's hue round the grey axis (luminance roughly kept)
fn hueRot(c: vec3f, a: f32) -> vec3f {
 let k = vec3f(0.57735027);
 let ca = cos(a);
 return c * ca + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - ca);
}

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
 var o = surfaceDefaults(s);
 let V = normalize(s.eye - s.world);
 let nl = max(length(s.normal), 1e-8);
 let ndv = clamp(abs(dot(s.normal, V)) / nl, 0.0, 1.0);
 let graze = 1.0 - ndv;
 let tone = s.tint.x;
 let gain = s.tint.y;
 let sg = s.tint.z;
 let tex = s.tint.w;
 let v = s.uv.y;
 let t = s.absTime;

 // hems: a thin hot line on each edge, about two pixels at any distance, plus a soft inner glow
 let ev = min(v, 1.0 - v);
 // degenerate (edge-on, sub-pixel) triangles can hand back non-finite derivatives: clamp them
 let fw = clamp(fwidth(v), 1e-4, 1.0);
 let hem = 1.0 - smoothstep(0.0, 2.0 * fw, ev);
 let hemGlow = exp(-ev / 0.07);

 // lengthwise threads, faded out where they would alias
 let tf = mix(70.0, 34.0, tex);
 let warp = sin(sg * 0.9 + v * 5.0) * 1.3;
 let bundle = 0.5 + 0.5 * sin(v * tf * 0.31 + 1.3 + sg * 0.23 + warp);
 let thr = (0.5 + 0.5 * sin(v * tf + warp)) * bundle;
 let aa = clamp(1.6 - clamp(fwidth(v * tf), 0.0, 4.0) * 1.2, 0.0, 1.0);
 let threads = mix(0.8, 0.45 + 1.1 * thr, aa);

 // light: face-on nearly clear, grazing and folds bright
 let g2 = graze * graze;
 let sheen = g2 * g2 * 0.95 + g2 * 0.3;
 let body = moodColor(p.mood, tone);
 let shadow = moodColor(p.mood, tone - 0.3);
 let hi = moodColor(p.mood, 1.0);
 // thin film WITHOUT the rainbow: the hue swings at most 0.15 of a cycle either side of the mood's body
 // colour (with graze, along the ribbon and over time) and is half the mood's own mid tone
 let ph = 1.4 * graze + 0.12 * sg - 0.05 * t + 0.35 * v + 2.0 * tone + 0.25 * p.tension;
 let film = mix(hueRot(body, TAU * 0.15 * sin(TAU * ph)), moodColor(p.mood, 0.6), 0.5);

 // the sheen warms toward the highlight tone as it grazes: folds and turned edges glow
 let warm = mix(body, hi, smoothstep(0.35, 0.95, graze) * 0.7);
 // face-on: a faint milky body that grows with illumination
 let face = mix(shadow, body, 0.6) * (0.04 + 0.025 * threads) * (0.75 + 1.1 * p.lum * p.lum);
 var col = face + warm * sheen * threads * 0.42 + film * sheen * 0.36;
 // the hems are kept apart: a thin line may be brighter than the sheer body
 let hems = hi * (hem * 1.1 + hemGlow * 0.12) * (0.5 + graze);
 // satin band: a sheen at a mid viewing angle that slides along as the ribbon rolls; its hottest part
 // leans to the warm accent
 let sb = (ndv - 0.42) / 0.15;
 let satin = exp(-sb * sb) * (0.35 + 0.9 * thr * aa);
 col = col + mix(film, mix(hi, WARM, 0.5), 0.45) * satin * 0.22;

 // warm glints: single peach-gold flecks riding single threads, drifting down the ribbon, the same
 // colour in every mood. A second, slower carrier across the width picks which thread lights.
 let gs = mix(0.9, 1.7, tex);
 let ga = max(sin(sg * gs - t * 0.75 + 7.0 * tone), 0.0);
 let gb = 0.5 + 0.5 * sin(v * 41.0 + sg * 0.6 + 3.0 * tone);
 let gc = max(sin(v * 6.3 + sg * 0.83 + 5.0 * tone + 0.4 * t), 0.0);
 let ga2 = ga * ga; let ga4 = ga2 * ga2; let ga8 = ga4 * ga4;
 let gb2 = gb * gb; let gb4 = gb2 * gb2; let gb8 = gb4 * gb4; let gb16 = gb8 * gb8;
 let gc2 = gc * gc; let gc4 = gc2 * gc2;
 let glint = WARM * ga8 * ga2 * gb16 * gc4 * gc4 * (1.2 + 2.0 * graze) * aa * (0.7 + 0.6 * p.energy);

 o.albedo = vec4f(0.0, 0.0, 0.0, 1.0);
 // calm and medium carry more lit form: the sheer body is lifted (about 2.2x at the calm floor of lum,
 // 1.3x at peak, where the cap below holds it)
 let lift = mix(2.2, 1.3, smoothstep(0.2, 1.0, p.lum));
 // PER-LAYER SOFT CAP: additive layers stack, so each layer's body light is compressed toward a ceiling
 // (0.32 at calm and medium, where layers rarely stack; 0.18 at peak, so three stacked bodies keep their
 // colour and never reach white) and its hems (and glints) toward 0.8 (luminance-based, hue kept)
 let cap = mix(0.32, 0.18, smoothstep(0.45, 0.95, p.lum));
 let k = gain * (0.65 + 0.7 * p.lum);
 let bodyE = col * (k * lift);
 let hemE = (hems + glint) * k;
 let lb = dot(bodyE, vec3f(0.3, 0.55, 0.15));
 let lh = dot(hemE, vec3f(0.3, 0.55, 0.15));
 let e = bodyE * (cap / (cap + lb)) + hemE * (0.8 / (0.8 + lh));
 o.emissive = clamp(e, vec3f(0.0), vec3f(2.0));
 return o;
}

// @use hash
struct Params {
 lum: f32, // @default 0.5 Illumination (rig lum): calm a translucent veil with a warm root, peak incandescent lace.
 mood: f32, // @default 0 Palette position (rig mood).
 tension: f32, // @default 0.3 Thin-film phase shift (rig tension).
 rC2: f32, // @default 1 Chord root on the circle of fifths, cosine, at the heart's stage (lag_herochord2.rC): the colour lean at the root of the veils.
 rS2: f32, // @default 0 The same, sine (lag_herochord2.rS).
 rC4: f32, // @default 1 The same, later, at the hems (lag_herochord4.rC).
 rS4: f32, // @default 0 (lag_herochord4.rS).
 chordGain: f32, // @default 1 How far the chord root leans the colour (as on the bell).
 react: f32, // @default 1 The owner's music reaction strength (rig reactGain, 0..2, eased): multiplies every gain above.
};
const TAU = 6.2831853;

fn vnoise(p: vec2f, seed: u32) -> f32 {
 let i = floor(p);
 let f = p - i;
 let w = f * f * (3.0 - 2.0 * f);
 let ii = vec2i(i);
 let a = unitFloat(hash2i(ii, seed));
 let b = unitFloat(hash2i(ii + vec2i(1, 0), seed));
 let c = unitFloat(hash2i(ii + vec2i(0, 1), seed));
 let d = unitFloat(hash2i(ii + vec2i(1, 1), seed));
 return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}
fn satn(c: vec3f) -> vec3f { return c / max(max(c.r, c.g), max(c.b, 0.05)); }
fn vivid(c: vec3f, k: f32) -> vec3f { let y = dot(c, vec3f(0.2126, 0.7152, 0.0722)); return max(mix(vec3f(y), c, k), vec3f(0.0)); }
// thin film tied to the palette (as on the bell): the mood's own hues with a quarter of the next mood
fn filmPal(m: f32, ph: f32) -> vec3f {
 let c = cos(TAU * ph);
 return satn(mix(moodColor(m, 0.5 + 0.5 * c), moodColor(m + 1.0, 0.6 + 0.4 * cos(TAU * ph + 2.1)), 0.28));
}
fn aaLine(d: f32, w: f32, aa: f32) -> f32 { return 1.0 - smoothstep(w, w + aa, d); }

// the four hues weighted by the root direction; while a far root change passes the lagged direction
// through the centre (weights small) the colour eases to their mean instead of flipping (pass 7)
fn chordHueM(w: vec4f, a: vec3f, b: vec3f, c: vec3f, d: vec3f) -> vec3f {
 let sw = w.x + w.y + w.z + w.w;
 return (w.x * a + w.y * b + w.z * c + w.w * d + max(0.6 - sw, 0.0) * 0.25 * (a + b + c + d)) / max(sw, 0.6);
}
fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
 var o = surfaceDefaults(s);
 o.albedo = vec4f(0.0, 0.0, 0.0, 1.0);
 let uv = s.uv;
 let du = max(fwidth(uv.x), 1e-5);
 let dv = max(fwidth(uv.y), 1e-5);
 let arm = s.tint.x;
 let presence = s.tint.y;
 let swell = s.tint.z;   // swim pressure and chord strikes running down from the root
 let chw = s.tint.w;     // the chord change's ripple (pass 6): it carries the chord's colour down
 let N = normalize(s.normal);
 let V = normalize(s.eye - s.world);
 let nv = abs(dot(N, V));
 let fres = 1.0 - nv;
 let L = p.lum;
 // pass 6: the chord root leans the palette, at the root of the veil first and at the hem later
 let rl = mix(vec2f(p.rC2, p.rS2), vec2f(p.rC4, p.rS4), smoothstep(0.0, 1.0, uv.y));
 let md = p.mood + (p.chordGain * p.react) * (0.25 * rl.x + 0.15 * rl.y);
 // the warm accent: the same peach-gold in every mood
 let ACC = vec3f(1.0, 0.66, 0.36);
 let warm = mix(ACC, moodColor(md, 0.93), 0.2);
 let gold = mix(ACC, ACC * ACC, 0.5);
 let ember = gold * gold;
 let burn = pow(L, 2.0);   // incandescence: only near peak
 let body = moodColor(md, 0.4);
 let lilac = moodColor(md, 0.55);
 let jewel = satn(mix(body, lilac, 0.5));
 let a = uv.x * 2.0 - 1.0;
 let sAlong = uv.y;
 let rootWarm = exp(-sAlong * 3.2);
 // lace edge: a crinkled rim line, with a fringe of small holes inside it
 let crink = vnoise(vec2f(sAlong * 140.0, arm * 7.0), 51u);
 let crink2 = vnoise(vec2f(sAlong * 420.0, arm * 7.0 + 3.0), 53u);
 let edgeD = 1.0 - abs(a) - 0.035 * crink - 0.02 * crink2;
 let rim = aaLine(abs(edgeD - 0.03), 0.018, du * 2.0);
 let fringe = smoothstep(0.03, 0.14, edgeD) * (1.0 - smoothstep(0.14, 0.3, edgeD));
 let holes = smoothstep(0.45, 0.62, vnoise(vec2f(sAlong * 260.0, a * 10.0 + arm * 5.0), 57u));
 let lace = fringe * (1.0 - holes) * smoothstep(0.1, 0.8, L + 0.4 * rootWarm);
 let cut = smoothstep(-0.005, 0.02, edgeD);
 // veins: a few meandering lines down the ribbon, lightning-like at peak
 let mean = (vnoise(vec2f(sAlong * 22.0, arm * 3.0), 59u) - 0.5) * 0.5;
 let vx = abs(fract(a * 2.0 + mean + 0.5) - 0.5);
 let vein = aaLine(vx, 0.02, du * 4.0) * (0.5 + 0.5 * vnoise(vec2f(sAlong * 60.0, arm), 61u));
 // silk: folds turned edge-on glow; thin film across the ribbon
 let rimSoft = pow(fres, 2.0);
 let thick = 0.45 + 0.3 * vnoise(vec2f(sAlong * 8.0, a * 2.0 + arm * 4.0), 63u) + 0.35 * p.tension;
 let cosT = sqrt(max(1.0 - (1.0 - nv * nv) / 1.77, 0.0));
 let fc = filmPal(md, thick * 2.0 * cosT + sAlong * 0.6);
 let tip = 1.0 - smoothstep(0.7, 1.0, sAlong);
 let head = smoothstep(0.0, 0.1, sAlong);
 var e = vec3f(0.0);
 // translucent veil: the glass colour with palette film where the folds turn edge-on
 e += mix(jewel, fc, 0.35 + 0.3 * L) * (0.04 + 0.2 * rimSoft) * (0.65 + 0.7 * L);
 // warm incandescent root, there even when calm
 e += mix(warm, gold, 0.3 + 0.7 * L) * rootWarm * rootWarm * (0.08 + 0.3 * pow(L, 1.3)) * (0.6 + 0.4 * nv) * (1.0 + 0.5 * swell);
 // inner light carried down the arm's middle, strongest at peak
 e += mix(mix(jewel, gold, 0.2 + 0.6 * rootWarm), ember, burn * 0.3 * rootWarm) * sqrt(max(1.0 - abs(a), 0.0)) * exp(-sAlong * 1.3) * (0.01 + 0.16 * burn);
 e += mix(mix(lilac, warm, 0.35 + 0.65 * rootWarm), gold, min(L * (0.4 + 0.6 * rootWarm) + burn * 0.5, 1.0)) * (rim * 0.9 + lace * 0.25) * (0.1 + 0.45 * pow(L, 1.3)) * (0.35 + 0.65 * rootWarm + 0.5 * swell);
 e += mix(gold, ember, 0.4) * vein * (0.01 + 0.8 * burn) * (0.4 + rootWarm);
 // the chord change's colour runs down the veil with its ripple (hue shift, little added light)
 let cw4 = max(vec4f(rl.x, rl.y, -rl.x, -rl.y), vec4f(0.0));
 let waveCol = chordHueM(cw4, satn(moodColor(md + 1.0, 0.5)), satn(moodColor(md + 2.0, 0.95)), satn(moodColor(md + 1.0, 0.25)), satn(moodColor(md + 2.0, 0.6)));
 let wy = dot(e, vec3f(0.2126, 0.7152, 0.0722));
 e = mix(e, waveCol * wy * 1.2, min(0.55 * chw, 0.7));
 o.emissive = vivid(e, 1.3) * cut * tip * head * presence;
 return o;
}
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}

