// ---- hero common (kernels): frame, pulse envelope, bell profile, trail ----
const TAU = 6.2831853;
// The bell in its own frame: rim radius 1, up +y, rim (margin) plane at BELL_Y0, apex BELL_H above it.
// World = hero position + rotZ(tiltZ) * rotX(tiltX) * (local * heroScale).
// A flattened dome (the boards: height/width about 0.38 for the dome, 0.45 with the lappets): the profile
// stops at 79 degrees, so the shoulders slope into the rim and never stand as a vertical wall; 16
// rounded lappets hang LAP_LEN below the rim.
const BELL_H = 0.64;
const BELL_Y0 = -0.35;
const BELL_THMAX = 1.38;
const BELL_VM = 0.9;       // exumbrella: v of the rim (ring canal); the lappets hang over VM..1
const LAP_LEN = 0.14;

struct HF { o: vec3f, ca: f32, sa: f32, cb: f32, sb: f32, k: f32, };
fn hfMake(x: f32, y: f32, z: f32, tx: f32, tz: f32, k: f32) -> HF {
 return HF(vec3f(x, y, z), cos(tx), sin(tx), cos(tz), sin(tz), k);
}
fn hfDir(f: HF, d: vec3f) -> vec3f {
 let y1 = d.y * f.ca - d.z * f.sa;
 let z1 = d.y * f.sa + d.z * f.ca;
 return vec3f(d.x * f.cb - y1 * f.sb, d.x * f.sb + y1 * f.cb, z1);
}
fn hfPos(f: HF, p: vec3f) -> vec3f { return f.o + hfDir(f, p * f.k); }

// The stroke, as a periodic function of the swim phase (the cycle is about 3.5 s): a slow full
// contraction over 30 % of it, a release over 40 %, then a 30 % glide at rest. Every geometric use of
// the swim reads this (the bell body too), so the bell and everything lagging it agree.
// the warm accent: one peach-gold for cores, canals, glints and beads in every mood
const ACC = vec3f(1.0, 0.66, 0.36);
fn smoother(a: f32, b: f32, x: f32) -> f32 {
 let t = clamp((x - a) / (b - a), 0.0, 1.0);
 return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}
fn pulseEnv(ph: f32) -> f32 {
 let x = fract(ph);
 return smoother(0.0, 0.3, x) * (1.0 - smoother(0.3, 0.7, x));
}
// A chord strike as a FORCE: the rig's strike age drives a short impulse through a chain of hero
// lag nodes; k.x (lag_herokick2) is the response at the bell, k.y (4) later and wider, k.z (5) later
// still, kS (7) a very slow mean of the same impulse. The RIPPLE is what is new: each response minus
// the slow mean, normalised so one isolated strike peaks near 1, softly limited, so a train of strikes
// does not hold the appendages splayed: each new strike still adds a travelling ripple, and the
// sustained part becomes a small, saturating STEADY opening.
fn kickRipple(k: vec3f, kS: f32) -> vec3f {
 let g = vec3f(2.0, 4.0, 5.5);
 let x = (k - vec3f(kS)) * g;
 return x / sqrt(vec3f(1.0) + x * x);
}
fn kickSteady(kS: f32) -> f32 { return 0.35 * (1.0 - exp(-2.5 * kS)); }
// positive part, smoothly (light and flares only grow)
fn softPos(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.0004)); }
// the margin flares a little with the strike (bell and tentacle roots must agree)
fn marginFlare(lp: vec3f, v: f32, k0: f32) -> vec3f {
 let g = 1.0 + 0.035 * k0 * smoothstep(0.75, 1.0, v);
 return vec3f(lp.x * g, lp.y, lp.z * g);
}

// Soft swim pressure: a raised cosine at the swim frequency, peaking with the contraction (phase 0.28).
// Lagged copies of it run down arms and tentacles as a gentle pressure wave, never a wiggle.
fn gaussK(x: f32) -> f32 { return exp(-x * x); }
// the strike ripple as felt at s along anything (0 the bell, 1 the tips), continuous in time and space
fn rippleAt(r: vec3f, s: f32) -> f32 {
 return mix(mix(r.x, r.y, smoother(0.0, 0.5, s)), r.z, smoother(0.5, 1.0, s));
}
fn pres(ph: f32) -> f32 { return 0.5 + 0.5 * cos(TAU * (ph - 0.28)); }
// Contraction felt at bell parameter v (0 apex, 1 lappet tips): the body follows pulse, the margin
// lags 0.06 of a cycle, the lappets 0.1, so the rim trails the squeeze and re-opens late.
// D is the stroke depth (fuller with louder music, set slowly).
fn bellPulseAt(v: f32, pl: f32, ph: f32, D: f32) -> f32 {
 let pm = pulseEnv(ph - 0.06) * D;
 let plap = pulseEnv(ph - 0.1) * D;
 return mix(pl, mix(pm, plap, smoothstep(0.86, 1.0, v)), smoothstep(0.55, 1.0, v));
}
fn strokeDepth(es: f32) -> f32 { return 0.75 + 0.4 * es; }
// The stroke's amplitude, softly limited to 1 (pass 6). A hard min(.., 1) on depth x strike clipped the
// top of the contraction inside a stroke whenever the music was full: a kink in its speed, seen as a
// light step at the stroke's peak (Clair 70.6 s, 88.1 s). Bell, filament roots and rhopalia all use it.
fn strokeAmp(a: f32) -> f32 { return a / pow(1.0 + pow(max(a, 0.0), 8.0), 0.125); }

fn bellSqueeze(v: f32, pm: f32) -> f32 {
 return 1.0 - 0.2 * pm * pow(smoothstep(0.12, 1.0, v), 1.3);
}
// Exumbrella point. p: body contraction, pm: (lagged) margin contraction, te: tension.
// the dome's height profile, 1 at the apex and 0 at the rim (slightly flattened top)
fn domeY(th: f32) -> f32 {
 let cm = pow(cos(BELL_THMAX), 0.88);
 return (pow(max(cos(th), 0.0), 0.88) - cm) / (1.0 - cm);
}
fn bellExo(phi: f32, v: f32, p: f32, pm: f32, te: f32) -> vec3f {
 let vd = min(v / BELL_VM, 1.0);
 let th = vd * BELL_THMAX;
 // a contraction closes the rim and lengthens the dome a little: it stays a dome (h/w under 0.6)
 let h = BELL_H * (1.0 + 0.12 * p + 0.06 * te);
 let rib = 1.0 + 0.022 * (0.5 + 0.5 * cos(16.0 * phi)) * smoothstep(0.08, 0.5, vd) * (1.0 - smoothstep(0.8, 0.95, vd));
 let wave = (0.025 * sin(8.0 * phi + 0.7) + 0.01 * sin(13.0 * phi + 2.0)) * smoothstep(0.6, 1.0, vd);
 var r = sin(th) / sin(BELL_THMAX) * bellSqueeze(vd, pm) * rib;
 var y = BELL_Y0 - 0.04 * pm * smoothstep(0.5, 1.0, vd) + h * domeY(th);
 if (v > BELL_VM) {
  // the lappets hang from the rim: flared a little outward at rest, curled in by the squeeze
  let s = (v - BELL_VM) / (1.0 - BELL_VM);
  r = r + s * LAP_LEN * (0.45 - 0.9 * pm) * bellSqueeze(1.0, pm);
  y = y - s * LAP_LEN * (0.9 + 0.2 * pm);
 }
 return vec3f(cos(phi) * r, y + wave, sin(phi) * r);
}

// Frame-independent per-id random in [0, 1). The built-in pointRand re-rolls EVERY FRAME (it hashes the
// frame index), so it must never shape geometry: that reads as high-frequency jitter in playback.
fn stableRand(id: u32, salt: u32) -> f32 {
 var x = id * 747796405u + salt * 2891336453u + 12345u;
 x = (x ^ (x >> 15u)) * 2246822519u;
 x = (x ^ (x >> 13u)) * 3266489917u;
 x = x ^ (x >> 16u);
 return f32(x >> 8u) * (1.0 / 16777216.0);
}
// ---- hero appendages in water (shared by tentacle beams, beads and oral arms) ----
// They HANG: almost passive, a slow curtain dragged behind the swim and swaying over many seconds.
// Point s = the root on the bell (rigidly attached, in the bell's own frame) + a hanging shape
// (gravity and a slow down-left current, leaning with the path) + a slow DRAG opposite the bell's
// mean velocity, growing toward the tip. The mean velocity is taken over one swim period (the bell
// now vs where it was one period, about 1.76 s, ago), so the surge of each thrust cancels out and
// is never replayed down the appendages; it is used as a vector that shrinks to nothing as the bell
// slows (never normalised), so the trail eases back to the rest hang. Each contraction sends one
// soft, slow bulge down them; chord strikes change only their light. Nothing may rise above its
// own root along the bell's axis (keepBelow).
const NT = 48u;            // tentacles
const DRAG_T = 4.0;        // tentacles: seconds of mean drift by which a tip trails
const ARM_DRAG_T = 5.5;    // oral arms: broad veils catch more water
struct TC { f: HF, fP: HF, h0: vec3f, vbar: vec3f, droop: vec3f, side: vec3f, side2: vec3f, pl: f32, ph: f32, te: f32, de: f32, t: f32, kick: vec3f, es: f32, steady: f32, act: f32, };

// the bell's path u steps of 0.7 s ago (u in 1..3), straight between the rig's samples (no overshoot)
fn pathBack(h1: vec3f, h2: vec3f, h3: vec3f, u: f32) -> vec3f {
 if (u < 2.0) { return mix(h1, h2, clamp(u - 1.0, 0.0, 1.0)); }
 return mix(h2, h3, clamp(u - 2.0, 0.0, 1.0));
}

fn tcMake(f: HF, h1: vec3f, h2: vec3f, h3: vec3f, rate: f32, tx: f32, tz: f32, pl: f32, ph: f32, te: f32, de: f32, t: f32, kick: vec3f, es: f32, kS: f32, rl: f32) -> TC {
 // mean velocity: the least-squares slope through the four samples (now, 0.7, 1.4, 2.1 s ago), far
 // less sensitive to the surge inside a stroke than a two-point difference
 let vbar = (1.5 * f.o + 0.5 * h1 - 0.5 * h2 - 1.5 * h3) / (5.0 * 0.7);
 // the bell's own axis with the per-stroke rocking taken out: the rig leans the bell by its 0.7 s
 // velocity; swap that for the period-mean velocity (same lean law), keep everything else it does
 // (with rigLean = 1 the rig's tilt already is that smooth lean, and everything hangs along it as is)
 let v07 = (f.o - h1) / 0.7;
 let swap = select(1.0, 0.0, rl > 0.5);
 let fP = hfMake(f.o.x, f.o.y, f.o.z, tx - 0.5 * (v07.z - vbar.z) * swap, tz + 1.6 * (v07.x - vbar.x) * swap, f.k);
 // appendages hang along that axis (no sideways current of their own)
 let droop = hfDir(fP, vec3f(0.0, -1.0, 0.0));
 let side = normalize(cross(droop, vec3f(0.0, 0.0, 1.0)));
 let side2 = normalize(cross(droop, side));
 // activity: slow musical energy plus how busy the strikes have been (both eased), 0 calm .. 1 full
 let steady = kickSteady(kS);
 let act = clamp(0.75 * es + 1.2 * steady, 0.0, 1.0);
 return TC(f, fP, f.o, vbar, droop, side, side2, pl, ph, te, de, t, kickRipple(kick, kS), es, steady, act);
}
// trail opposite the mean velocity, growing toward the tip, softly limited (no normalising)
fn dragAt(c: TC, s: f32, len: f32, secs: f32) -> vec3f {
 let d = -c.vbar * secs * pow(s, 1.5);
 let limit = 0.35 * len;
 return d / sqrt(1.0 + dot(d, d) / (limit * limit));
}
// never above the root along the bell's axis: a point at s hangs at least 10 % of its arclength below
fn keepBelow(c: TC, root: vec3f, p: vec3f, s: f32, len: f32) -> vec3f {
 let up = hfDir(c.f, vec3f(0.0, 1.0, 0.0));
 let along = dot(p - root, up);
 let floorA = -0.1 * s * len;
 let w = 0.08 * len * s + 1e-4;
 let hh = clamp(0.5 + 0.5 * (floorA - along) / w, 0.0, 1.0);
 let sm = mix(floorA, along, hh) - w * hh * (1.0 - hh);
 return p + up * (sm - along);
}
fn tentPhi(ti: u32) -> f32 {
 return (f32(ti) + 0.5 + 0.55 * (stableRand(ti, 11u) - 0.5)) / f32(NT) * TAU;
}
// active share of the tentacles: about 24 at density 0, all 48 at density 1 (unused ones fade)
fn tentActive(ti: u32, de: f32) -> f32 {
 let rank = stableRand(ti, 17u);
 return 1.0 - smoothstep(0.5 + 0.5 * de - 0.06, 0.5 + 0.5 * de + 0.02, rank);
}
fn tentLength(c: TC, ti: u32) -> f32 {
 return (1.2 + 3.0 * pow(stableRand(ti, 13u), 1.4)) * (0.85 + 0.3 * c.de) * (1.0 + 0.12 * c.te) * c.f.k;
}
// the bell's contraction as felt at s along an appendage: exact at the root, then the same envelope at
// a later phase, damped (a soft pressure wave). Returns (body pulse, margin pulse, phase used).
fn pulseAlong(c: TC, s: f32) -> vec3f {
 let lagc = 0.6 * s;
 let att = exp(-1.8 * s);
 let D = strokeDepth(c.es);
 let k0 = (c.kick.x + c.steady) * att;
 let ps = pulseEnv(c.ph - lagc) * strokeAmp(D * (1.0 + 0.2 * k0)) * att;
 let pm = bellPulseAt(0.9, ps, c.ph - lagc, D) * att;
 return vec3f(ps, pm, c.ph - lagc);
}
// the slow sweep of the whole hanging bundle (shared by tentacles and arms), travelling tipward
fn sweepAt(c: TC, s: f32) -> vec3f {
 let a = TAU * (0.05 * c.t - 0.35 * s);
 return (c.side * sin(a) + c.side2 * 0.5 * sin(a * 0.7 + 1.9)) * (0.12 + 0.14 * c.act) * s * s;
}
// the strike as felt at s: the bell's response at the root, later and wider responses toward the tip
fn kickAt(c: TC, s: f32) -> f32 { return rippleAt(c.kick, s) + c.steady; }
fn tentRoot(c: TC, phi: f32, s: f32) -> vec3f {
 let pa = pulseAlong(c, s);
 let k0 = (c.kick.x + c.steady) * exp(-1.8 * s);
 return hfPos(c.f, marginFlare(bellExo(phi, 0.9, pa.x, pa.y, c.te), 0.9, k0) * vec3f(0.965, 1.0, 0.965));
}
fn tentPoint(c: TC, ti: u32, s: f32) -> vec3f {
 let phi = tentPhi(ti);
 let h1 = stableRand(ti, 12u);
 let h2 = stableRand(ti, 14u);
 // root on the margin, squeezing with it (the squeeze reaches further points later and weaker)
 let anchor = tentRoot(c, phi, s);
 let outL = vec3f(cos(phi), 0.0, sin(phi));
 // one soft slow bulge per contraction, travelling down
 let pp = pres(c.ph - 0.1 - 0.6 * s);
 // loud passages open the whole curtain, quiet ones draw it in (slow)
 let spread = (0.16 + 0.2 * h1) * (0.7 + 0.7 * c.act) - 0.04 * pp;
 let d0 = hfDir(c.fP, normalize(vec3f(outL.x * spread, -1.0, outL.z * spread)));
 let len = tentLength(c, ti);
 let bendL = vec3f(cos(phi + 1.6 * (h2 - 0.5)), 0.0, sin(phi + 1.6 * (h2 - 0.5)));
 let b1 = d0 * 0.22 * len + hfDir(c.fP, bendL) * (0.04 + 0.08 * h2) * len;
 let b2 = b1 + normalize(c.droop + hfDir(c.fP, outL) * (0.05 + 0.12 * h1)) * 0.78 * len;
 var pos = anchor + 2.0 * s * (1.0 - s) * b1 + s * s * b2;
 // slow drag behind the mean swim
 pos += dragAt(c, s, len, DRAG_T * (0.8 + 0.4 * h2) * (0.8 + 0.4 * c.es));
 // always alive: a long slow undulation (about one wave every 9 s), larger when the music is fuller,
 // under a slower sweep the whole curtain shares (one every 20 s), travelling down it
 // the music shapes it through amplitude and (a little) wavelength, never its rate: calm = long lazy
 // waves, busy = fuller and livelier
 let w = TAU * ((0.55 + 0.35 * c.act) * s - 0.11 * c.t) + phi * 3.0 + h1 * 6.0;
 let amp = (0.06 + 0.1 * c.act) * len * pow(s, 1.5);
 pos += (c.side * sin(w) + c.side2 * 0.6 * cos(0.8 * w + 1.3)) * amp;
 pos += sweepAt(c, s) * len;
 // the bulge: the bundle breathes out a hair as it passes
 pos += hfDir(c.fP, outL) * 0.012 * len * sin(3.14159 * s) * pp;
 // a strike: the filaments flare outward and stretch back along the trail, as a slow wave tipward
 pos += (hfDir(c.fP, outL) * 0.7 + c.droop * 0.5) * 0.11 * len * sin(3.14159 * min(s * 1.1, 1.0) * 0.5) * kickAt(c, s);
 return keepBelow(c, tentRoot(c, phi, 0.0), pos, s, len);
}
// WORLD MOTES, pass 2 (Silk Medusa): a FIXED population of additive point sprites, stateless.
// Every position is a continuous function of time; nothing holds a pose.
//
// DUST (indices < DUST): three depth layers, world-anchored, scrolled by the medium's flow
// D(t) = -FLOW_DIR * flow * travel and wrapped in boxes that follow the camera. Real perspective
// gives the parallax: near dust streams fast, far dust crawls. Faded at every box face.
//
// WAKE (the rest). Geometry is pure water motion; music only lights it (and a smooth swell).
//   - shed motes: born at the margin / under the bell where the hero WAS at their birth (rig
//     history), carried away by the same flow as the dust and advected through slow curl eddies
//     fixed in the water; born bright, drift back, fade, recycle. Their frame is the bell's
//     period-mean lean (the hero's tentacle model), so the stroke's rocking is never replayed.
//   - RIM TENTACLES: five voices x four beaded strands rooted at FIXED points of the margin (each
//     voice owns a sector of the rim). They are built with the hero's own tentacle model
//     (hero/tent.common.wgsl: rigid roots in the bell frame, hang along the period-mean axis, slow
//     drag behind the mean velocity, slow undulation travelling root to tip, the strike as a smooth
//     lagged kick tipward). Beads of light flow slowly root to tip and dissolve into free motes
//     past the tip. Per voice, only constants: sector, handedness, undulation scale. The voice's
//     (lagged) envelope and the strike band only change their LIGHT.
//   - pulse rings: one calm vortex ring puffed per stroke, rolling and drifting off.
// Nothing here reads pitch, note starts or envelopes for position.
struct Params {
 energy: f32, // @default 0.5 Rig energy: wake activity and dust light.
 density: f32, // @default 0.5 Rig density: how much of the wake and strands is lit.
 lum: f32, // @default 0.45 Rig illumination: overall mote light.
 tension: f32, // @default 0.3 Rig tension: eddy strength.
 mood: f32, // @default 0 Rig palette position 0..4.
 pulse: f32, // @default 0 Rig pulse envelope.
 hit: f32, // @default 0 Chord accent, smoothed again by the world (lag_worldhit2: S-shaped, about 1 s to peak).
 heroX: f32, // @default 1 Hero x now.
 heroY: f32, // @default 1.2 Hero y now.
 heroZ: f32, // @default 0 Hero z now.
 heroX1: f32, // @default 1 Hero x 0.7 s ago.
 heroY1: f32, // @default 1.2 Hero y 0.7 s ago.
 heroZ1: f32, // @default 0 Hero z 0.7 s ago.
 heroX2: f32, // @default 1 Hero x 1.4 s ago.
 heroY2: f32, // @default 1.2 Hero y 1.4 s ago.
 heroZ2: f32, // @default 0 Hero z 1.4 s ago.
 heroX3: f32, // @default 1 Hero x 2.1 s ago.
 heroY3: f32, // @default 1.2 Hero y 2.1 s ago.
 heroZ3: f32, // @default 0 Hero z 2.1 s ago.
 heroScale: f32, // @default 1 Hero size.
 tiltX: f32, // @default 0 Hero lean about X (rig heroTiltX).
 tiltZ: f32, // @default -0.22 Hero lean about Z (rig heroTiltZ).
 pulsePhase: f32, // @default 0 Rig swim-cycle phase (the bell's stroke, felt along the rim tentacles).
 kick0: f32, // @default 0 Strike impulse at the root (hero lag chain, same as kernel_herotentacles.kick0).
 kick1: f32, // @default 0 Strike impulse mid-tentacle (kernel_herotentacles.kick1).
 kick2: f32, // @default 0 Strike impulse at the tip (kernel_herotentacles.kick2).
 kickS: f32, // @default 0 Steady strike level (kernel_herotentacles.kickS).
 tensionS: f32, // @default 0.3 The hero's bell tension (kernel_herotentacles.tension): rim anchor shape.
 densityS: f32, // @default 0.5 The hero's density (kernel_herotentacles.density): tcMake activity.
 rigLean: f32, // @default 1 1 = the rig's tilt is the smooth travel lean: hang along it (kernel_herotentacles.rigLean).
 energyS: f32, // @default 0.5 Slow energy (lag_heroslow2.energy): undulation size.
 travel: f32, // @default 0 Rig travel: distance swum (the wake's clock in the water).
 swimDirX: f32, // @default 0.22 The bell's up axis (rig swimDirX): the water streams the other way.
 swimDirY: f32, // @default 0.97 Rig swimDirY.
 swimDirZ: f32, // @default 0 Rig swimDirZ.
 flowX: f32, // @default 0 Integrated swim (speed_worldflow flowX): the running sum of swimDir * d(travel).
 flowY: f32, // @default 0 Integrated swim, y.
 flowZ: f32, // @default 0 Integrated swim, z.
 travel1: f32, // @default 0 Rig travel 0.7 s ago.
 travel2: f32, // @default 0 Rig travel 1.4 s ago.
 travel3: f32, // @default 0 Rig travel 2.1 s ago.
 swimRate: f32, // @default 0.567 Rig swim cycles per second.
 pu: f32, // @default 0 Rig swim cycle count (pulsePhase = fract(pu)): times the vortex rings.
 aperture: f32, // @default 40 Lens circle at infinity, full-res px (same as wgsl_worlddofprep.aperture).
 band: f32, // @default 1.5 Sharp depth band either side of the hero (same as the DOF passes).
 camX: f32, // @default 0 Camera eye x.
 camY: f32, // @default 0.4 Camera eye y.
 camZ: f32, // @default 9 Camera eye z.
 camTX: f32, // @default 0 Camera target x.
 camTY: f32, // @default 0.2 Camera target y.
 camTZ: f32, // @default 0 Camera target z.
 camFov: f32, // @default 38 Camera vertical fov, degrees.
 env0: f32, // @default 0.1 Voice 0 envelope (light only).
 env1: f32, // @default 0.1 Voice 1 envelope.
 env2: f32, // @default 0.1 Voice 2 envelope.
 env3: f32, // @default 0.1 Voice 3 envelope.
 env4: f32, // @default 0.1 Voice 4 envelope.
 flow: f32, // @default 7 Medium speed: world units of streaming per unit of travel.
 gain: f32, // @default 1 Overall mote light.
 react: f32, // @default 1 Reaction amount (rig reactGain, owner's slider): scales every music response here.
 env: f32, // @default 1 Environment amount (rig envGain, owner's slider, 0..2): scales the drifting dust only (the wake is the creature's).
};

const DUST: u32 = 4096u;
const WARM: vec3f = vec3f(1.0, 0.578, 0.278); // #ffc890, linear
// The hero swims bell-first, up and a little right and away; the medium streams the other way.

fn mHash(i: u32, salt: u32) -> f32 {
 var x = i * 747796405u + salt * 2891336453u + 12345u;
 x = (x ^ (x >> 15u)) * 2246822519u;
 x = (x ^ (x >> 13u)) * 3266489917u;
 x = x ^ (x >> 16u);
 return f32(x >> 8u) * (1.0 / 16777216.0);
}

// How far the water had moved at `age` seconds ago, from the rig's own history: travel now and
// 0.7 / 1.4 / 2.1 s ago, interpolated; beyond that, back along the current swim rate (travel
// advances 0.12 per swim cycle on average). Continuous in age and smooth when swimRate drifts, so
// it follows a rubato performance as well as the steady clock.
fn travelBack(age: f32, P: Params) -> f32 {
 if (age < 0.7) { return mix(P.travel, P.travel1, age / 0.7); }
 if (age < 1.4) { return mix(P.travel1, P.travel2, (age - 0.7) / 0.7); }
 if (age < 2.1) { return mix(P.travel2, P.travel3, (age - 1.4) / 0.7); }
 return P.travel3 - (age - 2.1) * 0.12 * P.swimRate;
}

fn tiltDir(d: vec3f, tx: f32, tz: f32) -> vec3f {
 let ca = cos(tx); let sa = sin(tx); let cb = cos(tz); let sb = sin(tz);
 let y1 = d.y * ca - d.z * sa;
 let z1 = d.y * sa + d.z * ca;
 return vec3f(d.x * cb - y1 * sb, d.x * sb + y1 * cb, z1);
}

// Divergence-free eddies: the curl of a two-octave sinusoidal vector potential, in the medium frame.
fn curlField(y: vec3f, time: f32, scale: f32) -> vec3f {
 let p = y * scale;
 let k1 = vec3f(0.9, 0.35, -0.55); let k2 = vec3f(-0.4, 0.8, 0.45); let k3 = vec3f(0.5, -0.6, 0.85);
 let c1 = cos(dot(k1, p) + 0.11 * time + 1.3);
 let c2 = cos(dot(k2, p) - 0.09 * time + 4.1);
 let c3 = cos(dot(k3, p) + 0.07 * time + 2.2);
 var v = vec3f(k3.y * c3 - k2.z * c2, k1.z * c1 - k3.x * c3, k2.x * c2 - k1.y * c1);
 let q = p * 2.13 + vec3f(3.1, 1.7, 5.3);
 let e1 = cos(dot(k2, q) + 0.17 * time);
 let e2 = cos(dot(k3, q) - 0.13 * time + 2.0);
 let e3 = cos(dot(k1, q) + 0.15 * time + 4.0);
 v = v + 0.45 * vec3f(k3.y * e3 - k2.z * e2, k1.z * e1 - k3.x * e3, k2.x * e2 - k1.y * e1);
 return v;
}

// A rim tentacle point at s (0 root .. 1 tip): the hero's tentPoint with our own root angle,
// length and per-strand constants (hand: which way the undulation circles; freq: its spatial scale).
fn rimPoint(c: TC, phi: f32, len: f32, h1: f32, h2: f32, hand: f32, freq: f32, s: f32) -> vec3f {
 let anchor = tentRoot(c, phi, s);
 let outL = vec3f(cos(phi), 0.0, sin(phi));
 let pp = pres(c.ph - 0.1 - 0.6 * s);
 let spread = (0.2 + 0.2 * h1) * (0.7 + 0.7 * c.act) - 0.04 * pp;
 let d0 = hfDir(c.fP, normalize(vec3f(outL.x * spread, -1.0, outL.z * spread)));
 let bendL = vec3f(cos(phi + 1.6 * (h2 - 0.5)), 0.0, sin(phi + 1.6 * (h2 - 0.5)));
 let b1 = d0 * 0.22 * len + hfDir(c.fP, bendL) * (0.05 + 0.08 * h2) * len;
 let b2 = b1 + normalize(c.droop + hfDir(c.fP, outL) * (0.08 + 0.12 * h1)) * 0.78 * len;
 var pos = anchor + 2.0 * s * (1.0 - s) * b1 + s * s * b2;
 pos += dragAt(c, s, len, DRAG_T * (0.8 + 0.4 * h2) * (0.8 + 0.4 * c.es));
 let w = TAU * ((freq + 0.35 * c.act) * s - 0.11 * c.t) + phi * 3.0 + h1 * 6.0;
 let amp = (0.06 + 0.1 * c.act) * len * pow(s, 1.5);
 pos += (c.side * sin(w) + c.side2 * 0.6 * hand * cos(0.8 * w + 1.3)) * amp;
 pos += sweepAt(c, s) * len;
 pos += hfDir(c.fP, outL) * 0.012 * len * sin(3.14159 * s) * pp;
 pos += (hfDir(c.fP, outL) * 0.7 + c.droop * 0.5) * 0.11 * len * sin(3.14159 * min(s * 1.1, 1.0) * 0.5) * kickAt(c, s);
 return keepBelow(c, tentRoot(c, phi, 0.0), pos, s, len);
}

fn process(p: Point, ctx: PointCtx) -> Point {
 var o = p;
 let P = ctx.params;
 let i = ctx.index;
 let t = ctx.absTime;
 // The music's part (the strike and the voices' envelopes) scales with the owner's reaction amount.
 let hitR = P.hit * P.react;
 let r0 = mHash(i, 1u); let r1 = mHash(i, 2u); let r2 = mHash(i, 3u); let r3 = mHash(i, 4u);
 let r4 = mHash(i, 5u); let r5 = mHash(i, 6u); let r6 = mHash(i, 7u); let r7 = mHash(i, 8u);
 // The bell leads; the water streams past along minus its (slowly turning) axis.
 let flowDir = normalize(vec3f(P.swimDirX, P.swimDirY, P.swimDirZ) + vec3f(0.0, 1e-4, 0.0));
 // The water's displacement so far: the INTEGRAL of the axis times d(travel), never axis * travel,
 // so a turning bell bends the stream from now on instead of swinging the whole field.
 let swum = vec3f(P.flowX, P.flowY, P.flowZ);
 // Camera basis.
 let eye = vec3f(P.camX, P.camY, P.camZ);
 let fwd = normalize(vec3f(P.camTX, P.camTY, P.camTZ) - eye);
 let right = normalize(cross(fwd, vec3f(0.0, 1.0, 0.0)));
 let up = cross(right, fwd);
 let tanH = tan(radians(P.camFov) * 0.5);
 let pxPerDepth = 2.0 * tanH / 1080.0;
 let lumK = (0.2 + 0.8 * sqrt(P.lum)) * P.gain;

 var pos = vec3f(0.0);
 var b = 0.0;
 var col = vec3f(1.0);
 var sizePx = 2.0;

 if (i < DUST) {
  // ---------------- DUST: three depth layers, world-anchored, streaming with the medium, plus
  // glitter clusters (the last 400) in the mid layer: dense clumps that only light up at peak.
  var dc = 23.0; var bs = vec3f(52.0, 28.0, 18.0); var layer = 0.0;
  if (i >= 1800u) { dc = 11.0; bs = vec3f(28.0, 15.0, 9.0); layer = 1.0; }
  if (i >= 3100u) { dc = 5.0; bs = vec3f(14.0, 8.0, 5.0); layer = 2.0; }
  let isGlitter = i >= 3696u;
  if (isGlitter) { dc = 9.0; bs = vec3f(24.0, 13.0, 8.0); layer = 1.0; }
  let centre = eye + fwd * dc;
  let drift = -swum * P.flow + 0.35 * vec3f(sin(t * 0.021 + r5 * TAU), sin(t * 0.017 + r6 * TAU), sin(t * 0.019 + r7 * TAU));
  var seed = vec3f(r1, r2, r3) * bs * 13.7;
  if (isGlitter) {
   let cl = (i - 3696u) / 66u;
   let cs = vec3f(mHash(cl, 61u), mHash(cl, 62u), mHash(cl, 63u)) * bs * 13.7;
   let g1 = sqrt(-2.0 * log(max(r5, 1e-4)));
   seed = cs + vec3f(g1 * cos(TAU * r6) * 0.9, g1 * sin(TAU * r6) * 0.5, (r7 - 0.5) * 1.2) * (0.35 + 0.65 * r3);
  }
  let f = fract((seed + drift - centre) / bs) - 0.5;
  pos = centre + f * bs;
  let w = smoothstep(0.5, 0.38, abs(f.x)) * smoothstep(0.5, 0.38, abs(f.y)) * smoothstep(0.5, 0.36, abs(f.z));
  let depth = dot(pos - eye, fwd);
  let nearFade = smoothstep(1.4, 2.6, depth);
  // Far dust is dim and blue (depth fog), near dust brighter, warmer and softer.
  let fog = smoothstep(4.0, 26.0, depth);
  let base = mix(0.95, 0.3, fog) * (0.45 + 2.5 * pow(r4, 6.0));
  // The creature lights the water: dust near the hero and its recent path brightens and takes its colour.
  let hero = vec3f(P.heroX, P.heroY, P.heroZ);
  let rr = 1.6 * P.heroScale;
  let d0 = pos - hero; let d1 = pos - vec3f(P.heroX1, P.heroY1, P.heroZ1);
  let d2 = pos - vec3f(P.heroX2, P.heroY2, P.heroZ2); let d3 = pos - vec3f(P.heroX3, P.heroY3, P.heroZ3);
  let prox = 1.0 / (1.0 + dot(d0, d0) / (rr * rr)) + 0.5 / (1.0 + dot(d1, d1) / (1.3 * rr * rr)) + 0.35 / (1.0 + dot(d2, d2) / (1.6 * rr * rr)) + 0.25 / (1.0 + dot(d3, d3) / (2.0 * rr * rr));
  let lit = prox * (0.9 + 0.1 * P.pulse + 0.2 * hitR);
  b = P.env * base * w * nearFade * (0.55 + 0.45 * P.energy) * (0.8 + 0.2 * sin(t * (0.3 + 0.5 * r5) + r6 * TAU)) * (1.0 + 2.5 * lit);
  col = mix(moodColor(P.mood, 0.45 + 0.35 * r0), mix(moodColor(P.mood, 0.1), vec3f(0.35, 0.45, 0.85), 0.5), fog);
  col = mix(col, moodColor(P.mood, 0.75), clamp(lit * 1.2, 0.0, 0.85));
  // A believable size spread: most specks tiny, a few larger soft ones.
  sizePx = 1.5 + 0.6 * r7 + 4.0 * pow(r7, 9.0) + layer * 0.3;
  if (isGlitter) {
   let gl = smoothstep(0.45, 1.0, P.density) * (0.3 + 0.7 * P.lum);
   let tw = 0.55 + 0.45 * sin(t * (2.5 + 2.5 * r6) * 0.2 + r3 * TAU);
   b = w * nearFade * (0.4 + 3.0 * pow(r4, 5.0)) * tw * tw * gl;
   col = mix(vec3f(1.0), 0.5 + 0.5 * cos(TAU * (vec3f(0.0, 0.33, 0.67) + r0 * 3.0 + t * 0.02)), 0.6);
   sizePx = 1.4 + 0.8 * r7;
  }
 } else {
  // ---------------- WAKE.
  let hero = vec3f(P.heroX, P.heroY, P.heroZ);
  let h1 = vec3f(P.heroX1, P.heroY1, P.heroZ1);
  let h2 = vec3f(P.heroX2, P.heroY2, P.heroZ2);
  let h3 = vec3f(P.heroX3, P.heroY3, P.heroZ3);
  let f = hfMake(P.heroX, P.heroY, P.heroZ, P.tiltX, P.tiltZ, P.heroScale);
  let tc = tcMake(f, h1, h2, h3, P.swimRate, P.tiltX, P.tiltZ, pulseEnv(P.pulsePhase), P.pulsePhase, P.tensionS, P.densityS, t, vec3f(P.kick0, P.kick1, P.kick2), P.energyS, P.kickS, P.rigLean);
  let upM = -tc.droop; // the bell's period-mean axis
  let k = i - DUST;
  let u = f32(k) / 6144.0;
  var envs = array<f32, 5>(P.env0, P.env1, P.env2, P.env3, P.env4);
  let sc = P.heroScale;
  var bright = 0.0;
  var colT = 0.85;
  if (u >= 0.42 && u < 0.9) {
   // ---- RIM TENTACLES: 20 strands, 147 beads each.
   let strand = min(u32((u - 0.42) / 0.024), 19u);
   let v = strand / 4u;
   let j = strand % 4u;
   let fv = f32(v);
   let phi = (fv + 0.15 + 0.7 * (f32(j) + 0.5) / 4.0 + 0.08 * (stableRand(strand, 31u) - 0.5)) / 5.0 * TAU + 0.4;
   let hs1 = stableRand(strand, 32u);
   let hs2 = stableRand(strand, 33u);
   let len = (1.0 + 1.5 * pow(stableRand(strand, 34u), 1.3)) * (0.85 + 0.3 * P.density) * sc;
   let hand = select(-1.0, 1.0, (v % 2u) == 0u);
   let freq = 0.45 + 0.08 * fv;
   // Beads flow slowly root to tip (about 28 s), then come loose and drift off with the water.
   let rate = 0.035;
   let sb = fract(r2 + t * rate);
   let sDet = 0.8;
   if (sb < sDet) {
    pos = rimPoint(tc, phi, len, hs1, hs2, hand, freq, sb / sDet);
   } else {
    let td = (sb - sDet) / rate;
    let tip = rimPoint(tc, phi, len, hs1, hs2, hand, freq, 1.0);
    let carried = -flowDir * P.flow * (P.travel - travelBack(td, P));
    let loose = normalize(vec3f(r5 - 0.5, r6 - 0.5, r7 - 0.5) + vec3f(1e-4)) * 0.18 * sqrt(td) * sc;
    pos = tip + carried + loose;
   }
   let sm = min(sb / sDet, 1.0);
   let en = clamp(envs[v] / 0.4, 0.0, 1.0) * clamp(P.react, 0.0, 2.0);
   // Beads, not a dotted line: about one in six of the strand's motes is a bead.
   let isBead = mHash(i, 71u) < 0.17;
   let act = smoothstep(stableRand(strand, 35u) - 0.1, stableRand(strand, 35u) + 0.1, 0.35 + 0.65 * P.density + select(0.0, 0.3, v == 4u)) * select(0.0, 1.0, isBead);
   let fadeIn = smoothstep(0.0, 0.05, sb);
   let fadeOut = 1.0 - smoothstep(sDet, 1.0, sb);
   // Light: the voice's envelope (soft), the hero's strike band travelling tipward, the swim swell.
   let swell = 0.2 * pres(P.pulsePhase - 0.1 - 0.6 * sm) + 0.3 * hitR * exp(-2.0 * sm);
   bright = (0.9 + 2.5 * pow(r5, 4.0)) * (0.5 + 0.5 * en) * (0.8 + swell) * act * fadeIn * fadeOut;
   colT = 0.97 - 0.25 * sm;
   sizePx = 1.8 + 0.9 * r7;
  } else {
   var L = 4.5 + 4.0 * r1;
   var age = 0.0;
   let isRing = u >= 0.9;
   if (isRing) {
    // Vortex rings: two alive at once, one per stroke at mid-squeeze (rig pu counts strokes). A mote
    // keeps its ring for the ring's whole life (group g owns every other stroke).
    let T = 1.0 / max(P.swimRate, 0.05);
    let x = P.pu - 0.12;
    let cyc = i32(floor(x));
    let g = i32(r1 * 2.0);
    let back = ((cyc - g) % 2 + 2) % 2;
    age = (fract(x) + f32(back)) * T;
    L = 2.0 * T;
   } else {
    age = fract(t / L + r2) * L;
   }
   // Where the hero was at birth: the rig's history, then (damped) its average velocity.
   var hb = hero;
   if (age < 0.7) { hb = mix(hero, h1, age / 0.7); }
   else if (age < 1.4) { hb = mix(h1, h2, (age - 0.7) / 0.7); }
   else if (age < 2.1) { hb = mix(h2, h3, (age - 1.4) / 0.7); }
   else { let x = age - 2.1; hb = h3 + (hero - h3) * (1.0 / 2.1) * 1.6 * (1.0 - exp(-x / 1.6)); }
   let carried = -flowDir * P.flow * (P.travel - travelBack(age, P));
   var local = vec3f(0.0, -0.45, 0.0);
   if (!isRing) {
    let a = r3 * TAU;
    if (r4 < 0.6) { local = vec3f(cos(a) * 0.98, -0.39, sin(a) * 0.98); }
    else { let rr = 0.25 + 0.55 * sqrt(r5); local = vec3f(cos(a) * rr, -0.55 - 2.2 * pow(r6, 1.3), sin(a) * rr); }
   }
   let birth = hb + hfDir(tc.fP, local * sc);
   pos = birth + carried;
   let lifeU = age / L;
   let born = smoothstep(0.0, 0.3, age);
   if (isRing) {
    let jet = -upM * 0.75 * sc * (1.0 - exp(-age / 1.2));
    let a1 = normalize(cross(upM, vec3f(0.0, 0.0, 1.0)));
    let a2 = cross(upM, a1);
    let al = r3 * TAU;
    let er = a1 * cos(al) + a2 * sin(al);
    let R = 0.8 * sc * (1.0 + 0.12 * age);
    let rm = (0.07 + 0.025 * age) * sc;
    let psi = r4 * TAU + 1.1 * age;
    pos = pos + jet + er * R + (er * cos(psi) - upM * sin(psi)) * rm;
    bright = (1.0 + 1.5 * pow(r5, 3.0)) * (0.4 + 0.6 * P.energy) * (1.0 - smoothstep(0.35, 1.0, lifeU)) * born;
    colT = 0.9;
   } else {
    // Spread from the body axis as they age, plus a smooth outward swell on a strike (rig hit is a
    // lagged pulse: no step in position or velocity), then the slow eddies of the water.
    let out = normalize(birth - hb - upM * dot(birth - hb, upM) + vec3f(1e-4));
    // (pass 13: the strike no longer pushes them: with real music it struck several times a second and
    // threw the motes about. The music only lights them.)
    pos = pos + out * (0.12 * sqrt(age)) * sc;
    var y = birth + P.flow * (swum - flowDir * (P.travel - travelBack(age, P)));
    var dsp = vec3f(0.0);
    let dt = age / 6.0;
    let amp = 0.3 + 0.3 * P.tension;
    for (var st = 0; st < 6; st = st + 1) {
     let tau = (t - age) + (f32(st) + 0.5) * dt;
     dsp = dsp + curlField(y + dsp, tau, 1.9) * dt * amp * smoothstep(0.0, 1.6, (f32(st) + 0.5) * dt);
    }
    pos = pos + dsp;
    // Thinned: at most about half the shed motes light, and fewer at calm.
    let act = smoothstep(r0 - 0.1, r0 + 0.1, 0.1 + 0.4 * P.energy);
    bright = (1.1 + 4.0 * pow(r5, 5.0)) * exp(-age * 0.2) * act * (1.0 + 0.2 * hitR * exp(-age)) * born * (1.0 - smoothstep(0.55, 1.0, lifeU));
    colT = 0.85 - 0.45 * lifeU;
   }
   sizePx = 1.9 + 1.0 * r7;
  }
  // Three size classes: 70 % tiny, 25 % small, 5 % large soft beads (dimmer per pixel, warm).
  let sc3 = mHash(i, 77u);
  var big = 0.0;
  if (sc3 < 0.7) { sizePx = 1.5; } else if (sc3 < 0.95) { sizePx = 2.6; } else { sizePx = 6.0; big = 1.0; }
  b = bright * select(1.0, 1.6, big > 0.5);
  col = moodColor(P.mood, colT);
  let film = 0.5 + 0.5 * cos(TAU * (vec3f(0.0, 0.33, 0.67) + r6 * 3.0 + t * 0.05));
  col = mix(col, film, select(0.0, 0.5, r7 < 0.15));
  col = mix(col, vec3f(1.0), 0.18);
  // The fixed warm accent (#ffc890) on the beads and the large motes, in every mood.
  if (u >= 0.42 && u < 0.9) { col = mix(col, WARM, 0.6); }
  col = mix(col, WARM, 0.7 * big);
 }

 // Depth of field, the same lens as the DOF passes: circle = aperture * |1 - focus / depth| (the
 // focus is the hero's view depth). Near motes open into large soft discs; far ones only soften
 // (capped), so the far dust still reads as points streaming. Light is spread, mostly kept.
 let depth = max(dot(pos - eye, fwd), 0.3);
 let focus = max(dot(vec3f(P.heroX, P.heroY, P.heroZ) - eye, fwd), 0.5);
 let cl = P.aperture * (1.0 - focus / (depth - clamp(depth - focus, -P.band, P.band)));
 let coc = select(min(cl, 0.3 * P.aperture), min(-cl, 18.0), cl < 0.0);
 let px = sizePx + coc;
 // Pass 14: never smaller than the pixel grid can draw round (4 px across); a finer point's light is spread, it dims.
 let dpx = max(px, 4.0);
 b = b * pow((sizePx * sizePx) / (px * px), 0.8) * pow(px / dpx, 1.6);
 let hot = select(1.0, 4.0 + 6.0 * r6, r5 > 0.965 && i >= DUST);
 b = b * hot * lumK;

 o.position = pos;
 o.size = 0.5 * dpx * pxPerDepth * depth;
 o.tint = vec4f(col * b, fract(0.6 + 0.3 * r3));
 return o;
}

parameters.source:
// WORLD LENS (Silk Medusa): one full-resolution pass, three taps. Radial chromatic fringe that
// grows toward the corners, a soft round vignette, and a HUE-PRESERVING highlight shoulder: above
// `knee` the brightest channel is compressed toward `ceiling` with all three channels scaled
// together, so the hottest silk and bell light keeps its colour instead of clipping to white in
// the grade's curve. Runs on scene-linear HDR, before the grade.
// Pass 10: it also COMPOSITES the bloom (replacing add_glow, whose opacity scaled its front input, the
// picture, not the glow): out = picture * `picture` + bloom * `glow`. `picture` keeps the old balance
// (0.4 + 0.3 lum); `glow` is the owner's glow slider (rig glowGain): 0 removes the bloom and only it.
// input = the picture (add_sky), inputTexture1 = the Bloom Pyramid's glow.
struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
struct Params {
 fringe: f32, // @default 1.4 Chromatic fringe at the frame corners, in pixels.
 vignette: f32, // @default 0.32 Darkening toward the corners.
 knee: f32, // @default 1.6 Brightest-channel level where the colour-keeping shoulder starts.
 ceiling: f32, // @default 5 Level the shoulder approaches.
 picture: f32, // @default 0.55 Picture level before the glow is added (0.4 + 0.3 * rig lum: the balance add_glow had).
 glow: f32, // @default 1 Bloom amount (rig glowGain): 0 = no glow, the picture untouched.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
fn tap(uv: vec2f) -> vec4f {
 return textureSampleLevel(inputTexture, inputSampler, uv, 0.0) * params.picture + textureSampleLevel(inputTexture1, inputSampler, uv, 0.0) * params.glow;
}
@fragment fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
 let res = frameU.resolution;
 let c = (uv - 0.5) * vec2f(res.x / res.y, 1.0);
 let r2 = dot(c, c) / (0.25 * (res.x / res.y) * (res.x / res.y) + 0.25);
 let off = normalize(uv - 0.5 + vec2f(1e-5)) * r2 * params.fringe / res;
 let rch = tap(uv + off).r;
 let g = tap(uv);
 let bch = tap(uv - off).b;
 let vr = dot(c, c) / 0.55;
 let vig = mix(1.0, 1.0 - smoothstep(0.15, 1.1, vr), params.vignette);
 var hc = vec3f(rch, g.g, bch) * vig;
 let m = max(hc.r, max(hc.g, hc.b));
 if (m > params.knee) {
  let x = m - params.knee;
  let span = max(params.ceiling - params.knee, 1e-3);
  hc = hc * ((params.knee + x / (1.0 + x / span)) / m);
 }
 return vec4f(hc, 1.0);
}

parameters.kernel:
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}
// WORLD LIFE, pass 10 (Silk Medusa): the PLACE around the creatures. A fixed population of additive
// point sprites at clearly different depths, stateless: every position is a continuous function of
// time and of the water's integrated displacement (the same water the dust streams in), anchored in
// the world, so the camera's truck and orbit give each layer the parallax of its depth.
//   SNOW    near the lens (0.6..6 deep): sparse marine snow sinking and streaming past, wide soft discs
//           from the shared lens; it slides fastest of all under the truck.
//   STRANDS mid water (6..26 behind the hero): long plankton strings hanging in the current, slowly
//           undulating; they light up where the hero has just swum (its last two seconds of path).
//   COMBS   mid water (2..9 behind the hero): four comb jellies; spectral glints run down their
//           eight comb rows (a steady metachronal wave, never driven by the music).
//   SHOALS  far (35..55 behind): two faint shoals of tiny lights turning slowly, galaxies of points;
//           musical energy lights more of them (energy -> particle density).
// (The large form passing far off once in a while is a silhouette in the medium pass.)
// Light only from: lum, density, energy (all slow rig levels) and the hero's proximity. No note
// timing, no envelopes, no resetting timers.
// PASS 12, BEATS (rig bioKick / bioSnare / bioHat: continuous 0..1 pulse envelopes, already scaled by
// the reaction slider; 0 outside the any-audio variant). Light only, never position:
//   PLANKTON (new, around the hero, dark until disturbed): each KICK sends a front of small blue-green
//           lights out from the hero over about a second. A point's delay comes from its distance (it
//           reads the kick through 0..5 lag stages of 0.18 s, interpolated), so the front travels; its
//           own slowly falling stage is its afterglow. Fronts overlap at fast tempi.
//   SNARE:  a chase down some strands (stages by position along the strand), a faster glint run on
//           the comb rows, a few shoal members answering.
//   HATS:   fine sparkle on tiny points (a slowly rotating few per cent of the plankton and shoals,
//           a little on the marine snow), proportional to the hat envelope.
// Eligibility rotates by slow per-point sines, never by a stepped hash, so nothing pops.
// PASS 13 (owner: "covering a bit too much on the front", "their movement and swerving"): the beat-lit
// life sits beside and behind the creature, not between it and the lens; the plankton hang still in the
// water (no stream, only a slow wander) and the strands and comb jellies take only a third of the
// stream, so lit points drift like suspended particles; the snow no longer twinkles with the hats.
// PASS 14 (owner: "spotty around the hero ... permanently feels a bit static", "the individual string creatures
// could use more polish", "the bioluminescence is kinda squarish, which looks a bit lofi"):
//   SPRITES  a point is never drawn smaller than MINPX pixels across: below that the engine's cone falloff lands
//           on one or two pixel centres (a square pixel that snaps on and off as the point crosses the grid).
//           The light is spread over the larger disc instead (a sub-pixel point DIMS).
//   PLANKTON drift in the water: a small share of the scene's stream, a slow eddy field fixed in the water, each
//           point's own slow drift and sink or rise; the hero's passage carries the nearest along a little and
//           parts them (from its mean velocity over the last 0.7 s and 1.4 s, never from a beat). At rest a few
//           per cent breathe, each on its own cycle (35 to 90 s, stable hash). The field is one soft ellipsoid of
//           fixed size in the water round the hero (it used to be a box that scaled with the hero), denser in
//           clumps that travel with the water; the clear zone in front of the creature is narrower and softer.
//   STRANDS  beaded chains: a tapering thread, 48 nodes of varying size, a soft sheath, a slow light travelling
//           down the chain (and the snare chase), a slight fixed bend under the travelling undulation.
//   COMBS    a translucent body (48 soft discs on the ovoid: the limb reads brighter), 8 comb rows of 14 plates
//           whose spectral glint runs smoothly down the row, an apical light.
struct Params {
 energy: f32, // @default 0.5 Rig energy (slow section level): how many shoal lights are lit.
 density: f32, // @default 0.5 Rig density: how many strands and snow flakes are present.
 lum: f32, // @default 0.45 Rig illumination: overall light.
 mood: f32, // @default 0 Rig palette position 0..4.
 heroX: f32, // @default 1 Hero x now.
 heroY: f32, // @default 1.2 Hero y now.
 heroZ: f32, // @default 0 Hero z now.
 heroX1: f32, // @default 1 Hero x 0.7 s ago.
 heroY1: f32, // @default 1.2 Hero y 0.7 s ago.
 heroZ1: f32, // @default 0 Hero z 0.7 s ago.
 heroX2: f32, // @default 1 Hero x 1.4 s ago.
 heroY2: f32, // @default 1.2 Hero y 1.4 s ago.
 heroZ2: f32, // @default 0 Hero z 1.4 s ago.
 heroScale: f32, // @default 1 Hero size.
 flowX: f32, // @default 0 Integrated swim (speed_worldflow flowX): the water's displacement, x.
 flowY: f32, // @default 0 Integrated swim, y.
 flowZ: f32, // @default 0 Integrated swim, z.
 flow: f32, // @default 7 Medium speed per unit of travel (same as kernel_worldmotes.flow).
 aperture: f32, // @default 40 Lens circle at infinity, full-res px (same as the DOF passes).
 band: f32, // @default 1.5 Sharp depth band either side of the hero (same as the DOF passes).
 camX: f32, // @default 0 Camera eye x.
 camY: f32, // @default 0.4 Camera eye y.
 camZ: f32, // @default 12 Camera eye z.
 camTX: f32, // @default 0 Camera target x.
 camTY: f32, // @default 0.2 Camera target y.
 camTZ: f32, // @default 0 Camera target z.
 camFov: f32, // @default 38 Camera vertical fov, degrees.
 gain: f32, // @default 1 Overall light.
 snow: f32, // @default 1 Marine snow gain.
 strands: f32, // @default 1 Plankton strand gain.
 combs: f32, // @default 1 Comb jelly gain.
 shoals: f32, // @default 1 Far shoal gain.
 kS0: f32, // @default 0 Kick front, stage 0 (rig bioKick).
 kS1: f32, // @default 0 Kick front, stage 1 (rig bioKick through 1 x 0.12 s lags: lag_worldbeat1).
 kS2: f32, // @default 0 Kick front, stage 2 (rig bioKick through 2 x 0.12 s lags: lag_worldbeat2).
 kS3: f32, // @default 0 Kick front, stage 3 (rig bioKick through 3 x 0.12 s lags: lag_worldbeat3).
 kS4: f32, // @default 0 Kick front, stage 4 (rig bioKick through 4 x 0.12 s lags: lag_worldbeat4).
 kS5: f32, // @default 0 Kick front, stage 5 (rig bioKick through 5 x 0.12 s lags: lag_worldbeat5).
 sS0: f32, // @default 0 Snare chase, stage 0 (rig bioSnare).
 sS1: f32, // @default 0 Snare chase, stage 1 (rig bioSnare, lag_worldbeat1).
 sS2: f32, // @default 0 Snare chase, stage 2 (rig bioSnare, lag_worldbeat2).
 sS3: f32, // @default 0 Snare chase, stage 3 (rig bioSnare, lag_worldbeat3).
 sS4: f32, // @default 0 Snare chase, stage 4 (rig bioSnare, lag_worldbeat4).
 sS5: f32, // @default 0 Snare chase, stage 5 (rig bioSnare, lag_worldbeat5).
 hat: f32, // @default 0 Hat sparkle (rig bioHat, direct: the scene's fastest light, on tiny points only).
 plankton: f32, // @default 1 Beat plankton gain.
 env: f32, // @default 1 Environment amount (rig envGain, owner's slider, 0..2): 0 = only the creatures in black water, 2 = rich.
};

const NSNOW: u32 = 384u;
const STR0: u32 = 384u;    // 8 strands x 192
const SPS: u32 = 192u;
const COMB0: u32 = 1920u;  // 4 comb jellies x 160 (8 rows x 20)
const CPS: u32 = 160u;
const SHOAL0: u32 = 2560u; // 2 shoals x 1920
const SHS: u32 = 1920u;
const PLANK0: u32 = 6400u; // 2560 plankton round the hero (pass 12)
// Stage gains: one isolated hit (test envelope, peak 0.737) peaks at 0.56 / 0.488 / 0.442 / 0.408 / 0.383 through
// the five 0.18 s lag stages (probe at 30 bpm; stage 5 peaks 1.0 s after the hit), so each stage is lifted
// back to the envelope's own peak.
const GA1: f32 = 1.32; const GA2: f32 = 1.51; const GA3: f32 = 1.67; const GA4: f32 = 1.8; const GA5: f32 = 1.92;
const BIO: vec3f = vec3f(0.25, 0.85, 1.0); // the classic blue-green bioluminescent accent, every mood

fn lHash(i: u32, salt: u32) -> f32 {
 var x = i * 747796405u + salt * 2891336453u + 7919u;
 x = (x ^ (x >> 15u)) * 2246822519u;
 x = (x ^ (x >> 13u)) * 3266489917u;
 x = x ^ (x >> 16u);
 return f32(x >> 8u) * (1.0 / 16777216.0);
}
fn lHash3(i: u32, salt: u32) -> vec3f { return vec3f(lHash(i, salt), lHash(i, salt + 1u), lHash(i, salt + 2u)); }
fn spectral(h: f32) -> vec3f {
 return clamp(abs(fract(h + vec3f(0.0, 0.667, 0.333)) * 6.0 - 3.0) - 1.0, vec3f(0.0), vec3f(1.0));
}
// Soft fade at every face of a wrapping box (f in -0.5..0.5 per axis).
fn boxFade(f: vec3f) -> f32 {
 return smoothstep(0.5, 0.36, abs(f.x)) * smoothstep(0.5, 0.36, abs(f.y)) * smoothstep(0.5, 0.36, abs(f.z));
}
// A beat channel seen through its lag stages: x = 0 the envelope itself .. 5 the fifth lag, linear
// between. Stages are normalised so a lone hit peaks about equally at every stage.
fn stageAt(x: f32, a0: f32, a1: f32, a2: f32, a3: f32, a4: f32, a5: f32) -> f32 {
 let y = clamp(x, 0.0, 4.999);
 let f = fract(y);
 var lo = a0; var hi = a1;
 if (y >= 1.0) { lo = a1; hi = a2; }
 if (y >= 2.0) { lo = a2; hi = a3; }
 if (y >= 3.0) { lo = a3; hi = a4; }
 if (y >= 4.0) { lo = a4; hi = a5; }
 return mix(lo, hi, f);
}
// A point's slowly rotating eligibility for sparkle (about `share` of them at a time).
fn rotGate(h1: f32, h2: f32, t: f32, share: f32) -> f32 {
 let w = 0.5 + 0.5 * sin(t * (0.3 + 0.9 * h1) + h2 * 6.2831853);
 return smoothstep(1.0 - share * 1.4, 1.0 - share * 0.6, w);
}

// Two vectors perpendicular to a.
fn basisOf(a: vec3f) -> mat2x3f {
 let h = select(vec3f(0.0, 0.0, 1.0), vec3f(1.0, 0.0, 0.0), abs(a.z) > 0.9);
 let n1 = normalize(cross(a, h));
 return mat2x3f(n1, cross(a, n1));
}

// The smallest disc the pixel grid resolves as a round, soft sprite (diameter, px): see PASS 14.
const MINPX: f32 = 4.0;
// Smooth value noise in the water (clumps of plankton, about 2 units across).
fn cellH(c: vec3i) -> f32 {
 let u = bitcast<vec3u>(c);
 return lHash(u.x * 73856093u + u.y * 19349663u + u.z * 83492791u, 91u);
}
fn vnoise3(p: vec3f) -> f32 {
 let c = vec3i(floor(p));
 let f = fract(p);
 let w = f * f * (3.0 - 2.0 * f);
 let x00 = mix(cellH(c), cellH(c + vec3i(1, 0, 0)), w.x);
 let x10 = mix(cellH(c + vec3i(0, 1, 0)), cellH(c + vec3i(1, 1, 0)), w.x);
 let x01 = mix(cellH(c + vec3i(0, 0, 1)), cellH(c + vec3i(1, 0, 1)), w.x);
 let x11 = mix(cellH(c + vec3i(0, 1, 1)), cellH(c + vec3i(1, 1, 1)), w.x);
 return mix(mix(x00, x10, w.y), mix(x01, x11, w.y), w.z);
}
fn process(p: Point, ctx: PointCtx) -> Point {
 var o = p;
 let P = ctx.params;
 let i = ctx.index;
 let t = ctx.absTime;
 let eye = vec3f(P.camX, P.camY, P.camZ);
 let fwd = normalize(vec3f(P.camTX, P.camTY, P.camTZ) - eye);
 let tanH = tan(radians(P.camFov) * 0.5);
 let pxPerDepth = 2.0 * tanH / 1080.0;
 let hero = vec3f(P.heroX, P.heroY, P.heroZ);
 let h1 = vec3f(P.heroX1, P.heroY1, P.heroZ1);
 let h2 = vec3f(P.heroX2, P.heroY2, P.heroZ2);
 let focus = max(dot(hero - eye, fwd), 0.5);
 // The water's displacement so far (the same field the dust and the wake ride on).
 let drift = -vec3f(P.flowX, P.flowY, P.flowZ) * P.flow;
 let litK = (0.3 + 0.7 * P.lum) * P.gain * P.env;
 // More of every population is present at a richer environment amount (light scales separately).
 let envD = clamp(0.5 + 0.5 * P.env, 0.0, 1.5);
 let r0 = lHash(i, 1u); let r1 = lHash(i, 2u); let r2 = lHash(i, 3u); let r3 = lHash(i, 4u);
 // normalised beat stages (stage gains from a probe of one isolated hit through the lag chain)
 let k0 = P.kS0; let k1 = P.kS1 * GA1; let k2 = P.kS2 * GA2; let k3 = P.kS3 * GA3; let k4 = P.kS4 * GA4; let k5 = P.kS5 * GA5;
 let s0 = P.sS0; let s1 = P.sS1 * GA1; let s2 = P.sS2 * GA2; let s3 = P.sS3 * GA3; let s4 = P.sS4 * GA4; let s5 = P.sS5 * GA5;

 var pos = vec3f(0.0);
 var b = 0.0;
 var col = vec3f(1.0);
 var sizePx = 1.4;
 var sizeW = 0.0;                 // > 0: the sprite's own diameter in world units (creatures keep their proportions)
 var cocCap = 0.3 * P.aperture;   // far points only soften (capped), near ones open wide

 if (i < NSNOW) {
  // ---- SNOW: flakes in a box hugging the lens, sinking slowly through the streaming water.
  let centre = eye + fwd * 3.4;
  let bs = vec3f(8.0, 4.8, 5.6);
  let seed = lHash3(i, 10u) * bs * 13.7;
  let sink = vec3f(0.0, -0.045 * t * (0.6 + 0.8 * r1), 0.0);
  let wob = 0.18 * vec3f(sin(t * (0.11 + 0.05 * r2) + r0 * 6.3), 0.5 * sin(t * 0.09 + r3 * 6.3), sin(t * (0.08 + 0.04 * r1) + r2 * 6.3));
  let f = fract((seed + drift + sink + wob - centre) / bs) - 0.5;
  pos = centre + f * bs;
  let depth = dot(pos - eye, fwd);
  let present = smoothstep(r2 - 0.08, r2 + 0.08, (0.35 + 0.65 * P.density) * envD);
  b = (3.0 + 8.0 * pow(r0, 6.0)) * boxFade(f) * smoothstep(0.55, 1.3, depth) * present * P.snow;
  col = mix(moodColor(P.mood, 0.5 + 0.2 * r3), vec3f(0.85, 0.9, 1.0), 0.55);
  sizePx = 1.6 + 1.6 * r1;
  cocCap = 1.2 * P.aperture;
 } else if (i < COMB0) {
  // ---- STRANDS: eight beaded chains hanging in the mid water. Of a strand's 192 points 120 are its thread,
  // 48 its nodes (unevenly spaced, a few large) and 24 the soft sheath round it.
  let k = i - STR0;
  let s = k / SPS;
  let j = k % SPS;
  let hs = lHash3(s, 20u);
  let hj = lHash(i, 31u);
  let hn = lHash(i, 32u);
  var u = (f32(j) + 0.5) / 120.0;
  var role = 0;
  if (j >= 168u) { role = 2; u = (f32(j - 168u) + 0.5) / 24.0; }
  else if (j >= 120u) { role = 1; u = (f32(j - 120u) + 0.5 + 0.7 * (hj - 0.5)) / 48.0; }
  let centre = eye + fwd * (focus + 14.0);
  let bs = vec3f(46.0, 22.0, 26.0);
  let anchorSeed = hs * bs * 9.1 + vec3f(f32(s) * 5.3, 0.0, 0.0);
  let fa = fract((anchorSeed + 0.3 * drift - centre) / bs) - 0.5;
  let anchor = centre + fa * bs;
  // Mostly hanging, leaning a little, turning very slowly.
  let ph = hs.x * 6.283;
  let ax = normalize(vec3f(0.35 * sin(0.013 * t + ph), 1.0, 0.25 * cos(0.011 * t + 2.0 * ph)));
  let nb = basisOf(ax);
  let len = 3.6 + 4.4 * hs.y;
  // A slight fixed bend, and slow undulations TRAVELLING down the chain (fixed rates: the current, not the
  // music), growing toward the free end.
  let w1 = sin(6.2831853 * (1.3 * u - 0.045 * t) + ph);
  let w2 = cos(6.2831853 * (0.8 * u - 0.031 * t) + 2.0 * ph);
  let bend = (hs.z - 0.5) * 1.1 * (u - 0.5) * (u - 0.5);
  let amp = (0.035 + 0.075 * u) * smoothstep(0.0, 0.25, u);
  pos = anchor + ax * (0.5 - u) * len + (nb[0] * (bend + w1 * amp * (0.6 + 0.4 * hs.z)) + nb[1] * (w2 * amp * 0.7 - 0.6 * bend)) * len;
  // The body tapers from the head to a fine tail, and both ends fade out rather than stop.
  let body = smoothstep(-0.02, 0.1, u) * mix(1.0, 0.22, smoothstep(0.05, 1.0, u));
  let ends = smoothstep(0.0, 0.1, u) * smoothstep(1.0, 0.62, u);
  // Plankton lights where the hero has just swum: its path over the last 1.4 s.
  let d0 = pos - hero; let d1 = pos - h1; let d2 = pos - h2;
  let rr = 1.8 * P.heroScale;
  let wake = 1.0 / (1.0 + dot(d0, d0) / (rr * rr)) + 0.7 / (1.0 + dot(d1, d1) / (rr * rr)) + 0.45 / (1.0 + dot(d2, d2) / (rr * rr));
  let present = smoothstep(hs.x - 0.1, hs.x + 0.1, (0.25 + 0.75 * P.density) * envD);
  // Light travels down the chain: a slow idle pulse (one soft band every 17 to 25 s, never the music), and on
  // the snare a chase (stage by position), on a slowly rotating third of the strands.
  let idle = pow(0.5 + 0.5 * cos(6.2831853 * (1.15 * u - (0.04 + 0.018 * hs.z) * t) + 3.0 * ph), 6.0);
  let gS = smoothstep(0.45, 0.85, 0.5 + 0.5 * sin(t * 0.23 * (0.7 + 0.6 * hs.y) + hs.z * 6.2831853));
  let chase = stageAt(u * 5.0, s0, s1, s2, s3, s4, s5) * gS;
  let big = hn * hn * hn;
  let sAll = (1.0 + 3.0 * wake) * boxFade(fa) * present * ends * P.strands;
  let bio = mix(BIO, moodColor(P.mood, 0.9), 0.35);
  if (role == 0) {
   b = 0.8 * body * (1.0 + 1.6 * idle + 3.0 * chase) * sAll;
   col = mix(moodColor(P.mood, 0.55), bio, clamp(0.25 + 0.5 * idle + 2.0 * chase, 0.0, 0.85));
   sizeW = 0.012 + 0.03 * body;
  } else if (role == 1) {
   b = (1.3 + 3.2 * big) * (0.45 + 0.55 * body) * (1.0 + 2.8 * idle + 10.0 * chase) * sAll;
   col = mix(moodColor(P.mood, 0.85), moodColor(P.mood, 0.95), clamp(wake, 0.0, 0.8));
   col = mix(col, bio, clamp(0.15 + 0.6 * idle + 3.0 * chase, 0.0, 0.85));
   sizeW = (0.03 + 0.065 * big) * (0.55 + 0.45 * body);
  } else {
   b = 0.12 * (0.35 + 0.65 * body) * (1.0 + 2.2 * idle + 5.0 * chase) * sAll;
   col = mix(bio, moodColor(P.mood, 0.6), 0.4);
   sizeW = 0.34 * (0.4 + 0.6 * body);
  }
  cocCap = 6.0;
 } else if (i < SHOAL0) {
  // ---- COMBS: four comb jellies drifting with the water. Of a jelly's 160 points 112 are its comb plates
  // (8 rows of 14) and 48 its body: soft discs spread over the ovoid, which add up to a translucent body
  // with a brighter limb (more of them overlap where the surface turns away).
  let k = i - COMB0;
  let c = k / CPS;
  let kk = k % CPS;
  let hc = lHash3(c, 40u);
  let centre = eye + fwd * (focus + 5.5);
  let bs = vec3f(20.0, 11.0, 9.0);
  let fa = fract((hc * bs * 7.3 + 0.3 * drift - centre) / bs) - 0.5;
  let anchor = centre + fa * bs;
  let ph = hc.x * 6.283;
  let ax = normalize(vec3f(0.6 * sin(0.07 * t + ph), 1.0, 0.45 * cos(0.05 * t + 2.0 * ph)));
  let nb = basisOf(ax);
  let L = 0.6 + 0.3 * hc.y;
  let plate = kk < 112u;
  let row = kk / 14u;
  let nB = kk - min(kk, 112u);
  let v = select((f32(nB) + 0.5) / 48.0, (f32(kk % 14u) + 0.5) / 14.0, plate);
  let az = select(f32(nB) * 2.3999632, f32(row) * 0.785398, plate) + 0.12 * t + ph;
  let prof = pow(sin(3.14159 * (0.05 + 0.9 * v)), 0.7);
  let R = L * 0.38 * prof;
  let radial = nb[0] * cos(az) + nb[1] * sin(az);
  pos = anchor + ax * (0.5 - v) * L + radial * R;
  let toEye = normalize(eye - pos);
  let facing = dot(toEye, radial);
  let bodyCol = mix(BIO, moodColor(P.mood, 0.7), 0.45);
  if (plate) {
   // The plates beat in a wave that runs down each row; the light they diffract is spectral and slides with it.
   // One band of light per row, a little later on each next row; the spectrum is spread ACROSS the band, so
   // the colours travel with it instead of flickering in place.
   let phase = 1.05 * v - 0.2 * t + f32(row) * 0.13 + hc.z;
   let wave = pow(0.5 + 0.5 * cos(6.2831853 * phase), 5.0);
   let hue = fract(2.2 * (fract(phase + 0.5) - 0.5) + 0.2 * facing + hc.y);
   // snare: a faster glint run down the rows
   let run = pow(0.5 + 0.5 * sin(6.2831853 * (2.0 * v - 1.3 * t) + f32(row) * 0.7), 6.0) * s1;
   let glint = clamp(wave + run, 0.0, 1.0);
   col = mix(bodyCol, mix(spectral(hue), vec3f(1.0), 0.32), 0.15 + 0.85 * glint);
   // (the far side shows through the body, dimmer)
   b = (0.4 + 2.4 * wave + 6.0 * run) * (0.6 + 0.4 * facing) * smoothstep(0.0, 0.12, prof);
   sizeW = 0.02 + 0.014 * glint;
  } else {
   let breathe = 0.85 + 0.15 * sin(0.21 * t + ph);
   b = 0.11 * breathe * (0.7 + 0.3 * prof);
   col = bodyCol;
   sizeW = 0.11 * L + 0.75 * R;
   if (nB == 0u) {
    // the apical organ: one small steady light at the pole
    b = 1.6 * breathe; sizeW = 0.05; col = mix(bodyCol, vec3f(1.0), 0.4);
   }
  }
  b = b * boxFade(fa) * P.combs;
 } else if (i < PLANK0) {
  // ---- SHOALS: two galaxies of tiny lights far behind the hero, turning slowly in their own
  // planes (shear makes soft spiral arms), breathing a little; they keep station in the water.
  let k = i - SHOAL0;
  let sh = k / SHS;
  let C = select(vec3f(-15.0, 8.0, -40.0), vec3f(19.0, -2.0, -50.0), sh == 1u) + vec3f(1.0, 1.2, 0.0)
        + vec3f(2.0 * sin(0.009 * t + f32(sh) * 2.0), 1.0 * sin(0.007 * t + 1.0), 1.5 * cos(0.008 * t + f32(sh)));
  let Rs = select(7.0, 9.5, sh == 1u);
  let nrm = normalize(vec3f(0.35 + 0.2 * sin(0.004 * t), 1.0, select(0.55, -0.4, sh == 1u)));
  let nb = basisOf(nrm);
  let rho = Rs * pow(r0, 0.65);
  let om = 0.035 / (0.25 + rho / Rs);
  let th = r1 * 6.2831853 + om * t;
  // Spiral arms: lights are denser (brighter) on two log-spiral arms.
  let arm = pow(0.5 + 0.5 * cos(2.0 * (th - 2.2 * log(0.3 + rho / Rs))), 3.0);
  let thick = (r2 - 0.5) * Rs * 0.16 * (1.0 - 0.6 * rho / Rs) + 0.25 * Rs * 0.1 * sin(2.0 * th + 0.05 * t + rho);
  pos = C + (nb[0] * cos(th) + nb[1] * sin(th)) * rho * (1.0 + 0.04 * sin(0.03 * t + rho)) + nrm * thick;
  let lit = smoothstep(r3 - 0.1, r3 + 0.1, (0.2 + 0.8 * P.energy) * envD);
  let tw = 0.7 + 0.3 * sin(t * (0.2 + 0.3 * r2) + r1 * 40.0);
  // beats: a few members answer the snare, a rotating few sparkle with the hats
  let ans = select(0.0, 6.0 * s1, r1 < 0.05) + 5.0 * P.hat * rotGate(r2, r0, t, 0.06);
  b = (1.6 + 8.0 * pow(r2, 8.0)) * (0.35 + 0.9 * arm) * (lit + ans) * tw * (1.0 - smoothstep(0.75, 1.0, rho / Rs)) * P.shoals;
  col = mix(moodColor(P.mood, 0.8), moodColor(P.mood + 0.45 * f32(sh), 0.7), 0.4 * r3);
  sizePx = 1.2 + 0.5 * r1;
  cocCap = 2.0;
 } else {
  // ---- PLANKTON: small lights suspended round the hero. They live in the WATER: a lattice of fixed size
  // (it no longer scales with the hero, which moved every point whenever the hero grew) that drifts with a
  // slow current down the scene's stream, plus each point's own slow drift, sink or rise and wander; wrapped
  // into a box that follows the hero, whose faces are never seen (the light is an ellipsoid inside it).
  let hsP = clamp(P.heroScale, 0.8, 1.8);
  let bs = vec3f(10.0, 9.0, 9.0);
  let centre = hero + fwd * (0.16 * bs.z);
  // The current: a steady set down the scene's stream (0.022 units a second) and a twentieth of the stream
  // itself. The stream surges with every swim stroke (0.15 to 0.33 units a second, period 3.4 s); a larger
  // share would make the plankton surge with it.
  let cur = 0.05 * drift + vec3f(-0.0085, -0.0205, -0.001) * t;
  let own = (lHash3(i, 70u) - 0.5) * vec3f(0.05, 0.024, 0.05) * t + vec3f(0.0, (r1 - 0.62) * 0.03 * t, 0.0);
  let wander = 0.16 * vec3f(sin((0.05 + 0.04 * r2) * t + r1 * 6.3), sin((0.04 + 0.03 * r3) * t + r2 * 6.3), sin((0.045 + 0.04 * r1) * t + r3 * 6.3));
  let f = fract((lHash3(i, 60u) * bs * 11.3 + cur + own + wander - centre) / bs) - 0.5;
  var pw = centre + f * bs;
  // A slow eddy field fixed in the water: neighbours move together (no point swerves on its own).
  let qw = pw - cur;
  pw = pw + 0.3 * vec3f(sin(0.45 * qw.y + 0.021 * t), sin(0.4 * qw.z + 0.017 * t + 1.7), sin(0.42 * qw.x + 0.019 * t + 3.1));
  // The hero's passage: the water it has just moved through is carried along a little (its mean velocity
  // over the last 0.7 s and the 0.7 s before, so the answer lags and decays as it leaves), and the points
  // right at the bell are parted round it.
  let hv = (hero - h1) * (0.6 / 0.7) + (h1 - h2) * (0.4 / 0.7);
  let dS = pw - h1;
  let rS = 1.5 * hsP;
  let gS = 1.0 / (1.0 + dot(dS, dS) / (rS * rS));
  let dH = pw - hero;
  let rH = 1.1 * hsP;
  let gH = 1.0 / (1.0 + dot(dH, dH) / (rH * rH));
  pos = pw + hv * 4.5 * gS * gS + dH * (0.35 * gH * gH);
  // One soft ellipsoid of light inside the box (dark well before any face), denser toward the hero.
  let q = 2.0 * f;
  let field = 1.0 - smoothstep(0.45, 0.96, length(q));
  // Clumps that travel with the water.
  let clump = 0.3 + 1.4 * smoothstep(0.3, 0.72, vnoise3(qw * 0.5 + vec3f(3.7, 9.1, 5.3)));
  // The clear zone: nothing bright between the lens and the creature. Points in front of the hero dim
  // (soft, by depth), and inside the cone from the lens to the hero in front of it they go dark. The cone is
  // narrower than it was (1.5 hero sizes, was 2.2) and its edge twice as soft, so it reads as thinning
  // water, not as a hole.
  let vP = pos - eye;
  let dP = dot(vP, fwd);
  let inFront = smoothstep(focus + 0.1 * hsP, focus - 1.5 * hsP, dP);
  let dirH = normalize(hero - eye);
  let lat = length(vP - dirH * dot(vP, dirH));
  let rc = 1.5 * hsP * max(dP, 0.3) / focus;
  let cone = 1.0 - smoothstep(0.55 * rc, 1.9 * rc, lat);
  let clear = (1.0 - 0.8 * inFront) * (1.0 - inFront * cone) * (1.0 - 0.45 * cone);
  let rr = length(pos - hero) / max(P.heroScale, 0.5);
  // KICK: the front's stage from the distance (ragged by a per-point offset). A point flashes near its
  // own stage's peak (cubed: the band where the wave is now, travelling out as the stages peak one
  // after another) and keeps a faint afterglow (the stage itself, falling slowly).
  // Every point answers a little and a few strongly (it was 40 % of them and the rest dark: holes).
  let x = rr / 3.2 * 5.0 + (r1 - 0.5) * 0.7;
  let sx = stageAt(x, k0, k1, k2, k3, k4, k5);
  let front = 2.2 * sx * sx * sx + 0.08 * sx;
  let resp = 0.05 + 0.22 * r0 * r0 + 1.2 * r2 * r2 * r2 * r2;
  // HATS: a rotating few per cent sparkle.
  let spk = P.hat * rotGate(r3, r1, t, 0.03) * 5.0;
  // AT REST: each point breathes on its own slow cycle (35 to 90 s); about one in twenty is lit at a time,
  // for a few seconds, softly. Never on the bell itself (the cone, at any depth).
  let cyc = 0.5 + 0.5 * sin(t * (0.07 + 0.11 * r3) + r1 * 6.2831853 + r0 * 17.0);
  let rest = 14.0 * smoothstep(0.982, 1.0, cyc) * (0.3 + 0.7 * r2 * r2) * (1.0 - 0.75 * cone);
  b = ((22.0 * front * resp * (1.0 - smoothstep(4.2, 5.2, x)) + rest) * clump + spk) * clear * field * P.plankton;
  col = mix(BIO, moodColor(P.mood, 0.85), 0.3 + 0.25 * r3);
  sizePx = 2.4 + 2.0 * r2 * r2;
  cocCap = 6.0;
 }

 // The sAll lens (as kernel_worldmotes and the DOF passes): circle = aperture * |1 - focus / depth|.
 let depth = max(dot(pos - eye, fwd), 0.3);
 if (sizeW > 0.0) { sizePx = sizeW / (pxPerDepth * depth); }
 let cl = P.aperture * (1.0 - focus / (depth - clamp(depth - focus, -P.band, P.band)));
 let coc = select(min(cl, cocCap), min(-cl, cocCap), cl < 0.0);
 let px = sizePx + coc;
 // Never smaller than the pixel grid can draw round: the light of a finer point is spread over MINPX.
 let dpx = max(px, MINPX);
 b = b * pow((sizePx * sizePx) / (px * px), 0.8) * pow(px / dpx, 1.6) * litK;
 // Nothing behind the camera and nothing right at the lens.
 b = b * smoothstep(0.35, 0.6, depth);
 o.position = pos;
 // (a dark point draws nothing: the plankton cost no fill between beats)
 o.size = select(0.0, 0.5 * dpx * pxPerDepth * depth, b > 1e-6);
 o.tint = vec4f(col * b, 1.0);
 return o;
}

parameters.defaults:
heroX3 = 1;
heroY3 = 1.2;
heroZ3 = 0;
heroVX = 0;
heroVY = 0;
heroVZ = 0

parameters.expressions:
hx3 = heroX3;
hy3 = heroY3;
hz3 = heroZ3;
hvx = heroVX;
hvy = heroVY;
hvz = heroVZ

parameters.kernel:
struct Params {
 heroX: f32, // @default 1.1 Bell centre now (rig heroX).
 heroY: f32, // @default 1.45 Bell centre now (rig heroY).
 heroZ: f32, // @default 0 Bell centre now (rig heroZ).
 heroX1: f32, // @default 1.1 Where the bell was 0.7 s ago (rig heroX1).
 heroY1: f32, // @default 1.45 (rig heroY1).
 heroZ1: f32, // @default 0 (rig heroZ1).
 heroX2: f32, // @default 1.1 Where the bell was 1.4 s ago (rig heroX2).
 heroY2: f32, // @default 1.45 (rig heroY2).
 heroZ2: f32, // @default 0 (rig heroZ2).
 heroX3: f32, // @default 1.1 Where the bell was 2.1 s ago (rig heroX3).
 heroY3: f32, // @default 1.45 (rig heroY3).
 heroZ3: f32, // @default 0 (rig heroZ3).
 tiltX: f32, // @default 0 Bell lean about X, radians (rig heroTiltX); shapes only the roots.
 tiltZ: f32, // @default -0.22 Bell lean about Z, radians (rig heroTiltZ); shapes only the roots.
 scale: f32, // @default 1 Size multiplier (rig heroScale).
 pulse: f32, // @default 0 Bell contraction 0..1 (rig pulse).
 pulsePhase: f32, // @default 0 Swim-cycle phase 0..1 (rig pulsePhase); only periodic functions of it are used.
 swimRate: f32, // @default 0.567 Swim cycles per second (rig swimRate): one period sets the mean-velocity window.
 tension: f32, // @default 0.3 Stretch and twist (rig tension).
 density: f32, // @default 0.5 How much is present: arm and tentacle count, length, veil width (rig density).
 lum: f32, // @default 0.5 Illumination (rig lum).
 mood: f32, // @default 0 Palette position (rig mood).
 kick0: f32, // @default 0 Strike force at the bell (lag_herokick2.imp).
 kick1: f32, // @default 0 The same a little later and wider (lag_herokick4.imp).
 kick2: f32, // @default 0 Later still (lag_herokick5.imp): reaches the tips.
 kickS: f32, // @default 0 Slow mean of the strikes (lag_herokick7.imp): what is sustained, not new.
 rigLean: f32, // @default 0 1 = the rig's heroTiltX/Z is already the smooth travel lean: hang everything along it.
 env4: f32, // @default 0 Melody envelope (lag_env.env4): beads and rhopalia twinkle with it.
 energyS: f32, // @default 0.5 Slow musical energy (rig energy through two 1.2 s lags) plus a share of the bass envelope (lag_heronote2.bs): how deep the strokes, how open, how far they trail, how alive.
 hitAge: f32, // @default 9 Seconds since the last chord strike (rig age): a soft swell of light runs down from the root.
 nt0: f32, // @default 0 Note place 0 (pitch class 0, circle-of-fifths order) now (lag_heronote2.s0).
 nt1: f32, // @default 0 Note place 1 (pitch class 7, circle-of-fifths order) now (lag_heronote2.s1).
 nt2: f32, // @default 0 Note place 2 (pitch class 2, circle-of-fifths order) now (lag_heronote2.s2).
 nt3: f32, // @default 0 Note place 3 (pitch class 9, circle-of-fifths order) now (lag_heronote2.s3).
 nt4: f32, // @default 0 Note place 4 (pitch class 4, circle-of-fifths order) now (lag_heronote2.s4).
 nt5: f32, // @default 0 Note place 5 (pitch class 11, circle-of-fifths order) now (lag_heronote2.s5).
 nt6: f32, // @default 0 Note place 6 (pitch class 6, circle-of-fifths order) now (lag_heronote2.s6).
 nt7: f32, // @default 0 Note place 7 (pitch class 1, circle-of-fifths order) now (lag_heronote2.s7).
 nt8: f32, // @default 0 Note place 8 (pitch class 8, circle-of-fifths order) now (lag_heronote2.s8).
 nt9: f32, // @default 0 Note place 9 (pitch class 3, circle-of-fifths order) now (lag_heronote2.s9).
 nt10: f32, // @default 0 Note place 10 (pitch class 10, circle-of-fifths order) now (lag_heronote2.s10).
 nt11: f32, // @default 0 Note place 11 (pitch class 5, circle-of-fifths order) now (lag_heronote2.s11).
 nu0: f32, // @default 0 Note place 0 later, for the tips (lag_heronote3.s0).
 nu1: f32, // @default 0 Note place 1 later, for the tips (lag_heronote3.s1).
 nu2: f32, // @default 0 Note place 2 later, for the tips (lag_heronote3.s2).
 nu3: f32, // @default 0 Note place 3 later, for the tips (lag_heronote3.s3).
 nu4: f32, // @default 0 Note place 4 later, for the tips (lag_heronote3.s4).
 nu5: f32, // @default 0 Note place 5 later, for the tips (lag_heronote3.s5).
 nu6: f32, // @default 0 Note place 6 later, for the tips (lag_heronote3.s6).
 nu7: f32, // @default 0 Note place 7 later, for the tips (lag_heronote3.s7).
 nu8: f32, // @default 0 Note place 8 later, for the tips (lag_heronote3.s8).
 nu9: f32, // @default 0 Note place 9 later, for the tips (lag_heronote3.s9).
 nu10: f32, // @default 0 Note place 10 later, for the tips (lag_heronote3.s10).
 nu11: f32, // @default 0 Note place 11 later, for the tips (lag_heronote3.s11).
 leadC: f32, // @default 0 The melody note's place, cosine (lag_herochord2.lC): its filaments carry the melody's gesture.
 leadS: f32, // @default 0 The same, sine (lag_herochord2.lS).
 melF: f32, // @default 60 Top voice pitch, quick (lag_heromel2.mp).
 melS: f32, // @default 60 Top voice pitch, slow (lag_heromel3.mp): melF - melS is the melodic motion.
 teS: f32, // @default 0.3 Tension, slow mean (lag_herotens.tension): above it = rising, below it = a release.
 rC3: f32, // @default 1 Chord root on the circle of fifths, cosine, at the margin's stage (lag_herochord3.rC).
 rS3: f32, // @default 0 The same, sine (lag_herochord3.rS).
 rC4: f32, // @default 1 The same, later, for the tips (lag_herochord4.rC).
 rS4: f32, // @default 0 (lag_herochord4.rS).
 noteGain: f32, // @default 1 How strongly notes light and move their places (0 = off).
 melodyGain: f32, // @default 1 How strongly the melody's rise and fall bend the arms and lead filaments.
 tensionGain: f32, // @default 1 How strongly tension stretches and a release spreads.
 chordGain: f32, // @default 1 How far the chord root leans the colour.
 react: f32, // @default 1 The owner's music reaction strength (rig reactGain, 0..2, eased): multiplies every gain above.
};
// Tentacles: NT filaments x 64 segments, one beam per segment (position -> endpoint).
const NS = 64u;
fn process(p: Point, ctx: PointCtx) -> Point {
 var q = p;
 let P = ctx.params;
 let ti = ctx.index / NS;
 let si = ctx.index % NS;
 let f = hfMake(P.heroX, P.heroY, P.heroZ, P.tiltX, P.tiltZ, P.scale);
 let c = tcMake(f, vec3f(P.heroX1, P.heroY1, P.heroZ1), vec3f(P.heroX2, P.heroY2, P.heroZ2), vec3f(P.heroX3, P.heroY3, P.heroZ3), P.swimRate, P.tiltX, P.tiltZ, pulseEnv(P.pulsePhase), P.pulsePhase, P.tension, P.density, ctx.absTime, vec3f(P.kick0, P.kick1, P.kick2), P.energyS, P.kickS, P.rigLean);
 let s0 = f32(si) / f32(NS);
 let s1 = f32(si + 1u) / f32(NS);
 q.position = heroTentPoint(c, P, ti, s0);
 q.endpoint = heroTentPoint(c, P, ti, s1);
 let act = tentActive(ti, P.density);
 let sm = 0.5 * (s0 + s1);
 // each filament has its own strength and fades out at its own pace
 let strength = 0.3 + 0.7 * stableRand(ti, 19u);
 let fadeAt = 0.55 + 0.45 * stableRand(ti, 23u);
 let along = pow(max(1.0 - sm / fadeAt, 0.0), 0.8) * smoothstep(0.0, 0.03, sm + 0.01) * strength;
 // the swim pressure and each chord strike travel down as a soft swell of light
 let swell = 0.35 * pres(P.pulsePhase - 0.1 - 0.6 * sm) + 1.2 * softPos(rippleAt(c.kick, sm));
 // the note of this filament's place lights it, travelling down (pass 6)
 let nl = 1.4 * noteAt(P, tentPhi(ti), sm);
 // warm hairlines: the accent, a quarter of the mood, gently varied along the length
 let col0 = mix(ACC, moodColor(P.mood + leanAt(P, sm), 0.85), 0.25 + 0.15 * sin(sm * 9.0 + f32(ti)));
 // a chord change runs down them in its own colour
 let cw = waveAt(P, sm);
 let col = mix(col0, waveColAt(P, sm), min(0.6 * cw, 0.75));
 // continuous even when calm (calm at least 0.6 of medium), so they never break into dots
 let lumK = 0.55 + 0.45 * P.lum;
 q.tint = vec4f(col * along * lumK * act * (0.8 + swell + nl + 0.6 * cw) * 0.45, 1.0);
 // never thinner than about 1.5 px at the normal camera distance: sub-pixel beams alias and crawl
 q.width = mix(1.0, 0.7, sm);
 return q;
}
// ---- hero common (kernels): frame, pulse envelope, bell profile, trail ----
const TAU = 6.2831853;
// The bell in its own frame: rim radius 1, up +y, rim (margin) plane at BELL_Y0, apex BELL_H above it.
// World = hero position + rotZ(tiltZ) * rotX(tiltX) * (local * heroScale).
// A flattened dome (the boards: height/width about 0.38 for the dome, 0.45 with the lappets): the profile
// stops at 79 degrees, so the shoulders slope into the rim and never stand as a vertical wall; 16
// rounded lappets hang LAP_LEN below the rim.
const BELL_H = 0.64;
const BELL_Y0 = -0.35;
const BELL_THMAX = 1.38;
const BELL_VM = 0.9;       // exumbrella: v of the rim (ring canal); the lappets hang over VM..1
const LAP_LEN = 0.14;

struct HF { o: vec3f, ca: f32, sa: f32, cb: f32, sb: f32, k: f32, };
fn hfMake(x: f32, y: f32, z: f32, tx: f32, tz: f32, k: f32) -> HF {
 return HF(vec3f(x, y, z), cos(tx), sin(tx), cos(tz), sin(tz), k);
}
fn hfDir(f: HF, d: vec3f) -> vec3f {
 let y1 = d.y * f.ca - d.z * f.sa;
 let z1 = d.y * f.sa + d.z * f.ca;
 return vec3f(d.x * f.cb - y1 * f.sb, d.x * f.sb + y1 * f.cb, z1);
}
fn hfPos(f: HF, p: vec3f) -> vec3f { return f.o + hfDir(f, p * f.k); }

// The stroke, as a periodic function of the swim phase (the cycle is about 3.5 s): a slow full
// contraction over 30 % of it, a release over 40 %, then a 30 % glide at rest. Every geometric use of
// the swim reads this (the bell body too), so the bell and everything lagging it agree.
// the warm accent: one peach-gold for cores, canals, glints and beads in every mood
const ACC = vec3f(1.0, 0.66, 0.36);
fn smoother(a: f32, b: f32, x: f32) -> f32 {
 let t = clamp((x - a) / (b - a), 0.0, 1.0);
 return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}
fn pulseEnv(ph: f32) -> f32 {
 let x = fract(ph);
 return smoother(0.0, 0.3, x) * (1.0 - smoother(0.3, 0.7, x));
}
// A chord strike as a FORCE: the rig's strike age drives a short impulse through a chain of hero
// lag nodes; k.x (lag_herokick2) is the response at the bell, k.y (4) later and wider, k.z (5) later
// still, kS (7) a very slow mean of the same impulse. The RIPPLE is what is new: each response minus
// the slow mean, normalised so one isolated strike peaks near 1, softly limited, so a train of strikes
// does not hold the appendages splayed: each new strike still adds a travelling ripple, and the
// sustained part becomes a small, saturating STEADY opening.
fn kickRipple(k: vec3f, kS: f32) -> vec3f {
 let g = vec3f(2.0, 4.0, 5.5);
 let x = (k - vec3f(kS)) * g;
 return x / sqrt(vec3f(1.0) + x * x);
}
fn kickSteady(kS: f32) -> f32 { return 0.35 * (1.0 - exp(-2.5 * kS)); }
// positive part, smoothly (light and flares only grow)
fn softPos(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.0004)); }
// the margin flares a little with the strike (bell and tentacle roots must agree)
fn marginFlare(lp: vec3f, v: f32, k0: f32) -> vec3f {
 let g = 1.0 + 0.035 * k0 * smoothstep(0.75, 1.0, v);
 return vec3f(lp.x * g, lp.y, lp.z * g);
}

// Soft swim pressure: a raised cosine at the swim frequency, peaking with the contraction (phase 0.28).
// Lagged copies of it run down arms and tentacles as a gentle pressure wave, never a wiggle.
fn gaussK(x: f32) -> f32 { return exp(-x * x); }
// the strike ripple as felt at s along anything (0 the bell, 1 the tips), continuous in time and space
fn rippleAt(r: vec3f, s: f32) -> f32 {
 return mix(mix(r.x, r.y, smoother(0.0, 0.5, s)), r.z, smoother(0.5, 1.0, s));
}
fn pres(ph: f32) -> f32 { return 0.5 + 0.5 * cos(TAU * (ph - 0.28)); }
// Contraction felt at bell parameter v (0 apex, 1 lappet tips): the body follows pulse, the margin
// lags 0.06 of a cycle, the lappets 0.1, so the rim trails the squeeze and re-opens late.
// D is the stroke depth (fuller with louder music, set slowly).
fn bellPulseAt(v: f32, pl: f32, ph: f32, D: f32) -> f32 {
 let pm = pulseEnv(ph - 0.06) * D;
 let plap = pulseEnv(ph - 0.1) * D;
 return mix(pl, mix(pm, plap, smoothstep(0.86, 1.0, v)), smoothstep(0.55, 1.0, v));
}
fn strokeDepth(es: f32) -> f32 { return 0.75 + 0.4 * es; }
// The stroke's amplitude, softly limited to 1 (pass 6). A hard min(.., 1) on depth x strike clipped the
// top of the contraction inside a stroke whenever the music was full: a kink in its speed, seen as a
// light step at the stroke's peak (Clair 70.6 s, 88.1 s). Bell, filament roots and rhopalia all use it.
fn strokeAmp(a: f32) -> f32 { return a / pow(1.0 + pow(max(a, 0.0), 8.0), 0.125); }

fn bellSqueeze(v: f32, pm: f32) -> f32 {
 return 1.0 - 0.2 * pm * pow(smoothstep(0.12, 1.0, v), 1.3);
}
// Exumbrella point. p: body contraction, pm: (lagged) margin contraction, te: tension.
// the dome's height profile, 1 at the apex and 0 at the rim (slightly flattened top)
fn domeY(th: f32) -> f32 {
 let cm = pow(cos(BELL_THMAX), 0.88);
 return (pow(max(cos(th), 0.0), 0.88) - cm) / (1.0 - cm);
}
fn bellExo(phi: f32, v: f32, p: f32, pm: f32, te: f32) -> vec3f {
 let vd = min(v / BELL_VM, 1.0);
 let th = vd * BELL_THMAX;
 // a contraction closes the rim and lengthens the dome a little: it stays a dome (h/w under 0.6)
 let h = BELL_H * (1.0 + 0.12 * p + 0.06 * te);
 let rib = 1.0 + 0.022 * (0.5 + 0.5 * cos(16.0 * phi)) * smoothstep(0.08, 0.5, vd) * (1.0 - smoothstep(0.8, 0.95, vd));
 let wave = (0.025 * sin(8.0 * phi + 0.7) + 0.01 * sin(13.0 * phi + 2.0)) * smoothstep(0.6, 1.0, vd);
 var r = sin(th) / sin(BELL_THMAX) * bellSqueeze(vd, pm) * rib;
 var y = BELL_Y0 - 0.04 * pm * smoothstep(0.5, 1.0, vd) + h * domeY(th);
 if (v > BELL_VM) {
  // the lappets hang from the rim: flared a little outward at rest, curled in by the squeeze
  let s = (v - BELL_VM) / (1.0 - BELL_VM);
  r = r + s * LAP_LEN * (0.45 - 0.9 * pm) * bellSqueeze(1.0, pm);
  y = y - s * LAP_LEN * (0.9 + 0.2 * pm);
 }
 return vec3f(cos(phi) * r, y + wave, sin(phi) * r);
}

// Frame-independent per-id random in [0, 1). The built-in pointRand re-rolls EVERY FRAME (it hashes the
// frame index), so it must never shape geometry: that reads as high-frequency jitter in playback.
fn stableRand(id: u32, salt: u32) -> f32 {
 var x = id * 747796405u + salt * 2891336453u + 12345u;
 x = (x ^ (x >> 15u)) * 2246822519u;
 x = (x ^ (x >> 13u)) * 3266489917u;
 x = x ^ (x >> 16u);
 return f32(x >> 8u) * (1.0 / 16777216.0);
}
// ---- hero appendages in water (shared by tentacle beams, beads and oral arms) ----
// They HANG: almost passive, a slow curtain dragged behind the swim and swaying over many seconds.
// Point s = the root on the bell (rigidly attached, in the bell's own frame) + a hanging shape
// (gravity and a slow down-left current, leaning with the path) + a slow DRAG opposite the bell's
// mean velocity, growing toward the tip. The mean velocity is taken over one swim period (the bell
// now vs where it was one period, about 1.76 s, ago), so the surge of each thrust cancels out and
// is never replayed down the appendages; it is used as a vector that shrinks to nothing as the bell
// slows (never normalised), so the trail eases back to the rest hang. Each contraction sends one
// soft, slow bulge down them; chord strikes change only their light. Nothing may rise above its
// own root along the bell's axis (keepBelow).
const NT = 48u;            // tentacles
const DRAG_T = 4.0;        // tentacles: seconds of mean drift by which a tip trails
const ARM_DRAG_T = 5.5;    // oral arms: broad veils catch more water
struct TC { f: HF, fP: HF, h0: vec3f, vbar: vec3f, droop: vec3f, side: vec3f, side2: vec3f, pl: f32, ph: f32, te: f32, de: f32, t: f32, kick: vec3f, es: f32, steady: f32, act: f32, };

// the bell's path u steps of 0.7 s ago (u in 1..3), straight between the rig's samples (no overshoot)
fn pathBack(h1: vec3f, h2: vec3f, h3: vec3f, u: f32) -> vec3f {
 if (u < 2.0) { return mix(h1, h2, clamp(u - 1.0, 0.0, 1.0)); }
 return mix(h2, h3, clamp(u - 2.0, 0.0, 1.0));
}

fn tcMake(f: HF, h1: vec3f, h2: vec3f, h3: vec3f, rate: f32, tx: f32, tz: f32, pl: f32, ph: f32, te: f32, de: f32, t: f32, kick: vec3f, es: f32, kS: f32, rl: f32) -> TC {
 // mean velocity: the least-squares slope through the four samples (now, 0.7, 1.4, 2.1 s ago), far
 // less sensitive to the surge inside a stroke than a two-point difference
 let vbar = (1.5 * f.o + 0.5 * h1 - 0.5 * h2 - 1.5 * h3) / (5.0 * 0.7);
 // the bell's own axis with the per-stroke rocking taken out: the rig leans the bell by its 0.7 s
 // velocity; swap that for the period-mean velocity (same lean law), keep everything else it does
 // (with rigLean = 1 the rig's tilt already is that smooth lean, and everything hangs along it as is)
 let v07 = (f.o - h1) / 0.7;
 let swap = select(1.0, 0.0, rl > 0.5);
 let fP = hfMake(f.o.x, f.o.y, f.o.z, tx - 0.5 * (v07.z - vbar.z) * swap, tz + 1.6 * (v07.x - vbar.x) * swap, f.k);
 // appendages hang along that axis (no sideways current of their own)
 let droop = hfDir(fP, vec3f(0.0, -1.0, 0.0));
 let side = normalize(cross(droop, vec3f(0.0, 0.0, 1.0)));
 let side2 = normalize(cross(droop, side));
 // activity: slow musical energy plus how busy the strikes have been (both eased), 0 calm .. 1 full
 let steady = kickSteady(kS);
 let act = clamp(0.75 * es + 1.2 * steady, 0.0, 1.0);
 return TC(f, fP, f.o, vbar, droop, side, side2, pl, ph, te, de, t, kickRipple(kick, kS), es, steady, act);
}
// trail opposite the mean velocity, growing toward the tip, softly limited (no normalising)
fn dragAt(c: TC, s: f32, len: f32, secs: f32) -> vec3f {
 let d = -c.vbar * secs * pow(s, 1.5);
 let limit = 0.35 * len;
 return d / sqrt(1.0 + dot(d, d) / (limit * limit));
}
// never above the root along the bell's axis: a point at s hangs at least 10 % of its arclength below
fn keepBelow(c: TC, root: vec3f, p: vec3f, s: f32, len: f32) -> vec3f {
 let up = hfDir(c.f, vec3f(0.0, 1.0, 0.0));
 let along = dot(p - root, up);
 let floorA = -0.1 * s * len;
 let w = 0.08 * len * s + 1e-4;
 let hh = clamp(0.5 + 0.5 * (floorA - along) / w, 0.0, 1.0);
 let sm = mix(floorA, along, hh) - w * hh * (1.0 - hh);
 return p + up * (sm - along);
}
fn tentPhi(ti: u32) -> f32 {
 return (f32(ti) + 0.5 + 0.55 * (stableRand(ti, 11u) - 0.5)) / f32(NT) * TAU;
}
// active share of the tentacles: about 24 at density 0, all 48 at density 1 (unused ones fade)
fn tentActive(ti: u32, de: f32) -> f32 {
 let rank = stableRand(ti, 17u);
 return 1.0 - smoothstep(0.5 + 0.5 * de - 0.06, 0.5 + 0.5 * de + 0.02, rank);
}
fn tentLength(c: TC, ti: u32) -> f32 {
 return (1.2 + 3.0 * pow(stableRand(ti, 13u), 1.4)) * (0.85 + 0.3 * c.de) * (1.0 + 0.12 * c.te) * c.f.k;
}
// the bell's contraction as felt at s along an appendage: exact at the root, then the same envelope at
// a later phase, damped (a soft pressure wave). Returns (body pulse, margin pulse, phase used).
fn pulseAlong(c: TC, s: f32) -> vec3f {
 let lagc = 0.6 * s;
 let att = exp(-1.8 * s);
 let D = strokeDepth(c.es);
 let k0 = (c.kick.x + c.steady) * att;
 let ps = pulseEnv(c.ph - lagc) * strokeAmp(D * (1.0 + 0.2 * k0)) * att;
 let pm = bellPulseAt(0.9, ps, c.ph - lagc, D) * att;
 return vec3f(ps, pm, c.ph - lagc);
}
// the slow sweep of the whole hanging bundle (shared by tentacles and arms), travelling tipward
fn sweepAt(c: TC, s: f32) -> vec3f {
 let a = TAU * (0.05 * c.t - 0.35 * s);
 return (c.side * sin(a) + c.side2 * 0.5 * sin(a * 0.7 + 1.9)) * (0.12 + 0.14 * c.act) * s * s;
}
// the strike as felt at s: the bell's response at the root, later and wider responses toward the tip
fn kickAt(c: TC, s: f32) -> f32 { return rippleAt(c.kick, s) + c.steady; }
fn tentRoot(c: TC, phi: f32, s: f32) -> vec3f {
 let pa = pulseAlong(c, s);
 let k0 = (c.kick.x + c.steady) * exp(-1.8 * s);
 return hfPos(c.f, marginFlare(bellExo(phi, 0.9, pa.x, pa.y, c.te), 0.9, k0) * vec3f(0.965, 1.0, 0.965));
}
fn tentPoint(c: TC, ti: u32, s: f32) -> vec3f {
 let phi = tentPhi(ti);
 let h1 = stableRand(ti, 12u);
 let h2 = stableRand(ti, 14u);
 // root on the margin, squeezing with it (the squeeze reaches further points later and weaker)
 let anchor = tentRoot(c, phi, s);
 let outL = vec3f(cos(phi), 0.0, sin(phi));
 // one soft slow bulge per contraction, travelling down
 let pp = pres(c.ph - 0.1 - 0.6 * s);
 // loud passages open the whole curtain, quiet ones draw it in (slow)
 let spread = (0.16 + 0.2 * h1) * (0.7 + 0.7 * c.act) - 0.04 * pp;
 let d0 = hfDir(c.fP, normalize(vec3f(outL.x * spread, -1.0, outL.z * spread)));
 let len = tentLength(c, ti);
 let bendL = vec3f(cos(phi + 1.6 * (h2 - 0.5)), 0.0, sin(phi + 1.6 * (h2 - 0.5)));
 let b1 = d0 * 0.22 * len + hfDir(c.fP, bendL) * (0.04 + 0.08 * h2) * len;
 let b2 = b1 + normalize(c.droop + hfDir(c.fP, outL) * (0.05 + 0.12 * h1)) * 0.78 * len;
 var pos = anchor + 2.0 * s * (1.0 - s) * b1 + s * s * b2;
 // slow drag behind the mean swim
 pos += dragAt(c, s, len, DRAG_T * (0.8 + 0.4 * h2) * (0.8 + 0.4 * c.es));
 // always alive: a long slow undulation (about one wave every 9 s), larger when the music is fuller,
 // under a slower sweep the whole curtain shares (one every 20 s), travelling down it
 // the music shapes it through amplitude and (a little) wavelength, never its rate: calm = long lazy
 // waves, busy = fuller and livelier
 let w = TAU * ((0.55 + 0.35 * c.act) * s - 0.11 * c.t) + phi * 3.0 + h1 * 6.0;
 let amp = (0.06 + 0.1 * c.act) * len * pow(s, 1.5);
 pos += (c.side * sin(w) + c.side2 * 0.6 * cos(0.8 * w + 1.3)) * amp;
 pos += sweepAt(c, s) * len;
 // the bulge: the bundle breathes out a hair as it passes
 pos += hfDir(c.fP, outL) * 0.012 * len * sin(3.14159 * s) * pp;
 // a strike: the filaments flare outward and stretch back along the trail, as a slow wave tipward
 pos += (hfDir(c.fP, outL) * 0.7 + c.droop * 0.5) * 0.11 * len * sin(3.14159 * min(s * 1.1, 1.0) * 0.5) * kickAt(c, s);
 return keepBelow(c, tentRoot(c, phi, 0.0), pos, s, len);
}
// ---- hero only: the music as characters (pass 6). Not part of the shared family. ----
// Twelve places round the bell, one per pitch class in circle-of-fifths order: sector k holds pitch class
// 7k mod 12, so a fifth is a neighbour and a triad is always the same small shape (root, its neighbour,
// and the third four places round). A note lights and moves its own place; a chord shows as the set of
// places its tones hold. The values per sector come from expression_herochord through lags (two 0.3 s
// stages with a four times slower release: S-shaped onset, seconds of decay; one more 0.8 s stage for
// the tips), so nothing here can step.
fn noteSecW(x: f32, k: f32) -> f32 {
 let d = abs(fract((x - k) / 12.0 + 0.5) - 0.5) * 12.0;   // distance in sectors, wrapped
 return 1.0 - smoother(0.3, 0.7, d);                       // a plateau per sector, soft 0.4-sector seams
}
fn secW4(x: f32, k0: f32) -> vec4f {
 return vec4f(noteSecW(x, k0), noteSecW(x, k0 + 1.0), noteSecW(x, k0 + 2.0), noteSecW(x, k0 + 3.0));
}
// the twelve sector values (a = sectors 0..3, b = 4..7, c = 8..11) as felt at bell azimuth phi
fn secSum(a: vec4f, b: vec4f, c: vec4f, phi: f32) -> f32 {
 let x = fract(phi / TAU) * 12.0;
 return dot(a, secW4(x, 0.0)) + dot(b, secW4(x, 4.0)) + dot(c, secW4(x, 8.0));
}
// where in its sector an azimuth lies, -0.5 .. 0.5 (a sector's filaments fan apart from its centre)
fn secOffset(phi: f32) -> f32 { return fract(fract(phi / TAU) * 12.0 + 0.5) - 0.5; }
// soft limit: many notes on one place never add up to more than about one
fn noteSoft(x: f32) -> f32 { return x / sqrt(1.0 + x * x); }
// melodic motion: the top voice's pitch through a quick and a slow lag; their difference (semitones)
// is a damped force, up > 0. Returns (rising, falling), each 0..1, softly limited.
fn melodyUD(melF: f32, melS: f32, g: f32) -> vec2f {
 let m = g * (melF - melS) / 4.0;
 return vec2f(noteSoft(softPos(m)), noteSoft(softPos(-m)));
}
// tension against its own slow mean: (rising, releasing), each 0..1. A release is the exhale.
fn tensionRR(teF: f32, teS: f32, g: f32) -> vec2f {
 let d = g * 5.0 * (teF - teS);
 return vec2f(noteSoft(softPos(d)), noteSoft(softPos(-d)));
}
// the chord root on the circle of fifths leans the palette (a hue change of the whole animal); the lean
// reaches the heart first and the margin, then the tips, later (lag_herochord2, 3, 4)
fn chordLean(r: vec2f, g: f32) -> f32 { return g * (0.25 * r.x + 0.15 * r.y); }
// A chord change as a wave with duration: differences of successive stages of the strike response
// (lag_herokick2 - 4, 4 - 5, 5 - 7; every stage is at least second order, so every difference starts
// with zero slope), normalised so one strike peaks near 1 at the heart (about 0.6 s after it), half way
// out (1.3 s) and at the margin and down the appendages (2.4 s). A train of strikes overlaps into a
// gentle shimmer, never a sum. (A first-order stage here, lag_herokick6, dropped the margin's light the
// instant a strike began and then stopped dead at zero: a light step 0.1 s after every strike.)
fn softKnee(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.01)); }
fn chordWave(k0: f32, k1: f32, k2: f32, kS: f32, g: f32) -> vec3f {
 let w = vec3f(3.0 * (k0 - k1), 10.0 * (k1 - k2), 15.0 * (k2 - kS));
 return g * vec3f(noteSoft(softKnee(w.x)), noteSoft(softKnee(w.y)), noteSoft(softKnee(w.z)));
}
// ---- hero appendages only (pass 6): notes, melody and tension as forces on the hanging curtain ----
// The twelve note places at the root stage (lag_heronote2) and the later tip stage (lag_heronote3).
fn ntNow(P: Params, phi: f32) -> f32 {
 return secSum(vec4f(P.nt0, P.nt1, P.nt2, P.nt3), vec4f(P.nt4, P.nt5, P.nt6, P.nt7), vec4f(P.nt8, P.nt9, P.nt10, P.nt11), phi);
}
fn ntLate(P: Params, phi: f32) -> f32 {
 return secSum(vec4f(P.nu0, P.nu1, P.nu2, P.nu3), vec4f(P.nu4, P.nu5, P.nu6, P.nu7), vec4f(P.nu8, P.nu9, P.nu10, P.nu11), phi);
}
// the note force at s along an appendage hanging at azimuth phi: the root feels the first stage, the
// tip the later one, so a strike travels down (0..about 1)
fn noteAt(P: Params, phi: f32, s: f32) -> f32 {
 return (P.noteGain * P.react) * noteSoft(mix(ntNow(P, phi), ntLate(P, phi), smoother(0.1, 0.9, s)));
}
// the palette lean of the chord root along an appendage: the margin's stage at the root, later at the tip
fn leanAt(P: Params, s: f32) -> f32 {
 return chordLean(mix(vec2f(P.rC3, P.rS3), vec2f(P.rC4, P.rS4), smoother(0.0, 1.0, s)), (P.chordGain * P.react));
}
// the chord's own colour: the root's place on the circle of fifths picks among four hues of the next
// two palettes, all cool against the warm body and lines (deep-blue mood: aqua, cyan, teal, blue), so
// neighbouring chords differ and the
// same root always returns in the same colour (as on the bell)
fn hl(c: vec3f) -> vec3f { return c / max(max(c.r, c.g), max(c.b, 0.05)); }
fn chordHue(md: f32, r: vec2f) -> vec3f {
 let w = max(vec4f(r.x, r.y, -r.x, -r.y), vec4f(0.0));
 let a = hl(moodColor(md + 1.0, 0.5));
 let b = hl(moodColor(md + 2.0, 0.95));
 let c = hl(moodColor(md + 1.0, 0.25));
 let d = hl(moodColor(md + 2.0, 0.6));
 // while a far root change passes the lagged direction through the centre, ease to the mean hue (pass 7)
 let sw = w.x + w.y + w.z + w.w;
 return (w.x * a + w.y * b + w.z * c + w.w * d + max(0.6 - sw, 0.0) * 0.25 * (a + b + c + d)) / max(sw, 0.6);
}
fn waveColAt(P: Params, s: f32) -> vec3f {
 return chordHue(P.mood + leanAt(P, s), mix(vec2f(P.rC3, P.rS3), vec2f(P.rC4, P.rS4), smoother(0.0, 1.0, s)));
}
// the chord-change wave at s along an appendage: the half-way stage at the root, the margin's stage below
fn waveAt(P: Params, s: f32) -> f32 {
 let w = chordWave(P.kick0, P.kick1, P.kick2, P.kickS, (P.chordGain * P.react));
 return mix(w.y, w.z, smoother(0.0, 0.6, s));
}
// A tentacle point with the music's gestures (the tentacle beams and the beads on them share it). All
// offsets are outward, sideways or down and grow from nothing at the root; keepBelow holds again.
fn heroTentPoint(c: TC, P: Params, ti: u32, s: f32) -> vec3f {
 let phi = tentPhi(ti);
 let len = tentLength(c, ti);
 var pos = tentPoint(c, ti, s);
 let out = hfDir(c.fP, vec3f(cos(phi), 0.0, sin(phi)));
 let tang = hfDir(c.fP, vec3f(-sin(phi), 0.0, cos(phi)));
 // a note: the filaments of its place flare out and fan apart from the place's centre
 let x = noteAt(P, phi, s);
 pos += (out * 0.08 + tang * 0.1 * secOffset(phi) + c.droop * 0.02) * len * sin(1.5708 * s) * x;
 // the melody: the filaments at the melody note's place curl out as the line rises, in as it falls
 let ud = melodyUD(P.melF, P.melS, (P.melodyGain * P.react));
 let lead = smoothstep(0.6, 1.0, dot(vec2f(cos(phi), sin(phi)), vec2f(P.leadC, P.leadS)));
 pos += out * (0.22 * ud.x - 0.14 * ud.y) * len * s * s * lead;
 // tension draws the curtain long; a release lets it spread (the exhale)
 let rr = tensionRR(P.tension, P.teS, (P.tensionGain * P.react));
 pos += (c.droop * 0.1 * rr.x - out * 0.04 * rr.x + out * 0.13 * rr.y) * len * s;
 return keepBelow(c, tentRoot(c, phi, 0.0), pos, s, len);
}
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}

