// ---- companion common (kernels): frame, pulse, bell profile, one companion's state ----
// Derived from the hero's common.wgsl (same species, same bell profile), simplified.
// Nine companions j, each following a harmony voice (VOICE in tools/gen.py), each at its own depth from the
// camera (4.5 to 26, continuous), each with its own size and its own visit cycle: it swims in from beyond a frame
// edge (or rises from the deep), takes its station in the harmony formation, then swims off and is gone a while.
const TAU = 6.2831853;
const NCOMP = 9u;
const BELL_H = 0.64;       // companions: a flattened dome (height / width about 0.5), as on the boards
const BELL_Y0 = -0.35;
const BELL_THMAX = 1.55;   // the margin flares out rather than curling under
const BELL_VM = 0.9;       // exumbrella: lappet roots (ring canal); lappets run VM..1
const BELL_VS = 0.74;      // subumbrella margin; the frill skirt runs VS..1
const GLIDE_TAU = 1.3;     // lag_compease time constant, seconds
const DEEP_TAU = 3.2;      // lag_compdeep time constant, seconds
const VCAP = 0.25;         // top swimming speed, bell diameters per second (arrivals, departures, glides)
const VISIT_TAU = 12.0;    // lag_compvisit time constant (the deepest ones' stations), seconds
const VOICE = array<u32, 9>(0u, 2u, 4u, 0u, 1u, 2u, 3u, 1u, 3u);   // the harmony voice each companion follows
// per companion (stable): distance from the camera, size factor, visit period (s), phase, loyalty
const DEPTH = array<f32, 9>(26.0, 21.0, 17.5, 15.0, 13.0, 11.5, 8.5, 6.0, 4.5);   // (pass-4 slots, kept for reference)
// depth as a multiple of the (slowly eased) hero distance: never nearer than 1.3 x, so nothing comes near the lens
// and everything is behind the hero; the far tier 1.7 to 2.4 x, the formation tier 1.32 to 1.62 x
const DM = array<f32, 9>(2.4, 2.05, 1.75, 1.55, 1.42, 1.32, 1.48, 1.62, 1.9);
const SIZE = array<f32, 9>(1.55, 0.75, 1.15, 0.5, 1.1, 0.8, 0.45, 0.95, 1.0);
// the near tier (beside the hero, in focus): broader arms and a ribbon set
fn isNear(j: u32) -> bool { return j == 4u || j == 5u || j == 7u; }
const PER = array<f32, 9>(97.0, 61.0, 83.0, 47.0, 74.0, 109.0, 56.0, 88.0, 68.0);
const PHS = array<f32, 9>(0.51, 0.32, 0.04, 0.18, 0.16, 0.94, 0.68, 0.9, 0.17);
const LOY = array<f32, 9>(0.1, -0.05, 0.0, 0.12, 0.05, 0.1, -0.08, -0.15, -0.06);
// where it comes from and where it goes (unit directions from its station, world, mean view down -z). The formation
// lies left of the hero, so nobody's path crosses it: most come down from above (ahead: the ensemble swims up) and
// fall behind down-left; 4 and 7 come in from the left edge and sink away below; the deepest rise from below and
// sink back into the deep.
const DIN = array<vec3f, 9>(vec3f(0.1, -0.95, -0.3), vec3f(0.25, -0.9, -0.3), vec3f(-0.2, -0.95, -0.25),
 vec3f(-0.2, -0.95, -0.2), vec3f(-0.95, 0.15, 0.0), vec3f(-0.35, 0.95, -0.05), vec3f(-0.15, 1.0, 0.1), vec3f(-0.95, 0.2, 0.05), vec3f(-0.45, 0.9, 0.0));
const DOUT = array<vec3f, 9>(vec3f(-0.7, -0.3, -0.65), vec3f(-0.75, -0.35, -0.55), vec3f(-0.7, -0.45, -0.55),
 vec3f(-0.75, -0.45, -0.4), vec3f(-0.5, -0.85, 0.0), vec3f(-0.75, -0.65, 0.05), vec3f(-0.8, -0.6, 0.0), vec3f(-0.45, -0.9, 0.0), vec3f(-0.7, -0.7, 0.0));

fn stableRand(id: u32, salt: u32) -> f32 {
 var x = id * 747796405u + salt * 2891336453u + 12345u;
 x = (x ^ (x >> 15u)) * 2246822519u;
 x = (x ^ (x >> 13u)) * 3266489917u;
 x = x ^ (x >> 16u);
 return f32(x >> 8u) * (1.0 / 16777216.0);
}

struct HF { o: vec3f, ca: f32, sa: f32, cb: f32, sb: f32, k: f32, };
fn hfMake(o: vec3f, tx: f32, tz: f32, k: f32) -> HF {
 return HF(o, cos(tx), sin(tx), cos(tz), sin(tz), k);
}
fn hfDir(f: HF, d: vec3f) -> vec3f {
 let y1 = d.y * f.ca - d.z * f.sa;
 let z1 = d.y * f.sa + d.z * f.ca;
 return vec3f(d.x * f.cb - y1 * f.sb, d.x * f.sb + y1 * f.cb, z1);
}
fn hfPos(f: HF, p: vec3f) -> vec3f { return f.o + hfDir(f, p * f.k); }

// Same shape as the rig's pulse: fast squeeze to 0.28 of the cycle, slow release.
fn pulseEnv(ph: f32) -> f32 {
 let x = fract(ph);
 return smoothstep(0.0, 0.28, x) * (1.0 - smoothstep(0.28, 1.0, x));
}
// Thrust: the surge that follows a squeeze (fast up), then the glide back (slow). 0..1..0, periodic.
fn thrust(ph: f32) -> f32 {
 let x = fract(ph);
 return smoothstep(0.04, 0.42, x) - smoothstep(0.42, 1.0, x);
}

fn bellSqueeze(v: f32, pm: f32) -> f32 {
 let s = smoothstep(0.12, 1.0, v);
 return 1.0 - 0.19 * pm * s * sqrt(s);
}
// Exumbrella point. p: body contraction, pm: lagged margin contraction, te: tension, tall: -1 flat .. 1 tall.
fn bellExo(phi: f32, v: f32, p: f32, pm: f32, te: f32, tall: f32, flr: f32) -> vec3f {
 let th = v * BELL_THMAX;
 let c = cos(th);
 let h = BELL_H * (1.0 + 0.24 * p + 0.08 * te) * (1.0 + 0.42 * tall);
 let rib = 1.0 + 0.022 * (0.5 + 0.5 * cos(16.0 * phi)) * smoothstep(0.08, 0.5, v) * (1.0 - smoothstep(0.8, 0.95, v));
 let wave = (0.03 * sin(8.0 * phi + 0.7) + 0.012 * sin(13.0 * phi + 2.0)) * smoothstep(0.6, 1.0, v);
 let flare = 1.0 + (0.05 * (1.0 - 1.6 * pm) + flr) * smoothstep(BELL_VM, 1.0, v);
 let r = sin(th) * bellSqueeze(v, pm) * rib * flare * (1.0 - 0.1 * tall);
 var y = BELL_Y0 - 0.05 * pm * smoothstep(0.5, 1.0, v);
 if (c > 0.0) { y = y + h * pow(c, 0.88); } else { y = y + h * c * 0.6; }
 return vec3f(cos(phi) * r, y + wave, sin(phi) * r);
}

struct Comp {
 f: HF,
 up: vec3f,     // the bell's axis (world)
 tall: f32,     // bell proportion, -1 flat .. 1 tall (identity cos psi; juveniles rounder, elders flatter)
 hand: f32,     // arm twist handedness and amount, -1 .. 1  (identity: sin(2 psi + 0.6))
 ph: f32,       // own swim phase, cycles                    (rig phase + identity offset)
 pl: f32,       // own contraction 0..1
 pm: f32,       // margin contraction (lags the body a little)
 pres: f32,     // visibility 0..1 (the visit fade; 0 between visits, when the body is folded away: unfold)
 gain: f32,     // emission gain: visit, strike, hit, depth falloff
 fog: f32,      // atmospheric depth 0..1: dims and shifts toward the palette shadow tone
 vel: vec3f,    // swimming velocity, world units per second (visit transit + formation glide)
 droop: vec3f,  // the direction appendages settle into
 side: vec3f,
 side2: vec3f,
 te: f32,
 t: f32,
 j: u32,
 tier: u32,     // 2 near-lens (closer than 7), else 1
 amp: f32,      // drift amplitude, rate (for the follow-through)
 rate: f32,
 surge: f32,    // thrust amplitude, world units
 cps: f32,      // swim cycles per second
 ic: f32,       // identity (cos, sin of the eased fifths angle) for the appendages
 is: f32,
 sf: f32,       // size factor (0.45 juvenile .. 1.55 elder)
 gvel: vec3f,   // swimming velocity (world units per second)
 st: f32,       // strike light (voice envelope)
 ra: f32,       // strike response at the bell (0..~1, rises over ~0.8 s, no step)
 rb: f32,       // the same response a stage later and wider (mid appendage)
 rc: f32,       // two stages later (appendage tips)
 nud: f32,      // nudge along the heading per unit response, world
};

fn driftAt(j: u32, amp: f32, w: f32, t: f32) -> vec3f {
 let kf = f32(j);
 return amp * vec3f(sin(t * w + kf * 1.7) + 0.35 * sin(t * w * 2.3 + kf * 4.1),
                    0.55 * sin(t * w * 1.37 + kf * 2.9 + 1.0),
                    0.6 * cos(t * w * 0.81 + kf * 0.7));
}

fn compMake(P: Params, j: u32, t: f32) -> Comp {
 var WX = array<f32, 9>(P.p0x, P.p1x, P.p2x, P.p3x, P.p4x, P.p5x, P.p6x, P.p7x, P.p8x);
 var WY = array<f32, 9>(P.p0y, P.p1y, P.p2y, P.p3y, P.p4y, P.p5y, P.p6y, P.p7y, P.p8y);
 var WZ = array<f32, 9>(P.p0z, P.p1z, P.p2z, P.p3z, P.p4z, P.p5z, P.p6z, P.p7z, P.p8z);
 var VIS = array<f32, 9>(P.vis0, P.vis1, P.vis2, P.vis3, P.vis4, P.vis5, P.vis6, P.vis7, P.vis8);
 var IC = array<f32, 5>(P.ic0, P.ic1, P.ic2, P.ic3, P.ic4);
 var IS = array<f32, 5>(P.is0, P.is1, P.is2, P.is3, P.is4);
 var RA = array<f32, 5>(P.r0a, P.r1a, P.r2a, P.r3a, P.r4a);
 var RB = array<f32, 5>(P.r0b, P.r1b, P.r2b, P.r3b, P.r4b);
 var RC = array<f32, 5>(P.r0c, P.r1c, P.r2c, P.r3c, P.r4c);
 let vi = VOICE[j];
 let kf = f32(j);
 let st = 0.0;
 let ic = IC[vi];
 let is = IS[vi];
 // the force of a struck note, as a heavy damped body answers it (soft-saturated so dense passages roll)
 let ra = RA[vi] / (1.0 + 0.6 * RA[vi]);
 let rb = RB[vi] / (1.0 + 0.6 * RB[vi]);
 let rc = RC[vi] / (1.0 + 0.6 * RC[vi]);
 let sf = SIZE[j];
 // identity: smooth functions of the eased fifths angle psi (neighbouring fifths look related)
 let c2 = ic * ic - is * is;
 let s2 = 2.0 * ic * is;
 let tall = clamp(0.75 * ic + 0.55 * (1.0 - sf), -1.0, 1.0);
 let lean = is;
 let hand = 0.825 * s2 + 0.565 * c2;
 let phOff = 0.3 * (0.622 * is + 0.783 * ic) + 0.12 * s2 + 0.37 * kf;
 let tv = tan(radians(P.camFov) * 0.5);
 // its WORLD position (expression_compworld: school centre + home + harmonic offset + slow drift + visit drift; no
 // camera term); its own drift is a few hundredths of a unit per second, so the velocity the appendages trail behind
 // is the school's: 0.4 of the hero's
 var o = vec3f(WX[j], WY[j], WZ[j]);
 let vel = 0.4 * vec3f(P.heroVX, P.heroVY, P.heroVZ);
 let speed = length(vel);
 let amp = 0.0;
 let rate = 0.0;
 let sz = 0.6 * sf;
 // the camera is used for LIGHT only: the depth haze, and a companion that passes behind the hero's bell on screen
 // dims there (it is behind a bright bell), so nothing ever hides or veils the hero
 let cam = vec3f(P.camX, P.camY, P.camZ);
 let fwd = normalize(vec3f(P.camTX, P.camTY, P.camTZ) - cam);
 let rgt = normalize(cross(fwd, vec3f(0.0, 1.0, 0.0)));
 let cup = cross(rgt, fwd);
 let hrel = vec3f(P.heroX, P.heroY, P.heroZ) - cam;
 let hdz = max(dot(hrel, fwd), 0.5);
 let hc = vec2f(dot(hrel, rgt), dot(hrel, cup)) / (hdz * tv) + vec2f(0.0, 0.12 * P.heroScale / (hdz * tv));
 let hrs = 1.15 * P.heroScale / (hdz * tv);
 let rel = o - cam;
 let dz = max(dot(rel, fwd), 0.3);
 let sc = vec2f(dot(rel, rgt), dot(rel, cup)) / (dz * tv);
 let crad = 1.1 * sz / (dz * tv);
 let behindBell = 1.0 - 0.85 * (1.0 - smoothstep(0.9 * hrs, 1.4 * hrs + crad, length(sc - hc)));
 // swim: the hero's slow rate with its own phase; the same proportions and damping as the hero (no extra stroke
 // while drifting); a note gives a slightly fuller stroke
 let ph = P.pulsePhase + phOff;
 let stroke = 1.0 + 0.25 * ra;
 let pl = pulseEnv(ph) * stroke;
 let pm = pulseEnv(ph - 0.06) * stroke;
 let cps = max(P.swimRate, 0.01);
 // visibility: its visit fades it in from the dark and back out (expression_compworld vis)
 let pres = VIS[j];
 // lean: identity bias, into the travel, a slow sway
 let tz = -0.38 * lean - 0.3 * tanh(vel.x * 0.6) + 0.08 * sin(t * 0.23 + kf * 2.0);
 let tx = 0.1 * sin(t * 0.17 + kf * 1.3) + 0.2 * tanh(vel.z * 0.4);
 let f0 = hfMake(o, tx, tz, sz);
 let up = hfDir(f0, vec3f(0.0, 1.0, 0.0));
 // pulse thrust: surge along the bell's own axis after each squeeze, glide back between (mean-free)
 let surge = 0.1 * sz;
 let nud = 0.25 * sz;
 let f = hfMake(o + up * (surge * (thrust(ph - 0.03) - 0.42) + nud * ra), tx, tz, sz);
 // appendages hang along the bell's own axis (the hero family: no sideways current of their own); motion acts
 // through dragAt, never by tilting the hang
 let droop = -up;
 let side = normalize(cross(droop, vec3f(0.0, 0.0, 1.0)));
 let side2 = normalize(cross(droop, side));
 let dcam = length(o - cam);
 // no haze of our own: the depth pass (wgsl_worlddepth) applies aerial perspective and depth of field to this layer
 // from its own depth, so near companions keep the full palette and only the far ones fade toward the water
 let fog = 0.0;
 let near = mix(0.55, 1.0, smoothstep(4.5, 8.0, dcam));
 // no whole-body brightness response to the music: a note's light is a glow that travels (glowAt)
 // never brighter than the hero at equal depth (the bell material is the hero's): distance only dims
 let gain = pres * behindBell;
 let tier = 1u;
 return Comp(f, up, tall, hand, ph, pl, pm, pres, gain, fog, vel, droop, side, side2, P.tension, t, j, tier, amp, rate, surge, cps, ic, is, sf, vel, st, ra, rb, rc, nud);
}

// An absent companion (visibility 0, between visits, where its station may jump) is folded to a point at its bell,
// so it writes nothing into the companion layer's depth: the depth of field reads that depth per pixel, and an
// invisible body there would lend its focus to whatever glows behind it, and pop it sharp or soft as it moves.
// It unfolds while its light is still under 3 % (about the first second of its 10 s fade), so the depth grows in
// with it instead of appearing in one frame. 0 absent, 1 present.
fn unfold(c: Comp) -> f32 {
 return smoothstep(0.0, 0.03, c.pres);
}
fn shown(c: Comp, x: vec3f) -> vec3f {
 return c.f.o + unfold(c) * (x - c.f.o);
}

// The strike's follow-through down an appendage (s 0 at the bell, 1 at the tip): the bell moved nud * ra along
// its heading; a point further down moved by the LATER, wider response (rb, rc), and less of it. Returned relative
// to the rigid attachment, so nothing ever moves ahead of its bell. side: a gentle transverse swell rides with it.
fn strikeLag(c: Comp, s: f32) -> vec3f {
 let rs = select(mix(c.rb, c.rc, 2.0 * s - 1.0), mix(c.ra, c.rb, 2.0 * s), s < 0.5);
 return c.up * c.nud * (rs * (1.0 - 0.35 * s) - c.ra) + c.side * (0.5 * c.nud * rs * s);
}

// Never above (or ahead of) its bell: a point of an appendage hanging from root, s along it of length L, is held at
// least 0.1 L s below the root along the bell's axis (a smooth clamp, so nothing kinks).
fn keepBelow(c: Comp, root: vec3f, p: vec3f, s: f32, L: f32) -> vec3f {
 let h = dot(p - root, c.up) + 0.1 * L * s;
 let k = 0.05 * L + 1e-4;
 return p - c.up * (0.5 * (h + sqrt(h * h + k * k)));
}

// ---- the appendage family (shared with the hero: M/hero/tent.common.wgsl) ----
const DRAG_T = 4.0;        // tentacles: seconds of mean swimming by which a tip trails
const ARM_DRAG_T = 5.5;    // oral arms and silk trains: broad veils catch more water
// trail opposite the companion's (smooth, surge-free) swimming velocity, growing toward the tip, softly limited
// (never normalised: as it slows the trail eases back to the rest hang)
fn dragAt(c: Comp, s: f32, len: f32, secs: f32) -> vec3f {
 let dd = -c.vel * secs * pow(s, 1.5);
 let limit = 0.35 * len;
 return dd / sqrt(1.0 + dot(dd, dd) / (limit * limit));
}
// the slow sweep of the whole hanging bundle (one every 20 s), travelling tipward
fn sweepAt(c: Comp, s: f32) -> vec3f {
 let a = TAU * (0.05 * c.t - 0.35 * s) + f32(c.j) * 1.7;
 return (c.side * sin(a) + c.side2 * 0.5 * sin(a * 0.7 + 1.9)) * 0.08 * s * s;
}

// A note's light: a soft glow born in the core (the bell's response, ra), reaching the canals and margin a stage
// later (rb) and the appendage tips two stages later (rc): about 0.8, 1.2 and 1.6 s after the strike, building with
// no step; saturating, so a dense passage gives a steady warm breathing. x: 0 core .. 1 margin .. 2 appendage tip.
fn glowAt(c: Comp, x: f32) -> f32 {
 let r = select(mix(c.rb, c.rc, clamp(x - 1.0, 0.0, 1.0)), mix(c.ra, c.rb, x), x < 1.0);
 return r / (1.0 + r);
}
// Companion oral arms: 9 companions x 4 veils, one 6 x 40 grid sheet per veil. The veils are fins round
// one shared trailing axis that hangs from where the bell WAS (follow-through); they twist about it as a
// helix whose handedness and amount are the companion's identity (hand); the outer edge is ruffled.
// uv = (across 0..1, along 0..1). tint = (veil + 4 * companion, gain, fog, travelling pulse).
const AC = 6u;
const AR = 40u;
const NV = 4u;

fn armAxis(c: Comp, s: f32, len: f32) -> vec3f {
 let root = hfPos(c.f, vec3f(0.0, BELL_Y0 + 0.16 + 0.1 * c.pl, 0.0));
 let d0 = -c.up;
 let p1 = root + d0 * 0.3 * len;
 let p2 = p1 + c.droop * 0.7 * len;
 let a = 1.0 - s;
 var pos = a * a * root + 2.0 * s * a * p1 + s * s * p2;
 pos += dragAt(c, s, len, ARM_DRAG_T) + sweepAt(c, s) * len + strikeLag(c, s);
 // a slow S-wave travelling down the bundle (about 0.1 Hz)
 let w = TAU * (0.6 * s - 0.11 * c.t) + f32(c.j) * 1.3;
 let amp = 0.12 * len * s;
 pos += (c.side * (sin(w) + 0.2 * sin(2.1 * w + 1.0)) + c.side2 * 0.45 * cos(0.75 * w + 0.6)) * amp;
 return pos;
}

fn process(p: Point, ctx: PointCtx) -> Point {
 var q = p;
 let P = ctx.params;
 let per = AC * AR;
 let sh = ctx.index / per;
 let j = min(sh / NV, NCOMP - 1u);
 let arm = sh % NV;
 let r = ctx.index % per;
 let i = r % AC;
 let jj = r / AC;
 let a = f32(i) / f32(AC - 1u) * 2.0 - 1.0;
 let s = f32(jj) / f32(AR - 1u);
 let c = compMake(P, j, ctx.absTime);
 let h = stableRand(j * 7u + arm, 43u);
 let psi = f32(arm) / f32(NV) * TAU + 0.7 * f32(j);
 // identity: arm length from the fifths angle (0.6 psi rotated), so neighbours are related
 let armK = 1.0 + 0.3 * (0.416 * c.ic + 0.909 * c.is);
 let len = (1.5 + 0.6 * h) * armK * (0.8 + 0.2 * c.sf) * (0.9 + 0.2 * P.dv) * c.f.k;
 let ds = 0.02;
 let axis = armAxis(c, s, len);
 let T = normalize(armAxis(c, min(s + ds, 1.0), len) - armAxis(c, max(s - ds, 0.0), len));
 // helix about the axis: identity handedness; a slow constant drift of the braid
 let th = psi + TAU * (1.2 * c.hand + 0.12 * c.te) * s - 0.12 * c.t + 0.2 * sin(TAU * (0.8 * s - 0.08 * c.t) + h * 6.0) * s;
 let radial0 = c.side * cos(th) + c.side2 * sin(th);
 let W = normalize(radial0 - T * dot(radial0, T));
 let Nn = cross(T, W);
 // thin frilled arms: each at most about a quarter of the bell's width
 // the near tier carries the hero's broad veils, the others thinner arms
 let width = select(0.34, 0.62, isNear(j)) * c.f.k * (0.6 + 0.4 * smoothstep(0.0, 0.2, s)) * (1.0 - 0.5 * s) * (1.0 + 0.15 * sin(s * 9.0 + h * 9.0));
 let off = 0.03 * c.f.k + width * (0.55 + 0.45 * a);
 // lettuce edge: the rim is longer than the midline, so it waves (about 9 waves down an arm)
 let edge = smoothstep(0.2, 1.0, abs(a));
 let rw = TAU * (s * 5.0) + a * 2.0 + h * 7.0 - c.t * 0.25;
 let e2 = edge * edge;
 let ruffle = width * (0.14 * e2 * e2 * sin(rw) + 0.07 * e2 * edge * sin(rw * 1.73 + 2.1 + h * 3.0));
 let curl = width * (0.12 * a * a + 0.14 * sin(a * 4.7 + s * 6.0 + h * 4.0 - c.t * 0.25));
 q.position = shown(c, axis + W * off + Nn * (ruffle + curl));
 q.uv = vec2f(a * 0.5 + 0.5, s);
 let travelPulse = pulseEnv(c.ph - 0.1 - 0.5 * s);
 q.tint = vec4f(f32(arm) + 4.0 * f32(j) + 0.45 * glowAt(c, 1.0 + s), c.gain, c.fog, travelPulse);
 return q;
}

parameters.source:
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}
// WORLD DOF 2/3, gather (Silk Medusa): HALF resolution, 48-tap disc (golden-angle spiral). Scatter-as-gather with
// separate fields:
//  - far: a sample covers this pixel if the SMALLER of the two circles reaches it, so a far
//    creature never bleeds over the sharp hero and the hero never smears into the background;
//  - near: a near sample covers anything its own circle reaches, so near things veil softly over
//    what is behind them; its coverage becomes the near alpha.
// Samples are weighted up by brightness so highlights open into discs (bokeh), not gaussian mush.
struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
struct Params {
 radius: f32, // @default 16 Kernel radius in half-res pixels (the largest circle it can draw).
 bokeh: f32, // @default 1.5 Highlight weighting: how strongly bright samples dominate (disc bokeh).
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

const N: i32 = 48;

fn ign(p: vec2f) -> f32 { return fract(52.9829189 * fract(dot(p, vec2f(0.06711056, 0.00583715)))); }

@fragment fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
 let size = vec2f(textureDimensions(inputTexture));
 let texel = 1.0 / size;
 let s0 = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
 let c0 = s0.a;
 let R = params.radius;
 // A fixed spiral: per-pixel turns turned the coverage count into speckle at soft edges; the soft
 // coverage ramp and the tent pass hide the fixed pattern instead.
 let rot = 0.0 * ign(uv * size);
 var bg = vec4f(0.0);
 var fg = vec4f(0.0);
 var fgN = 0.0;
 var fgC = 0.0;
 for (var k = 0; k < N; k = k + 1) {
  let fk = f32(k);
  let r = sqrt((fk + 0.5) / f32(N)) * R;
  let a = fk * 2.3999632 + rot;
  let offs = vec2f(cos(a), sin(a)) * r;
  let s = textureSampleLevel(inputTexture, inputSampler, uv + offs * texel, 0.0);
  let cs = s.a;
  let y = dot(s.rgb, vec3f(0.2126, 0.7152, 0.0722));
  let hw = 1.0 + params.bokeh * y / (1.0 + 0.25 * y);
  let bgC = max(min(c0, cs), 0.0);
  let bw = clamp((bgC - r) * 0.5 + 1.0, 0.0, 1.0);
  let fw = clamp((-cs - r) * 0.5 + 1.0, 0.0, 1.0) * step(1.0, -cs);
  bg = bg + vec4f(s.rgb * hw, hw) * bw;
  fg = fg + vec4f(s.rgb * hw, hw) * fw;
  fgN = fgN + fw;
  fgC = fgC + fw * (-cs);
 }
 // The centre always counts for the background field (an in-focus pixel stays itself).
 let y0 = dot(s0.rgb, vec3f(0.2126, 0.7152, 0.0722));
 let hw0 = 1.0 + params.bokeh * y0 / (1.0 + 0.25 * y0);
 bg = bg + vec4f(s0.rgb * hw0, hw0);
 let bgc = bg.rgb / max(bg.a, 1e-4);
 let fgc = fg.rgb / max(fg.a, 1e-4);
 let cav = fgC / max(fgN, 1e-4);
 let alpha = clamp(fgN * R * R / (f32(N) * max(cav * cav, 1.0)), 0.0, 1.0);
 return vec4f(mix(bgc, fgc, alpha), alpha);
}

parameters.defaults:
heroX = 1;
heroY = 1.2;
heroZ = 0;
density = 0.5;
rc0 = 1;
rc1 = 1;
rc2 = 1;
rc3 = 1;
rc4 = 1;
rs0 = 0;
rs1 = 0;
rs2 = 0;
rs3 = 0;
rs4 = 0

parameters.source:
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}
// WORLD DOF 3/3, combine (Silk Medusa): FULL resolution. LAYERED depth of field (all light is
// additive, so layers simply add): the COMPANION layer is defocused from its OWN depth (sharp with
// aerial perspective where in focus, the half-res gather where far, its near field by alpha; a
// near-lens veil is dimmed and soft-capped so it never washes the hero out). The HERO layer (hero,
// silk and the motes, which defocus in their own kernel) is in focus by definition and is added
// sharp on top. Silk can no longer lend its focus to a companion seen through it.
// inputTexture = companion render (full or half res), 1 = its depth, 2 = gather after its tent
// (half res), 3 = the hero layer (render_scene).
struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
struct Params {
 heroX: f32, // @default 1 Hero x (focus).
 heroY: f32, // @default 1.2 Hero y.
 heroZ: f32, // @default 0 Hero z.
 camX: f32, // @default 0 Camera eye x.
 camY: f32, // @default 0.4 Camera eye y.
 camZ: f32, // @default 9 Camera eye z.
 camTX: f32, // @default 0 Camera target x.
 camTY: f32, // @default 0.2 Camera target y.
 camTZ: f32, // @default 0 Camera target z.
 far: f32, // @default 90 Camera far plane (camera_main far).
 mood: f32, // @default 0 Rig palette position: the water's colour.
 haze: f32, // @default 0.85 Aerial perspective strength (same value as wgsl_worlddofprep.haze).
 aperture: f32, // @default 40 Circle of confusion (radius) at infinity, full-res pixels (same as the prep).
 nearMax: f32, // @default 32 Largest near circle, full-res pixels (same as the prep).
 band: f32, // @default 1.5 Sharp depth band either side of the hero (same as the prep).
 cap: f32, // @default 1.2 Luminance above which a near-field veil rolls off (keeps the hero readable).
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;
@group(0) @binding(6) var inputTexture3: texture_2d<f32>;

fn bilinear(t: texture_2d<f32>, uv: vec2f) -> vec4f {
 let size = vec2f(textureDimensions(t));
 let p = uv * size - 0.5;
 let i = vec2i(floor(p));
 let f = p - floor(p);
 let m = vec2i(size) - vec2i(1);
 let a = textureLoad(t, clamp(i, vec2i(0), m), 0);
 let b = textureLoad(t, clamp(i + vec2i(1, 0), vec2i(0), m), 0);
 let c = textureLoad(t, clamp(i + vec2i(0, 1), vec2i(0), m), 0);
 let d = textureLoad(t, clamp(i + vec2i(1, 1), vec2i(0), m), 0);
 return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

@fragment fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
 let dsize = vec2i(textureDimensions(inputTexture1));
 let ip = clamp(vec2i(uv * vec2f(dsize)), vec2i(0), dsize - vec2i(1));
 let dz = textureLoad(inputTexture1, ip, 0).r;
 let eye = vec3f(params.camX, params.camY, params.camZ);
 let fwd = normalize(vec3f(params.camTX, params.camTY, params.camTZ) - eye);
 let focus = max(dot(vec3f(params.heroX, params.heroY, params.heroZ) - eye, fwd), 0.5);
 var sharp = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
 var c = params.aperture;
 if (dz > 0.0 && dz < 0.9999) {
  let z = dz * params.far;
  c = clamp(params.aperture * (1.0 - focus / (z - clamp(z - focus, -params.band, params.band))), -params.nearMax, params.aperture);
  let h = (1.0 - exp(-max(z - focus, 0.0) * 0.09)) * params.haze;
  let y = dot(sharp.rgb, vec3f(0.2126, 0.7152, 0.0722));
  let water = mix(moodColor(params.mood, 0.25), vec3f(0.3, 0.45, 0.95), 0.5);
  sharp = vec4f(mix(sharp.rgb, water * y * 1.1, h * 0.7) * (1.0 - 0.55 * h), sharp.a);
 }
 let dof = bilinear(inputTexture2, uv);
 let far = smoothstep(1.0, 3.5, c);
 var col = mix(sharp.rgb, dof.rgb, max(far, dof.a));
 // A near-lens companion is a soft veil: dimmer, and its brightness rolls off above `cap`.
 col = col * (1.0 - 0.3 * dof.a);
 let yl = dot(col, vec3f(0.2126, 0.7152, 0.0722));
 let capped = select(yl, params.cap + (yl - params.cap) * 0.25, yl > params.cap);
 col = mix(col, col * (capped / max(yl, 1e-4)), dof.a);
 let hsize = vec2i(textureDimensions(inputTexture3));
 col = col + textureLoad(inputTexture3, clamp(vec2i(uv * vec2f(hsize)), vec2i(0), hsize - vec2i(1)), 0).rgb;
 return vec4f(col, sharp.a);
}

// ---- material_comptrains: the silk worker's pass-6 material_silk (M/silk/p6/silk.material.wgsl), plus the
// companions' atmospheric depth (fog packed in tint.x as tone + 2 * round(fog * 20)).
// ---- material_silk: sheer chiffon, additive. Face-on almost clear, grazing and folds bright, hems, threads,
// a thin-film shimmer kept inside the mood's own hue, warm peach-gold glints. tint: x tone, y gain,
// z arc length, w texture (from kernel_silk).
struct Params {
 lum: f32, // @default 0.5 Rig illumination 0.2..1.
 mood: f32, // @default 0 Rig palette position 0..4.
 energy: f32, // @default 0.5 Rig energy: glint brightness.
 tension: f32, // @default 0.3 Rig tension: film shifts toward the highlight.
};

const TAU: f32 = 6.2831853;
// the fixed warm accent (peach-gold #ffc890): glints keep it in every mood
const WARM: vec3f = vec3f(1.0, 0.784, 0.565);

// rotate a colour's hue round the grey axis (luminance roughly kept)
fn hueRot(c: vec3f, a: f32) -> vec3f {
 let k = vec3f(0.57735027);
 let ca = cos(a);
 return c * ca + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - ca);
}

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
 var o = surfaceDefaults(s);
 let V = normalize(s.eye - s.world);
 let nl = max(length(s.normal), 1e-8);
 let ndv = clamp(abs(dot(s.normal, V)) / nl, 0.0, 1.0);
 let graze = 1.0 - ndv;
 let fogq = floor(s.tint.x * 0.5 + 1e-3);
 let tone = s.tint.x - 2.0 * fogq;
 let fog = fogq / 20.0;
 let gain = s.tint.y;
 let sg = s.tint.z;
 let tex = s.tint.w;
 let v = s.uv.y;
 let t = s.absTime;

 // hems: a thin hot line on each edge, about two pixels at any distance, plus a soft inner glow
 let ev = min(v, 1.0 - v);
 // degenerate (edge-on, sub-pixel) triangles can hand back non-finite derivatives: clamp them
 let fw = clamp(fwidth(v), 1e-4, 1.0);
 let hem = 1.0 - smoothstep(0.0, 2.0 * fw, ev);
 let hemGlow = exp(-ev / 0.07);

 // lengthwise threads, faded out where they would alias
 let tf = mix(70.0, 34.0, tex);
 let warp = sin(sg * 0.9 + v * 5.0) * 1.3;
 let bundle = 0.5 + 0.5 * sin(v * tf * 0.31 + 1.3 + sg * 0.23 + warp);
 let thr = (0.5 + 0.5 * sin(v * tf + warp)) * bundle;
 let aa = clamp(1.6 - clamp(fwidth(v * tf), 0.0, 4.0) * 1.2, 0.0, 1.0);
 let threads = mix(0.8, 0.45 + 1.1 * thr, aa);

 // light: face-on nearly clear, grazing and folds bright
 let g2 = graze * graze;
 let sheen = g2 * g2 * 0.95 + g2 * 0.3;
 let body = moodColor(p.mood, tone);
 let shadow = moodColor(p.mood, tone - 0.3);
 let hi = moodColor(p.mood, 1.0);
 // thin film WITHOUT the rainbow: the hue swings at most 0.15 of a cycle either side of the mood's body
 // colour (with graze, along the ribbon and over time) and is half the mood's own mid tone
 let ph = 1.4 * graze + 0.12 * sg - 0.05 * t + 0.35 * v + 2.0 * tone + 0.25 * p.tension;
 let film = mix(hueRot(body, TAU * 0.15 * sin(TAU * ph)), moodColor(p.mood, 0.6), 0.5);

 // the sheen warms toward the highlight tone as it grazes: folds and turned edges glow
 let warm = mix(body, hi, smoothstep(0.35, 0.95, graze) * 0.7);
 // face-on: a faint milky body that grows with illumination
 let face = mix(shadow, body, 0.6) * (0.04 + 0.025 * threads) * (0.75 + 1.1 * p.lum * p.lum);
 var col = face + warm * sheen * threads * 0.42 + film * sheen * 0.36;
 // the hems are kept apart: a thin line may be brighter than the sheer body
 let hems = hi * (hem * 1.1 + hemGlow * 0.12) * (0.5 + graze);
 // satin band: a sheen at a mid viewing angle that slides along as the ribbon rolls; its hottest part
 // leans to the warm accent
 let sb = (ndv - 0.42) / 0.15;
 let satin = exp(-sb * sb) * (0.35 + 0.9 * thr * aa);
 col = col + mix(film, mix(hi, WARM, 0.5), 0.45) * satin * 0.22;

 // warm glints: single peach-gold flecks riding single threads, drifting down the ribbon, the same
 // colour in every mood. A second, slower carrier across the width picks which thread lights.
 let gs = mix(0.9, 1.7, tex);
 let ga = max(sin(sg * gs - t * 0.75 + 7.0 * tone), 0.0);
 let gb = 0.5 + 0.5 * sin(v * 41.0 + sg * 0.6 + 3.0 * tone);
 let gc = max(sin(v * 6.3 + sg * 0.83 + 5.0 * tone + 0.4 * t), 0.0);
 let ga2 = ga * ga; let ga4 = ga2 * ga2; let ga8 = ga4 * ga4;
 let gb2 = gb * gb; let gb4 = gb2 * gb2; let gb8 = gb4 * gb4; let gb16 = gb8 * gb8;
 let gc2 = gc * gc; let gc4 = gc2 * gc2;
 let glint = WARM * ga8 * ga2 * gb16 * gc4 * gc4 * (1.2 + 2.0 * graze) * aa * (0.7 + 0.6 * p.energy);

 o.albedo = vec4f(0.0, 0.0, 0.0, 1.0);
 // calm and medium carry more lit form: the sheer body is lifted (about 2.2x at the calm floor of lum,
 // 1.3x at peak, where the cap below holds it)
 let lift = mix(2.2, 1.3, smoothstep(0.2, 1.0, p.lum));
 // PER-LAYER SOFT CAP: additive layers stack, so each layer's body light is compressed toward a ceiling
 // (0.32 at calm and medium, where layers rarely stack; 0.18 at peak, so three stacked bodies keep their
 // colour and never reach white) and its hems (and glints) toward 0.8 (luminance-based, hue kept)
 let cap = mix(0.32, 0.18, smoothstep(0.45, 0.95, p.lum));
 let k = gain * (0.65 + 0.7 * p.lum);
 let bodyE = col * (k * lift);
 let hemE = (hems + glint) * k;
 let lb = dot(bodyE, vec3f(0.3, 0.55, 0.15));
 let lh = dot(hemE, vec3f(0.3, 0.55, 0.15));
 let e = bodyE * (cap / (cap + lb)) + hemE * (0.8 / (0.8 + lh));
 let sh = moodColor(p.mood, 0.06);
 let atone = mix(vec3f(1.0), sh / max(dot(sh, vec3f(0.3, 0.5, 0.2)), 0.05), 0.75);
 let ea = mix(e, atone * dot(e, vec3f(0.3, 0.5, 0.2)), 0.8 * fog);
 o.emissive = clamp(ea, vec3f(0.0), vec3f(2.0));
 return o;
}
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}

