// WORLD DOF 1/3, prep (Silk Medusa): HALF resolution. Reads the creature render (bilinear at the
// shared corner = a 2x2 average) and its linear depth (R = view depth / far, 4 texels). Applies
// aerial perspective per source (beyond the hero: dimmer, bluer, lower contrast), and writes the
// signed circle of confusion in HALF-res pixels to alpha: negative near, positive far. Empty depth
// (nothing but black there) counts as infinitely far, so far creatures spread softly into it.
struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
struct Params {
 heroX: f32, // @default 1 Hero x (focus).
 heroY: f32, // @default 1.2 Hero y.
 heroZ: f32, // @default 0 Hero z.
 camX: f32, // @default 0 Camera eye x.
 camY: f32, // @default 0.4 Camera eye y.
 camZ: f32, // @default 9 Camera eye z.
 camTX: f32, // @default 0 Camera target x.
 camTY: f32, // @default 0.2 Camera target y.
 camTZ: f32, // @default 0 Camera target z.
 far: f32, // @default 90 Camera far plane (camera_main far): depth is view depth / far.
 mood: f32, // @default 0 Rig palette position: the water's colour.
 haze: f32, // @default 0.85 Aerial perspective strength beyond the hero.
 aperture: f32, // @default 40 Circle of confusion (radius) at infinity, in full-res pixels.
 nearMax: f32, // @default 32 Largest near-field circle, full-res pixels.
 band: f32, // @default 1.5 Depth either side of the hero kept fully sharp (world units; ~1.5 x heroScale).
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

@fragment fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
 let dsize = vec2i(textureDimensions(inputTexture1));
 let base = vec2i(floor(uv * vec2f(dsize) - 0.5));
 let eye = vec3f(params.camX, params.camY, params.camZ);
 let fwd = normalize(vec3f(params.camTX, params.camTY, params.camTZ) - eye);
 let focus = max(dot(vec3f(params.heroX, params.heroY, params.heroZ) - eye, fwd), 0.5);
 var c = 1e5;
 var zmin = 1e5;
 for (var k = 0; k < 4; k = k + 1) {
  let ip = clamp(base + vec2i(k & 1, k >> 1), vec2i(0), dsize - vec2i(1));
  let dz = textureLoad(inputTexture1, ip, 0).r;
  var ck = params.aperture;
  if (dz > 0.0 && dz < 0.9999) {
   let z = dz * params.far;
   zmin = min(zmin, z);
   ck = clamp(params.aperture * (1.0 - focus / (z - clamp(z - focus, -params.band, params.band))), -params.nearMax, params.aperture);
  }
  c = min(c, ck);
 }
 // A 4x4 box (four bilinear taps): thin bright threads arrive soft enough for the gather.
 let tx = 1.0 / vec2f(dsize);
 var col = 0.25 * (textureSampleLevel(inputTexture, inputSampler, uv + tx * vec2f(-1.0, -1.0), 0.0).rgb + textureSampleLevel(inputTexture, inputSampler, uv + tx * vec2f(1.0, -1.0), 0.0).rgb
  + textureSampleLevel(inputTexture, inputSampler, uv + tx * vec2f(-1.0, 1.0), 0.0).rgb + textureSampleLevel(inputTexture, inputSampler, uv + tx * vec2f(1.0, 1.0), 0.0).rgb);
 if (zmin < 1e4) {
  let h = (1.0 - exp(-max(zmin - focus, 0.0) * 0.09)) * params.haze;
  let y = dot(col, vec3f(0.2126, 0.7152, 0.0722));
  let water = mix(moodColor(params.mood, 0.25), vec3f(0.3, 0.45, 0.95), 0.5);
  col = mix(col, water * y * 1.1, h * 0.7) * (1.0 - 0.55 * h);
 }
 return vec4f(col, c * 0.5);
}

