}
fn hfDir(f: HF, d: vec3f) -> vec3f {
 let y1 = d.y * f.ca - d.z * f.sa;
 let z1 = d.y * f.sa + d.z * f.ca;
 return vec3f(d.x * f.cb - y1 * f.sb, d.x * f.sb + y1 * f.cb, z1);
}
fn hfPos(f: HF, p: vec3f) -> vec3f { return f.o + hfDir(f, p * f.k); }

// Same shape as the rig's pulse: fast squeeze to 0.28 of the cycle, slow release.
fn pulseEnv(ph: f32) -> f32 {
 let x = fract(ph);
 return smoothstep(0.0, 0.28, x) * (1.0 - smoothstep(0.28, 1.0, x));
}
// Thrust: the surge that follows a squeeze (fast up), then the glide back (slow). 0..1..0, periodic.
fn thrust(ph: f32) -> f32 {
 let x = fract(ph);
 return smoothstep(0.04, 0.42, x) - smoothstep(0.42, 1.0, x);
}

fn bellSqueeze(v: f32, pm: f32) -> f32 {
 let s = smoothstep(0.12, 1.0, v);
 return 1.0 - 0.19 * pm * s * sqrt(s);
}
// Exumbrella point. p: body contraction, pm: lagged margin contraction, te: tension, tall: -1 flat .. 1 tall.
fn bellExo(phi: f32, v: f32, p: f32, pm: f32, te: f32, tall: f32, flr: f32) -> vec3f {
 let th = v * BELL_THMAX;
 let c = cos(th);
 let h = BELL_H * (1.0 + 0.24 * p + 0.08 * te) * (1.0 + 0.42 * tall);
 let rib = 1.0 + 0.022 * (0.5 + 0.5 * cos(16.0 * phi)) * smoothstep(0.08, 0.5, v) * (1.0 - smoothstep(0.8, 0.95, v));
 let wave = (0.03 * sin(8.0 * phi + 0.7) + 0.012 * sin(13.0 * phi + 2.0)) * smoothstep(0.6, 1.0, v);
 let flare = 1.0 + (0.05 * (1.0 - 1.6 * pm) + flr) * smoothstep(BELL_VM, 1.0, v);
 let r = sin(th) * bellSqueeze(v, pm) * rib * flare * (1.0 - 0.1 * tall);
 var y = BELL_Y0 - 0.05 * pm * smoothstep(0.5, 1.0, v);
 if (c > 0.0) { y = y + h * pow(c, 0.88); } else { y = y + h * c * 0.6; }
 return vec3f(cos(phi) * r, y + wave, sin(phi) * r);
}

struct Comp {
 f: HF,
 up: vec3f,     // the bell's axis (world)
 tall: f32,     // bell proportion, -1 flat .. 1 tall (identity cos psi; juveniles rounder, elders flatter)
 hand: f32,     // arm twist handedness and amount, -1 .. 1  (identity: sin(2 psi + 0.6))
 ph: f32,       // own swim phase, cycles                    (rig phase + identity offset)
 pl: f32,       // own contraction 0..1
 pm: f32,       // margin contraction (lags the body a little)
 pres: f32,     // visibility 0..1 (the visit fade; 0 between visits, when the body is folded away: unfold)
 gain: f32,     // emission gain: visit, strike, hit, depth falloff
 fog: f32,      // atmospheric depth 0..1: dims and shifts toward the palette shadow tone
 vel: vec3f,    // swimming velocity, world units per second (visit transit + formation glide)
 droop: vec3f,  // the direction appendages settle into
 side: vec3f,
 side2: vec3f,
 te: f32,
 t: f32,
 j: u32,
 tier: u32,     // 2 near-lens (closer than 7), else 1
 amp: f32,      // drift amplitude, rate (for the follow-through)
 rate: f32,
 surge: f32,    // thrust amplitude, world units
 cps: f32,      // swim cycles per second
 ic: f32,       // identity (cos, sin of the eased fifths angle) for the appendages
 is: f32,
 sf: f32,       // size factor (0.45 juvenile .. 1.55 elder)
 gvel: vec3f,   // swimming velocity (world units per second)
 st: f32,       // strike light (voice envelope)
 ra: f32,       // strike response at the bell (0..~1, rises over ~0.8 s, no step)
 rb: f32,       // the same response a stage later and wider (mid appendage)
 rc: f32,       // two stages later (appendage tips)
 nud: f32,      // nudge along the heading per unit response, world
};

fn driftAt(j: u32, amp: f32, w: f32, t: f32) -> vec3f {
 let kf = f32(j);
 return amp * vec3f(sin(t * w + kf * 1.7) + 0.35 * sin(t * w * 2.3 + kf * 4.1),
                    0.55 * sin(t * w * 1.37 + kf * 2.9 + 1.0),
                    0.6 * cos(t * w * 0.81 + kf * 0.7));
}

fn compMake(P: Params, j: u32, t: f32) -> Comp {
 var WX = array<f32, 9>(P.p0x, P.p1x, P.p2x, P.p3x, P.p4x, P.p5x, P.p6x, P.p7x, P.p8x);
 var WY = array<f32, 9>(P.p0y, P.p1y, P.p2y, P.p3y, P.p4y, P.p5y, P.p6y, P.p7y, P.p8y);
 var WZ = array<f32, 9>(P.p0z, P.p1z, P.p2z, P.p3z, P.p4z, P.p5z, P.p6z, P.p7z, P.p8z);
 var VIS = array<f32, 9>(P.vis0, P.vis1, P.vis2, P.vis3, P.vis4, P.vis5, P.vis6, P.vis7, P.vis8);
 var IC = array<f32, 5>(P.ic0, P.ic1, P.ic2, P.ic3, P.ic4);
 var IS = array<f32, 5>(P.is0, P.is1, P.is2, P.is3, P.is4);
 var RA = array<f32, 5>(P.r0a, P.r1a, P.r2a, P.r3a, P.r4a);
 var RB = array<f32, 5>(P.r0b, P.r1b, P.r2b, P.r3b, P.r4b);
 var RC = array<f32, 5>(P.r0c, P.r1c, P.r2c, P.r3c, P.r4c);
 let vi = VOICE[j];
 let kf = f32(j);
 let st = 0.0;
 let ic = IC[vi];
 let is = IS[vi];
 // the force of a struck note, as a heavy damped body answers it (soft-saturated so dense passages roll)
 let ra = RA[vi] / (1.0 + 0.6 * RA[vi]);
 let rb = RB[vi] / (1.0 + 0.6 * RB[vi]);
 let rc = RC[vi] / (1.0 + 0.6 * RC[vi]);
 let sf = SIZE[j];
 // identity: smooth functions of the eased fifths angle psi (neighbouring fifths look related)
 let c2 = ic * ic - is * is;
 let s2 = 2.0 * ic * is;
 let tall = clamp(0.75 * ic + 0.55 * (1.0 - sf), -1.0, 1.0);
 let lean = is;
 let hand = 0.825 * s2 + 0.565 * c2;
 let phOff = 0.3 * (0.622 * is + 0.783 * ic) + 0.12 * s2 + 0.37 * kf;
 let tv = tan(radians(P.camFov) * 0.5);
 // its WORLD position (expression_compworld: school centre + home + harmonic offset + slow drift + visit drift; no
 // camera term); its own drift is a few hundredths of a unit per second, so the velocity the appendages trail behind
 // is the school's: 0.4 of the hero's
 var o = vec3f(WX[j], WY[j], WZ[j]);
 let vel = 0.4 * vec3f(P.heroVX, P.heroVY, P.heroVZ);
 let speed = length(vel);
 let amp = 0.0;
 let rate = 0.0;
 let sz = 0.6 * sf;
 // the camera is used for LIGHT only: the depth haze, and a companion that passes behind the hero's bell on screen
 // dims there (it is behind a bright bell), so nothing ever hides or veils the hero
 let cam = vec3f(P.camX, P.camY, P.camZ);
 let fwd = normalize(vec3f(P.camTX, P.camTY, P.camTZ) - cam);
 let rgt = normalize(cross(fwd, vec3f(0.0, 1.0, 0.0)));
 let cup = cross(rgt, fwd);
 let hrel = vec3f(P.heroX, P.heroY, P.heroZ) - cam;
 let hdz = max(dot(hrel, fwd), 0.5);
 let hc = vec2f(dot(hrel, rgt), dot(hrel, cup)) / (hdz * tv) + vec2f(0.0, 0.12 * P.heroScale / (hdz * tv));
 let hrs = 1.15 * P.heroScale / (hdz * tv);
 let rel = o - cam;
 let dz = max(dot(rel, fwd), 0.3);
 let sc = vec2f(dot(rel, rgt), dot(rel, cup)) / (dz * tv);
 let crad = 1.1 * sz / (dz * tv);
 let behindBell = 1.0 - 0.85 * (1.0 - smoothstep(0.9 * hrs, 1.4 * hrs + crad, length(sc - hc)));
 // swim: the hero's slow rate with its own phase; the same proportions and damping as the hero (no extra stroke
 // while drifting); a note gives a slightly fuller stroke
 let ph = P.pulsePhase + phOff;
 let stroke = 1.0 + 0.25 * ra;
 let pl = pulseEnv(ph) * stroke;
 let pm = pulseEnv(ph - 0.06) * stroke;
 let cps = max(P.swimRate, 0.01);
 // visibility: its visit fades it in from the dark and back out (expression_compworld vis)
 let pres = VIS[j];
 // lean: identity bias, into the travel, a slow sway
 let tz = -0.38 * lean - 0.3 * tanh(vel.x * 0.6) + 0.08 * sin(t * 0.23 + kf * 2.0);
 let tx = 0.1 * sin(t * 0.17 + kf * 1.3) + 0.2 * tanh(vel.z * 0.4);
 let f0 = hfMake(o, tx, tz, sz);
 let up = hfDir(f0, vec3f(0.0, 1.0, 0.0));
 // pulse thrust: surge along the bell's own axis after each squeeze, glide back between (mean-free)
 let surge = 0.1 * sz;
 let nud = 0.25 * sz;
 let f = hfMake(o + up * (surge * (thrust(ph - 0.03) - 0.42) + nud * ra), tx, tz, sz);
 // appendages hang along the bell's own axis (the hero family: no sideways current of their own); motion acts
 // through dragAt, never by tilting the hang
 let droop = -up;
 let side = normalize(cross(droop, vec3f(0.0, 0.0, 1.0)));
 let side2 = normalize(cross(droop, side));
 let dcam = length(o - cam);
 // no haze of our own: the depth pass (wgsl_worlddepth) applies aerial perspective and depth of field to this layer
 // from its own depth, so near companions keep the full palette and only the far ones fade toward the water
 let fog = 0.0;
 let near = mix(0.55, 1.0, smoothstep(4.5, 8.0, dcam));
 // no whole-body brightness response to the music: a note's light is a glow that travels (glowAt)
 // never brighter than the hero at equal depth (the bell material is the hero's): distance only dims
 let gain = pres * behindBell;
 let tier = 1u;
 return Comp(f, up, tall, hand, ph, pl, pm, pres, gain, fog, vel, droop, side, side2, P.tension, t, j, tier, amp, rate, surge, cps, ic, is, sf, vel, st, ra, rb, rc, nud);
}

// An absent companion (visibility 0, between visits, where its station may jump) is folded to a point at its bell,
// so it writes nothing into the companion layer's depth: the depth of field reads that depth per pixel, and an
// invisible body there would lend its focus to whatever glows behind it, and pop it sharp or soft as it moves.
// It unfolds while its light is still under 3 % (about the first second of its 10 s fade), so the depth grows in
// with it instead of appearing in one frame. 0 absent, 1 present.
fn unfold(c: Comp) -> f32 {
 return smoothstep(0.0, 0.03, c.pres);
}
fn shown(c: Comp, x: vec3f) -> vec3f {
 return c.f.o + unfold(c) * (x - c.f.o);
}

// The strike's follow-through down an appendage (s 0 at the bell, 1 at the tip): the bell moved nud * ra along
// its heading; a point further down moved by the LATER, wider response (rb, rc), and less of it. Returned relative
// to the rigid attachment, so nothing ever moves ahead of its bell. side: a gentle transverse swell rides with it.
fn strikeLag(c: Comp, s: f32) -> vec3f {
 let rs = select(mix(c.rb, c.rc, 2.0 * s - 1.0), mix(c.ra, c.rb, 2.0 * s), s < 0.5);
 return c.up * c.nud * (rs * (1.0 - 0.35 * s) - c.ra) + c.side * (0.5 * c.nud * rs * s);
}

// Never above (or ahead of) its bell: a point of an appendage hanging from root, s along it of length L, is held at
// least 0.1 L s below the root along the bell's axis (a smooth clamp, so nothing kinks).
fn keepBelow(c: Comp, root: vec3f, p: vec3f, s: f32, L: f32) -> vec3f {
 let h = dot(p - root, c.up) + 0.1 * L * s;
 let k = 0.05 * L + 1e-4;
 return p - c.up * (0.5 * (h + sqrt(h * h + k * k)));
}

// ---- the appendage family (shared with the hero: M/hero/tent.common.wgsl) ----
const DRAG_T = 4.0;        // tentacles: seconds of mean swimming by which a tip trails
const ARM_DRAG_T = 5.5;    // oral arms and silk trains: broad veils catch more water
// trail opposite the companion's (smooth, surge-free) swimming velocity, growing toward the tip, softly limited
// (never normalised: as it slows the trail eases back to the rest hang)
fn dragAt(c: Comp, s: f32, len: f32, secs: f32) -> vec3f {
 let dd = -c.vel * secs * pow(s, 1.5);
 let limit = 0.35 * len;
 return dd / sqrt(1.0 + dot(dd, dd) / (limit * limit));
}
// the slow sweep of the whole hanging bundle (one every 20 s), travelling tipward
fn sweepAt(c: Comp, s: f32) -> vec3f {
 let a = TAU * (0.05 * c.t - 0.35 * s) + f32(c.j) * 1.7;
 return (c.side * sin(a) + c.side2 * 0.5 * sin(a * 0.7 + 1.9)) * 0.08 * s * s;
}

// A note's light: a soft glow born in the core (the bell's response, ra), reaching the canals and margin a stage
// later (rb) and the appendage tips two stages later (rc): about 0.8, 1.2 and 1.6 s after the strike, building with
// no step; saturating, so a dense passage gives a steady warm breathing. x: 0 core .. 1 margin .. 2 appendage tip.
fn glowAt(c: Comp, x: f32) -> f32 {
 let r = select(mix(c.rb, c.rc, clamp(x - 1.0, 0.0, 1.0)), mix(c.ra, c.rb, x), x < 1.0);
 return r / (1.0 + r);
}
// Silk trains: 10 sheer ribbons, one 7 x 96 grid sheet each (across x along). Elders 0 and 4 tow two, the
// juvenile 3 none, the others one. Smaller relatives of the hero's silk: a train grows from the centre under the
// bell (the manubrium), leaves along the bell's axis through the opening, narrow there, then flares wide toward
// a soft tapered tail; it rolls and twists gently along its length (face, then edge), trails behind the mean swim
// (the hero family's drag) in long slow S-curves, 2.5 to 5 bell lengths long by size. Its curl, handedness and
// roll are the companion's pitch-class fingerprint (silk grammar: coil = (1 - cos psi) / 2, hand = sin psi,
// roll = 0.5 + 0.5 cos 2 psi). The light reaction to a note is a soft glow travelling down it (the later taps of
// the impulse chain), never a flash of the whole.
// uv = (along, across). tint = (tone + 2 * fog step, gain, arc length (world), texture) for material_comptrains.
const TC = 7u;
const TR = 96u;
const NRIB = 10u;
// the near tier tows a small ribbon set (4 and 7 three, 5 two); 0 and 8 one each; the rest none
const ROWNER = array<u32, 10>(4u, 4u, 4u, 7u, 7u, 7u, 5u, 5u, 0u, 8u);
const RIDX = array<u32, 10>(0u, 1u, 2u, 0u, 1u, 2u, 0u, 1u, 0u, 0u);
const NRIBS = array<u32, 9>(1u, 0u, 0u, 0u, 3u, 2u, 0u, 3u, 1u);

struct TS { p: vec3f, root: vec3f, };
fn trainCentre(c: Comp, r: u32, s: f32, Lt: f32, two: f32) -> vec3f {
 let kf = f32(c.j);
 let rf = f32(r);
 let coil = 0.5 - 0.5 * c.ic;
 let hand = c.is;
 // rooted at the centre under the bell, on its axis just below the subumbrella (where the arms hang); a
 // companion with two trains roots them a little apart, and they separate further down
 let az = kf * 1.1 + 0.6;
 let pair = vec3f(cos(az), 0.0, sin(az)) * (rf - 0.5 * (two - 1.0));
 let root = hfPos(c.f, vec3f(0.0, BELL_Y0 + 0.12 + 0.08 * c.pl, 0.0) + pair * 0.14);
 // the first stretch leaves along the bell's axis through the opening, then hangs
 var p = root - c.up * Lt * s + hfDir(c.f, pair) * 0.45 * Lt * s * s;
 // the family's slow drag behind the mean swim, the shared sweep
 p += dragAt(c, s, Lt, ARM_DRAG_T) + sweepAt(c, s) * Lt;
 // its own long slow S-curves (at the sweep's tempo), in its own hand, growing from nothing at the root
 let ncyc = 0.7 + 0.8 * coil;
 let A = Lt * (0.07 + 0.12 * coil) * smoothstep(0.0, 0.3, s) * (0.35 + s);
 let ph = TAU * (ncyc * s - 0.05 * c.t) + 2.1 * rf + kf;
 p += (c.side * sin(ph) + c.side2 * cos(ph) * (0.25 + 0.75 * hand)) * A;
 p += strikeLag(c, s) * 1.4;
 return keepBelow(c, root, p, s, Lt);
}

fn process(p: Point, ctx: PointCtx) -> Point {
 var q = p;
 let P = ctx.params;
 let per = TC * TR;
 let k = min(ctx.index / per, NRIB - 1u);
 let loc = ctx.index % per;
 let ci = loc % TC;
 let rj = loc / TC;
 let a = f32(ci) / f32(TC - 1u) - 0.5;
 let s = f32(rj) / f32(TR - 1u);
 let j = ROWNER[k];
 let r = RIDX[k];
 let c = compMake(P, j, ctx.absTime);
 let h = stableRand(k, 61u);
 let two = f32(NRIBS[j]);
 // 2.5 to 5 bell lengths (diameters) by size, elders longest
 let Lt = 2.0 * c.f.k * mix(2.5, 5.0, clamp((c.sf - 0.45) / 1.1, 0.0, 1.0)) * (0.9 + 0.2 * h);
 let ds = 0.015;
 let ctr = trainCentre(c, r, s, Lt, two);
 let T = normalize(trainCentre(c, r, min(s + ds, 1.0), Lt, two) - trainCentre(c, r, max(s - ds, 0.0), Lt, two) + vec3f(0.0, -1e-5, 0.0));
 // a frame about the centre line, then the ribbon's own roll: it swings face-on / edge-on along its length
 let B0 = normalize(c.side - T * dot(c.side, T) + vec3f(1e-4, 0.0, 0.0));
 let D0 = cross(T, B0);
 let roll = 0.5 + 0.5 * (c.ic * c.ic - c.is * c.is);
 let ra = 1.1 + 0.4 * c.te;
 let x0 = TAU * (0.55 * s - 0.022 * c.t) + f32(j) * 1.3 + 1.7 * f32(r);
 let chi = ra * mix(sin(x0), sin(1.9 * x0 + 1.1), 0.4 * roll) + 0.9 * c.is * s;
 let W = cos(chi) * B0 - sin(chi) * D0;
 let N = cross(T, W);
 // width: narrow where it leaves the manubrium, flaring wide toward the tail, then easing to a soft tapered end
 // one of the animal's features, not its body: about half a bell radius at the widest
 let wmax = c.f.k * select(0.45 + 0.2 * h, 0.7 + 0.25 * h, isNear(j)) * (0.85 + 0.25 * c.sf);
 // the silk family: narrow where it leaves the manubrium, then a near-constant width, tapering only at the end
 let width = wmax * (0.12 + 0.88 * smoothstep(0.0, 0.2, s)) * (1.0 - 0.45 * smoothstep(0.85, 1.0, s));
 let cup = 0.2 * (4.0 * a * a - 0.33) * width;
 let flut = 0.03 * width * sin(TAU * (1.6 * s - 0.04 * c.t) + 6.0 * a + h * 6.0);
 // a soft scalloped hem at the tail: the end is not cut straight
 let scal = 0.04 * width * smoothstep(0.8, 1.0, s) * sin(TAU * (3.0 * a + 0.5 * h));
 q.position = shown(c, ctr + W * (a * width) + N * (cup + flut) + T * scal);
 q.uv = vec2f(s, a + 0.5);
 // light: fades to nothing at the tail (and at the very root); the note's glow travels down it
 let tip = 1.0 - smoothstep(0.45, 0.98, s);
 let rootF = smoothstep(0.0, 0.05, s);
 let glow = mix(c.rb, c.rc, smoothstep(0.0, 0.8, s));
 let light = 1.0 + 0.6 * glow / (1.0 + glow) * (1.0 - 0.5 * s);
 let tone = 0.42 + 0.06 * c.is + 0.04 * f32(r) + 0.06 * c.te;
 q.tint = vec4f(tone + 2.0 * round(c.fog * 20.0), 0.5 * c.gain * tip * rootF * light, s * Lt, 0.5 + 0.5 * c.ic);
 return q;
}

parameters.expressions:
flowX = swimDirX * tr;
flowY = swimDirY * tr;
flowZ = swimDirZ * tr

parameters.kernel:
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}
// ---- hero common (kernels): frame, pulse envelope, bell profile, trail ----
const TAU = 6.2831853;
// The bell in its own frame: rim radius 1, up +y, rim (margin) plane at BELL_Y0, apex BELL_H above it.
// World = hero position + rotZ(tiltZ) * rotX(tiltX) * (local * heroScale).
// A flattened dome (the boards: height/width about 0.38 for the dome, 0.45 with the lappets): the profile
// stops at 79 degrees, so the shoulders slope into the rim and never stand as a vertical wall; 16
// rounded lappets hang LAP_LEN below the rim.
const BELL_H = 0.64;
const BELL_Y0 = -0.35;
const BELL_THMAX = 1.38;
const BELL_VM = 0.9;       // exumbrella: v of the rim (ring canal); the lappets hang over VM..1
const LAP_LEN = 0.14;

struct HF { o: vec3f, ca: f32, sa: f32, cb: f32, sb: f32, k: f32, };
fn hfMake(x: f32, y: f32, z: f32, tx: f32, tz: f32, k: f32) -> HF {
 return HF(vec3f(x, y, z), cos(tx), sin(tx), cos(tz), sin(tz), k);
}
fn hfDir(f: HF, d: vec3f) -> vec3f {
 let y1 = d.y * f.ca - d.z * f.sa;
 let z1 = d.y * f.sa + d.z * f.ca;
 return vec3f(d.x * f.cb - y1 * f.sb, d.x * f.sb + y1 * f.cb, z1);
}
fn hfPos(f: HF, p: vec3f) -> vec3f { return f.o + hfDir(f, p * f.k); }

// The stroke, as a periodic function of the swim phase (the cycle is about 3.5 s): a slow full
// contraction over 30 % of it, a release over 40 %, then a 30 % glide at rest. Every geometric use of
// the swim reads this (the bell body too), so the bell and everything lagging it agree.
// the warm accent: one peach-gold for cores, canals, glints and beads in every mood
const ACC = vec3f(1.0, 0.66, 0.36);
fn smoother(a: f32, b: f32, x: f32) -> f32 {
 let t = clamp((x - a) / (b - a), 0.0, 1.0);
 return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}
fn pulseEnv(ph: f32) -> f32 {
 let x = fract(ph);
 return smoother(0.0, 0.3, x) * (1.0 - smoother(0.3, 0.7, x));
}
// A chord strike as a FORCE: the rig's strike age drives a short impulse through a chain of hero
// lag nodes; k.x (lag_herokick2) is the response at the bell, k.y (4) later and wider, k.z (5) later
// still, kS (7) a very slow mean of the same impulse. The RIPPLE is what is new: each response minus
// the slow mean, normalised so one isolated strike peaks near 1, softly limited, so a train of strikes
// does not hold the appendages splayed: each new strike still adds a travelling ripple, and the
// sustained part becomes a small, saturating STEADY opening.
fn kickRipple(k: vec3f, kS: f32) -> vec3f {
 let g = vec3f(2.0, 4.0, 5.5);
 let x = (k - vec3f(kS)) * g;
 return x / sqrt(vec3f(1.0) + x * x);
}
fn kickSteady(kS: f32) -> f32 { return 0.35 * (1.0 - exp(-2.5 * kS)); }
// positive part, smoothly (light and flares only grow)
fn softPos(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.0004)); }
// the margin flares a little with the strike (bell and tentacle roots must agree)
fn marginFlare(lp: vec3f, v: f32, k0: f32) -> vec3f {
 let g = 1.0 + 0.035 * k0 * smoothstep(0.75, 1.0, v);
 return vec3f(lp.x * g, lp.y, lp.z * g);
}

// Soft swim pressure: a raised cosine at the swim frequency, peaking with the contraction (phase 0.28).
// Lagged copies of it run down arms and tentacles as a gentle pressure wave, never a wiggle.
fn gaussK(x: f32) -> f32 { return exp(-x * x); }
// the strike ripple as felt at s along anything (0 the bell, 1 the tips), continuous in time and space
fn rippleAt(r: vec3f, s: f32) -> f32 {
 return mix(mix(r.x, r.y, smoother(0.0, 0.5, s)), r.z, smoother(0.5, 1.0, s));
}
fn pres(ph: f32) -> f32 { return 0.5 + 0.5 * cos(TAU * (ph - 0.28)); }
// Contraction felt at bell parameter v (0 apex, 1 lappet tips): the body follows pulse, the margin
// lags 0.06 of a cycle, the lappets 0.1, so the rim trails the squeeze and re-opens late.
// D is the stroke depth (fuller with louder music, set slowly).
fn bellPulseAt(v: f32, pl: f32, ph: f32, D: f32) -> f32 {
 let pm = pulseEnv(ph - 0.06) * D;
 let plap = pulseEnv(ph - 0.1) * D;
 return mix(pl, mix(pm, plap, smoothstep(0.86, 1.0, v)), smoothstep(0.55, 1.0, v));
}
fn strokeDepth(es: f32) -> f32 { return 0.75 + 0.4 * es; }

fn bellSqueeze(v: f32, pm: f32) -> f32 {
 return 1.0 - 0.2 * pm * pow(smoothstep(0.12, 1.0, v), 1.3);
}
// Exumbrella point. p: body contraction, pm: (lagged) margin contraction, te: tension.
// the dome's height profile, 1 at the apex and 0 at the rim (slightly flattened top)
fn domeY(th: f32) -> f32 {
 let cm = pow(cos(BELL_THMAX), 0.88);
 return (pow(max(cos(th), 0.0), 0.88) - cm) / (1.0 - cm);
}
fn bellExo(phi: f32, v: f32, p: f32, pm: f32, te: f32) -> vec3f {
 let vd = min(v / BELL_VM, 1.0);
 let th = vd * BELL_THMAX;
 // a contraction closes the rim and lengthens the dome a little: it stays a dome (h/w under 0.6)
 let h = BELL_H * (1.0 + 0.12 * p + 0.06 * te);
 let rib = 1.0 + 0.022 * (0.5 + 0.5 * cos(16.0 * phi)) * smoothstep(0.08, 0.5, vd) * (1.0 - smoothstep(0.8, 0.95, vd));
 let wave = (0.025 * sin(8.0 * phi + 0.7) + 0.01 * sin(13.0 * phi + 2.0)) * smoothstep(0.6, 1.0, vd);
 var r = sin(th) / sin(BELL_THMAX) * bellSqueeze(vd, pm) * rib;
 var y = BELL_Y0 - 0.04 * pm * smoothstep(0.5, 1.0, vd) + h * domeY(th);
 if (v > BELL_VM) {
  // the lappets hang from the rim: flared a little outward at rest, curled in by the squeeze
  let s = (v - BELL_VM) / (1.0 - BELL_VM);
  r = r + s * LAP_LEN * (0.45 - 0.9 * pm) * bellSqueeze(1.0, pm);
  y = y - s * LAP_LEN * (0.9 + 0.2 * pm);
 }
 return vec3f(cos(phi) * r, y + wave, sin(phi) * r);
}

// Frame-independent per-id random in [0, 1). The built-in pointRand re-rolls EVERY FRAME (it hashes the
// frame index), so it must never shape geometry: that reads as high-frequency jitter in playback.
fn stableRand(id: u32, salt: u32) -> f32 {
 var x = id * 747796405u + salt * 2891336453u + 12345u;
 x = (x ^ (x >> 15u)) * 2246822519u;
 x = (x ^ (x >> 13u)) * 3266489917u;
 x = x ^ (x >> 16u);
 return f32(x >> 8u) * (1.0 / 16777216.0);
}
// ---- hero appendages in water (shared by tentacle beams, beads and oral arms) ----
// They HANG: almost passive, a slow curtain dragged behind the swim and swaying over many seconds.
// Point s = the root on the bell (rigidly attached, in the bell's own frame) + a hanging shape
// (gravity and a slow down-left current, leaning with the path) + a slow DRAG opposite the bell's
// mean velocity, growing toward the tip. The mean velocity is taken over one swim period (the bell
// now vs where it was one period, about 1.76 s, ago), so the surge of each thrust cancels out and
// is never replayed down the appendages; it is used as a vector that shrinks to nothing as the bell
// slows (never normalised), so the trail eases back to the rest hang. Each contraction sends one
// soft, slow bulge down them; chord strikes change only their light. Nothing may rise above its
// own root along the bell's axis (keepBelow).
const NT = 48u;            // tentacles
const DRAG_T = 4.0;        // tentacles: seconds of mean drift by which a tip trails
const ARM_DRAG_T = 5.5;    // oral arms: broad veils catch more water
struct TC { f: HF, fP: HF, h0: vec3f, vbar: vec3f, droop: vec3f, side: vec3f, side2: vec3f, pl: f32, ph: f32, te: f32, de: f32, t: f32, kick: vec3f, es: f32, steady: f32, act: f32, };

// the bell's path u steps of 0.7 s ago (u in 1..3), straight between the rig's samples (no overshoot)
fn pathBack(h1: vec3f, h2: vec3f, h3: vec3f, u: f32) -> vec3f {
 if (u < 2.0) { return mix(h1, h2, clamp(u - 1.0, 0.0, 1.0)); }
 return mix(h2, h3, clamp(u - 2.0, 0.0, 1.0));
}

fn tcMake(f: HF, h1: vec3f, h2: vec3f, h3: vec3f, rate: f32, tx: f32, tz: f32, pl: f32, ph: f32, te: f32, de: f32, t: f32, kick: vec3f, es: f32, kS: f32, rl: f32) -> TC {
 // mean velocity: the least-squares slope through the four samples (now, 0.7, 1.4, 2.1 s ago), far
 // less sensitive to the surge inside a stroke than a two-point difference
 let vbar = (1.5 * f.o + 0.5 * h1 - 0.5 * h2 - 1.5 * h3) / (5.0 * 0.7);
 // the bell's own axis with the per-stroke rocking taken out: the rig leans the bell by its 0.7 s
 // velocity; swap that for the period-mean velocity (same lean law), keep everything else it does
 // (with rigLean = 1 the rig's tilt already is that smooth lean, and everything hangs along it as is)
 let v07 = (f.o - h1) / 0.7;
 let swap = select(1.0, 0.0, rl > 0.5);
 let fP = hfMake(f.o.x, f.o.y, f.o.z, tx - 0.5 * (v07.z - vbar.z) * swap, tz + 1.6 * (v07.x - vbar.x) * swap, f.k);
 // appendages hang along that axis (no sideways current of their own)
 let droop = hfDir(fP, vec3f(0.0, -1.0, 0.0));
 let side = normalize(cross(droop, vec3f(0.0, 0.0, 1.0)));
 let side2 = normalize(cross(droop, side));
 // activity: slow musical energy plus how busy the strikes have been (both eased), 0 calm .. 1 full
 let steady = kickSteady(kS);
 let act = clamp(0.75 * es + 1.2 * steady, 0.0, 1.0);
 return TC(f, fP, f.o, vbar, droop, side, side2, pl, ph, te, de, t, kickRipple(kick, kS), es, steady, act);
}
// trail opposite the mean velocity, growing toward the tip, softly limited (no normalising)
fn dragAt(c: TC, s: f32, len: f32, secs: f32) -> vec3f {
 let d = -c.vbar * secs * pow(s, 1.5);
 let limit = 0.35 * len;
 return d / sqrt(1.0 + dot(d, d) / (limit * limit));
}
// never above the root along the bell's axis: a point at s hangs at least 10 % of its arclength below
fn keepBelow(c: TC, root: vec3f, p: vec3f, s: f32, len: f32) -> vec3f {
 let up = hfDir(c.f, vec3f(0.0, 1.0, 0.0));
 let along = dot(p - root, up);
 let floorA = -0.1 * s * len;
 let w = 0.08 * len * s + 1e-4;
 let hh = clamp(0.5 + 0.5 * (floorA - along) / w, 0.0, 1.0);
 let sm = mix(floorA, along, hh) - w * hh * (1.0 - hh);
 return p + up * (sm - along);
}
fn tentPhi(ti: u32) -> f32 {
 return (f32(ti) + 0.5 + 0.55 * (stableRand(ti, 11u) - 0.5)) / f32(NT) * TAU;
}
// active share of the tentacles: about 24 at density 0, all 48 at density 1 (unused ones fade)
fn tentActive(ti: u32, de: f32) -> f32 {
 let rank = stableRand(ti, 17u);
 return 1.0 - smoothstep(0.5 + 0.5 * de - 0.06, 0.5 + 0.5 * de + 0.02, rank);
}
fn tentLength(c: TC, ti: u32) -> f32 {
 return (1.2 + 3.0 * pow(stableRand(ti, 13u), 1.4)) * (0.85 + 0.3 * c.de) * (1.0 + 0.12 * c.te) * c.f.k;
}
// the bell's contraction as felt at s along an appendage: exact at the root, then the same envelope at
// a later phase, damped (a soft pressure wave). Returns (body pulse, margin pulse, phase used).
fn pulseAlong(c: TC, s: f32) -> vec3f {
 let lagc = 0.6 * s;
 let att = exp(-1.8 * s);
 let D = strokeDepth(c.es);
 let k0 = (c.kick.x + c.steady) * att;
 let ps = min(pulseEnv(c.ph - lagc) * D * (1.0 + 0.2 * k0), 1.0) * att;
 let pm = bellPulseAt(0.9, ps, c.ph - lagc, D) * att;
 return vec3f(ps, pm, c.ph - lagc);
}
// the slow sweep of the whole hanging bundle (shared by tentacles and arms), travelling tipward
fn sweepAt(c: TC, s: f32) -> vec3f {
 let a = TAU * (0.05 * c.t - 0.35 * s);
 return (c.side * sin(a) + c.side2 * 0.5 * sin(a * 0.7 + 1.9)) * (0.12 + 0.14 * c.act) * s * s;
}
// the strike as felt at s: the bell's response at the root, later and wider responses toward the tip
fn kickAt(c: TC, s: f32) -> f32 { return rippleAt(c.kick, s) + c.steady; }
fn tentRoot(c: TC, phi: f32, s: f32) -> vec3f {
 let pa = pulseAlong(c, s);
 let k0 = (c.kick.x + c.steady) * exp(-1.8 * s);
 return hfPos(c.f, marginFlare(bellExo(phi, 0.9, pa.x, pa.y, c.te), 0.9, k0) * vec3f(0.965, 1.0, 0.965));
}
fn tentPoint(c: TC, ti: u32, s: f32) -> vec3f {
 let phi = tentPhi(ti);
 let h1 = stableRand(ti, 12u);
 let h2 = stableRand(ti, 14u);
 // root on the margin, squeezing with it (the squeeze reaches further points later and weaker)
 let anchor = tentRoot(c, phi, s);
 let outL = vec3f(cos(phi), 0.0, sin(phi));
 // one soft slow bulge per contraction, travelling down
 let pp = pres(c.ph - 0.1 - 0.6 * s);
 // loud passages open the whole curtain, quiet ones draw it in (slow)
 let spread = (0.16 + 0.2 * h1) * (0.7 + 0.7 * c.act) - 0.04 * pp;
 let d0 = hfDir(c.fP, normalize(vec3f(outL.x * spread, -1.0, outL.z * spread)));
 let len = tentLength(c, ti);
 let bendL = vec3f(cos(phi + 1.6 * (h2 - 0.5)), 0.0, sin(phi + 1.6 * (h2 - 0.5)));
 let b1 = d0 * 0.22 * len + hfDir(c.fP, bendL) * (0.04 + 0.08 * h2) * len;
 let b2 = b1 + normalize(c.droop + hfDir(c.fP, outL) * (0.05 + 0.12 * h1)) * 0.78 * len;
 var pos = anchor + 2.0 * s * (1.0 - s) * b1 + s * s * b2;
 // slow drag behind the mean swim
 pos += dragAt(c, s, len, DRAG_T * (0.8 + 0.4 * h2) * (0.8 + 0.4 * c.es));
 // always alive: a long slow undulation (about one wave every 9 s), larger when the music is fuller,
 // under a slower sweep the whole curtain shares (one every 20 s), travelling down it
 // the music shapes it through amplitude and (a little) wavelength, never its rate: calm = long lazy
 // waves, busy = fuller and livelier
 let w = TAU * ((0.55 + 0.35 * c.act) * s - 0.11 * c.t) + phi * 3.0 + h1 * 6.0;
 let amp = (0.06 + 0.1 * c.act) * len * pow(s, 1.5);
 pos += (c.side * sin(w) + c.side2 * 0.6 * cos(0.8 * w + 1.3)) * amp;
 pos += sweepAt(c, s) * len;
 // the bulge: the bundle breathes out a hair as it passes
 pos += hfDir(c.fP, outL) * 0.012 * len * sin(3.14159 * s) * pp;
 // a strike: the filaments flare outward and stretch back along the trail, as a slow wave tipward
 pos += (hfDir(c.fP, outL) * 0.7 + c.droop * 0.5) * 0.11 * len * sin(3.14159 * min(s * 1.1, 1.0) * 0.5) * kickAt(c, s);
 return keepBelow(c, tentRoot(c, phi, 0.0), pos, s, len);
}
// ---- SILK (pass 6): five DISTINCT aerial ribbons on the appendage family's closed-form base. ----
// Shared by kernel_silk, kernel_silkthreads and kernel_silkbeads; build.sh prepends the hero's
// common.wgsl and tent.common.wgsl VERBATIM, so the silk hangs, drags and undulates on the same model
// and clock as the hero's tentacles and oral arms: root rigid in the bell's frame (hfPos), hang along
// the bell's period-mean axis (c.droop), slow drag behind the mean velocity (dragAt), the shared slow
// undulation and sweep (sweepAt), the bell's strike (kickAt), keepBelow.
// What makes five separate ribbons (pass 6):
//   - roots on a fixed pentagon of radius 0.6 under the bell, ordered across the picture;
//   - each ribbon has its own LANE: a heading in the picture plane (from straight down toward the trail
//     side) that it turns into over a fixed bend, plus a slow drift in depth; the lanes fan out, wider with
//     density;
//   - each ribbon carries its own big S-curve (wavelength 9 to 18 bell radii), with its own phase; chord
//     tones lock to the chord's phase, thirds sit half a wave off it so they cross the root's ribbon and
//     pass in front of / behind it (a braid), the others run free;
//   - curvature budget: S amplitude is a fixed fraction of its wavelength and the width is capped at half a
//     bell diameter, so no ribbon folds over its own edge (no cusps, no hood);
//   - the width faces the camera at the root and rolls at most a half turn per 7 bell radii.
// The READABLE music layer (unchanged in kind): one swell per strike rolls down that voice's ribbon
// (sideways, wider, brighter); slow activity sets the S size and wavelength; density the lit length,
// width and the fan. Every temporal frequency is a constant.

struct Params {
 lum: f32, // @default 0.5 Rig illumination 0.12..1 (light only).
 mood: f32, // @default 0 Rig palette position 0..4 (colour only).
 hit: f32, // @default 0 Rig chord-strike pulse, continuous (light only).
 pulsePhase: f32, // @default 0 Rig swim phase 0..1 (the stroke felt along the silk, as in the hero's appendages).
 swimRate: f32, // @default 0.567 Rig swim cycles per second.
 heroX: f32, // @default 1.1 Rig hero X.
 heroY: f32, // @default 1.45 Rig hero Y.
 heroZ: f32, // @default 0 Rig hero Z.
 tiltX: f32, // @default 0 Rig heroTiltX.
 tiltZ: f32, // @default -0.22 Rig heroTiltZ.
 scale: f32, // @default 1 Rig heroScale.
 heroX1: f32, // @default 1.1 Rig: hero X 0.7 s ago.
 heroY1: f32, // @default 1.45 Rig: hero Y 0.7 s ago.
 heroZ1: f32, // @default 0 Rig: hero Z 0.7 s ago.
 heroX2: f32, // @default 1.1 Rig: hero X 1.4 s ago.
 heroY2: f32, // @default 1.45 Rig: hero Y 1.4 s ago.
 heroZ2: f32, // @default 0 Rig: hero Z 1.4 s ago.
 heroX3: f32, // @default 1.1 Rig: hero X 2.1 s ago.
 heroY3: f32, // @default 1.45 Rig: hero Y 2.1 s ago.
 heroZ3: f32, // @default 0 Rig: hero Z 2.1 s ago.
 tension: f32, // @default 0.3 Slow tension (lag_heroslow2), as the hero's appendages.
 energyS: f32, // @default 0.5 Slow energy (lag_heroslow2): undulation size, as the hero's appendages.
 density: f32, // @default 0.5 Density through the silk's own 2nd-order lag (lag_silkid gD, ~4 s): presence, width, lit length.
 act: f32, // @default 0.2 Slow note activity: the mean voice envelope through lag_silkid (~4 s): undulation fullness.
 kick0: f32, // @default 0 The bell's strike force at the root (lag_herokick2 imp x 0.2), shared with every appendage.
 kick1: f32, // @default 0 Bell strike force mid-length (lag_herokick4 imp x 0.2).
 kick2: f32, // @default 0 Bell strike force at the tip (lag_herokick5 imp).
 kickS: f32, // @default 0 Steady strike activity (lag_herokick7 imp), as the hero's appendages.
 rigLean: f32, // @default 1 As the hero (hero pass 5): 1 = the rig's tilt already is the smooth travel lean; hang along it.
 rootC: f32, // @default 1 Chord root on the circle of fifths, cosine (lag_silkid).
 rootS: f32, // @default 0 Chord root, fifths sine (lag_silkid).
 rootCS: f32, // @default 1 Chord root, fifths cosine, slow (lag_silkidslow): the far half.
 rootSS: f32, // @default 0 Chord root, fifths sine, slow.
 id0c: f32, // @default 1 Voice 0 pitch class on the circle of fifths, cosine (lag_silkid).
 id0s: f32, // @default 0 Voice 0 fifths sine.
 anchor0: f32, // @default 1 Voice 0 role: rides the chord's character.
 mirror0: f32, // @default 0 Voice 0 role: mirrors it (fifth).
 braid0: f32, // @default 0 Voice 0 role: braids with it (third).
 fan0: f32, // @default 0 Voice 0 role: sideways lean.
 need0: f32, // @default 0.3 Voice 0 role: density at which its ribbon enters (lag_silkidslow).
 glow0: f32, // @default 0 Voice 0 note light (lag_silkglow then lag_silkglow2: S-shaped onset, long release).
 sa0: f32, // @default 0 Voice 0 strike swell at the root (lag_compimp3 k0: peak ~0.8 s).
 sb0: f32, // @default 0 Voice 0 strike swell, a quarter down (lag_compimp5 k0: ~1.6 s).
 sc0: f32, // @default 0 Voice 0 strike swell, half way (lag_silkswell2 k0: ~3.6 s).
 sd0: f32, // @default 0 Voice 0 strike swell near the tip (lag_silkswell4 k0: ~5.6 s).
 id0cS: f32, // @default 1 Voice 0 fifths cosine, slow.
 id0sS: f32, // @default 0 Voice 0 fifths sine, slow.
 anchor0S: f32, // @default 1 Voice 0 anchor, slow.
 mirror0S: f32, // @default 0 Voice 0 mirror, slow.
 braid0S: f32, // @default 0 Voice 0 braid, slow.
 fan0S: f32, // @default 0 Voice 0 lean, slow.
 id1c: f32, // @default 1 Voice 1 pitch class on the circle of fifths, cosine (lag_silkid).
 id1s: f32, // @default 0 Voice 1 fifths sine.
 anchor1: f32, // @default 1 Voice 1 role: rides the chord's character.
 mirror1: f32, // @default 0 Voice 1 role: mirrors it (fifth).
 braid1: f32, // @default 0 Voice 1 role: braids with it (third).
 fan1: f32, // @default 0 Voice 1 role: sideways lean.
 need1: f32, // @default 0.3 Voice 1 role: density at which its ribbon enters (lag_silkidslow).
 glow1: f32, // @default 0 Voice 1 note light (lag_silkglow then lag_silkglow2: S-shaped onset, long release).
 sa1: f32, // @default 0 Voice 1 strike swell at the root (lag_compimp3 k1: peak ~0.8 s).
 sb1: f32, // @default 0 Voice 1 strike swell, a quarter down (lag_compimp5 k1: ~1.6 s).
 sc1: f32, // @default 0 Voice 1 strike swell, half way (lag_silkswell2 k1: ~3.6 s).
 sd1: f32, // @default 0 Voice 1 strike swell near the tip (lag_silkswell4 k1: ~5.6 s).
 id1cS: f32, // @default 1 Voice 1 fifths cosine, slow.
 id1sS: f32, // @default 0 Voice 1 fifths sine, slow.
 anchor1S: f32, // @default 1 Voice 1 anchor, slow.
 mirror1S: f32, // @default 0 Voice 1 mirror, slow.
 braid1S: f32, // @default 0 Voice 1 braid, slow.
 fan1S: f32, // @default 0 Voice 1 lean, slow.
 id2c: f32, // @default 1 Voice 2 pitch class on the circle of fifths, cosine (lag_silkid).
 id2s: f32, // @default 0 Voice 2 fifths sine.
 anchor2: f32, // @default 1 Voice 2 role: rides the chord's character.
 mirror2: f32, // @default 0 Voice 2 role: mirrors it (fifth).
 braid2: f32, // @default 0 Voice 2 role: braids with it (third).
 fan2: f32, // @default 0 Voice 2 role: sideways lean.
 need2: f32, // @default 0.3 Voice 2 role: density at which its ribbon enters (lag_silkidslow).
 glow2: f32, // @default 0 Voice 2 note light (lag_silkglow then lag_silkglow2: S-shaped onset, long release).
 sa2: f32, // @default 0 Voice 2 strike swell at the root (lag_compimp3 k2: peak ~0.8 s).
 sb2: f32, // @default 0 Voice 2 strike swell, a quarter down (lag_compimp5 k2: ~1.6 s).
 sc2: f32, // @default 0 Voice 2 strike swell, half way (lag_silkswell2 k2: ~3.6 s).
 sd2: f32, // @default 0 Voice 2 strike swell near the tip (lag_silkswell4 k2: ~5.6 s).
 id2cS: f32, // @default 1 Voice 2 fifths cosine, slow.
 id2sS: f32, // @default 0 Voice 2 fifths sine, slow.
 anchor2S: f32, // @default 1 Voice 2 anchor, slow.
 mirror2S: f32, // @default 0 Voice 2 mirror, slow.
 braid2S: f32, // @default 0 Voice 2 braid, slow.
 fan2S: f32, // @default 0 Voice 2 lean, slow.
 id3c: f32, // @default 1 Voice 3 pitch class on the circle of fifths, cosine (lag_silkid).
 id3s: f32, // @default 0 Voice 3 fifths sine.
 anchor3: f32, // @default 1 Voice 3 role: rides the chord's character.
 mirror3: f32, // @default 0 Voice 3 role: mirrors it (fifth).
 braid3: f32, // @default 0 Voice 3 role: braids with it (third).
 fan3: f32, // @default 0 Voice 3 role: sideways lean.
 need3: f32, // @default 0.3 Voice 3 role: density at which its ribbon enters (lag_silkidslow).
 glow3: f32, // @default 0 Voice 3 note light (lag_silkglow then lag_silkglow2: S-shaped onset, long release).
 sa3: f32, // @default 0 Voice 3 strike swell at the root (lag_compimp3 k3: peak ~0.8 s).
 sb3: f32, // @default 0 Voice 3 strike swell, a quarter down (lag_compimp5 k3: ~1.6 s).
 sc3: f32, // @default 0 Voice 3 strike swell, half way (lag_silkswell2 k3: ~3.6 s).
 sd3: f32, // @default 0 Voice 3 strike swell near the tip (lag_silkswell4 k3: ~5.6 s).
 id3cS: f32, // @default 1 Voice 3 fifths cosine, slow.
 id3sS: f32, // @default 0 Voice 3 fifths sine, slow.
 anchor3S: f32, // @default 1 Voice 3 anchor, slow.
 mirror3S: f32, // @default 0 Voice 3 mirror, slow.
 braid3S: f32, // @default 0 Voice 3 braid, slow.
 fan3S: f32, // @default 0 Voice 3 lean, slow.
 id4c: f32, // @default 1 Voice 4 pitch class on the circle of fifths, cosine (lag_silkid).
 id4s: f32, // @default 0 Voice 4 fifths sine.
 anchor4: f32, // @default 1 Voice 4 role: rides the chord's character.
 mirror4: f32, // @default 0 Voice 4 role: mirrors it (fifth).
 braid4: f32, // @default 0 Voice 4 role: braids with it (third).
 fan4: f32, // @default 0 Voice 4 role: sideways lean.
 need4: f32, // @default 0.3 Voice 4 role: density at which its ribbon enters (lag_silkidslow).
 glow4: f32, // @default 0 Voice 4 note light (lag_silkglow then lag_silkglow2: S-shaped onset, long release).
 sa4: f32, // @default 0 Voice 4 strike swell at the root (lag_compimp3 k4: peak ~0.8 s).
 sb4: f32, // @default 0 Voice 4 strike swell, a quarter down (lag_compimp5 k4: ~1.6 s).
 sc4: f32, // @default 0 Voice 4 strike swell, half way (lag_silkswell2 k4: ~3.6 s).
 sd4: f32, // @default 0 Voice 4 strike swell near the tip (lag_silkswell4 k4: ~5.6 s).
 id4cS: f32, // @default 1 Voice 4 fifths cosine, slow.
 id4sS: f32, // @default 0 Voice 4 fifths sine, slow.
 anchor4S: f32, // @default 1 Voice 4 anchor, slow.
 mirror4S: f32, // @default 0 Voice 4 mirror, slow.
 braid4S: f32, // @default 0 Voice 4 braid, slow.
 fan4S: f32, // @default 0 Voice 4 lean, slow.
};

const PI: f32 = 3.14159265;
// study switches (build.sh SILK_OFF="DRAG S ..." sets them to 0 in a -dbg copy); all 1 in the real build
const SILK_K_DRAG: f32 = 1.0;
const SILK_K_SWAY: f32 = 1.0;
const SILK_K_S: f32 = 1.0;
const SILK_K_FLOOR: f32 = 1.0;
const SILK_K_DEPTH: f32 = 1.0;
const SILK_COLS: u32 = 288u;
const SILK_ROWS: u32 = 12u;

struct Voice { c: f32, s: f32, anchor: f32, mirror: f32, braid: f32, fan: f32, };

fn silkVoice(P: Params, v: u32) -> Voice {
 if (v == 0u) { return Voice(P.id0c, P.id0s, P.anchor0, P.mirror0, P.braid0, P.fan0); }
 if (v == 1u) { return Voice(P.id1c, P.id1s, P.anchor1, P.mirror1, P.braid1, P.fan1); }
 if (v == 2u) { return Voice(P.id2c, P.id2s, P.anchor2, P.mirror2, P.braid2, P.fan2); }
 if (v == 3u) { return Voice(P.id3c, P.id3s, P.anchor3, P.mirror3, P.braid3, P.fan3); }
 return Voice(P.id4c, P.id4s, P.anchor4, P.mirror4, P.braid4, P.fan4);
}
fn silkVoiceS(P: Params, v: u32) -> Voice {
 if (v == 0u) { return Voice(P.id0cS, P.id0sS, P.anchor0S, P.mirror0S, P.braid0S, P.fan0S); }
 if (v == 1u) { return Voice(P.id1cS, P.id1sS, P.anchor1S, P.mirror1S, P.braid1S, P.fan1S); }
 if (v == 2u) { return Voice(P.id2cS, P.id2sS, P.anchor2S, P.mirror2S, P.braid2S, P.fan2S); }
 if (v == 3u) { return Voice(P.id3cS, P.id3sS, P.anchor3S, P.mirror3S, P.braid3S, P.fan3S); }
 return Voice(P.id4cS, P.id4sS, P.anchor4S, P.mirror4S, P.braid4S, P.fan4S);
}
fn silkStrikeTaps(P: Params, v: u32) -> vec4f {
 if (v == 0u) { return vec4f(P.sa0, P.sb0, P.sc0, P.sd0); }
 if (v == 1u) { return vec4f(P.sa1, P.sb1, P.sc1, P.sd1); }
 if (v == 2u) { return vec4f(P.sa2, P.sb2, P.sc2, P.sd2); }
 if (v == 3u) { return vec4f(P.sa3, P.sb3, P.sc3, P.sd3); }
 return vec4f(P.sa4, P.sb4, P.sc4, P.sd4);
}
fn silkGlow(P: Params, v: u32) -> f32 {
 if (v == 0u) { return P.glow0; }
 if (v == 1u) { return P.glow1; }
 if (v == 2u) { return P.glow2; }
 if (v == 3u) { return P.glow3; }
 return P.glow4;
}
fn mixVoice(a: Voice, b: Voice, t: f32) -> Voice {
 return Voice(mix(a.c, b.c, t), mix(a.s, b.s, t), mix(a.anchor, b.anchor, t), mix(a.mirror, b.mirror, t),
  mix(a.braid, b.braid, t), mix(a.fan, b.fan, t));
}

// THE FINGERPRINT GRAMMAR. A pitch class sits on the circle of fifths at angle th (C = 0, G = 30 deg, ...),
// handed in as (c, s) = (cos th, sin th) through slow lags, so a new note cross-fades. Traits are
// low-order trigonometric polynomials of th, so neighbours are related:
//  c  (1st): openness. F C G: long open S-curves; B F# C#: shorter, curlier S-curves.
//  s  (1st): hand. The S-curve's corkscrew: sharp side right-handed, flat side left-handed, C planar.
//  c2 (2nd): roll. C, F# roll face-on/edge-on more; A, Eb hold their face.
//  s2 (2nd): lilt: a long-short skew in the S-curve.
//  c3 (3rd): texture (material): thread fineness and glint spacing.
struct Char { hand: f32, coil: f32, roll: f32, lilt: f32, phase: f32, tex: f32, };
fn silkChar(c: f32, s: f32) -> Char {
 let c2 = c * c - s * s;
 let s2 = 2.0 * c * s;
 let c3 = c * (c * c - 3.0 * s * s);
 return Char(s, clamp(0.5 - 0.5 * c, 0.0, 1.0), 0.5 + 0.5 * c2, 0.5 * s2, 1.7 * c + 2.3 * s, 0.5 + 0.5 * c3);
}
fn mixChar(a: Char, b: Char, t: f32) -> Char {
 return Char(mix(a.hand, b.hand, t), mix(a.coil, b.coil, t), mix(a.roll, b.roll, t), mix(a.lilt, b.lilt, t),
  mix(a.phase, b.phase, t), mix(a.tex, b.tex, t));
}

// The character a voice's silk wears at s: its own, or the chord's (the root's) by its role, mirrored for
// the fifth; the near half reads the lag_silkid targets, the far half the slower ones.
fn silkCharAt(P: Params, v: u32, s: f32) -> Char {
 let w = smoothstep(0.2, 0.9, s);
 let V = mixVoice(silkVoice(P, v), silkVoiceS(P, v), w);
 let own = silkChar(V.c, V.s);
 var rc = silkChar(mix(P.rootC, P.rootCS, w), mix(P.rootS, P.rootSS, w));
 let ms = 1.0 - 2.0 * clamp(V.mirror, 0.0, 1.0);
 rc.hand = rc.hand * ms; rc.lilt = rc.lilt * ms;
 return mixChar(own, rc, clamp(V.anchor, 0.0, 1.0));
}

// Roots: a fixed regular pentagon of radius 0.6 under the bell, numbered so a root's place across the
// picture (bell-local -x is the trail side) matches its lane: no two ribbons cross at the bell.
fn silkRootAngle(v: u32) -> f32 {
 var a = array<f32, 5>(1.5708, -0.9425, -2.1991, 0.3142, 2.8274);
 return a[v];
}
fn silkRootLocal(v: u32) -> vec3f {
 let psi = silkRootAngle(v);
 return vec3f(cos(psi) * 0.6, BELL_Y0 + 0.02, sin(psi) * 0.6);
}
fn silkRoot(c: TC, v: u32) -> vec3f { return hfPos(c.f, silkRootLocal(v)); }

// A ribbon's lane, one per ribbon (read at a fixed mix of the near and far lags, so it is constant along
// the ribbon): the heading it hangs from (th0) and turns into (thf) in the picture plane, measured from the
// bell's period-mean axis toward the trail side; its drift in depth; the hang's outward lean; its role.
//   root: its own lane, the chord's phase.          fifth: lane pulled toward the column, mirrored hand.
//   thirds: lane pulled toward the middle, the chord's phase plus half a wave: they cross the root's ribbon.
//   sevenths, extensions: lane opened outward and toward the camera, their own phase.
//   tensions: lane pulled inward, flare in depth, their own phase.
struct Lane { th0: f32, thf: f32, depth: f32, lean: f32, spread: f32, braid: f32, flare: f32, third: f32, reach: f32, mir: f32, };
fn silkLane(P: Params, c: TC, v: u32) -> Lane {
 let V = mixVoice(silkVoice(P, v), silkVoiceS(P, v), 0.6);
 let own = silkChar(V.c, V.s);
 let rc = silkChar(mix(P.rootC, P.rootCS, 0.6), mix(P.rootS, P.rootSS, 0.6));
 let mir = clamp(V.mirror, 0.0, 1.0);
 let anc = clamp(V.anchor, 0.0, 1.0);
 let br = clamp(V.braid, 0.0, 1.0);
 let flare = 1.0 - anc;
 let rh = rc.hand * (1.0 - 2.0 * mir);
 let fixed = -cos(silkRootAngle(v));            // -0.95 .. 0.95 across the picture
 let h = stableRand(v, 71u);
 let reach = smoothstep(0.1, 0.8, P.density);
 let laneRaw = fixed * (1.0 - 0.5 * br) + 0.5 * V.fan - 0.6 * mir + 0.4 * flare * own.hand;
 // calm: about 9 deg from the axis (a lazy S hanging down-left), peak about 30 deg, fanned to +-29 deg (the
 // bell's own lean adds about 20 deg on screen: down-left, as the boards); a slow
 // whole-ribbon gesture (0.045 Hz)
 let thb = 0.15 + 0.37 * reach + tanh(laneRaw / 1.2) * (0.15 + 0.35 * reach) + 0.08 * sin(TAU * 0.045 * c.t + 6.0 * h);
 // soft ceiling at about 50 deg: the far part keeps going down the bell axis, its S-curve never lifts it
 // above the margin (the upper left stays empty)
 let e = max(thb - 0.8, 0.0);
 let thf = thb - e + 0.12 * tanh(e / 0.12);
 // the ribbons already fan as they leave the bell (a third of the way to their lane, spread by it)
 let th0 = 0.3 * thf + 0.1 * tanh(laneRaw / 1.2);
 let depthRaw = -0.35 + 0.25 * rh + 0.6 * V.fan - 0.9 * mir * (0.35 + 0.25 * rh) + 0.8 * flare * own.hand + 0.5 * fixed;
 let depth = 0.3 * tanh(depthRaw / 1.2) * (0.5 + 0.5 * reach);
 let leanRaw = 0.55 * V.fan + 0.6 * flare * own.hand + 0.35 * mir;
 return Lane(th0, thf, depth, 0.8 * tanh(leanRaw / 0.8), 0.1 + 0.1 * flare + 0.06 * P.density, br, flare,
  smoothstep(0.4, 0.9, br), reach, mir);
}

// The lane's centre line in closed form: straight along th0 to xb0, a constant-curvature bend of fixed
// length Lb into thf, then straight (position and heading continuous; the bend's curvature is the angle
// over Lb, at most 0.3 per bell radius). Returned as (along the axis, toward the trail side).
fn headInt(th0: f32, k: f32, u: f32) -> vec2f {
 let hu = 0.5 * k * u;
 let sc = select(sin(hu) / hu, 1.0 - hu * hu / 6.0, abs(hu) < 1e-3);
 return u * sc * vec2f(cos(th0 + hu), sin(th0 + hu));
}
fn silkLaneXY(L: Lane, x: f32, xb0: f32, Lb: f32) -> vec2f {
 let k = (L.thf - L.th0) / Lb;
 let u1 = min(x, xb0);
 let u2 = clamp(x - xb0, 0.0, Lb);
 let u3 = max(x - xb0 - Lb, 0.0);
 return u1 * vec2f(cos(L.th0), sin(L.th0)) + headInt(L.th0, k, u2) + u3 * vec2f(cos(L.thf), sin(L.thf));
}
fn silkHeadAngle(L: Lane, x: f32, xb0: f32, Lb: f32) -> f32 { return L.th0 + (L.thf - L.th0) * clamp((x - xb0) / Lb, 0.0, 1.0); }

// Presence by harmonic role (melody first, then root, third, fifth, seventh, extensions, tensions).
fn silkPresence(P: Params, v: u32) -> f32 {
 var need = array<f32, 5>(P.need0 - 0.1, P.need1, P.need2, P.need3, -0.2);
 let t = need[v];
 return smoothstep(t, t + 0.3, P.density);
}

// The geometric length is fixed (scaled with the bell); density decides how much of it is lit, so the tip
// never retracts. Lit length in bell radii: calm 10, medium about 14, peak about 17. Never a stub.
fn silkLen(P: Params) -> f32 { return 17.5 * P.scale; }
fn silkLitLen(P: Params, pres: f32) -> f32 { return P.scale * (10.0 + 7.0 * pow(max(P.density, 1e-4), 0.9)) * (0.85 + 0.15 * pres); }
fn silkLit(P: Params, pres: f32) -> f32 { return min(silkLitLen(P, pres) / silkLen(P), 1.0); }

// A voice's strike as felt at s: the four response taps blended down the ribbon (each later and
// wider), normalised to about 1 per strike near the root and fading with distance; soft-saturated.
fn silkSwell(P: Params, v: u32, s: f32) -> f32 {
 let u = s / max(silkLit(P, silkPresence(P, v)), 0.15);
 let k = silkStrikeTaps(P, v) * vec4f(1.5, 1.9, 3.2, 4.2);
 var x = k.x;
 x = mix(x, k.y, smoother(0.06, 0.25, u));
 x = mix(x, k.z, smoother(0.25, 0.5, u));
 x = mix(x, k.w, smoother(0.5, 0.85, u));
 x = x * (1.0 - 0.25 * min(u, 1.0)) * smoothstep(0.0, 0.08, u);
 return x / (1.0 + 0.8 * x);
}

// The ribbon's width at s: gathered at the root, constant from 10 to 85 % of the lit length, tapering
// to nothing by 110 % (and by the geometry's end). Grows with density and presence, a little with the
// swell, softly capped at half a bell diameter (a band, never a balloon).
fn silkWidth(P: Params, v: u32, s: f32, pres: f32, sw: f32) -> f32 {
 var wv = array<f32, 5>(1.1, 0.85, 0.95, 0.9, 1.2);
 let u = s / silkLit(P, pres);
 let x = s * silkLen(P);
 let raw = (0.3 + 0.65 * P.density) * P.scale * wv[v] * (0.4 + 0.6 * pres) * pres * (1.0 + 0.35 * sw);
 let cap = 1.0 * P.scale;
 let r = raw / cap;
 let wf = cap * r / sqrt(sqrt(1.0 + r * r * r * r));
 let prof = mix(0.2, 1.0, smoother(0.0, 1.0, x / (1.2 * P.scale))) * (1.0 - smoother(0.85, 1.1, u)) * (1.0 - smoothstep(0.85, 1.0, s));
 return wf * prof;
}

// The silk's centre line at s (0 root .. 1 tip) for voice v and its lane L.
fn silkSpineL(P: Params, c: TC, L: Lane, v: u32, s: f32, len: f32) -> vec3f {
 let psi = silkRootAngle(v);
 let h = stableRand(v, 71u);
 let ch = silkCharAt(P, v, s);
 let x = s * len;
 let near = min(len, 7.0 * P.scale);
 // the family's own 0..1 along the hang, saturating SMOOTHLY (zero slope where it reaches 1): a hard
 // min() here put a knee in the silk where the drag, sway and sweep stop growing
 let un = min(x / (1.3 * near), 1.0);
 let sn = un * (2.0 - un);
 let xb0 = 0.3 * P.scale;
 let Lb = 2.8 * P.scale;
 // the lane: down the period-mean axis, turning toward the trail side, drifting in depth; the hang
 // leans a little outward from its root
 let b = silkLaneXY(L, x, xb0, Lb);
 let outL = vec3f(cos(psi + L.lean), 0.0, sin(psi + L.lean));
 let xo = 1.5 * P.scale;
 var pos = silkRoot(c, v) + c.droop * b.x + c.side * b.y + c.side2 * (L.depth * x * smoother(0.02, 0.35, s) * SILK_K_DEPTH)
  + hfDir(c.fP, outL) * (L.spread * xo * tanh(x / xo));
 // drag, undulation and sweep, as the hero's appendages (on the hang's own scale)
 // (the silk trails behind the swim but does not float up when the bell sinks: most of the drag's
 // upward part along the period-mean axis is taken out, smoothly)
 // (at calm the long silk trails at about half the drag, so the calm trail hangs rather than streams)
 var dr = dragAt(c, sn, near, ARM_DRAG_T * 1.1 * (0.85 + 0.3 * h) * (0.8 + 0.4 * c.es)) * (0.55 + 0.45 * L.reach + 0.5 * L.reach * smoother(0.3, 1.0, s));
 dr = dr + c.droop * (0.85 * softPos(-dot(dr, c.droop)));
 pos += dr * SILK_K_DRAG;
 let sway = normalize(c.side * cos(psi + h) + c.side2 * sin(psi + h));
 let sway2 = normalize(cross(c.droop, sway));
 let w = TAU * (0.5 * sn - 0.09 * c.t) + psi * 1.7 + h * 5.0;
 let amp = (0.08 + 0.06 * c.es) * near * pow(sn, 1.3);
 pos += ((sway * sin(w) + sway2 * 0.5 * cos(0.8 * w + 0.6)) * amp + sweepAt(c, sn) * near) * SILK_K_SWAY;
 // the ribbon's own big S-curve, across its lane in the picture plane and (by its hand) in depth: a
 // corkscrew whose handedness is the note's. Amplitude a share of the wavelength, 8 % calm to 18 % busy (the curvature
 // budget). Busy notes: fuller, shorter waves; calm: long lazy ones. Never the temporal frequency.
 let env = smoother(0.0, 4.5 * P.scale, x);
 let busy = clamp(0.5 * P.act + 0.2 * P.energyS + 0.3 * c.act, 0.0, 1.0);
 let vf = f32(v) - 2.0;
 let lam = mix(15.0, 10.5, ch.coil) * P.scale * (1.1 - 0.25 * busy) * (1.0 + 0.06 * vf * (1.0 - L.braid));
 // phases: chord tones lock to the chord's phase (the fifth a quarter wave on, thirds half a wave: they
 // cross the root's ribbon), the rest run free; a small fixed offset per ribbon so none run parallel
 let ph = 0.8 * ch.phase + 0.6 * vf + (0.7 * vf + 2.0 * h) * L.flare + PI * L.third + 0.5 * PI * L.mir;
 let ws = TAU * (x / lam - 0.04 * c.t) + ph;
 let th = silkHeadAngle(L, x, xb0, Lb);
 let nS = c.side * cos(th) - c.droop * sin(th);
 let As = (0.08 + 0.1 * busy) * lam * env * SILK_K_S;
 let hd = tanh(1.5 * ch.hand);
 let Ad = (0.04 + 0.06 * abs(hd)) * lam * env * SILK_K_S;
 pos += nS * (As * (sin(ws) + 0.2 * ch.lilt * sin(2.0 * ws + 0.9)));
 pos += c.side2 * (Ad * (0.85 * hd * cos(ws) + 0.45 * sin(0.7 * ws + 1.3 + 4.0 * h)));
 // the bell's own strike, felt as by every appendage
 pos += (hfDir(c.fP, outL) * 0.7 + c.droop * 0.5) * 0.08 * near * sin(PI * sn * 0.5) * kickAt(c, sn);
 // this voice's strike: one swell rolling down its ribbon, across its lane and in depth, growing with
 // distance from the root so it reads all the way down
 let sw = silkSwell(P, v, s);
 pos += (nS * 0.55 + c.side2 * 0.8) * ((0.25 + 0.045 * x / P.scale) * P.scale * sw);
 // the silk's own floor, softer and deeper than the family's: a point hangs at least 30 % of its arc
 // length below its root along the bell's axis (rarely reached; it only flattens a crest)
 return mix(pos, keepBelow(c, silkRoot(c, v), pos, s, 3.0 * len), SILK_K_FLOOR);
}
fn silkSpine(P: Params, c: TC, v: u32, s: f32, len: f32) -> vec3f { return silkSpineL(P, c, silkLane(P, c, v), v, s, len); }

// minimal rotation carrying a vector from direction a to direction T
fn silkCarryA(a: vec3f, T: vec3f, v: vec3f) -> vec3f {
 let k = cross(a, T);
 let co = dot(a, T);
 return v + cross(k, v) + cross(k, cross(k, v)) / max(1.0 + co, 0.05);
}

fn silkTC(P: Params, t: f32) -> TC {
 let f = hfMake(P.heroX, P.heroY, P.heroZ, P.tiltX, P.tiltZ, P.scale);
 return tcMake(f, vec3f(P.heroX1, P.heroY1, P.heroZ1), vec3f(P.heroX2, P.heroY2, P.heroZ2), vec3f(P.heroX3, P.heroY3, P.heroZ3),
  P.swimRate, P.tiltX, P.tiltZ, pulseEnv(P.pulsePhase), P.pulsePhase, P.tension, P.density, t, vec3f(P.kick0, P.kick1, P.kick2), P.energyS, P.kickS, P.rigLean);
}

// The silk's frame at s, unrolled: position, tangent, and the width direction: across the lane in the
// picture plane (the ribbon shows its face), carried onto the true tangent by the minimal rotation from
// the lane's heading (never more than about 60 deg apart, so it never flips).
struct SFr { p: vec3f, t: vec3f, w: vec3f, n: vec3f, };
fn silkFrame0(P: Params, c: TC, v: u32, s: f32, len: f32) -> SFr {
 let L = silkLane(P, c, v);
 let ds = 0.01;
 let p = silkSpineL(P, c, L, v, s, len);
 let T = normalize(silkSpineL(P, c, L, v, min(s + ds, 1.0), len) - silkSpineL(P, c, L, v, max(s - ds, 0.0), len) + vec3f(0.0, -1e-5, 0.0));
 let th = silkHeadAngle(L, s * len, 0.3 * P.scale, 2.8 * P.scale);
 let Hb = c.droop * cos(th) + c.side * sin(th);
 let nS = c.side * cos(th) - c.droop * sin(th);
 let wc = silkCarryA(Hb, T, nS);
 let W0 = normalize(wc - T * dot(wc, T));
 return SFr(p, T, W0, cross(T, W0));
}
// ... and rolled: a half turn per 6 to 10 bell radii at peak, 4 to 6.5 for the narrow calm band (rolling
// notes and tension roll faster), so an edge-on passage always spans at least 0.75 bell radius of length
// (about 0.4 bell diameter: no pinch), plus a slow drift; zero at the root
fn silkFrame(P: Params, c: TC, v: u32, s: f32, len: f32) -> SFr {
 let F = silkFrame0(P, c, v, s, len);
 let ch = silkCharAt(P, v, s);
 let h = stableRand(v, 71u);
 let tw = PI * s * len / (mix(10.0, 6.0, clamp(0.6 * ch.roll + 0.4 * P.tension, 0.0, 1.0)) * (0.65 + 0.35 * P.density) * P.scale) * smoother(0.0, 0.2, s) + 0.35 * sin(0.25 * c.t + h * 6.0) * s;
 let Wd = F.w * cos(tw) + F.n * sin(tw);
 return SFr(F.p, F.t, Wd, cross(F.t, Wd));
}

// A soft breath of light down the silk with each stroke (periodic in the swim phase only).
fn silkBreath(P: Params, s: f32) -> f32 { return pres(P.pulsePhase - 0.12 - 0.6 * s) * smoothstep(0.05, 0.3, s); }

// A filament: tied to its ribbon by a FIXED offset in the ribbon's UNROLLED frame (the roll would wind
// it round the spine and kink it), an edge side and a peel that grows smoothly with arc length.
fn silkThreadPos(P: Params, c: TC, v: u32, j: u32, s: f32, len: f32, pres: f32) -> vec3f {
 let F = silkFrame0(P, c, v, s, len);
 let side = select(-1.0, 1.0, j == 0u);
 let wd = silkWidth(P, v, s, pres, 0.0);
 let peel = (0.2 + 0.18 * f32(j)) * P.scale * smoother(0.05, 0.6, s);
 let off = F.w * side * (0.45 * wd + peel) + F.n * 0.18 * P.scale * smoother(0.1, 0.6, s) * sin(TAU * (s * len / (8.0 * P.scale) - 0.05 * c.t) + f32(j) * 2.0 + f32(v));
 return keepBelow(c, silkRoot(c, v), F.p + off, s, len);
}
fn silkThreadSpan(j: u32) -> vec2f { return vec2f(0.03 + 0.03 * f32(j), 0.8 + 0.08 * f32(j)); }
// ---- kernel_silkbeads: three small beads drifting tipward along each filament (points: size, tint). ----
fn process(p: Point, ctx: PointCtx) -> Point {
 var q = p;
 let P = ctx.params;
 let fil = min(ctx.index / 3u, 9u);
 let m = ctx.index % 3u;
 let v = min(fil / 2u, 4u);
 let j = fil % 2u;
 let c = silkTC(P, ctx.absTime);
 let len = silkLen(P);
 let presence = silkPresence(P, v);
 let sp = silkThreadSpan(j);
 let u = fract(0.333 * f32(m) + 0.618 * f32(fil) + ctx.absTime * 0.02 * (1.0 + 0.25 * f32(m)));
 let s = mix(sp.x, sp.y, u);
 q.position = silkThreadPos(P, c, v, j, s, len, presence);
 let lit = silkLit(P, presence) * (1.0 + 0.1 * f32(j));
 let fade = smoothstep(0.05, 0.2, u) * (1.0 - smoothstep(0.75, 0.95, u)) * (1.0 - smoothstep(0.55, 0.95, s / lit));
 let tw = 0.75 + 0.25 * sin(ctx.absTime * (0.9 + 0.37 * f32(m)) + 2.0 * f32(fil));
 // the fixed warm accent (peach-gold, #ffc890): the same in every mood
 let col = vec3f(1.0, 0.784, 0.565);
 q.tint = vec4f(col * presence * fade * tw * (0.3 + 0.8 * P.lum), 2.4);
 // a size hierarchy: one larger glassy bead per thread, two small ones
 var sz = array<f32, 3>(1.3, 0.6, 0.45);
 q.size = sz[m] * (0.7 + 0.4 * P.density);
 return q;
}

