// ---- companion common (kernels): frame, pulse, bell profile, one companion's state ----
// Derived from the hero's common.wgsl (same species, same bell profile), simplified.
// Nine companions j, each following a harmony voice (VOICE in tools/gen.py), each at its own depth from the
// camera (4.5 to 26, continuous), each with its own size and its own visit cycle: it swims in from beyond a frame
// edge (or rises from the deep), takes its station in the harmony formation, then swims off and is gone a while.
const TAU = 6.2831853;
const NCOMP = 9u;
const BELL_H = 0.64;       // companions: a flattened dome (height / width about 0.5), as on the boards
const BELL_Y0 = -0.35;
const BELL_THMAX = 1.55;   // the margin flares out rather than curling under
const BELL_VM = 0.9;       // exumbrella: lappet roots (ring canal); lappets run VM..1
const BELL_VS = 0.74;      // subumbrella margin; the frill skirt runs VS..1
const GLIDE_TAU = 1.3;     // lag_compease time constant, seconds
const DEEP_TAU = 3.2;      // lag_compdeep time constant, seconds
const VCAP = 0.25;         // top swimming speed, bell diameters per second (arrivals, departures, glides)
const VISIT_TAU = 12.0;    // lag_compvisit time constant (the deepest ones' stations), seconds
const VOICE = array<u32, 9>(0u, 2u, 4u, 0u, 1u, 2u, 3u, 1u, 3u);   // the harmony voice each companion follows
// per companion (stable): distance from the camera, size factor, visit period (s), phase, loyalty
const DEPTH = array<f32, 9>(26.0, 21.0, 17.5, 15.0, 13.0, 11.5, 8.5, 6.0, 4.5);   // (pass-4 slots, kept for reference)
// depth as a multiple of the (slowly eased) hero distance: never nearer than 1.3 x, so nothing comes near the lens
// and everything is behind the hero; the far tier 1.7 to 2.4 x, the formation tier 1.32 to 1.62 x
const DM = array<f32, 9>(2.4, 2.05, 1.75, 1.55, 1.42, 1.32, 1.48, 1.62, 1.9);
const SIZE = array<f32, 9>(1.55, 0.75, 1.15, 0.5, 1.1, 0.8, 0.45, 0.95, 1.0);
// the near tier (beside the hero, in focus): broader arms and a ribbon set
fn isNear(j: u32) -> bool { return j == 4u || j == 5u || j == 7u; }
const PER = array<f32, 9>(97.0, 61.0, 83.0, 47.0, 74.0, 109.0, 56.0, 88.0, 68.0);
const PHS = array<f32, 9>(0.51, 0.32, 0.04, 0.18, 0.16, 0.94, 0.68, 0.9, 0.17);
const LOY = array<f32, 9>(0.1, -0.05, 0.0, 0.12, 0.05, 0.1, -0.08, -0.15, -0.06);
// where it comes from and where it goes (unit directions from its station, world, mean view down -z). The formation
// lies left of the hero, so nobody's path crosses it: most come down from above (ahead: the ensemble swims up) and
// fall behind down-left; 4 and 7 come in from the left edge and sink away below; the deepest rise from below and
// sink back into the deep.
const DIN = array<vec3f, 9>(vec3f(0.1, -0.95, -0.3), vec3f(0.25, -0.9, -0.3), vec3f(-0.2, -0.95, -0.25),
 vec3f(-0.2, -0.95, -0.2), vec3f(-0.95, 0.15, 0.0), vec3f(-0.35, 0.95, -0.05), vec3f(-0.15, 1.0, 0.1), vec3f(-0.95, 0.2, 0.05), vec3f(-0.45, 0.9, 0.0));
const DOUT = array<vec3f, 9>(vec3f(-0.7, -0.3, -0.65), vec3f(-0.75, -0.35, -0.55), vec3f(-0.7, -0.45, -0.55),
 vec3f(-0.75, -0.45, -0.4), vec3f(-0.5, -0.85, 0.0), vec3f(-0.75, -0.65, 0.05), vec3f(-0.8, -0.6, 0.0), vec3f(-0.45, -0.9, 0.0), vec3f(-0.7, -0.7, 0.0));

fn stableRand(id: u32, salt: u32) -> f32 {
 var x = id * 747796405u + salt * 2891336453u + 12345u;
 x = (x ^ (x >> 15u)) * 2246822519u;
 x = (x ^ (x >> 13u)) * 3266489917u;
 x = x ^ (x >> 16u);
 return f32(x >> 8u) * (1.0 / 16777216.0);
}

struct HF { o: vec3f, ca: f32, sa: f32, cb: f32, sb: f32, k: f32, };
fn hfMake(o: vec3f, tx: f32, tz: f32, k: f32) -> HF {
 return HF(o, cos(tx), sin(tx), cos(tz), sin(tz), k);
}
fn hfDir(f: HF, d: vec3f) -> vec3f {
 let y1 = d.y * f.ca - d.z * f.sa;
 let z1 = d.y * f.sa + d.z * f.ca;
 return vec3f(d.x * f.cb - y1 * f.sb, d.x * f.sb + y1 * f.cb, z1);
}
fn hfPos(f: HF, p: vec3f) -> vec3f { return f.o + hfDir(f, p * f.k); }

// Same shape as the rig's pulse: fast squeeze to 0.28 of the cycle, slow release.
fn pulseEnv(ph: f32) -> f32 {
 let x = fract(ph);
 return smoothstep(0.0, 0.28, x) * (1.0 - smoothstep(0.28, 1.0, x));
}
// Thrust: the surge that follows a squeeze (fast up), then the glide back (slow). 0..1..0, periodic.
fn thrust(ph: f32) -> f32 {
 let x = fract(ph);
 return smoothstep(0.04, 0.42, x) - smoothstep(0.42, 1.0, x);
}

fn bellSqueeze(v: f32, pm: f32) -> f32 {
 let s = smoothstep(0.12, 1.0, v);
 return 1.0 - 0.19 * pm * s * sqrt(s);
}
// Exumbrella point. p: body contraction, pm: lagged margin contraction, te: tension, tall: -1 flat .. 1 tall.
fn bellExo(phi: f32, v: f32, p: f32, pm: f32, te: f32, tall: f32, flr: f32) -> vec3f {
 let th = v * BELL_THMAX;
 let c = cos(th);
 let h = BELL_H * (1.0 + 0.24 * p + 0.08 * te) * (1.0 + 0.42 * tall);
 let rib = 1.0 + 0.022 * (0.5 + 0.5 * cos(16.0 * phi)) * smoothstep(0.08, 0.5, v) * (1.0 - smoothstep(0.8, 0.95, v));
 let wave = (0.03 * sin(8.0 * phi + 0.7) + 0.012 * sin(13.0 * phi + 2.0)) * smoothstep(0.6, 1.0, v);
 let flare = 1.0 + (0.05 * (1.0 - 1.6 * pm) + flr) * smoothstep(BELL_VM, 1.0, v);
 let r = sin(th) * bellSqueeze(v, pm) * rib * flare * (1.0 - 0.1 * tall);
 var y = BELL_Y0 - 0.05 * pm * smoothstep(0.5, 1.0, v);
 if (c > 0.0) { y = y + h * pow(c, 0.88); } else { y = y + h * c * 0.6; }
 return vec3f(cos(phi) * r, y + wave, sin(phi) * r);
}

struct Comp {
 f: HF,
 up: vec3f,     // the bell's axis (world)
 tall: f32,     // bell proportion, -1 flat .. 1 tall (identity cos psi; juveniles rounder, elders flatter)
 hand: f32,     // arm twist handedness and amount, -1 .. 1  (identity: sin(2 psi + 0.6))
 ph: f32,       // own swim phase, cycles                    (rig phase + identity offset)
 pl: f32,       // own contraction 0..1
 pm: f32,       // margin contraction (lags the body a little)
 pres: f32,     // visibility 0..1 (the visit fade; 0 between visits, when the body is folded away: unfold)
 gain: f32,     // emission gain: visit, strike, hit, depth falloff
 fog: f32,      // atmospheric depth 0..1: dims and shifts toward the palette shadow tone
 vel: vec3f,    // swimming velocity, world units per second (visit transit + formation glide)
 droop: vec3f,  // the direction appendages settle into
 side: vec3f,
 side2: vec3f,
 te: f32,
 t: f32,
 j: u32,
 tier: u32,     // 2 near-lens (closer than 7), else 1
 amp: f32,      // drift amplitude, rate (for the follow-through)
 rate: f32,
 surge: f32,    // thrust amplitude, world units
 cps: f32,      // swim cycles per second
 ic: f32,       // identity (cos, sin of the eased fifths angle) for the appendages
 is: f32,
 sf: f32,       // size factor (0.45 juvenile .. 1.55 elder)
 gvel: vec3f,   // swimming velocity (world units per second)
 st: f32,       // strike light (voice envelope)
 ra: f32,       // strike response at the bell (0..~1, rises over ~0.8 s, no step)
 rb: f32,       // the same response a stage later and wider (mid appendage)
 rc: f32,       // two stages later (appendage tips)
 nud: f32,      // nudge along the heading per unit response, world
};

fn driftAt(j: u32, amp: f32, w: f32, t: f32) -> vec3f {
 let kf = f32(j);
 return amp * vec3f(sin(t * w + kf * 1.7) + 0.35 * sin(t * w * 2.3 + kf * 4.1),
                    0.55 * sin(t * w * 1.37 + kf * 2.9 + 1.0),
                    0.6 * cos(t * w * 0.81 + kf * 0.7));
}

fn compMake(P: Params, j: u32, t: f32) -> Comp {
 var WX = array<f32, 9>(P.p0x, P.p1x, P.p2x, P.p3x, P.p4x, P.p5x, P.p6x, P.p7x, P.p8x);
 var WY = array<f32, 9>(P.p0y, P.p1y, P.p2y, P.p3y, P.p4y, P.p5y, P.p6y, P.p7y, P.p8y);
 var WZ = array<f32, 9>(P.p0z, P.p1z, P.p2z, P.p3z, P.p4z, P.p5z, P.p6z, P.p7z, P.p8z);
 var VIS = array<f32, 9>(P.vis0, P.vis1, P.vis2, P.vis3, P.vis4, P.vis5, P.vis6, P.vis7, P.vis8);
 var IC = array<f32, 5>(P.ic0, P.ic1, P.ic2, P.ic3, P.ic4);
 var IS = array<f32, 5>(P.is0, P.is1, P.is2, P.is3, P.is4);
 var RA = array<f32, 5>(P.r0a, P.r1a, P.r2a, P.r3a, P.r4a);
 var RB = array<f32, 5>(P.r0b, P.r1b, P.r2b, P.r3b, P.r4b);
 var RC = array<f32, 5>(P.r0c, P.r1c, P.r2c, P.r3c, P.r4c);
 let vi = VOICE[j];
 let kf = f32(j);
 let st = 0.0;
 let ic = IC[vi];
 let is = IS[vi];
 // the force of a struck note, as a heavy damped body answers it (soft-saturated so dense passages roll)
 let ra = RA[vi] / (1.0 + 0.6 * RA[vi]);
 let rb = RB[vi] / (1.0 + 0.6 * RB[vi]);
 let rc = RC[vi] / (1.0 + 0.6 * RC[vi]);
 let sf = SIZE[j];
 // identity: smooth functions of the eased fifths angle psi (neighbouring fifths look related)
 let c2 = ic * ic - is * is;
 let s2 = 2.0 * ic * is;
 let tall = clamp(0.75 * ic + 0.55 * (1.0 - sf), -1.0, 1.0);
 let lean = is;
 let hand = 0.825 * s2 + 0.565 * c2;
 let phOff = 0.3 * (0.622 * is + 0.783 * ic) + 0.12 * s2 + 0.37 * kf;
 let tv = tan(radians(P.camFov) * 0.5);
 // its WORLD position (expression_compworld: school centre + home + harmonic offset + slow drift + visit drift; no
 // camera term); its own drift is a few hundredths of a unit per second, so the velocity the appendages trail behind
 // is the school's: 0.4 of the hero's
 var o = vec3f(WX[j], WY[j], WZ[j]);
 let vel = 0.4 * vec3f(P.heroVX, P.heroVY, P.heroVZ);
 let speed = length(vel);
 let amp = 0.0;
 let rate = 0.0;
 let sz = 0.6 * sf;
 // the camera is used for LIGHT only: the depth haze, and a companion that passes behind the hero's bell on screen
 // dims there (it is behind a bright bell), so nothing ever hides or veils the hero
 let cam = vec3f(P.camX, P.camY, P.camZ);
 let fwd = normalize(vec3f(P.camTX, P.camTY, P.camTZ) - cam);
 let rgt = normalize(cross(fwd, vec3f(0.0, 1.0, 0.0)));
 let cup = cross(rgt, fwd);
 let hrel = vec3f(P.heroX, P.heroY, P.heroZ) - cam;
 let hdz = max(dot(hrel, fwd), 0.5);
 let hc = vec2f(dot(hrel, rgt), dot(hrel, cup)) / (hdz * tv) + vec2f(0.0, 0.12 * P.heroScale / (hdz * tv));
 let hrs = 1.15 * P.heroScale / (hdz * tv);
 let rel = o - cam;
 let dz = max(dot(rel, fwd), 0.3);
 let sc = vec2f(dot(rel, rgt), dot(rel, cup)) / (dz * tv);
 let crad = 1.1 * sz / (dz * tv);
 let behindBell = 1.0 - 0.85 * (1.0 - smoothstep(0.9 * hrs, 1.4 * hrs + crad, length(sc - hc)));
 // swim: the hero's slow rate with its own phase; the same proportions and damping as the hero (no extra stroke
 // while drifting); a note gives a slightly fuller stroke
 let ph = P.pulsePhase + phOff;
 let stroke = 1.0 + 0.25 * ra;
 let pl = pulseEnv(ph) * stroke;
 let pm = pulseEnv(ph - 0.06) * stroke;
 let cps = max(P.swimRate, 0.01);
 // visibility: its visit fades it in from the dark and back out (expression_compworld vis)
 let pres = VIS[j];
 // lean: identity bias, into the travel, a slow sway
 let tz = -0.38 * lean - 0.3 * tanh(vel.x * 0.6) + 0.08 * sin(t * 0.23 + kf * 2.0);
 let tx = 0.1 * sin(t * 0.17 + kf * 1.3) + 0.2 * tanh(vel.z * 0.4);
 let f0 = hfMake(o, tx, tz, sz);
 let up = hfDir(f0, vec3f(0.0, 1.0, 0.0));
 // pulse thrust: surge along the bell's own axis after each squeeze, glide back between (mean-free)
 let surge = 0.1 * sz;
 let nud = 0.25 * sz;
 let f = hfMake(o + up * (surge * (thrust(ph - 0.03) - 0.42) + nud * ra), tx, tz, sz);
 // appendages hang along the bell's own axis (the hero family: no sideways current of their own); motion acts
 // through dragAt, never by tilting the hang
 let droop = -up;
 let side = normalize(cross(droop, vec3f(0.0, 0.0, 1.0)));
 let side2 = normalize(cross(droop, side));
 let dcam = length(o - cam);
 // no haze of our own: the depth pass (wgsl_worlddepth) applies aerial perspective and depth of field to this layer
 // from its own depth, so near companions keep the full palette and only the far ones fade toward the water
 let fog = 0.0;
 let near = mix(0.55, 1.0, smoothstep(4.5, 8.0, dcam));
 // no whole-body brightness response to the music: a note's light is a glow that travels (glowAt)
 // never brighter than the hero at equal depth (the bell material is the hero's): distance only dims
 let gain = pres * behindBell;
 let tier = 1u;
 return Comp(f, up, tall, hand, ph, pl, pm, pres, gain, fog, vel, droop, side, side2, P.tension, t, j, tier, amp, rate, surge, cps, ic, is, sf, vel, st, ra, rb, rc, nud);
}

// An absent companion (visibility 0, between visits, where its station may jump) is folded to a point at its bell,
// so it writes nothing into the companion layer's depth: the depth of field reads that depth per pixel, and an
// invisible body there would lend its focus to whatever glows behind it, and pop it sharp or soft as it moves.
// It unfolds while its light is still under 3 % (about the first second of its 10 s fade), so the depth grows in
// with it instead of appearing in one frame. 0 absent, 1 present.
fn unfold(c: Comp) -> f32 {
 return smoothstep(0.0, 0.03, c.pres);
}
fn shown(c: Comp, x: vec3f) -> vec3f {
 return c.f.o + unfold(c) * (x - c.f.o);
}

// The strike's follow-through down an appendage (s 0 at the bell, 1 at the tip): the bell moved nud * ra along
// its heading; a point further down moved by the LATER, wider response (rb, rc), and less of it. Returned relative
// to the rigid attachment, so nothing ever moves ahead of its bell. side: a gentle transverse swell rides with it.
fn strikeLag(c: Comp, s: f32) -> vec3f {
 let rs = select(mix(c.rb, c.rc, 2.0 * s - 1.0), mix(c.ra, c.rb, 2.0 * s), s < 0.5);
 return c.up * c.nud * (rs * (1.0 - 0.35 * s) - c.ra) + c.side * (0.5 * c.nud * rs * s);
}

// Never above (or ahead of) its bell: a point of an appendage hanging from root, s along it of length L, is held at
// least 0.1 L s below the root along the bell's axis (a smooth clamp, so nothing kinks).
fn keepBelow(c: Comp, root: vec3f, p: vec3f, s: f32, L: f32) -> vec3f {
 let h = dot(p - root, c.up) + 0.1 * L * s;
 let k = 0.05 * L + 1e-4;
 return p - c.up * (0.5 * (h + sqrt(h * h + k * k)));
}

// ---- the appendage family (shared with the hero: M/hero/tent.common.wgsl) ----
const DRAG_T = 4.0;        // tentacles: seconds of mean swimming by which a tip trails
const ARM_DRAG_T = 5.5;    // oral arms and silk trains: broad veils catch more water
// trail opposite the companion's (smooth, surge-free) swimming velocity, growing toward the tip, softly limited
// (never normalised: as it slows the trail eases back to the rest hang)
fn dragAt(c: Comp, s: f32, len: f32, secs: f32) -> vec3f {
 let dd = -c.vel * secs * pow(s, 1.5);
 let limit = 0.35 * len;
 return dd / sqrt(1.0 + dot(dd, dd) / (limit * limit));
}
// the slow sweep of the whole hanging bundle (one every 20 s), travelling tipward
fn sweepAt(c: Comp, s: f32) -> vec3f {
 let a = TAU * (0.05 * c.t - 0.35 * s) + f32(c.j) * 1.7;
 return (c.side * sin(a) + c.side2 * 0.5 * sin(a * 0.7 + 1.9)) * 0.08 * s * s;
}

// A note's light: a soft glow born in the core (the bell's response, ra), reaching the canals and margin a stage
// later (rb) and the appendage tips two stages later (rc): about 0.8, 1.2 and 1.6 s after the strike, building with
// no step; saturating, so a dense passage gives a steady warm breathing. x: 0 core .. 1 margin .. 2 appendage tip.
fn glowAt(c: Comp, x: f32) -> f32 {
 let r = select(mix(c.rb, c.rc, clamp(x - 1.0, 0.0, 1.0)), mix(c.ra, c.rb, x), x < 1.0);
 return r / (1.0 + r);
}
// Companion bells: 9 companions x 2 sheets of one 41 x 16 grid (u around with a duplicated seam, v apex
// to margin). Sheet 0 the exumbrella (a flattened glass dome; lappets, canals and frill are painted by the
// material), sheet 1 the gonads: the hero's four warm loops (a tube round a rosette), small, under the crown.
// uv = (around, along). tint = (sheet + 4 * companion, gain, fog, contraction).
const C = 41u;
const R = 16u;
const NSH = 2u;

fn process(p: Point, ctx: PointCtx) -> Point {
 var q = p;
 let per = C * R;
 let sh = ctx.index / per;
 let j = min(sh / NSH, NCOMP - 1u);
 let sheet = sh % NSH;
 let k = ctx.index % per;
 let i = k % C;
 let jj = k / C;
 let u = f32(i) / f32(C - 1u);
 let v = f32(jj) / f32(R - 1u);
 let cm = compMake(ctx.params, j, ctx.absTime);
 // seam at the back (-z local)
 let phi = u * TAU - 1.5707963 + 0.1 * cm.te * v;
 var lp: vec3f;
 if (sheet == 0u) {
  lp = bellExo(phi, v, cm.pl, mix(cm.pl, cm.pm, smoothstep(0.6, 1.0, v)), cm.te, cm.tall, 0.1 * cm.ra);
 } else {
  // the gonads: the hero's four loops, a tube round a rosette (r = 0.34 |cos 2 psi| ^ 0.55) under the crown
  let hk = 1.0 + 0.3 * cm.tall;
  let psi = u * TAU + 0.3927;
  let rho = 0.34 * pow(abs(cos(2.0 * psi)), 0.55);
  let c0 = vec2f(cos(psi), sin(psi)) * rho;
  let c1 = vec2f(cos(psi + 0.004), sin(psi + 0.004)) * 0.34 * pow(abs(cos(2.0 * psi + 0.008)), 0.55);
  let tg = normalize(c1 - c0 + vec2f(1e-5, 0.0));
  let sd = vec2f(-tg.y, tg.x);
  let al = v * TAU;
  let tr = 0.065 * smoothstep(0.02, 0.15, rho) * (1.0 + 0.2 * sin(psi * 40.0) * sin(al * 3.0 + psi * 9.0));
  let xz = (c0 + sd * cos(al) * tr) * (1.0 - 0.1 * cm.pl);
  lp = vec3f(xz.x, BELL_Y0 + (0.34 + 0.08 * cm.pl) * hk - 0.6 * rho * rho + sin(al) * tr * 0.9, xz.y);
 }
 q.position = shown(cm, hfPos(cm.f, lp));
 q.uv = vec2f(u, v);
 // the note's glow: in the core at once, reaching the margin a stage later
 let gl = select(glowAt(cm, 0.15), glowAt(cm, 0.1 + 0.9 * v), sheet == 0u);
 q.tint = vec4f(f32(sheet) + 4.0 * f32(j) + 0.45 * gl, cm.gain, cm.fog, cm.pl);
 return q;
}

struct Params {
 heroX: f32, // @default 1.1 Bell centre now (rig heroX).
 heroY: f32, // @default 1.45 Bell centre now (rig heroY).
 heroZ: f32, // @default 0 Bell centre now (rig heroZ).
 heroX1: f32, // @default 1.1 Where the bell was 0.7 s ago (rig heroX1).
 heroY1: f32, // @default 1.45 (rig heroY1).
 heroZ1: f32, // @default 0 (rig heroZ1).
 heroX2: f32, // @default 1.1 Where the bell was 1.4 s ago (rig heroX2).
 heroY2: f32, // @default 1.45 (rig heroY2).
 heroZ2: f32, // @default 0 (rig heroZ2).
 heroX3: f32, // @default 1.1 Where the bell was 2.1 s ago (rig heroX3).
 heroY3: f32, // @default 1.45 (rig heroY3).
 heroZ3: f32, // @default 0 (rig heroZ3).
 tiltX: f32, // @default 0 Bell lean about X, radians (rig heroTiltX); shapes only the roots.
 tiltZ: f32, // @default -0.22 Bell lean about Z, radians (rig heroTiltZ); shapes only the roots.
 scale: f32, // @default 1 Size multiplier (rig heroScale).
 pulse: f32, // @default 0 Bell contraction 0..1 (rig pulse).
 pulsePhase: f32, // @default 0 Swim-cycle phase 0..1 (rig pulsePhase); only periodic functions of it are used.
 swimRate: f32, // @default 0.567 Swim cycles per second (rig swimRate): one period sets the mean-velocity window.
 tension: f32, // @default 0.3 Stretch and twist (rig tension).
 density: f32, // @default 0.5 How much is present: arm and tentacle count, length, veil width (rig density).
 lum: f32, // @default 0.5 Illumination (rig lum).
 mood: f32, // @default 0 Palette position (rig mood).
 kick0: f32, // @default 0 Strike force at the bell (lag_herokick2.imp).
 kick1: f32, // @default 0 The same a little later and wider (lag_herokick4.imp).
 kick2: f32, // @default 0 Later still (lag_herokick5.imp): reaches the tips.
 kickS: f32, // @default 0 Slow mean of the strikes (lag_herokick7.imp): what is sustained, not new.
 rigLean: f32, // @default 0 1 = the rig's heroTiltX/Z is already the smooth travel lean: hang everything along it.
 env4: f32, // @default 0 Melody envelope (lag_env.env4): beads and rhopalia twinkle with it.
 energyS: f32, // @default 0.5 Slow musical energy (rig energy through two 1.2 s lags) plus a share of the bass envelope (lag_heronote2.bs): how deep the strokes, how open, how far they trail, how alive.
 hitAge: f32, // @default 9 Seconds since the last chord strike (rig age): a soft swell of light runs down from the root.
 nt0: f32, // @default 0 Note place 0 (pitch class 0, circle-of-fifths order) now (lag_heronote2.s0).
 nt1: f32, // @default 0 Note place 1 (pitch class 7, circle-of-fifths order) now (lag_heronote2.s1).
 nt2: f32, // @default 0 Note place 2 (pitch class 2, circle-of-fifths order) now (lag_heronote2.s2).
 nt3: f32, // @default 0 Note place 3 (pitch class 9, circle-of-fifths order) now (lag_heronote2.s3).
 nt4: f32, // @default 0 Note place 4 (pitch class 4, circle-of-fifths order) now (lag_heronote2.s4).
 nt5: f32, // @default 0 Note place 5 (pitch class 11, circle-of-fifths order) now (lag_heronote2.s5).
 nt6: f32, // @default 0 Note place 6 (pitch class 6, circle-of-fifths order) now (lag_heronote2.s6).
 nt7: f32, // @default 0 Note place 7 (pitch class 1, circle-of-fifths order) now (lag_heronote2.s7).
 nt8: f32, // @default 0 Note place 8 (pitch class 8, circle-of-fifths order) now (lag_heronote2.s8).
 nt9: f32, // @default 0 Note place 9 (pitch class 3, circle-of-fifths order) now (lag_heronote2.s9).
 nt10: f32, // @default 0 Note place 10 (pitch class 10, circle-of-fifths order) now (lag_heronote2.s10).
 nt11: f32, // @default 0 Note place 11 (pitch class 5, circle-of-fifths order) now (lag_heronote2.s11).
 nu0: f32, // @default 0 Note place 0 later, for the tips (lag_heronote3.s0).
 nu1: f32, // @default 0 Note place 1 later, for the tips (lag_heronote3.s1).
 nu2: f32, // @default 0 Note place 2 later, for the tips (lag_heronote3.s2).
 nu3: f32, // @default 0 Note place 3 later, for the tips (lag_heronote3.s3).
 nu4: f32, // @default 0 Note place 4 later, for the tips (lag_heronote3.s4).
 nu5: f32, // @default 0 Note place 5 later, for the tips (lag_heronote3.s5).
 nu6: f32, // @default 0 Note place 6 later, for the tips (lag_heronote3.s6).
 nu7: f32, // @default 0 Note place 7 later, for the tips (lag_heronote3.s7).
 nu8: f32, // @default 0 Note place 8 later, for the tips (lag_heronote3.s8).
 nu9: f32, // @default 0 Note place 9 later, for the tips (lag_heronote3.s9).
 nu10: f32, // @default 0 Note place 10 later, for the tips (lag_heronote3.s10).
 nu11: f32, // @default 0 Note place 11 later, for the tips (lag_heronote3.s11).
 leadC: f32, // @default 0 The melody note's place, cosine (lag_herochord2.lC): its filaments carry the melody's gesture.
 leadS: f32, // @default 0 The same, sine (lag_herochord2.lS).
 melF: f32, // @default 60 Top voice pitch, quick (lag_heromel2.mp).
 melS: f32, // @default 60 Top voice pitch, slow (lag_heromel3.mp): melF - melS is the melodic motion.
 teS: f32, // @default 0.3 Tension, slow mean (lag_herotens.tension): above it = rising, below it = a release.
 rC3: f32, // @default 1 Chord root on the circle of fifths, cosine, at the margin's stage (lag_herochord3.rC).
 rS3: f32, // @default 0 The same, sine (lag_herochord3.rS).
 rC4: f32, // @default 1 The same, later, for the tips (lag_herochord4.rC).
 rS4: f32, // @default 0 (lag_herochord4.rS).
 noteGain: f32, // @default 1 How strongly notes light and move their places (0 = off).
 melodyGain: f32, // @default 1 How strongly the melody's rise and fall bend the arms and lead filaments.
 tensionGain: f32, // @default 1 How strongly tension stretches and a release spreads.
 chordGain: f32, // @default 1 How far the chord root leans the colour.
 react: f32, // @default 1 The owner's music reaction strength (rig reactGain, 0..2, eased): multiplies every gain above.
};
// Beads: NB per tentacle on the same curves, then 8 rhopalia at the margin notches.
// size multiplies the geometry's Size; tint alpha 0.75 lights the spherical splat from above.
const NB = 12u;
fn process(p: Point, ctx: PointCtx) -> Point {
 var q = p;
 let P = ctx.params;
 let f = hfMake(P.heroX, P.heroY, P.heroZ, P.tiltX, P.tiltZ, P.scale);
 let c = tcMake(f, vec3f(P.heroX1, P.heroY1, P.heroZ1), vec3f(P.heroX2, P.heroY2, P.heroZ2), vec3f(P.heroX3, P.heroY3, P.heroZ3), P.swimRate, P.tiltX, P.tiltZ, pulseEnv(P.pulsePhase), P.pulsePhase, P.tension, P.density, ctx.absTime, vec3f(P.kick0, P.kick1, P.kick2), P.energyS, P.kickS, P.rigLean);
 let i = ctx.index;
 let warm = mix(ACC, moodColor(P.mood + leanAt(P, 0.5), 0.95), 0.15);
 let hot = moodColor(P.mood, 1.0);
 if (i < NT * NB) {
  let ti = i / NB;
  let bi = i % NB;
  let r = stableRand(i, 31u);
  let s = clamp((f32(bi) + 0.5 + 0.8 * (r - 0.5)) / f32(NB), 0.03, 0.97) * 0.95;
  q.position = heroTentPoint(c, P, ti, s);
  let travel = pres(P.pulsePhase - 0.1 - 0.6 * s) + 1.5 * softPos(rippleAt(c.kick, s)) + 1.6 * noteAt(P, tentPhi(ti), s);
  // twinkle: a slow pattern travelling down the filament, lit by the melody envelope
  let tw = 0.75 + 0.25 * sin(ctx.absTime * (0.4 + 0.6 * r) + r * 40.0) + 1.2 * P.env4 * (0.5 + 0.5 * sin(TAU * (1.5 * s - 0.15 * ctx.absTime) + f32(ti) * 0.9));
  // three sizes: 70 % tiny, 25 % small, 5 % large glassy beads (the spherical splat gives the rim light)
  let cls = stableRand(i, 33u);
  let sz = select(select(2.1, 1.05, cls < 0.95), 0.55, cls < 0.7);
  let kb = select(select(1.3, 1.0, cls < 0.95), 0.7, cls < 0.7);
  let k = tentActive(ti, P.density) * (0.3 + 0.7 * stableRand(ti, 19u)) * max(1.0 - s / (0.55 + 0.45 * stableRand(ti, 23u)), 0.0) * tw * (0.35 + 2.2 * pow(P.lum, 1.1)) * (0.7 + 0.5 * travel) * 0.55 * kb;
  // at most one bead per 0.3 bell radius of filament
  let keep = min(0.45, tentLength(c, ti) / (0.3 * f.k * f32(NB)));
  let show = step(1.0 - keep, stableRand(i, 37u));
  let bw = mix(warm, waveColAt(P, s), min(0.6 * waveAt(P, s), 0.75));
  q.tint = vec4f(mix(bw, vec3f(1.0), 0.35) * k * show, 0.75);
  q.size = sz * (1.0 - 0.25 * s);
  return q;
 }
 // the 8 rhopalia: bright points in the margin notches
 let j = i - NT * NB;
 let phi = f32(j) / 8.0 * TAU;
 let D = strokeDepth(c.es);
 let k0 = c.kick.x + c.steady;
 let ps = pulseEnv(P.pulsePhase) * strokeAmp(D * (1.0 + 0.2 * k0));
 q.position = hfPos(f, marginFlare(bellExo(phi, BELL_VM + 0.01, ps, bellPulseAt(BELL_VM + 0.01, ps, P.pulsePhase, D), P.tension), BELL_VM + 0.01, k0) * vec3f(1.01, 1.0, 1.01));
 // each rhopalium is a marker of the note place it sits in: it brightens with that note (pass 6)
 let nr = (P.noteGain * P.react) * noteSoft(ntNow(P, phi));
 q.tint = vec4f(mix(warm, vec3f(1.0), 0.4) * (0.45 + 1.6 * P.lum) * (1.0 + 1.2 * softPos(c.kick.y) + 1.5 * P.env4 * (0.5 + 0.5 * sin(phi * 2.0 - 0.3 * ctx.absTime)) + 2.0 * nr), 0.75);
 q.size = 1.1;
 return q;
}
// ---- hero common (kernels): frame, pulse envelope, bell profile, trail ----
const TAU = 6.2831853;
// The bell in its own frame: rim radius 1, up +y, rim (margin) plane at BELL_Y0, apex BELL_H above it.
// World = hero position + rotZ(tiltZ) * rotX(tiltX) * (local * heroScale).
// A flattened dome (the boards: height/width about 0.38 for the dome, 0.45 with the lappets): the profile
// stops at 79 degrees, so the shoulders slope into the rim and never stand as a vertical wall; 16
// rounded lappets hang LAP_LEN below the rim.
const BELL_H = 0.64;
const BELL_Y0 = -0.35;
const BELL_THMAX = 1.38;
const BELL_VM = 0.9;       // exumbrella: v of the rim (ring canal); the lappets hang over VM..1
const LAP_LEN = 0.14;

struct HF { o: vec3f, ca: f32, sa: f32, cb: f32, sb: f32, k: f32, };
fn hfMake(x: f32, y: f32, z: f32, tx: f32, tz: f32, k: f32) -> HF {
 return HF(vec3f(x, y, z), cos(tx), sin(tx), cos(tz), sin(tz), k);
}
fn hfDir(f: HF, d: vec3f) -> vec3f {
 let y1 = d.y * f.ca - d.z * f.sa;
 let z1 = d.y * f.sa + d.z * f.ca;
 return vec3f(d.x * f.cb - y1 * f.sb, d.x * f.sb + y1 * f.cb, z1);
}
fn hfPos(f: HF, p: vec3f) -> vec3f { return f.o + hfDir(f, p * f.k); }

// The stroke, as a periodic function of the swim phase (the cycle is about 3.5 s): a slow full
// contraction over 30 % of it, a release over 40 %, then a 30 % glide at rest. Every geometric use of
// the swim reads this (the bell body too), so the bell and everything lagging it agree.
// the warm accent: one peach-gold for cores, canals, glints and beads in every mood
const ACC = vec3f(1.0, 0.66, 0.36);
fn smoother(a: f32, b: f32, x: f32) -> f32 {
 let t = clamp((x - a) / (b - a), 0.0, 1.0);
 return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}
fn pulseEnv(ph: f32) -> f32 {
 let x = fract(ph);
 return smoother(0.0, 0.3, x) * (1.0 - smoother(0.3, 0.7, x));
}
// A chord strike as a FORCE: the rig's strike age drives a short impulse through a chain of hero
// lag nodes; k.x (lag_herokick2) is the response at the bell, k.y (4) later and wider, k.z (5) later
// still, kS (7) a very slow mean of the same impulse. The RIPPLE is what is new: each response minus
// the slow mean, normalised so one isolated strike peaks near 1, softly limited, so a train of strikes
// does not hold the appendages splayed: each new strike still adds a travelling ripple, and the
// sustained part becomes a small, saturating STEADY opening.
fn kickRipple(k: vec3f, kS: f32) -> vec3f {
 let g = vec3f(2.0, 4.0, 5.5);
 let x = (k - vec3f(kS)) * g;
 return x / sqrt(vec3f(1.0) + x * x);
}
fn kickSteady(kS: f32) -> f32 { return 0.35 * (1.0 - exp(-2.5 * kS)); }
// positive part, smoothly (light and flares only grow)
fn softPos(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.0004)); }
// the margin flares a little with the strike (bell and tentacle roots must agree)
fn marginFlare(lp: vec3f, v: f32, k0: f32) -> vec3f {
 let g = 1.0 + 0.035 * k0 * smoothstep(0.75, 1.0, v);
 return vec3f(lp.x * g, lp.y, lp.z * g);
}

// Soft swim pressure: a raised cosine at the swim frequency, peaking with the contraction (phase 0.28).
// Lagged copies of it run down arms and tentacles as a gentle pressure wave, never a wiggle.
fn gaussK(x: f32) -> f32 { return exp(-x * x); }
// the strike ripple as felt at s along anything (0 the bell, 1 the tips), continuous in time and space
fn rippleAt(r: vec3f, s: f32) -> f32 {
 return mix(mix(r.x, r.y, smoother(0.0, 0.5, s)), r.z, smoother(0.5, 1.0, s));
}
fn pres(ph: f32) -> f32 { return 0.5 + 0.5 * cos(TAU * (ph - 0.28)); }
// Contraction felt at bell parameter v (0 apex, 1 lappet tips): the body follows pulse, the margin
// lags 0.06 of a cycle, the lappets 0.1, so the rim trails the squeeze and re-opens late.
// D is the stroke depth (fuller with louder music, set slowly).
fn bellPulseAt(v: f32, pl: f32, ph: f32, D: f32) -> f32 {
 let pm = pulseEnv(ph - 0.06) * D;
 let plap = pulseEnv(ph - 0.1) * D;
 return mix(pl, mix(pm, plap, smoothstep(0.86, 1.0, v)), smoothstep(0.55, 1.0, v));
}
fn strokeDepth(es: f32) -> f32 { return 0.75 + 0.4 * es; }
// The stroke's amplitude, softly limited to 1 (pass 6). A hard min(.., 1) on depth x strike clipped the
// top of the contraction inside a stroke whenever the music was full: a kink in its speed, seen as a
// light step at the stroke's peak (Clair 70.6 s, 88.1 s). Bell, filament roots and rhopalia all use it.
fn strokeAmp(a: f32) -> f32 { return a / pow(1.0 + pow(max(a, 0.0), 8.0), 0.125); }

fn bellSqueeze(v: f32, pm: f32) -> f32 {
 return 1.0 - 0.2 * pm * pow(smoothstep(0.12, 1.0, v), 1.3);
}
// Exumbrella point. p: body contraction, pm: (lagged) margin contraction, te: tension.
// the dome's height profile, 1 at the apex and 0 at the rim (slightly flattened top)
fn domeY(th: f32) -> f32 {
 let cm = pow(cos(BELL_THMAX), 0.88);
 return (pow(max(cos(th), 0.0), 0.88) - cm) / (1.0 - cm);
}
fn bellExo(phi: f32, v: f32, p: f32, pm: f32, te: f32) -> vec3f {
 let vd = min(v / BELL_VM, 1.0);
 let th = vd * BELL_THMAX;
 // a contraction closes the rim and lengthens the dome a little: it stays a dome (h/w under 0.6)
 let h = BELL_H * (1.0 + 0.12 * p + 0.06 * te);
 let rib = 1.0 + 0.022 * (0.5 + 0.5 * cos(16.0 * phi)) * smoothstep(0.08, 0.5, vd) * (1.0 - smoothstep(0.8, 0.95, vd));
 let wave = (0.025 * sin(8.0 * phi + 0.7) + 0.01 * sin(13.0 * phi + 2.0)) * smoothstep(0.6, 1.0, vd);
 var r = sin(th) / sin(BELL_THMAX) * bellSqueeze(vd, pm) * rib;
 var y = BELL_Y0 - 0.04 * pm * smoothstep(0.5, 1.0, vd) + h * domeY(th);
 if (v > BELL_VM) {
  // the lappets hang from the rim: flared a little outward at rest, curled in by the squeeze
  let s = (v - BELL_VM) / (1.0 - BELL_VM);
  r = r + s * LAP_LEN * (0.45 - 0.9 * pm) * bellSqueeze(1.0, pm);
  y = y - s * LAP_LEN * (0.9 + 0.2 * pm);
 }
 return vec3f(cos(phi) * r, y + wave, sin(phi) * r);
}

// Frame-independent per-id random in [0, 1). The built-in pointRand re-rolls EVERY FRAME (it hashes the
// frame index), so it must never shape geometry: that reads as high-frequency jitter in playback.
fn stableRand(id: u32, salt: u32) -> f32 {
 var x = id * 747796405u + salt * 2891336453u + 12345u;
 x = (x ^ (x >> 15u)) * 2246822519u;
 x = (x ^ (x >> 13u)) * 3266489917u;
 x = x ^ (x >> 16u);
 return f32(x >> 8u) * (1.0 / 16777216.0);
}
// ---- hero appendages in water (shared by tentacle beams, beads and oral arms) ----
// They HANG: almost passive, a slow curtain dragged behind the swim and swaying over many seconds.
// Point s = the root on the bell (rigidly attached, in the bell's own frame) + a hanging shape
// (gravity and a slow down-left current, leaning with the path) + a slow DRAG opposite the bell's
// mean velocity, growing toward the tip. The mean velocity is taken over one swim period (the bell
// now vs where it was one period, about 1.76 s, ago), so the surge of each thrust cancels out and
// is never replayed down the appendages; it is used as a vector that shrinks to nothing as the bell
// slows (never normalised), so the trail eases back to the rest hang. Each contraction sends one
// soft, slow bulge down them; chord strikes change only their light. Nothing may rise above its
// own root along the bell's axis (keepBelow).
const NT = 48u;            // tentacles
const DRAG_T = 4.0;        // tentacles: seconds of mean drift by which a tip trails
const ARM_DRAG_T = 5.5;    // oral arms: broad veils catch more water
struct TC { f: HF, fP: HF, h0: vec3f, vbar: vec3f, droop: vec3f, side: vec3f, side2: vec3f, pl: f32, ph: f32, te: f32, de: f32, t: f32, kick: vec3f, es: f32, steady: f32, act: f32, };

// the bell's path u steps of 0.7 s ago (u in 1..3), straight between the rig's samples (no overshoot)
fn pathBack(h1: vec3f, h2: vec3f, h3: vec3f, u: f32) -> vec3f {
 if (u < 2.0) { return mix(h1, h2, clamp(u - 1.0, 0.0, 1.0)); }
 return mix(h2, h3, clamp(u - 2.0, 0.0, 1.0));
}

fn tcMake(f: HF, h1: vec3f, h2: vec3f, h3: vec3f, rate: f32, tx: f32, tz: f32, pl: f32, ph: f32, te: f32, de: f32, t: f32, kick: vec3f, es: f32, kS: f32, rl: f32) -> TC {
 // mean velocity: the least-squares slope through the four samples (now, 0.7, 1.4, 2.1 s ago), far
 // less sensitive to the surge inside a stroke than a two-point difference
 let vbar = (1.5 * f.o + 0.5 * h1 - 0.5 * h2 - 1.5 * h3) / (5.0 * 0.7);
 // the bell's own axis with the per-stroke rocking taken out: the rig leans the bell by its 0.7 s
 // velocity; swap that for the period-mean velocity (same lean law), keep everything else it does
 // (with rigLean = 1 the rig's tilt already is that smooth lean, and everything hangs along it as is)
 let v07 = (f.o - h1) / 0.7;
 let swap = select(1.0, 0.0, rl > 0.5);
 let fP = hfMake(f.o.x, f.o.y, f.o.z, tx - 0.5 * (v07.z - vbar.z) * swap, tz + 1.6 * (v07.x - vbar.x) * swap, f.k);
 // appendages hang along that axis (no sideways current of their own)
 let droop = hfDir(fP, vec3f(0.0, -1.0, 0.0));
 let side = normalize(cross(droop, vec3f(0.0, 0.0, 1.0)));
 let side2 = normalize(cross(droop, side));
 // activity: slow musical energy plus how busy the strikes have been (both eased), 0 calm .. 1 full
 let steady = kickSteady(kS);
 let act = clamp(0.75 * es + 1.2 * steady, 0.0, 1.0);
 return TC(f, fP, f.o, vbar, droop, side, side2, pl, ph, te, de, t, kickRipple(kick, kS), es, steady, act);
}
// trail opposite the mean velocity, growing toward the tip, softly limited (no normalising)
fn dragAt(c: TC, s: f32, len: f32, secs: f32) -> vec3f {
 let d = -c.vbar * secs * pow(s, 1.5);
 let limit = 0.35 * len;
 return d / sqrt(1.0 + dot(d, d) / (limit * limit));
}
// never above the root along the bell's axis: a point at s hangs at least 10 % of its arclength below
fn keepBelow(c: TC, root: vec3f, p: vec3f, s: f32, len: f32) -> vec3f {
 let up = hfDir(c.f, vec3f(0.0, 1.0, 0.0));
 let along = dot(p - root, up);
 let floorA = -0.1 * s * len;
 let w = 0.08 * len * s + 1e-4;
 let hh = clamp(0.5 + 0.5 * (floorA - along) / w, 0.0, 1.0);
 let sm = mix(floorA, along, hh) - w * hh * (1.0 - hh);
 return p + up * (sm - along);
}
fn tentPhi(ti: u32) -> f32 {
 return (f32(ti) + 0.5 + 0.55 * (stableRand(ti, 11u) - 0.5)) / f32(NT) * TAU;
}
// active share of the tentacles: about 24 at density 0, all 48 at density 1 (unused ones fade)
fn tentActive(ti: u32, de: f32) -> f32 {
 let rank = stableRand(ti, 17u);
 return 1.0 - smoothstep(0.5 + 0.5 * de - 0.06, 0.5 + 0.5 * de + 0.02, rank);
}
fn tentLength(c: TC, ti: u32) -> f32 {
 return (1.2 + 3.0 * pow(stableRand(ti, 13u), 1.4)) * (0.85 + 0.3 * c.de) * (1.0 + 0.12 * c.te) * c.f.k;
}
// the bell's contraction as felt at s along an appendage: exact at the root, then the same envelope at
// a later phase, damped (a soft pressure wave). Returns (body pulse, margin pulse, phase used).
fn pulseAlong(c: TC, s: f32) -> vec3f {
 let lagc = 0.6 * s;
 let att = exp(-1.8 * s);
 let D = strokeDepth(c.es);
 let k0 = (c.kick.x + c.steady) * att;
 let ps = pulseEnv(c.ph - lagc) * strokeAmp(D * (1.0 + 0.2 * k0)) * att;
 let pm = bellPulseAt(0.9, ps, c.ph - lagc, D) * att;
 return vec3f(ps, pm, c.ph - lagc);
}
// the slow sweep of the whole hanging bundle (shared by tentacles and arms), travelling tipward
fn sweepAt(c: TC, s: f32) -> vec3f {
 let a = TAU * (0.05 * c.t - 0.35 * s);
 return (c.side * sin(a) + c.side2 * 0.5 * sin(a * 0.7 + 1.9)) * (0.12 + 0.14 * c.act) * s * s;
}
// the strike as felt at s: the bell's response at the root, later and wider responses toward the tip
fn kickAt(c: TC, s: f32) -> f32 { return rippleAt(c.kick, s) + c.steady; }
fn tentRoot(c: TC, phi: f32, s: f32) -> vec3f {
 let pa = pulseAlong(c, s);
 let k0 = (c.kick.x + c.steady) * exp(-1.8 * s);
 return hfPos(c.f, marginFlare(bellExo(phi, 0.9, pa.x, pa.y, c.te), 0.9, k0) * vec3f(0.965, 1.0, 0.965));
}
fn tentPoint(c: TC, ti: u32, s: f32) -> vec3f {
 let phi = tentPhi(ti);
 let h1 = stableRand(ti, 12u);
 let h2 = stableRand(ti, 14u);
 // root on the margin, squeezing with it (the squeeze reaches further points later and weaker)
 let anchor = tentRoot(c, phi, s);
 let outL = vec3f(cos(phi), 0.0, sin(phi));
 // one soft slow bulge per contraction, travelling down
 let pp = pres(c.ph - 0.1 - 0.6 * s);
 // loud passages open the whole curtain, quiet ones draw it in (slow)
 let spread = (0.16 + 0.2 * h1) * (0.7 + 0.7 * c.act) - 0.04 * pp;
 let d0 = hfDir(c.fP, normalize(vec3f(outL.x * spread, -1.0, outL.z * spread)));
 let len = tentLength(c, ti);
 let bendL = vec3f(cos(phi + 1.6 * (h2 - 0.5)), 0.0, sin(phi + 1.6 * (h2 - 0.5)));
 let b1 = d0 * 0.22 * len + hfDir(c.fP, bendL) * (0.04 + 0.08 * h2) * len;
 let b2 = b1 + normalize(c.droop + hfDir(c.fP, outL) * (0.05 + 0.12 * h1)) * 0.78 * len;
 var pos = anchor + 2.0 * s * (1.0 - s) * b1 + s * s * b2;
 // slow drag behind the mean swim
 pos += dragAt(c, s, len, DRAG_T * (0.8 + 0.4 * h2) * (0.8 + 0.4 * c.es));
 // always alive: a long slow undulation (about one wave every 9 s), larger when the music is fuller,
 // under a slower sweep the whole curtain shares (one every 20 s), travelling down it
 // the music shapes it through amplitude and (a little) wavelength, never its rate: calm = long lazy
 // waves, busy = fuller and livelier
 let w = TAU * ((0.55 + 0.35 * c.act) * s - 0.11 * c.t) + phi * 3.0 + h1 * 6.0;
 let amp = (0.06 + 0.1 * c.act) * len * pow(s, 1.5);
 pos += (c.side * sin(w) + c.side2 * 0.6 * cos(0.8 * w + 1.3)) * amp;
 pos += sweepAt(c, s) * len;
 // the bulge: the bundle breathes out a hair as it passes
 pos += hfDir(c.fP, outL) * 0.012 * len * sin(3.14159 * s) * pp;
 // a strike: the filaments flare outward and stretch back along the trail, as a slow wave tipward
 pos += (hfDir(c.fP, outL) * 0.7 + c.droop * 0.5) * 0.11 * len * sin(3.14159 * min(s * 1.1, 1.0) * 0.5) * kickAt(c, s);
 return keepBelow(c, tentRoot(c, phi, 0.0), pos, s, len);
}
// ---- hero only: the music as characters (pass 6). Not part of the shared family. ----
// Twelve places round the bell, one per pitch class in circle-of-fifths order: sector k holds pitch class
// 7k mod 12, so a fifth is a neighbour and a triad is always the same small shape (root, its neighbour,
// and the third four places round). A note lights and moves its own place; a chord shows as the set of
// places its tones hold. The values per sector come from expression_herochord through lags (two 0.3 s
// stages with a four times slower release: S-shaped onset, seconds of decay; one more 0.8 s stage for
// the tips), so nothing here can step.
fn noteSecW(x: f32, k: f32) -> f32 {
 let d = abs(fract((x - k) / 12.0 + 0.5) - 0.5) * 12.0;   // distance in sectors, wrapped
 return 1.0 - smoother(0.3, 0.7, d);                       // a plateau per sector, soft 0.4-sector seams
}
fn secW4(x: f32, k0: f32) -> vec4f {
 return vec4f(noteSecW(x, k0), noteSecW(x, k0 + 1.0), noteSecW(x, k0 + 2.0), noteSecW(x, k0 + 3.0));
}
// the twelve sector values (a = sectors 0..3, b = 4..7, c = 8..11) as felt at bell azimuth phi
fn secSum(a: vec4f, b: vec4f, c: vec4f, phi: f32) -> f32 {
 let x = fract(phi / TAU) * 12.0;
 return dot(a, secW4(x, 0.0)) + dot(b, secW4(x, 4.0)) + dot(c, secW4(x, 8.0));
}
// where in its sector an azimuth lies, -0.5 .. 0.5 (a sector's filaments fan apart from its centre)
fn secOffset(phi: f32) -> f32 { return fract(fract(phi / TAU) * 12.0 + 0.5) - 0.5; }
// soft limit: many notes on one place never add up to more than about one
fn noteSoft(x: f32) -> f32 { return x / sqrt(1.0 + x * x); }
// melodic motion: the top voice's pitch through a quick and a slow lag; their difference (semitones)
// is a damped force, up > 0. Returns (rising, falling), each 0..1, softly limited.
fn melodyUD(melF: f32, melS: f32, g: f32) -> vec2f {
 let m = g * (melF - melS) / 4.0;
 return vec2f(noteSoft(softPos(m)), noteSoft(softPos(-m)));
}
// tension against its own slow mean: (rising, releasing), each 0..1. A release is the exhale.
fn tensionRR(teF: f32, teS: f32, g: f32) -> vec2f {
 let d = g * 5.0 * (teF - teS);
 return vec2f(noteSoft(softPos(d)), noteSoft(softPos(-d)));
}
// the chord root on the circle of fifths leans the palette (a hue change of the whole animal); the lean
// reaches the heart first and the margin, then the tips, later (lag_herochord2, 3, 4)
fn chordLean(r: vec2f, g: f32) -> f32 { return g * (0.25 * r.x + 0.15 * r.y); }
// A chord change as a wave with duration: differences of successive stages of the strike response
// (lag_herokick2 - 4, 4 - 5, 5 - 7; every stage is at least second order, so every difference starts
// with zero slope), normalised so one strike peaks near 1 at the heart (about 0.6 s after it), half way
// out (1.3 s) and at the margin and down the appendages (2.4 s). A train of strikes overlaps into a
// gentle shimmer, never a sum. (A first-order stage here, lag_herokick6, dropped the margin's light the
// instant a strike began and then stopped dead at zero: a light step 0.1 s after every strike.)
fn softKnee(x: f32) -> f32 { return 0.5 * (x + sqrt(x * x + 0.01)); }
fn chordWave(k0: f32, k1: f32, k2: f32, kS: f32, g: f32) -> vec3f {
 let w = vec3f(3.0 * (k0 - k1), 10.0 * (k1 - k2), 15.0 * (k2 - kS));
 return g * vec3f(noteSoft(softKnee(w.x)), noteSoft(softKnee(w.y)), noteSoft(softKnee(w.z)));
}
// ---- hero appendages only (pass 6): notes, melody and tension as forces on the hanging curtain ----
// The twelve note places at the root stage (lag_heronote2) and the later tip stage (lag_heronote3).
fn ntNow(P: Params, phi: f32) -> f32 {
 return secSum(vec4f(P.nt0, P.nt1, P.nt2, P.nt3), vec4f(P.nt4, P.nt5, P.nt6, P.nt7), vec4f(P.nt8, P.nt9, P.nt10, P.nt11), phi);
}
fn ntLate(P: Params, phi: f32) -> f32 {
 return secSum(vec4f(P.nu0, P.nu1, P.nu2, P.nu3), vec4f(P.nu4, P.nu5, P.nu6, P.nu7), vec4f(P.nu8, P.nu9, P.nu10, P.nu11), phi);
}
// the note force at s along an appendage hanging at azimuth phi: the root feels the first stage, the
// tip the later one, so a strike travels down (0..about 1)
fn noteAt(P: Params, phi: f32, s: f32) -> f32 {
 return (P.noteGain * P.react) * noteSoft(mix(ntNow(P, phi), ntLate(P, phi), smoother(0.1, 0.9, s)));
}
// the palette lean of the chord root along an appendage: the margin's stage at the root, later at the tip
fn leanAt(P: Params, s: f32) -> f32 {
 return chordLean(mix(vec2f(P.rC3, P.rS3), vec2f(P.rC4, P.rS4), smoother(0.0, 1.0, s)), (P.chordGain * P.react));
}
// the chord's own colour: the root's place on the circle of fifths picks among four hues of the next
// two palettes, all cool against the warm body and lines (deep-blue mood: aqua, cyan, teal, blue), so
// neighbouring chords differ and the
// same root always returns in the same colour (as on the bell)
fn hl(c: vec3f) -> vec3f { return c / max(max(c.r, c.g), max(c.b, 0.05)); }
fn chordHue(md: f32, r: vec2f) -> vec3f {
 let w = max(vec4f(r.x, r.y, -r.x, -r.y), vec4f(0.0));
 let a = hl(moodColor(md + 1.0, 0.5));
 let b = hl(moodColor(md + 2.0, 0.95));
 let c = hl(moodColor(md + 1.0, 0.25));
 let d = hl(moodColor(md + 2.0, 0.6));
 // while a far root change passes the lagged direction through the centre, ease to the mean hue (pass 7)
 let sw = w.x + w.y + w.z + w.w;
 return (w.x * a + w.y * b + w.z * c + w.w * d + max(0.6 - sw, 0.0) * 0.25 * (a + b + c + d)) / max(sw, 0.6);
}
fn waveColAt(P: Params, s: f32) -> vec3f {
 return chordHue(P.mood + leanAt(P, s), mix(vec2f(P.rC3, P.rS3), vec2f(P.rC4, P.rS4), smoother(0.0, 1.0, s)));
}
// the chord-change wave at s along an appendage: the half-way stage at the root, the margin's stage below
fn waveAt(P: Params, s: f32) -> f32 {
 let w = chordWave(P.kick0, P.kick1, P.kick2, P.kickS, (P.chordGain * P.react));
 return mix(w.y, w.z, smoother(0.0, 0.6, s));
}
// A tentacle point with the music's gestures (the tentacle beams and the beads on them share it). All
// offsets are outward, sideways or down and grow from nothing at the root; keepBelow holds again.
fn heroTentPoint(c: TC, P: Params, ti: u32, s: f32) -> vec3f {
 let phi = tentPhi(ti);
 let len = tentLength(c, ti);
 var pos = tentPoint(c, ti, s);
 let out = hfDir(c.fP, vec3f(cos(phi), 0.0, sin(phi)));
 let tang = hfDir(c.fP, vec3f(-sin(phi), 0.0, cos(phi)));
 // a note: the filaments of its place flare out and fan apart from the place's centre
 let x = noteAt(P, phi, s);
 pos += (out * 0.08 + tang * 0.1 * secOffset(phi) + c.droop * 0.02) * len * sin(1.5708 * s) * x;
 // the melody: the filaments at the melody note's place curl out as the line rises, in as it falls
 let ud = melodyUD(P.melF, P.melS, (P.melodyGain * P.react));
 let lead = smoothstep(0.6, 1.0, dot(vec2f(cos(phi), sin(phi)), vec2f(P.leadC, P.leadS)));
 pos += out * (0.22 * ud.x - 0.14 * ud.y) * len * s * s * lead;
 // tension draws the curtain long; a release lets it spread (the exhale)
 let rr = tensionRR(P.tension, P.teS, (P.tensionGain * P.react));
 pos += (c.droop * 0.1 * rr.x - out * 0.04 * rr.x + out * 0.13 * rr.y) * len * s;
 return keepBelow(c, tentRoot(c, phi, 0.0), pos, s, len);
}
// SHARED PALETTE: paste verbatim into every material/kernel that colours anything. Do not edit locally.
// pal: 0 deep blue>amethyst>peach, 1 teal>aqua>gold, 2 magenta>violet>cyan, 3 amber>rose>lilac (continuous, wraps at 4).
// t: 0 shadow tone, 0.5 body tone, 1 highlight tone.
fn moodStops(i: i32, t: f32) -> vec3f {
 var a: vec3f; var b: vec3f; var c: vec3f;
 switch (((i % 4) + 4) % 4) {
  case 0 { a = vec3f(0.06, 0.12, 0.60); b = vec3f(0.42, 0.26, 0.90); c = vec3f(1.00, 0.60, 0.40); }
  case 1 { a = vec3f(0.00, 0.30, 0.40); b = vec3f(0.10, 0.85, 0.72); c = vec3f(1.00, 0.76, 0.28); }
  case 2 { a = vec3f(0.80, 0.06, 0.55); b = vec3f(0.42, 0.18, 0.95); c = vec3f(0.18, 0.82, 1.00); }
  default { a = vec3f(1.00, 0.50, 0.10); b = vec3f(0.95, 0.32, 0.48); c = vec3f(0.68, 0.52, 1.00); }
 }
 let x = clamp(t, 0.0, 1.0) * 2.0;
 return mix(mix(a, b, clamp(x, 0.0, 1.0)), c, clamp(x - 1.0, 0.0, 1.0));
}
fn moodColor(pal: f32, t: f32) -> vec3f {
 let i = i32(floor(pal));
 return mix(moodStops(i, t), moodStops(i + 1, t), smoothstep(0.0, 1.0, fract(pal)));
}
